export const safeSsrfFetchForSdk = async (
  input: RequestInfo | URL,
  init?: RequestInit,
  _hooks?: SafeSsrfFetchHooks
): Promise<globalThis.Response> => {
  let targetUrl = '';
  let mergedInit: RequestInit = init ? { ...init } : {};

  if (typeof input === 'string') {
    targetUrl = input;
  } else if (input instanceof URL) {
    targetUrl = input.toString();
  } else if (input && typeof input === 'object' && 'url' in input) {
    const reqObj = input as globalThis.Request;
    targetUrl = reqObj.url;
    const mergedHeaders = new Headers(reqObj.headers);
    if (init?.headers) {
      new Headers(init.headers).forEach((v, k) => mergedHeaders.set(k, v));
    }
    let body = init?.body;
    if (body === undefined && reqObj.method !== 'GET' && reqObj.method !== 'HEAD' && reqObj.body) {
      body = await reqObj.arrayBuffer();
    }
    mergedInit = {
      ...mergedInit,
      method: init?.method || reqObj.method,
      headers: mergedHeaders,
      ...(body !== undefined ? { body } : {}),
      signal: init?.signal ?? reqObj.signal,
    };
  } else {
    throw new Error('SSRF 安全拦截：无效的 SDK 请求目标');
  }

  return await safeSsrfFetch(targetUrl, mergedInit, _hooks);
};

export async function createCustomGeminiClient(params: {
  baseUrl: string;
  apiKey?: string;
  headers?: Record<string, string>;
  timeoutMs?: number;
  _hooks?: SafeSsrfFetchHooks;
}): Promise<GoogleGenAI> {
  const sdkBaseUrl = String(params.baseUrl || '')
    .trim()
    .replace(/\/+$/, '')
    .replace(/\/v1beta.*$/i, '')
    .replace(/\/v1$/i, '');

  if (!sdkBaseUrl) {
    throw new Error('SSRF 安全拦截：自定义 Gemini Base URL 不能为空');
  }

  // Pre-validate baseUrl (protocol, credentials, port, IPv4/IPv6, DNS A/AAAA, production HTTPS) before SDK instantiation
  await validateSafeSsrfTargetUrl(sdkBaseUrl, {
    dnsLookup: params._hooks?.dnsLookup,
    isProductionOverride: params._hooks?.isProductionOverride,
  });

  const customSdkFetch = params._hooks
    ? (input: RequestInfo | URL, init?: RequestInit) => safeSsrfFetchForSdk(input, init, params._hooks)
    : safeSsrfFetchForSdk;

  return new GoogleGenAI({
    apiKey: params.apiKey || 'local-key',
    httpOptions: {
      baseUrl: sdkBaseUrl,
      ...(params.timeoutMs ? { timeout: params.timeoutMs } : {}),
      headers: {
        ...(params.headers || {}),
        'User-Agent': 'aistudio-build',
      },
      fetch: customSdkFetch,
    },
  });
}

export function safeJsonParse<T>(raw: string | null | undefined, fallback: T): T {
  if (!raw || typeof raw !== 'string') return fallback;
  try {
    return JSON.parse(raw);
  } catch {
    return fallback;
  }
}

export function extractFirstJsonObject(raw: string | null | undefined): Record<string, any> | null {
  if (!raw || typeof raw !== 'string') return null;
  const scanBalancedObject = (src: string): Record<string, any> | null => {
    const direct = safeJsonParse<any>(src, null);
    if (direct && typeof direct === 'object' && !Array.isArray(direct)) {
      return direct;
    }
    let inString = false;
    let escaped = false;
    let depth = 0;
    let startIdx = -1;
    for (let i = 0; i < src.length; i++) {
      const ch = src[i];
      if (inString) {
        if (escaped) {
          escaped = false;
        } else if (ch === '\\') {
          escaped = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
        continue;
      }
      if (ch === '{') {
        if (depth === 0) startIdx = i;
        depth++;
      } else if (ch === '}' && depth > 0) {
        depth--;
        if (depth === 0 && startIdx >= 0) {
          const parsed = safeJsonParse<any>(src.slice(startIdx, i + 1), null);
          if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
            return parsed;
          }
          startIdx = -1;
        }
      }
    }
    return null;
  };

  const trimmed = raw.trim();
  if (!trimmed) return null;
  const fenceRegex = /```(?:json)?\s*([\s\S]*?)```/gi;
  let match: RegExpExecArray | null;
  while ((match = fenceRegex.exec(trimmed)) !== null) {
    const inner = String(match[1] || '').trim();
    if (!inner) continue;
    const parsedBlock = scanBalancedObject(inner);
    if (parsedBlock) return parsedBlock;
  }
  const cleaned = trimmed
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  return cleaned ? scanBalancedObject(cleaned) : null;
}

export function sanitizeHttpHeaderValue(val?: any): string {
  if (!val || typeof val !== 'string') return '';
  return val.replace(/[^\x20-\x7E]/g, '').trim();
}

export function buildCustomOpenAiUrls(baseUrl: string): string[] {
  const clean = baseUrl.trim().replace(/\/+$/, '');
  if (clean.endsWith('/chat/completions')) {
    return [clean];
  }
  if (clean.endsWith('/v1')) {
    const root = clean.replace(/\/v1$/, '');
    return [`${clean}/chat/completions`, `${root}/chat/completions`, `${root}/api/chat/completions`];
  }
  return [
    `${clean}/v1/chat/completions`,
    `${clean}/chat/completions`,
    `${clean}/api/chat/completions`,
    `${clean}/api/v1/chat/completions`
  ];
}

export function buildCustomAnthropicUrls(baseUrl: string): string[] {
  const clean = baseUrl.trim().replace(/\/+$/, '');
  if (clean.endsWith('/messages')) {
    return [clean];
  }
  if (clean.endsWith('/v1')) {
    return [`${clean}/messages`];
  }
  return [`${clean}/v1/messages`, `${clean}/messages`];
}

export function formatAnthropicMessages(
  messages: Array<{ role: string; content?: string; text?: string; sender?: string }>,
  systemInstruction?: string
): { system?: string; messages: Array<{ role: 'user' | 'assistant'; content: string }> } {
  const systemParts: string[] = [];
  if (systemInstruction && systemInstruction.trim()) {
    systemParts.push(systemInstruction.trim());
  }
  const mapped: Array<{ role: 'user' | 'assistant'; content: string }> = [];
  for (const m of messages) {
    const txt = (m.content || m.text || '').trim();
    if (!txt) continue;
    if (m.role === 'system') {
      systemParts.push(txt);
      continue;
    }
    const role: 'user' | 'assistant' =
      m.role === 'peer' || m.sender === 'peer' || m.role === 'user' ? 'user' : 'assistant';
    if (mapped.length > 0 && mapped[mapped.length - 1].role === role) {
      mapped[mapped.length - 1].content += `\n${txt}`;
    } else {
      mapped.push({ role, content: txt });
    }
  }
  if (mapped.length === 0) {
    mapped.push({ role: 'user', content: 'Hello' });
  } else if (mapped[0].role === 'assistant') {
    mapped.unshift({ role: 'user', content: '...' });
  }
  return {
    system: systemParts.length > 0 ? systemParts.join('\n\n') : undefined,
    messages: mapped,
  };
}

