// ==================== UNIFIED CONVERSATION SYNC & RESOLUTION PIPELINE ====================

export interface UnifiedChatMessage {
  id: string;
  clientMessageId?: string;
  telegramMessageId?: number;
  chatId: string;
  accountId: string;
  sender: 'me' | 'peer' | 'system';
  senderName: string;
  senderId?: string;
  senderAvatarUrl?: string;
  text: string;
  translatedText: string;
  isAudio: boolean;
  audioDuration: number;
  audioUrl: string;
  sttText: string;
  voiceTone: string;
  isImage: boolean;
  imageUrl: string;
  imageCaption: string;
  isVideo: boolean;
  videoUrl: string;
  videoDuration: number;
  isFile: boolean;
  fileName: string;
  fileSize: string;
  fileUrl: string;
  timestamp: string;
  createdAt: number;
  deliveryStatus: string;
  queuePauseReason?: string;
  floodWaitUntil?: number;
  replyTo?: { id: string; telegramMessageId?: number; senderName?: string; text: string };
  reactions?: Record<string, number>;
  myReactions?: string[];
  isEdited?: boolean;
  isPinned?: boolean;
  forwardFrom?: string;
  isCall?: boolean;
  callType?: 'incoming' | 'outgoing' | 'missed';
  callDuration?: number;
  isVideoCall?: boolean;
  telegramCallId?: string;
  systemEventType?: TelegramSystemEventType;
}

export function parseStoredReactionsJson(raw: any): {
  reactions?: Record<string, number>;
  myReactions?: string[];
} {
  if (!raw) return {};
  const obj = typeof raw === 'string' ? safeJsonParse<any>(raw, null) : raw;
  if (!obj || typeof obj !== 'object') return {};

  // Structured format: { reactions: Record<string, number>, myReactions?: string[] }
  if ('reactions' in obj || 'myReactions' in obj) {
    const rawMap = obj.reactions && typeof obj.reactions === 'object' ? obj.reactions : {};
    const reactions: Record<string, number> = {};
    for (const [emoji, cnt] of Object.entries(rawMap)) {
      const n = Number(cnt);
      if (emoji && Number.isFinite(n) && n > 0) reactions[emoji] = n;
    }
    const myReactions = Array.isArray(obj.myReactions)
      ? obj.myReactions.filter((e: any) => typeof e === 'string' && e.length > 0)
      : [];
    return {
      ...(Object.keys(reactions).length > 0 ? { reactions } : {}),
      ...(myReactions.length > 0 ? { myReactions } : {}),
    };
  }

  // Flat map fallback: { "👍": 2 }
  const flatReactions: Record<string, number> = {};
  for (const [emoji, cnt] of Object.entries(obj)) {
    const n = Number(cnt);
    if (emoji && Number.isFinite(n) && n > 0) flatReactions[emoji] = n;
  }
  return Object.keys(flatReactions).length > 0 ? { reactions: flatReactions } : {};
}

export function serializeStoredReactionsJson(raw: any): string | null {
  if (!raw || typeof raw !== 'object') return null;
  const hasExplicit =
    raw.reactions !== undefined ||
    raw.myReactions !== undefined ||
    raw.reactions_json !== undefined ||
    raw.reactionsJson !== undefined;
  if (!hasExplicit) return null;

  const parsed =
    raw.reactions !== undefined || raw.myReactions !== undefined
      ? parseStoredReactionsJson({ reactions: raw.reactions, myReactions: raw.myReactions })
      : parseStoredReactionsJson(raw.reactions_json ?? raw.reactionsJson);
  const hasReactions = Boolean(parsed.reactions && Object.keys(parsed.reactions).length > 0);
  const hasMine = Boolean(parsed.myReactions && parsed.myReactions.length > 0);
  if (!hasReactions && !hasMine) {
    return '{}';
  }
  return JSON.stringify({
    ...(hasReactions ? { reactions: parsed.reactions } : {}),
    ...(hasMine ? { myReactions: parsed.myReactions } : {}),
  });
}

export function sanitizeDbMediaUrl(url: any): string {
  const s = typeof url === 'string' ? url.trim() : '';
  if (!s) return '';
  if (s.startsWith('blob:')) {
    return '';
  }
  if (s.startsWith('data:') && s.length > 512 * 1024) {
    return '';
  }
  return s;
}

export function normalizeStoredMessageRecord(
  raw: any,
  fallbackChatId = '',
  fallbackAccountId = 'acc_1'
): UnifiedChatMessage | null {
  if (!raw || typeof raw !== 'object') return null;
  const chatId = String(raw.chatId || raw.chat_id || fallbackChatId || '').trim();
  if (!chatId) return null;

  const createdAtRaw = Number(raw.createdAt ?? raw.created_at);
  const createdAt = Number.isFinite(createdAtRaw) && createdAtRaw > 0 ? createdAtRaw : Date.now();
  const tgIdRaw = Number(raw.telegramMessageId ?? raw.telegram_message_id ?? resolveTelegramMessageNumericId(raw.id) ?? 0);
  const telegramMessageId = Number.isInteger(tgIdRaw) && tgIdRaw > 0 ? tgIdRaw : undefined;
  const senderRaw = String(raw.sender || 'me');
  const sender: 'me' | 'peer' | 'system' =
    senderRaw === 'peer' ? 'peer' : senderRaw === 'system' ? 'system' : 'me';

  const id = String(
    raw.id ||
      (telegramMessageId
        ? `tg_cloud_${telegramMessageId}_${createdAt}`
        : `msg_${createdAt}_${Math.random().toString(36).slice(2, 6)}`)
  );

  const parsedReplyTo =
    raw.replyTo && typeof raw.replyTo === 'object'
      ? raw.replyTo
      : typeof raw.reply_to_json === 'string' && raw.reply_to_json
      ? safeJsonParse<{ id: string; telegramMessageId?: number; senderName?: string; text: string } | undefined>(raw.reply_to_json, undefined)
      : undefined;

  const parsedReactions =
    raw.reactions !== undefined || raw.myReactions !== undefined
      ? parseStoredReactionsJson({ reactions: raw.reactions, myReactions: raw.myReactions })
      : parseStoredReactionsJson(raw.reactions_json ?? raw.reactionsJson);

  const senderId = String(raw.senderId ?? raw.sender_id ?? '').trim();
  const rawSenderAvatarUrl = String(raw.senderAvatarUrl ?? raw.sender_avatar_url ?? '').trim();

  const clientMessageId = String(raw.clientMessageId ?? raw.client_message_id ?? '').trim();
  const queuePauseReason = String(raw.queuePauseReason ?? raw.queue_pause_reason ?? '').trim();
  const floodWaitUntilRaw = Number(raw.floodWaitUntil ?? raw.flood_wait_until ?? 0);
  const floodWaitUntil = Number.isFinite(floodWaitUntilRaw) && floodWaitUntilRaw > 0 ? floodWaitUntilRaw : undefined;

  return {
    id,
    ...(clientMessageId ? { clientMessageId } : {}),
    telegramMessageId,
    chatId,
    accountId: String(raw.accountId || raw.account_id || fallbackAccountId || 'acc_1'),
    sender,
    senderName: String(raw.senderName ?? raw.sender_name ?? ''),
    ...(senderId ? { senderId } : {}),
    ...(rawSenderAvatarUrl ? { senderAvatarUrl: rawSenderAvatarUrl } : {}),
    text: String(raw.text ?? ''),
    translatedText: String(raw.translatedText ?? raw.translated_text ?? ''),
    isAudio: Boolean(raw.isAudio ?? raw.is_audio),
    audioDuration: Number(raw.audioDuration ?? raw.audio_duration ?? 0) || 0,
    audioUrl: String(raw.audioUrl ?? raw.audio_url ?? ''),
    sttText: String(raw.sttText ?? raw.stt_text ?? ''),
    voiceTone: String(raw.voiceTone ?? raw.voice_tone ?? ''),
    isImage: Boolean(raw.isImage ?? raw.is_image),
    imageUrl: String(raw.imageUrl ?? raw.image_url ?? ''),
    imageCaption: String(raw.imageCaption ?? raw.image_caption ?? ''),
    isVideo: Boolean(raw.isVideo ?? raw.is_video),
    videoUrl: String(raw.videoUrl ?? raw.video_url ?? ''),
    videoDuration: Number(raw.videoDuration ?? raw.video_duration ?? 0) || 0,
    isFile: Boolean(raw.isFile ?? raw.is_file),
    fileName: String(raw.fileName ?? raw.file_name ?? ''),
    fileSize: String(raw.fileSize ?? raw.file_size ?? ''),
    fileUrl: String(raw.fileUrl ?? raw.file_url ?? ''),
    timestamp: String(
      raw.timestamp ||
        new Date(createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false })
    ),
    createdAt,
    deliveryStatus: String(raw.deliveryStatus ?? raw.delivery_status ?? 'delivered'),
    ...(queuePauseReason ? { queuePauseReason } : {}),
    ...(floodWaitUntil ? { floodWaitUntil } : {}),
    ...(parsedReplyTo ? { replyTo: parsedReplyTo } : {}),
    ...(parsedReactions.reactions ? { reactions: parsedReactions.reactions } : {}),
    ...(parsedReactions.myReactions ? { myReactions: parsedReactions.myReactions } : {}),
    isEdited: Boolean(raw.isEdited ?? raw.is_edited),
    isPinned: Boolean(raw.isPinned ?? raw.is_pinned),
    ...(raw.forwardFrom || raw.forward_from ? { forwardFrom: String(raw.forwardFrom ?? raw.forward_from) } : {}),
    ...inferCallMetadataFromStoredRecord(raw, sender),
    ...((raw.systemEventType || raw.system_event_type)
      ? { systemEventType: String(raw.systemEventType ?? raw.system_event_type) as TelegramSystemEventType }
      : {}),
  };
}

export function getScopedAccountIdVariants(accountId?: string): string[] {
  const raw = String(accountId || 'acc_1').trim() || 'acc_1';
  const clean = raw.replace(/^acc_tg_/, '');
  const set = new Set<string>([raw]);
  if (clean && clean !== 'acc_1' && clean !== 'acc_telegram_bot') {
    set.add(clean);
    set.add(`acc_tg_${clean}`);
  }
  return Array.from(set);
}

export function resolveScopedAccountFromRequest(
  req: Request,
  options?: { allowBot?: boolean; allowMasterOverride?: boolean }
): { ok: true; accountId: string; isExplicit: boolean } | { ok: false; status: number; code: string; error: string } {
  const authContext = (req as any).auth;
  const session = authContext?.session;
  if (!session) {
    return { ok: false, status: 401, code: 'AUTH_SESSION_REQUIRED', error: '未授权访问：缺少有效会话' };
  }

  const allowBot = options?.allowBot ?? false;
  if (!allowBot && (session.isBot || authContext?.isBot)) {
    return {
      ok: false,
      status: 403,
      code: 'BOT_FORBIDDEN',
      error: '权限不足：Bot Webhook 凭证无权访问个人账号或系统控制接口',
    };
  }

  const rawRequested =
    (typeof req.body?.accountId === 'string' && req.body.accountId.trim()) ||
    (typeof req.query?.accountId === 'string' && req.query.accountId.trim()) ||
    (typeof req.headers['x-account-id'] === 'string' && req.headers['x-account-id'].trim()) ||
    '';
  const effective = String(authContext?.effectiveAccountId || session.accountId || 'acc_1').trim() || 'acc_1';

  if (session.isBot || authContext?.isBot) {
    if (rawRequested && rawRequested !== 'acc_telegram_bot') {
      return {
        ok: false,
        status: 403,
        code: 'BOT_CROSS_ACCOUNT_FORBIDDEN',
        error: 'Bot 会话已锁定为 acc_telegram_bot，禁止越权指定或访问其他账号',
      };
    }
    return { ok: true, accountId: 'acc_telegram_bot', isExplicit: Boolean(rawRequested) };
  }

  if (!session.isMaster) {
    if (rawRequested && rawRequested !== effective) {
      return {
        ok: false,
        status: 403,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `无权跨账号操作目标账号 (${rawRequested})`,
      };
    }
    return { ok: true, accountId: effective, isExplicit: Boolean(rawRequested) };
  }

  if (options?.allowMasterOverride !== false && rawRequested) {
    const authorized: string[] = Array.isArray(session.authorizedAccounts) ? session.authorizedAccounts : [];
    if (
      rawRequested === effective ||
      rawRequested.startsWith('acc_tg_') ||
      authorized.includes(rawRequested)
    ) {
      return { ok: true, accountId: rawRequested, isExplicit: true };
    }
    return {
      ok: false,
      status: 403,
      code: 'ACCOUNT_SCOPE_FORBIDDEN',
      error: `无权访问未授权账号 (${rawRequested})`,
    };
  }

  return { ok: true, accountId: effective, isExplicit: Boolean(rawRequested) };
}

export function resolveScopedAiAccountId(
  req: Request
): { ok: true; accountId: string } | { ok: false; status: number; error: string } {
  const authContext = (req as any).auth;
  const session = authContext?.session;
  if (!session) {
    return { ok: false, status: 401, error: '未授权访问：缺少有效会话' };
  }
  const rawRequested =
    typeof req.body?.accountId === 'string' && req.body.accountId.trim()
      ? req.body.accountId.trim()
      : typeof req.query?.accountId === 'string' && req.query.accountId.trim()
      ? req.query.accountId.trim()
      : '';

  if (authContext?.isBot || session.isBot) {
    if (rawRequested && rawRequested !== 'acc_telegram_bot') {
      return { ok: false, status: 403, error: 'Bot 会话禁止跨账号访问其他账号的知识库或人设数据' };
    }
    return { ok: true, accountId: 'acc_telegram_bot' };
  }

  const effective = String(authContext?.effectiveAccountId || session?.accountId || 'acc_1').trim() || 'acc_1';
  if (!session.isMaster) {
    if (rawRequested && rawRequested !== effective) {
      return { ok: false, status: 403, error: `无权跨账号访问目标账号 (${rawRequested}) 的知识库或进化数据` };
    }
    return { ok: true, accountId: effective };
  }
  if (!rawRequested) {
    return { ok: true, accountId: effective };
  }

  const authorized: string[] = Array.isArray(session?.authorizedAccounts) ? session.authorizedAccounts : [];
  if (
    rawRequested === effective ||
    rawRequested.startsWith('acc_tg_') ||
    authorized.includes(rawRequested)
  ) {
    return { ok: true, accountId: rawRequested };
  }

  return { ok: false, status: 403, error: `无权访问未授权账号 (${rawRequested}) 的知识库或进化数据` };
}

export async function getScopedCustomerProfile(chatId: string, accountId?: string): Promise<any | undefined> {
  const effAcc = String(accountId || 'acc_1').trim() || 'acc_1';
  const variants = getScopedAccountIdVariants(effAcc);
  const canonicalId = canonicalizeCustomerChatId(chatId);
  const altChatId = canonicalId.startsWith('tg_') ? canonicalId.replace(/^tg_/, '') : `tg_${canonicalId}`;
  const rawInput = String(chatId || '').trim();
  const chatCandidates = Array.from(new Set([canonicalId, altChatId, rawInput].filter(Boolean)));
  const chatPh = chatCandidates.map(() => '?').join(', ');
  const placeholders = variants.map(() => '?').join(', ');

  try {
    const scopedRows = (await db
      .prepare(
        `SELECT * FROM account_customer_profiles
         WHERE chat_id IN (${chatPh}) AND account_id IN (${placeholders})
         ORDER BY CASE WHEN chat_id = ? THEN 0 ELSE 1 END, updated_at DESC`
      )
      .all(...chatCandidates, ...variants, canonicalId)) as any[];
    if (scopedRows && scopedRows.length > 0) {
      if (scopedRows.length === 1) {
        return { ...scopedRows[0], chat_id: canonicalId };
      }
      // Merge split rows (e.g. legacy 123 and tg_123) so no manual memories/tags are lost
      const primary = scopedRows[0];
      const merged = scopedRows.slice(1).reduce(
        (acc, row) =>
          mergeCustomerProfileWithManualData({
            existingProfile: acc,
            aiData: {
              clientName: row.client_name,
              relationshipStage: row.relationship_stage,
              ageEstimate: row.age_estimate,
              occupation: row.occupation,
              locationTimezone: row.location_timezone,
              toneStyle: row.tone_style,
              likesInterests: safeJsonParse(row.likes_interests, []),
              dislikesTaboos: safeJsonParse(row.dislikes_taboos, []),
              emotionalNeeds: row.emotional_needs,
              familyMaritalStatus: row.family_marital_status,
              activeSchedule: row.active_schedule,
              financialProfile: row.financial_profile,
              investmentAttitude: row.investment_attitude,
              trustLevel: row.trust_level,
              nextStepStrategy: row.next_step_strategy,
              keyMemories: safeJsonParse(row.key_memories, []),
            },
            preserveOnSparse: true,
          }),
        primary as any
      );
      return {
        ...primary,
        chat_id: canonicalId,
        client_name: merged.clientName,
        relationship_stage: merged.relationshipStage,
        age_estimate: merged.ageEstimate,
        occupation: merged.occupation,
        location_timezone: merged.locationTimezone,
        family_marital_status: merged.familyMaritalStatus,
        active_schedule: merged.activeSchedule,
        tone_style: merged.toneStyle,
        likes_interests: JSON.stringify(merged.likesInterests),
        dislikes_taboos: JSON.stringify(merged.dislikesTaboos),
        emotional_needs: merged.emotionalNeeds,
        financial_profile: merged.financialProfile,
        investment_attitude: merged.investmentAttitude,
        trust_level: merged.trustLevel,
        next_step_strategy: merged.nextStepStrategy,
        key_memories: JSON.stringify(merged.keyMemories),
      };
    }
  } catch {}

  try {
    const legacy = (await db
      .prepare(
        `SELECT * FROM customer_profiles
         WHERE chat_id IN (${chatPh}) AND account_id IN (${placeholders})
         ORDER BY CASE WHEN chat_id = ? THEN 0 ELSE 1 END, updated_at DESC
         LIMIT 1`
      )
      .get(...chatCandidates, ...variants, canonicalId)) as any;
    if (legacy) return { ...legacy, chat_id: canonicalId };
  } catch {}

  return undefined;
}

export async function getScopedChatTargetLang(
  chatId?: string | number | null,
  accountId?: string | null
): Promise<string> {
  const { customerId, altCustomerId, accountId: effAcc } = resolveCanonicalChatIds(chatId, accountId);
  if (!customerId) return '';
  const variants = getScopedAccountIdVariants(effAcc);
  if ((effAcc === 'acc_telegram_bot' || effAcc === 'acc_1') && !variants.includes('acc_telegram_bot')) {
    variants.push('acc_telegram_bot');
  }
  if (effAcc === 'acc_telegram_bot' && !variants.includes('acc_1')) {
    variants.push('acc_1');
  }
  const chatIds = altCustomerId && altCustomerId !== customerId ? [customerId, altCustomerId] : [customerId];
  const chatPh = chatIds.map(() => '?').join(', ');
  const accPh = variants.map(() => '?').join(', ');
  try {
    const rows = (await db
      .prepare(
        `SELECT account_id, chat_id, target_lang, updated_at
         FROM chat_language_prefs
         WHERE chat_id IN (${chatPh}) AND account_id IN (${accPh})
         ORDER BY updated_at DESC`
      )
      .all(...chatIds, ...variants)) as any[];
    const exactMatch =
      rows.find((r) => r?.chat_id === customerId && r?.account_id === effAcc) ||
      rows.find((r) => r?.account_id === effAcc) ||
      rows[0];
    const targetLang = String(exactMatch?.target_lang || '').trim();
    return targetLang && targetLang !== 'Auto' ? targetLang : '';
  } catch {
    return '';
  }
}

export async function countScopedChatMessages(chatId: string, accountId?: string): Promise<number> {
  const effAcc = String(accountId || 'acc_1').trim() || 'acc_1';
  const variants = getScopedAccountIdVariants(effAcc);
  const canonicalId = canonicalizeCustomerChatId(chatId);
  const altChatId = canonicalId.startsWith('tg_') ? canonicalId.replace(/^tg_/, '') : `tg_${canonicalId}`;
  const rawInput = String(chatId || '').trim();
  const chatCandidates = Array.from(new Set([canonicalId, altChatId, rawInput].filter(Boolean)));
  if (chatCandidates.length === 0) return 0;
  const chatPh = chatCandidates.map(() => '?').join(', ');
  const accPh = variants.map(() => '?').join(', ');
  try {
    const row = (await db
      .prepare(`SELECT COUNT(*) as cnt FROM messages WHERE chat_id IN (${chatPh}) AND account_id IN (${accPh})`)
      .get(...chatCandidates, ...variants)) as any;
    return Math.max(0, Number(row?.cnt) || 0);
  } catch {
    return 0;
  }
}

export async function upsertScopedCustomerProfile(params: {
  chatId: string;
  accountId: string;
  clientName: string;
  relationshipStage: string;
  ageEstimate: string;
  occupation: string;
  locationTimezone: string;
  familyMaritalStatus?: string;
  activeSchedule?: string;
  toneStyle: string;
  likesInterests: string;
  dislikesTaboos: string;
  emotionalNeeds: string;
  financialProfile?: string;
  investmentAttitude?: string;
  trustLevel?: string;
  nextStepStrategy?: string;
  keyMemories: string;
  totalMessagesCount?: number;
  lastAnalyzedAt?: number;
  updatedAt: number;
}): Promise<void> {
  const effAcc = String(params.accountId || 'acc_1').trim() || 'acc_1';
  const canonicalChatId = canonicalizeCustomerChatId(params.chatId);
  const altChatId = canonicalChatId.startsWith('tg_') ? canonicalChatId.replace(/^tg_/, '') : '';
  const familyMaritalVal = String(params.familyMaritalStatus ?? '');
  const activeScheduleVal = String(params.activeSchedule ?? '');
  const financialProfileVal = String(params.financialProfile ?? '');
  const investmentAttitudeVal = String(params.investmentAttitude ?? '');
  const trustLevelVal = String(params.trustLevel ?? '');
  const nextStepStrategyVal = String(params.nextStepStrategy ?? '');

  await db
    .prepare(
      `INSERT INTO account_customer_profiles (
        account_id, chat_id, client_name, relationship_stage, age_estimate, occupation,
        location_timezone, family_marital_status, active_schedule, tone_style, likes_interests, dislikes_taboos, emotional_needs,
        financial_profile, investment_attitude, trust_level, next_step_strategy,
        key_memories, total_messages_count, last_analyzed_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(account_id, chat_id) DO UPDATE SET
        client_name = excluded.client_name,
        relationship_stage = excluded.relationship_stage,
        age_estimate = excluded.age_estimate,
        occupation = excluded.occupation,
        location_timezone = excluded.location_timezone,
        family_marital_status = excluded.family_marital_status,
        active_schedule = excluded.active_schedule,
        tone_style = excluded.tone_style,
        likes_interests = excluded.likes_interests,
        dislikes_taboos = excluded.dislikes_taboos,
        emotional_needs = excluded.emotional_needs,
        financial_profile = excluded.financial_profile,
        investment_attitude = excluded.investment_attitude,
        trust_level = excluded.trust_level,
        next_step_strategy = excluded.next_step_strategy,
        key_memories = excluded.key_memories,
        total_messages_count = CASE WHEN excluded.total_messages_count > account_customer_profiles.total_messages_count THEN excluded.total_messages_count ELSE account_customer_profiles.total_messages_count END,
        last_analyzed_at = CASE WHEN excluded.last_analyzed_at > 0 THEN excluded.last_analyzed_at ELSE account_customer_profiles.last_analyzed_at END,
        updated_at = excluded.updated_at`
    )
    .run(
      effAcc,
      canonicalChatId,
      params.clientName,
      params.relationshipStage,
      params.ageEstimate,
      params.occupation,
      params.locationTimezone,
      familyMaritalVal,
      activeScheduleVal,
      params.toneStyle,
      params.likesInterests,
      params.dislikesTaboos,
      params.emotionalNeeds,
      financialProfileVal,
      investmentAttitudeVal,
      trustLevelVal,
      nextStepStrategyVal,
      params.keyMemories,
      params.totalMessagesCount ?? 0,
      params.lastAnalyzedAt ?? 0,
      params.updatedAt
    );

  // Consolidate legacy unprefixed duplicate row if canonicalized from bare numeric Telegram ID
  if (altChatId && altChatId !== canonicalChatId) {
    try {
      await db
        .prepare('DELETE FROM account_customer_profiles WHERE account_id = ? AND chat_id = ?')
        .run(effAcc, altChatId);
    } catch {}
  }

  // Preserve compatibility with legacy customer_profiles table for single-account / bot records
  if (effAcc === 'acc_1' || effAcc === 'acc_telegram_bot') {
    const existingLegacy = (await db
      .prepare('SELECT account_id FROM customer_profiles WHERE chat_id = ?')
      .get(canonicalChatId)) as any;
    if (
      !existingLegacy ||
      !existingLegacy.account_id ||
      existingLegacy.account_id === effAcc
    ) {
      await db
        .prepare(
          `INSERT INTO customer_profiles (
            chat_id, account_id, client_name, relationship_stage, age_estimate, occupation,
            location_timezone, family_marital_status, active_schedule, tone_style, likes_interests, dislikes_taboos, emotional_needs,
            financial_profile, investment_attitude, trust_level, next_step_strategy,
            key_memories, total_messages_count, last_analyzed_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          ON CONFLICT(chat_id) DO UPDATE SET
            account_id = excluded.account_id,
            client_name = excluded.client_name,
            relationship_stage = excluded.relationship_stage,
            age_estimate = excluded.age_estimate,
            occupation = excluded.occupation,
            location_timezone = excluded.location_timezone,
            family_marital_status = excluded.family_marital_status,
            active_schedule = excluded.active_schedule,
            tone_style = excluded.tone_style,
            likes_interests = excluded.likes_interests,
            dislikes_taboos = excluded.dislikes_taboos,
            emotional_needs = excluded.emotional_needs,
            financial_profile = excluded.financial_profile,
            investment_attitude = excluded.investment_attitude,
            trust_level = excluded.trust_level,
            next_step_strategy = excluded.next_step_strategy,
            key_memories = excluded.key_memories,
            total_messages_count = CASE WHEN excluded.total_messages_count > customer_profiles.total_messages_count THEN excluded.total_messages_count ELSE customer_profiles.total_messages_count END,
            last_analyzed_at = CASE WHEN excluded.last_analyzed_at > 0 THEN excluded.last_analyzed_at ELSE customer_profiles.last_analyzed_at END,
            updated_at = excluded.updated_at`
        )
        .run(
          canonicalChatId,
          effAcc,
          params.clientName,
          params.relationshipStage,
          params.ageEstimate,
          params.occupation,
          params.locationTimezone,
          familyMaritalVal,
          activeScheduleVal,
          params.toneStyle,
          params.likesInterests,
          params.dislikesTaboos,
          params.emotionalNeeds,
          financialProfileVal,
          investmentAttitudeVal,
          trustLevelVal,
          nextStepStrategyVal,
          params.keyMemories,
          params.totalMessagesCount ?? 0,
          params.lastAnalyzedAt ?? 0,
          params.updatedAt
        );
      if (altChatId && altChatId !== canonicalChatId) {
        try {
          await db.prepare('DELETE FROM customer_profiles WHERE chat_id = ? AND account_id = ?').run(altChatId, effAcc);
        } catch {}
      }
    }
  }
}

// ==================== CAUSAL BOUNDED SQLITE MESSAGE WRITE QUEUE ====================
export type MessageDbWritePriority = 'HIGH' | 'NORMAL' | 'LOW';
export type MessageDbWriteKind =
  | 'upsert'
  | 'edit'
  | 'delete_channel'
  | 'delete_non_channel'
  | 'pin'
  | 'reactions'
  | 'stt'
  | 'clear_chat'
  | 'sync_empty_clear';

export const MESSAGE_DB_QUEUE_MAX_SIZE = 2000;
export const MESSAGE_DB_QUEUE_HIGH_WATER = 1400;
export const MESSAGE_DB_QUEUE_BATCH_SIZE = 50;
export const MESSAGE_DB_QUEUE_BATCH_WINDOW_MS = 35;
export const MESSAGE_DELETE_BARRIER_TTL_MS = 20_000;
export const MESSAGE_DELETE_BARRIER_MAX = 5000;

interface MessageDbWriteTask {
  seq: number;
  priority: MessageDbWritePriority;
  kind: MessageDbWriteKind;
  accountId: string;
  accountKey: string;
  canonicalChatId: string;
  tgMsgIds: number[];
  causalKey: string;
  snapshotTakenAt?: number;
  enqueuedAt: number;
  exec: () => Promise<any>;
  resolve: (val: any) => void;
  reject: (err: any) => void;
}

const msgDbHighQueue: MessageDbWriteTask[] = [];
const msgDbNormalQueue: MessageDbWriteTask[] = [];
const msgDbLowQueue: MessageDbWriteTask[] = [];
let msgDbQueueSeq = 0;
let msgDbFlushTimer: NodeJS.Timeout | null = null;
let msgDbActiveFlushPromise: Promise<void> | null = null;

// Short-lived deletion barrier so stale in-flight LOW history sync snapshots cannot resurrect deleted messages
const recentDeletedTgBarriers = new Map<string, number>();
const recentClearedChatBarriers = new Map<string, number>();

const messageDbWriteQueueStats = {
  enqueuedTotal: 0,
  committedTotal: 0,
  failedTotal: 0,
  batchCommitsTotal: 0,
  busyRetriesTotal: 0,
  droppedLowTotal: 0,
  suppressedResurrectionTotal: 0,
  maxQueueDepth: 0,
};

function normalizeMsgDbAccountKey(accountId?: string): string {
  const raw = String(accountId || '').trim();
  if (!raw) return 'default';
  return resolveTelegramAccountRuntimeKey({ accountId: raw }) || raw;
}

function normalizeMsgDbCanonicalChatId(chatId?: string): string {
  const raw = String(chatId || '').trim();
  if (!raw) return '';
  if (raw.startsWith('tg_') || raw.startsWith('chat_')) return raw;
  return /^-?\d+$/.test(raw) ? `tg_${raw}` : raw;
}

export function isMessageBlockedByDeleteBarrier(
  accountId: string | undefined,
  chatId: string | undefined,
  tgMsgId: number | undefined,
  snapshotTakenAt?: number,
  now = Date.now()
): boolean {
  const accKey = normalizeMsgDbAccountKey(accountId);
  const canonicalChat = normalizeMsgDbCanonicalChatId(chatId);
  const refTs = snapshotTakenAt ?? now;

  if (canonicalChat) {
    const clearKey = `${accKey}::${canonicalChat}`;
    const clearTs = recentClearedChatBarriers.get(clearKey);
    if (clearTs !== undefined) {
      if (now - clearTs > MESSAGE_DELETE_BARRIER_TTL_MS) {
        recentClearedChatBarriers.delete(clearKey);
      } else if (refTs <= clearTs) {
        return true;
      }
    }
  }

  if (tgMsgId && Number.isInteger(tgMsgId) && tgMsgId > 0) {
    if (canonicalChat) {
      const chBarrierKey = `${accKey}::${canonicalChat}::tg_${tgMsgId}`;
      const chTs = recentDeletedTgBarriers.get(chBarrierKey);
      if (chTs !== undefined) {
        if (now - chTs > MESSAGE_DELETE_BARRIER_TTL_MS) {
          recentDeletedTgBarriers.delete(chBarrierKey);
        } else if (refTs <= chTs) {
          return true;
        }
      }
    }
    const nonChBarrierKey = `${accKey}::nonchannel::tg_${tgMsgId}`;
    const isChannelChat = Boolean(
      canonicalChat && (canonicalChat.startsWith('tg_-100') || canonicalChat.startsWith('-100'))
    );
    if (!isChannelChat) {
      const ncTs = recentDeletedTgBarriers.get(nonChBarrierKey);
      if (ncTs !== undefined) {
        if (now - ncTs > MESSAGE_DELETE_BARRIER_TTL_MS) {
          recentDeletedTgBarriers.delete(nonChBarrierKey);
        } else if (refTs <= ncTs) {
          return true;
        }
      }
    }
  }
  return false;
}

export function recordMessageDeleteResurrectionBarrier(opts: {
  accountId?: string;
  chatId?: string;
  tgMsgIds?: number[];
  clearChat?: boolean;
  now?: number;
}): void {
  const now = opts.now ?? Date.now();
  const accKey = normalizeMsgDbAccountKey(opts.accountId);
  const canonicalChat = normalizeMsgDbCanonicalChatId(opts.chatId);

  if (opts.clearChat && canonicalChat) {
    recentClearedChatBarriers.set(`${accKey}::${canonicalChat}`, now);
    // Cancel pending stale LOW history upserts for the cleared chat
    for (let i = msgDbLowQueue.length - 1; i >= 0; i--) {
      const t = msgDbLowQueue[i];
      if (t.accountKey === accKey && t.canonicalChatId === canonicalChat && t.kind === 'upsert') {
        msgDbLowQueue.splice(i, 1);
        t.resolve(false);
      }
    }
  }

  if (Array.isArray(opts.tgMsgIds) && opts.tgMsgIds.length > 0) {
    const idSet = new Set(opts.tgMsgIds.map((n) => Number(n)).filter((n) => Number.isInteger(n) && n > 0));
    for (const tgId of idSet) {
      const bKey = canonicalChat
        ? `${accKey}::${canonicalChat}::tg_${tgId}`
        : `${accKey}::nonchannel::tg_${tgId}`;
      recentDeletedTgBarriers.set(bKey, now);
    }
    // Purge pending LOW upserts referencing the same deleted telegramMessageIds
    for (let i = msgDbLowQueue.length - 1; i >= 0; i--) {
      const t = msgDbLowQueue[i];
      if (t.accountKey !== accKey || t.kind !== 'upsert') continue;
      if (canonicalChat && t.canonicalChatId && t.canonicalChatId !== canonicalChat) continue;
      if (t.tgMsgIds.some((id) => idSet.has(id))) {
        msgDbLowQueue.splice(i, 1);
        t.resolve(false);
      }
    }
  }

  if (recentDeletedTgBarriers.size > MESSAGE_DELETE_BARRIER_MAX) {
    for (const [k, ts] of recentDeletedTgBarriers.entries()) {
      if (now - ts > MESSAGE_DELETE_BARRIER_TTL_MS) recentDeletedTgBarriers.delete(k);
    }
    while (recentDeletedTgBarriers.size > MESSAGE_DELETE_BARRIER_MAX) {
      const oldest = recentDeletedTgBarriers.keys().next().value;
      if (oldest === undefined) break;
      recentDeletedTgBarriers.delete(oldest);
    }
  }
}

export function clearMessageDeleteBarriersForTesting(): void {
  recentDeletedTgBarriers.clear();
  recentClearedChatBarriers.clear();
}

function areMsgDbTasksCausallyDependent(earlier: MessageDbWriteTask, later: MessageDbWriteTask): boolean {
  if (earlier.accountKey !== later.accountKey) return false;
  if (
    earlier.kind === 'clear_chat' ||
    earlier.kind === 'sync_empty_clear' ||
    later.kind === 'clear_chat' ||
    later.kind === 'sync_empty_clear'
  ) {
    if (!earlier.canonicalChatId || !later.canonicalChatId || earlier.canonicalChatId === later.canonicalChatId) {
      return true;
    }
  }
  if (earlier.kind === 'delete_non_channel' || later.kind === 'delete_non_channel') {
    const other = earlier.kind === 'delete_non_channel' ? later : earlier;
    const delTask = earlier.kind === 'delete_non_channel' ? earlier : later;
    const isOtherChannel = Boolean(
      other.canonicalChatId &&
        (other.canonicalChatId.startsWith('tg_-100') || other.canonicalChatId.startsWith('-100'))
    );
    if (!isOtherChannel) {
      if (other.tgMsgIds.length === 0 || delTask.tgMsgIds.some((id) => other.tgMsgIds.includes(id))) {
        return true;
      }
    }
  }
  if (earlier.canonicalChatId && later.canonicalChatId && earlier.canonicalChatId !== later.canonicalChatId) {
    return false;
  }
  if (earlier.causalKey && later.causalKey && earlier.causalKey === later.causalKey) {
    return true;
  }
  if (earlier.tgMsgIds.length > 0 && later.tgMsgIds.length > 0) {
    const set = new Set(earlier.tgMsgIds);
    if (later.tgMsgIds.some((id) => set.has(id))) {
      return true;
    }
  }
  return false;
}

function getMsgDbPendingTotal(): number {
  return msgDbHighQueue.length + msgDbNormalQueue.length + msgDbLowQueue.length;
}

function removeTaskFromQueues(task: MessageDbWriteTask): void {
  for (const q of [msgDbHighQueue, msgDbNormalQueue, msgDbLowQueue]) {
    const idx = q.indexOf(task);
    if (idx >= 0) {
      q.splice(idx, 1);
      return;
    }
  }
}

function dequeueCausalOrderedBatch(maxBatch = MESSAGE_DB_QUEUE_BATCH_SIZE): MessageDbWriteTask[] {
  const picked: MessageDbWriteTask[] = [];
  const pickedSet = new Set<MessageDbWriteTask>();

  const pullPrerequisitesAndTask = (root: MessageDbWriteTask) => {
    if (pickedSet.has(root)) return;
    const stack: MessageDbWriteTask[] = [root];
    const closure: MessageDbWriteTask[] = [];
    const seen = new Set<MessageDbWriteTask>([root]);

    while (stack.length > 0) {
      const cur = stack.pop()!;
      closure.push(cur);
      const allPending = [...msgDbHighQueue, ...msgDbNormalQueue, ...msgDbLowQueue];
      for (const candidate of allPending) {
        if (pickedSet.has(candidate) || seen.has(candidate)) continue;
        if (candidate.seq < cur.seq && areMsgDbTasksCausallyDependent(candidate, cur)) {
          seen.add(candidate);
          stack.push(candidate);
        }
      }
    }

    closure.sort((a, b) => a.seq - b.seq);
    for (const item of closure) {
      if (!pickedSet.has(item)) {
        removeTaskFromQueues(item);
        pickedSet.add(item);
        picked.push(item);
      }
    }
  };

  for (const q of [msgDbHighQueue, msgDbNormalQueue, msgDbLowQueue]) {
    while (q.length > 0 && picked.length < maxBatch) {
      pullPrerequisitesAndTask(q[0]);
    }
    if (picked.length >= maxBatch) break;
  }

  picked.sort((a, b) => a.seq - b.seq);
  return picked;
}

function isSqliteBusyError(err: any): boolean {
  const code = String(err?.code || '').toUpperCase();
  const msg = String(err?.message || err || '').toUpperCase();
  return code.includes('SQLITE_BUSY') || msg.includes('SQLITE_BUSY') || msg.includes('DATABASE IS LOCKED');
}

let sqliteWriteLockChain: Promise<void> = Promise.resolve();

function runWithSqliteWriteLock<T>(fn: () => Promise<T>): Promise<T> {
  const run = sqliteWriteLockChain.then(fn, fn);
  sqliteWriteLockChain = run.then(
    () => undefined,
    () => undefined
  );
  return run;
}

async function runMessageDbBatchWithRetries(batch: MessageDbWriteTask[]): Promise<void> {
  if (batch.length === 0) return;

  const attemptBatchTx = async () => {
    const runTx = db.transaction(async () => {
      const results: Array<{ ok: boolean; value?: any; error?: any }> = [];
      for (const task of batch) {
        const res = await task.exec();
        results.push({ ok: true, value: res });
      }
      return results;
    });
    return await runTx();
  };

  let lastErr: any = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const results = await runWithSqliteWriteLock(() => attemptBatchTx());
      messageDbWriteQueueStats.batchCommitsTotal += 1;
      for (let i = 0; i < batch.length; i++) {
        messageDbWriteQueueStats.committedTotal += 1;
        batch[i].resolve(results[i]?.value ?? true);
      }
      return;
    } catch (err: any) {
      lastErr = err;
      if (isSqliteBusyError(err) && attempt < 3) {
        messageDbWriteQueueStats.busyRetriesTotal += 1;
        await new Promise((r) => setTimeout(r, attempt * 35));
        continue;
      }
      break;
    }
  }

  // Batch failed fatally or exhausted SQLITE_BUSY retries -> isolate row faults cleanly
  for (const task of batch) {
    let settled = false;
    let taskErr: any = lastErr;
    for (let attempt = 1; attempt <= 2; attempt++) {
      try {
        const val = await runWithSqliteWriteLock(() => task.exec());
        messageDbWriteQueueStats.committedTotal += 1;
        task.resolve(val);
        settled = true;
        break;
      } catch (singleErr: any) {
        taskErr = singleErr;
        if (isSqliteBusyError(singleErr) && attempt < 2) {
          messageDbWriteQueueStats.busyRetriesTotal += 1;
          await new Promise((r) => setTimeout(r, 30));
          continue;
        }
        break;
      }
    }
    if (!settled) {
      messageDbWriteQueueStats.failedTotal += 1;
      task.reject(taskErr);
    }
  }
}

async function drainMessageDbWriteQueue(): Promise<void> {
  if (msgDbFlushTimer) {
    clearTimeout(msgDbFlushTimer);
    msgDbFlushTimer = null;
  }
  while (getMsgDbPendingTotal() > 0) {
    const batch = dequeueCausalOrderedBatch(MESSAGE_DB_QUEUE_BATCH_SIZE);
    if (batch.length === 0) break;
    await runMessageDbBatchWithRetries(batch);
  }
}

function scheduleMessageDbFlush(immediate = false): Promise<void> {
  if (immediate || getMsgDbPendingTotal() >= MESSAGE_DB_QUEUE_BATCH_SIZE) {
    if (msgDbFlushTimer) {
      clearTimeout(msgDbFlushTimer);
      msgDbFlushTimer = null;
    }
    if (!msgDbActiveFlushPromise) {
      msgDbActiveFlushPromise = drainMessageDbWriteQueue().finally(() => {
        msgDbActiveFlushPromise = null;
        if (getMsgDbPendingTotal() > 0) {
          scheduleMessageDbFlush(false);
        }
      });
    }
    return msgDbActiveFlushPromise;
  }

  if (!msgDbActiveFlushPromise && !msgDbFlushTimer) {
    msgDbFlushTimer = setTimeout(() => {
      msgDbFlushTimer = null;
      void scheduleMessageDbFlush(true);
    }, MESSAGE_DB_QUEUE_BATCH_WINDOW_MS);
  }
  return msgDbActiveFlushPromise || Promise.resolve();
}

export function enqueueMessageDbWrite<T = any>(opts: {
  priority: MessageDbWritePriority;
  kind: MessageDbWriteKind;
  accountId?: string;
  chatId?: string;
  tgMsgIds?: number[];
  msgId?: string;
  snapshotTakenAt?: number;
  exec: () => Promise<T>;
}): Promise<T> {
  const accountId = String(opts.accountId || 'acc_1').trim() || 'acc_1';
  const accountKey = normalizeMsgDbAccountKey(accountId);
  const canonicalChatId = normalizeMsgDbCanonicalChatId(opts.chatId);
  const tgMsgIds = Array.isArray(opts.tgMsgIds)
    ? opts.tgMsgIds.map((n) => Number(n)).filter((n) => Number.isInteger(n) && n > 0)
    : [];
  const primaryTgId = tgMsgIds.length === 1 ? tgMsgIds[0] : 0;
  const causalKey = primaryTgId
    ? `${accountKey}::${canonicalChatId || 'any'}::tg_${primaryTgId}`
    : opts.msgId
      ? `${accountKey}::${canonicalChatId || 'any'}::id_${opts.msgId}`
      : `${accountKey}::${canonicalChatId || 'any'}::${opts.kind}`;

  // Record delete/clear barriers synchronously upon enqueue so in-flight LOW snapshots are blocked right away
  if (opts.kind === 'delete_channel' || opts.kind === 'delete_non_channel') {
    recordMessageDeleteResurrectionBarrier({
      accountId,
      chatId: opts.kind === 'delete_channel' ? canonicalChatId : '',
      tgMsgIds,
    });
  } else if (opts.kind === 'clear_chat') {
    recordMessageDeleteResurrectionBarrier({
      accountId,
      chatId: canonicalChatId,
      clearChat: true,
    });
  }

  const totalPending = getMsgDbPendingTotal();
  if (totalPending >= MESSAGE_DB_QUEUE_MAX_SIZE) {
    if (opts.priority === 'LOW') {
      messageDbWriteQueueStats.droppedLowTotal += 1;
      return Promise.resolve(false as any);
    }
    if (msgDbLowQueue.length > 0) {
      const dropped = msgDbLowQueue.shift()!;
      messageDbWriteQueueStats.droppedLowTotal += 1;
      dropped.resolve(false as any);
    }
  }

  return new Promise<T>((resolve, reject) => {
    const task: MessageDbWriteTask = {
      seq: ++msgDbQueueSeq,
      priority: opts.priority,
      kind: opts.kind,
      accountId,
      accountKey,
      canonicalChatId,
      tgMsgIds,
      causalKey,
      snapshotTakenAt: opts.snapshotTakenAt,
      enqueuedAt: Date.now(),
      exec: opts.exec,
      resolve,
      reject,
    };

    if (opts.priority === 'HIGH') msgDbHighQueue.push(task);
    else if (opts.priority === 'NORMAL') msgDbNormalQueue.push(task);
    else msgDbLowQueue.push(task);

    messageDbWriteQueueStats.enqueuedTotal += 1;
    const depth = getMsgDbPendingTotal();
    if (depth > messageDbWriteQueueStats.maxQueueDepth) {
      messageDbWriteQueueStats.maxQueueDepth = depth;
    }

    const needImmediate =
      opts.priority === 'HIGH' ||
      depth >= MESSAGE_DB_QUEUE_BATCH_SIZE ||
      depth >= MESSAGE_DB_QUEUE_HIGH_WATER;
    void scheduleMessageDbFlush(needImmediate);
  });
}

export async function flushMessageDbWriteQueue(opts?: { timeoutMs?: number }): Promise<void> {
  const timeoutMs = opts?.timeoutMs ?? 5000;
  const doFlush = async () => {
    while (getMsgDbPendingTotal() > 0 || msgDbActiveFlushPromise) {
      await scheduleMessageDbFlush(true);
      if (getMsgDbPendingTotal() === 0 && !msgDbActiveFlushPromise) break;
    }
  };
  await Promise.race([
    doFlush(),
    new Promise<void>((resolve) => setTimeout(resolve, timeoutMs).unref?.()),
  ]);
}

export async function flushMessageDbWriteQueueForChat(
  accountId?: string,
  chatId?: string,
  opts?: { timeoutMs?: number }
): Promise<void> {
  const accKey = normalizeMsgDbAccountKey(accountId);
  const canonicalChat = normalizeMsgDbCanonicalChatId(chatId);
  const hasMatching = () => {
    for (const q of [msgDbHighQueue, msgDbNormalQueue, msgDbLowQueue]) {
      for (const t of q) {
        if (accountId && t.accountKey !== accKey) continue;
        if (canonicalChat && t.canonicalChatId && t.canonicalChatId !== canonicalChat) continue;
        return true;
      }
    }
    return Boolean(msgDbActiveFlushPromise);
  };
  if (!hasMatching()) return;
  await flushMessageDbWriteQueue({ timeoutMs: opts?.timeoutMs ?? 3000 });
}

export function getMessageDbWriteQueueStats() {
  return {
    pendingHigh: msgDbHighQueue.length,
    pendingNormal: msgDbNormalQueue.length,
    pendingLow: msgDbLowQueue.length,
    pendingTotal: getMsgDbPendingTotal(),
    inFlight: Boolean(msgDbActiveFlushPromise),
    highWater: MESSAGE_DB_QUEUE_HIGH_WATER,
    maxSize: MESSAGE_DB_QUEUE_MAX_SIZE,
    activeDeleteBarriers: recentDeletedTgBarriers.size + recentClearedChatBarriers.size,
    ...messageDbWriteQueueStats,
  };
}

registerPerformanceQueueStatsProvider('messageDbWriteQueue', getMessageDbWriteQueueStats);

async function executeUpsertSyncedMessageToDbInternal(
  msg: UnifiedChatMessage,
  rawMsg: any
): Promise<boolean> {
  try {
    const altChatId = msg.chatId.startsWith('tg_') ? msg.chatId.replace(/^tg_/, '') : `tg_${msg.chatId}`;
    const accVariants = getScopedAccountIdVariants(msg.accountId);
    const accPlaceholders = accVariants.map(() => '?').join(', ');
    const reactionsJson = serializeStoredReactionsJson(rawMsg);
    let existingMatchId: string | null = null;
    if (msg.telegramMessageId) {
      const existingByTg = (await db
        .prepare(
          `SELECT id FROM messages
           WHERE (chat_id = ? OR chat_id = ?) AND account_id IN (${accPlaceholders}) AND telegram_message_id = ?
           LIMIT 1`
        )
        .get(msg.chatId, altChatId, ...accVariants, msg.telegramMessageId)) as any;
      if (existingByTg?.id && existingByTg.id !== msg.id) {
        existingMatchId = existingByTg.id;
      }
    }
    if (!existingMatchId && msg.clientMessageId) {
      const existingByClient = (await db
        .prepare(
          `SELECT id FROM messages
           WHERE account_id IN (${accPlaceholders}) AND client_message_id = ?
           LIMIT 1`
        )
        .get(...accVariants, msg.clientMessageId)) as any;
      if (existingByClient?.id && existingByClient.id !== msg.id) {
        existingMatchId = existingByClient.id;
      }
    }

    if (existingMatchId) {
      const replyToJson = msg.replyTo ? JSON.stringify(msg.replyTo) : null;
      const safeAudioUrl = sanitizeDbMediaUrl(msg.audioUrl);
      const safeImageUrl = sanitizeDbMediaUrl(msg.imageUrl);
      const safeVideoUrl = sanitizeDbMediaUrl(msg.videoUrl);
      const safeFileUrl = sanitizeDbMediaUrl(msg.fileUrl);
      const safeSenderName =
        msg.senderName && !['客户', '对方', '我方', 'Telegram 联系人'].includes(msg.senderName)
          ? msg.senderName
          : '';
      const safeSenderId = msg.senderId || '';
      await db
        .prepare(
          `UPDATE messages SET
             sender = CASE WHEN ? = 'system' THEN 'system' ELSE sender END,
             sender_name = CASE WHEN ? != '' THEN ? ELSE sender_name END,
             sender_id = CASE WHEN ? != '' THEN ? ELSE sender_id END,
             text = CASE WHEN ? != '' THEN ? ELSE text END,
             translated_text = CASE WHEN ? != '' THEN ? ELSE translated_text END,
             stt_text = CASE WHEN ? != '' THEN ? ELSE stt_text END,
             voice_tone = CASE WHEN ? != '' THEN ? ELSE voice_tone END,
             is_audio = CASE WHEN ? = 1 THEN 1 ELSE is_audio END,
             audio_duration = CASE WHEN ? > 0 THEN ? ELSE audio_duration END,
             audio_url = CASE WHEN ? != '' THEN ? ELSE audio_url END,
             is_image = CASE WHEN ? = 1 THEN 1 ELSE is_image END,
             image_caption = CASE WHEN ? != '' THEN ? ELSE image_caption END,
             image_url = CASE WHEN ? != '' THEN ? ELSE image_url END,
             is_video = CASE WHEN ? = 1 THEN 1 ELSE is_video END,
             video_duration = CASE WHEN ? > 0 THEN ? ELSE video_duration END,
             video_url = CASE WHEN ? != '' THEN ? ELSE video_url END,
             is_file = CASE WHEN ? = 1 THEN 1 ELSE is_file END,
             file_name = CASE WHEN ? != '' THEN ? ELSE file_name END,
             file_size = CASE WHEN ? != '' THEN ? ELSE file_size END,
             file_url = CASE WHEN ? != '' THEN ? ELSE file_url END,
             delivery_status = CASE WHEN ? != '' THEN ? ELSE delivery_status END,
             telegram_message_id = COALESCE(?, telegram_message_id),
             client_message_id = COALESCE(NULLIF(?, ''), client_message_id),
             queue_pause_reason = ?,
             flood_wait_until = ?,
             reply_to_json = COALESCE(?, reply_to_json),
             is_edited = CASE WHEN ? = 1 THEN 1 ELSE is_edited END,
             is_pinned = ?,
             forward_from = COALESCE(?, forward_from),
             reactions_json = COALESCE(?, reactions_json),
             system_event_type = CASE WHEN ? != '' THEN ? ELSE system_event_type END
           WHERE id = ?`
        )
        .run(
          msg.sender,
          safeSenderName,
          safeSenderName,
          safeSenderId,
          safeSenderId,
          msg.text,
          msg.text,
          msg.translatedText,
          msg.translatedText,
          msg.sttText,
          msg.sttText,
          msg.voiceTone,
          msg.voiceTone,
          msg.isAudio ? 1 : 0,
          msg.audioDuration,
          msg.audioDuration,
          safeAudioUrl,
          safeAudioUrl,
          msg.isImage ? 1 : 0,
          msg.imageCaption,
          msg.imageCaption,
          safeImageUrl,
          safeImageUrl,
          msg.isVideo ? 1 : 0,
          msg.videoDuration,
          msg.videoDuration,
          safeVideoUrl,
          safeVideoUrl,
          msg.isFile ? 1 : 0,
          msg.fileName,
          msg.fileName,
          msg.fileSize,
          msg.fileSize,
          safeFileUrl,
          safeFileUrl,
          msg.deliveryStatus,
          msg.deliveryStatus,
          msg.telegramMessageId ?? null,
          msg.clientMessageId || '',
          msg.queuePauseReason ?? null,
          msg.floodWaitUntil ?? null,
          replyToJson,
          msg.isEdited ? 1 : 0,
          msg.isPinned ? 1 : 0,
          msg.forwardFrom || null,
          reactionsJson,
          msg.systemEventType || '',
          msg.systemEventType || '',
          existingMatchId
        );
      return true;
    }

    const replyToJson = msg.replyTo ? JSON.stringify(msg.replyTo) : null;
    await db
      .prepare(
        `INSERT INTO messages (
          id, chat_id, account_id, sender, sender_name, sender_id, text, translated_text,
          is_audio, audio_duration, audio_url, stt_text, voice_tone,
          is_image, image_url, image_caption, is_video, video_url, video_duration,
          is_file, file_name, file_size, file_url,
          timestamp, created_at, delivery_status, telegram_message_id,
          client_message_id, queue_pause_reason, flood_wait_until,
          reply_to_json, is_edited, is_pinned, forward_from, reactions_json, system_event_type
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          sender = CASE WHEN excluded.sender = 'system' THEN 'system' ELSE messages.sender END,
          sender_name = CASE WHEN excluded.sender_name != '' AND excluded.sender_name NOT IN ('客户', '对方', '我方', 'Telegram 联系人') THEN excluded.sender_name ELSE messages.sender_name END,
          sender_id = CASE WHEN excluded.sender_id != '' THEN excluded.sender_id ELSE messages.sender_id END,
          text = CASE WHEN excluded.text != '' THEN excluded.text ELSE messages.text END,
          translated_text = CASE WHEN excluded.translated_text != '' THEN excluded.translated_text ELSE messages.translated_text END,
          stt_text = CASE WHEN excluded.stt_text != '' THEN excluded.stt_text ELSE messages.stt_text END,
          voice_tone = CASE WHEN excluded.voice_tone != '' THEN excluded.voice_tone ELSE messages.voice_tone END,
          is_audio = CASE WHEN excluded.is_audio = 1 THEN 1 ELSE messages.is_audio END,
          audio_duration = CASE WHEN excluded.audio_duration > 0 THEN excluded.audio_duration ELSE messages.audio_duration END,
          audio_url = CASE WHEN excluded.audio_url != '' THEN excluded.audio_url ELSE messages.audio_url END,
          is_image = CASE WHEN excluded.is_image = 1 THEN 1 ELSE messages.is_image END,
          image_caption = CASE WHEN excluded.image_caption != '' THEN excluded.image_caption ELSE messages.image_caption END,
          image_url = CASE WHEN excluded.image_url != '' THEN excluded.image_url ELSE messages.image_url END,
          is_video = CASE WHEN excluded.is_video = 1 THEN 1 ELSE messages.is_video END,
          video_duration = CASE WHEN excluded.video_duration > 0 THEN excluded.video_duration ELSE messages.video_duration END,
          video_url = CASE WHEN excluded.video_url != '' THEN excluded.video_url ELSE messages.video_url END,
          is_file = CASE WHEN excluded.is_file = 1 THEN 1 ELSE messages.is_file END,
          file_name = CASE WHEN excluded.file_name != '' THEN excluded.file_name ELSE messages.file_name END,
          file_size = CASE WHEN excluded.file_size != '' THEN excluded.file_size ELSE messages.file_size END,
          file_url = CASE WHEN excluded.file_url != '' THEN excluded.file_url ELSE messages.file_url END,
          delivery_status = CASE WHEN excluded.delivery_status != '' THEN excluded.delivery_status ELSE messages.delivery_status END,
          telegram_message_id = COALESCE(excluded.telegram_message_id, messages.telegram_message_id),
          client_message_id = COALESCE(NULLIF(excluded.client_message_id, ''), messages.client_message_id),
          queue_pause_reason = excluded.queue_pause_reason,
          flood_wait_until = excluded.flood_wait_until,
          reply_to_json = COALESCE(excluded.reply_to_json, messages.reply_to_json),
          is_edited = CASE WHEN excluded.is_edited = 1 THEN 1 ELSE messages.is_edited END,
          is_pinned = excluded.is_pinned,
          forward_from = COALESCE(excluded.forward_from, messages.forward_from),
          reactions_json = COALESCE(excluded.reactions_json, messages.reactions_json),
          system_event_type = CASE WHEN excluded.system_event_type != '' THEN excluded.system_event_type ELSE messages.system_event_type END`
      )
      .run(
        msg.id,
        msg.chatId,
        msg.accountId,
        msg.sender,
        msg.senderName,
        msg.senderId || '',
        msg.text,
        msg.translatedText,
        msg.isAudio ? 1 : 0,
        msg.audioDuration,
        sanitizeDbMediaUrl(msg.audioUrl),
        msg.sttText,
        msg.voiceTone,
        msg.isImage ? 1 : 0,
        sanitizeDbMediaUrl(msg.imageUrl),
        msg.imageCaption,
        msg.isVideo ? 1 : 0,
        sanitizeDbMediaUrl(msg.videoUrl),
        msg.videoDuration,
        msg.isFile ? 1 : 0,
        msg.fileName,
        msg.fileSize,
        sanitizeDbMediaUrl(msg.fileUrl),
        msg.timestamp,
        msg.createdAt,
        msg.deliveryStatus,
        msg.telegramMessageId ?? null,
        msg.clientMessageId || null,
        msg.queuePauseReason ?? null,
        msg.floodWaitUntil ?? null,
        replyToJson,
        msg.isEdited ? 1 : 0,
        msg.isPinned ? 1 : 0,
        msg.forwardFrom || null,
        reactionsJson,
        msg.systemEventType || ''
      );
    return true;
  } catch (err: any) {
    console.warn('[Unified Message Store] Failed to upsert synced message:', err?.message || err);
    return false;
  }
}

export async function upsertSyncedMessageToDb(
  rawMsg: any,
  fallbackChatId = '',
  fallbackAccountId = 'acc_1',
  options?: {
    priority?: MessageDbWritePriority;
    bypassQueue?: boolean;
    snapshotTakenAt?: number;
    source?: string;
  }
): Promise<boolean> {
  const msg = normalizeStoredMessageRecord(rawMsg, fallbackChatId, fallbackAccountId);
  if (!msg) return false;
  if (
    options?.priority === 'LOW' &&
    isMessageBlockedByDeleteBarrier(
      msg.accountId,
      msg.chatId,
      msg.telegramMessageId ?? undefined,
      options?.snapshotTakenAt ?? msg.createdAt
    )
  ) {
    messageDbWriteQueueStats.suppressedResurrectionTotal += 1;
    return false;
  }
  if (options?.bypassQueue) {
    return await executeUpsertSyncedMessageToDbInternal(msg, rawMsg);
  }
  return await enqueueMessageDbWrite({
    priority: options?.priority || 'NORMAL',
    kind: 'upsert',
    accountId: msg.accountId,
    chatId: msg.chatId,
    tgMsgIds: msg.telegramMessageId ? [msg.telegramMessageId] : [],
    msgId: msg.id,
    snapshotTakenAt: options?.snapshotTakenAt,
    exec: async () => {
      if (
        options?.priority === 'LOW' &&
        isMessageBlockedByDeleteBarrier(
          msg.accountId,
          msg.chatId,
          msg.telegramMessageId ?? undefined,
          options?.snapshotTakenAt ?? msg.createdAt
        )
      ) {
        messageDbWriteQueueStats.suppressedResurrectionTotal += 1;
        return false;
      }
      return await executeUpsertSyncedMessageToDbInternal(msg, rawMsg);
    },
  });
}

export function mergeUnifiedConversationMessages(lists: Array<Array<any>>): UnifiedChatMessage[] {
  const merged: UnifiedChatMessage[] = [];
  const byId = new Map<string, number>();
  const byTgKey = new Map<string, number>();

  for (const list of lists) {
    if (!Array.isArray(list)) continue;
    for (const raw of list) {
      const item = normalizeStoredMessageRecord(raw);
      if (!item) continue;
      const canonicalChat = item.chatId.replace(/^tg_/, '');
      const tgKey = item.telegramMessageId ? `${canonicalChat}:${item.telegramMessageId}` : '';

      let matchIdx = byId.get(item.id);
      if (matchIdx === undefined && tgKey) {
        matchIdx = byTgKey.get(tgKey);
      }
      if (matchIdx === undefined) {
        const trimmedText = item.text.trim();
        if (trimmedText) {
          matchIdx = merged.findIndex(
            (m) =>
              m.chatId.replace(/^tg_/, '') === canonicalChat &&
              m.sender === item.sender &&
              m.text.trim() === trimmedText &&
              (m.timestamp === item.timestamp || Math.abs(m.createdAt - item.createdAt) < 120000)
          );
          if (matchIdx === -1) matchIdx = undefined;
        }
      }

      if (matchIdx !== undefined) {
        const prev = merged[matchIdx];
        const combined: UnifiedChatMessage = {
          ...prev,
          ...item,
          id: prev.id || item.id,
          telegramMessageId: item.telegramMessageId || prev.telegramMessageId,
          senderName:
            item.senderName && !['客户', '对方', '我方', 'Telegram 联系人'].includes(item.senderName)
              ? item.senderName
              : prev.senderName,
          senderId: item.senderId || prev.senderId,
          senderAvatarUrl: item.senderAvatarUrl || prev.senderAvatarUrl,
          text: item.text || prev.text,
          translatedText: item.translatedText || prev.translatedText,
          sttText: item.sttText || prev.sttText,
          voiceTone: item.voiceTone || prev.voiceTone,
          audioUrl: item.audioUrl || prev.audioUrl,
          imageUrl: item.imageUrl || prev.imageUrl,
          videoUrl: item.videoUrl || prev.videoUrl,
          isFile: Boolean(item.isFile || prev.isFile),
          fileName: item.fileName || prev.fileName,
          fileSize: item.fileSize || prev.fileSize,
          fileUrl: item.fileUrl || prev.fileUrl,
          reactions: item.reactions || prev.reactions,
          myReactions: item.myReactions || prev.myReactions,
          deliveryStatus: item.deliveryStatus === 'delivered' || prev.deliveryStatus === 'delivered'
            ? 'delivered'
            : (item.deliveryStatus || prev.deliveryStatus),
          createdAt: Math.min(prev.createdAt, item.createdAt),
        };
        merged[matchIdx] = combined;
        byId.set(item.id, matchIdx);
        byId.set(combined.id, matchIdx);
        if (tgKey) byTgKey.set(tgKey, matchIdx);
      } else {
        const idx = merged.length;
        merged.push(item);
        byId.set(item.id, idx);
        if (tgKey) byTgKey.set(tgKey, idx);
      }
    }
  }

  return merged.sort((a, b) => a.createdAt - b.createdAt);
}

export async function resolveUnifiedChatMessages(params: {
  chatId: string;
  accountId?: string;
  clientMessages?: any[];
  limit?: number;
  syncCloud?: boolean;
  persistClientMessages?: boolean;
}): Promise<{
  messages: UnifiedChatMessage[];
  sourcesUsed: { db: number; client: number; cloud: number };
}> {
  const {
    chatId,
    accountId = 'acc_1',
    clientMessages = [],
    limit = 50,
    syncCloud = true,
    persistClientMessages = true,
  } = params;

  const altChatId = chatId.startsWith('tg_') ? chatId.replace(/^tg_/, '') : `tg_${chatId}`;
  const accVariants = getScopedAccountIdVariants(accountId);
  const accPlaceholders = accVariants.map(() => '?').join(', ');

  let dbRows: any[] = [];
  try {
    dbRows = (await db
      .prepare(
        `SELECT
          id, chat_id as chatId, account_id as accountId, sender, sender_name as senderName,
          sender_id as senderId,
          text, translated_text as translatedText, is_audio as isAudio, audio_duration as audioDuration,
          audio_url as audioUrl, stt_text as sttText, voice_tone as voiceTone,
          is_image as isImage, image_url as imageUrl, image_caption as imageCaption,
          is_video as isVideo, video_url as videoUrl, video_duration as videoDuration,
          is_file as isFile, file_name as fileName, file_size as fileSize, file_url as fileUrl,
          timestamp, created_at as createdAt, delivery_status as deliveryStatus,
          telegram_message_id as telegramMessageId,
          client_message_id as clientMessageId,
          queue_pause_reason as queuePauseReason,
          flood_wait_until as floodWaitUntil,
          reply_to_json as replyToJson, is_edited as isEdited, is_pinned as isPinned,
          forward_from as forwardFrom, reactions_json as reactionsJson,
          system_event_type as systemEventType
        FROM (
          SELECT * FROM messages
          WHERE (chat_id = ? OR chat_id = ?) AND account_id IN (${accPlaceholders})
          ORDER BY created_at DESC
          LIMIT ?
        ) ORDER BY created_at ASC`
      )
      .all(chatId, altChatId, ...accVariants, Math.max(1, limit))) as any[];
  } catch (err: any) {
    console.warn('[Unified Chat Resolver] DB query failed:', err?.message || err);
  }

  const normalizedClient = Array.isArray(clientMessages)
    ? clientMessages
        .slice(-limit)
        .map((m) => normalizeStoredMessageRecord(m, chatId, accountId))
        .filter((m): m is UnifiedChatMessage => Boolean(m))
    : [];

  if (persistClientMessages && normalizedClient.length > 0) {
    for (const cm of normalizedClient.slice(-30)) {
      await upsertSyncedMessageToDb(cm, chatId, accountId, { priority: 'LOW', source: 'client_sync' });
    }
  }

  let cloudRows: any[] = [];
  const isTelegramPersonalChat =
    (chatId.startsWith('tg_') || /^-?\d+$/.test(chatId)) && accountId !== 'acc_telegram_bot';
  if (syncCloud && isTelegramPersonalChat) {
    const connected = resolveConnectedTelegramUser(accountId);
    if (connected?.client) {
      try {
        const timeoutPromise = new Promise<any[]>((resolve) => setTimeout(() => resolve([]), 6000));
        cloudRows = await Promise.race([
          syncTelegramUserChatMessages(connected.client, chatId, Math.min(limit, 50), connected.userId),
          timeoutPromise,
        ]);
      } catch (err: any) {
        console.warn(`[Unified Chat Resolver] Cloud sync failed for ${chatId}:`, err?.message || err);
      }
    }
  }

  const unified = mergeUnifiedConversationMessages([dbRows, cloudRows, normalizedClient]);
  return {
    messages: unified.slice(-limit),
    sourcesUsed: {
      db: dbRows.length,
      client: normalizedClient.length,
      cloud: cloudRows.length,
    },
  };
}

export async function resolveUnifiedEvolutionCorpus(params: {
  sampleTexts?: any[];
  clientMessages?: any[];
  accountId?: string;
  limit?: number;
  sinceCreatedAt?: number;
}): Promise<{
  corpusText: string;
  analyzedConversationsCount: number;
  totalMessagesCount: number;
  incrementalMessagesCount: number;
  maxMessageCreatedAt: number;
  corpusHash: string;
}> {
  const { sampleTexts = [], clientMessages = [], accountId, limit = 50, sinceCreatedAt = 0 } = params;
  const cleanAccountId = typeof accountId === 'string' ? accountId.trim() : '';
  const accVariants = cleanAccountId ? getScopedAccountIdVariants(cleanAccountId) : [];

  let dbMsgs: any[] = [];
  try {
    // Strictly forbid cross-account DB sampling when accountId is missing
    if (accVariants.length > 0) {
      const accPlaceholders = accVariants.map(() => '?').join(', ');
      dbMsgs = (await db
        .prepare(
          `SELECT
            id, chat_id as chatId, account_id as accountId, sender, sender_name as senderName,
            text, translated_text as translatedText, stt_text as sttText, timestamp, created_at as createdAt,
            telegram_message_id as telegramMessageId
          FROM messages WHERE account_id IN (${accPlaceholders}) ORDER BY created_at DESC LIMIT ?`
        )
        .all(...accVariants, limit)) as any[];
    }
  } catch {}

  const accVariantSet = new Set(accVariants);
  const filteredClientMessages = Array.isArray(clientMessages)
    ? clientMessages.filter((m) => {
        if (!cleanAccountId) return false;
        const msgAcc = typeof m?.accountId === 'string' ? m.accountId.trim() : '';
        if (!msgAcc) return false;
        return msgAcc === cleanAccountId || accVariantSet.has(msgAcc);
      })
    : [];

  const normalizedClient = filteredClientMessages
    .slice(-limit)
    .map((m) => normalizeStoredMessageRecord(m, m?.chatId || 'client_synced', cleanAccountId))
    .filter((m): m is UnifiedChatMessage => Boolean(m));

  if (normalizedClient.length > 0) {
    for (const cm of normalizedClient.slice(-30)) {
      if (cm.chatId && cm.chatId !== 'client_synced') {
        await upsertSyncedMessageToDb(cm, cm.chatId, cm.accountId, { priority: 'LOW', source: 'evolution_sync' });
      }
    }
  }

  let cloudMsgs: any[] = [];
  if (cleanAccountId && dbMsgs.length + normalizedClient.length < 6 && connectedUserClients.size > 0) {
    const connected = resolveConnectedTelegramUser(cleanAccountId);
    if (connected?.client) {
      try {
        let dialogIds: string[] = Array.isArray(connected.dialogs)
          ? connected.dialogs.map((d: any) => String(d?.rawId || String(d?.id || '').replace(/^tg_/, ''))).filter(Boolean)
          : [];
        if (
          dialogIds.length === 0 &&
          !getTelegramFloodCooldown({ accountId: cleanAccountId, userId: connected.userId, phone: connected.phone })
        ) {
          const fetched = await Promise.race([
            getOrFetchConnectedAccountDialogs(connected, { limit: 12 }).then((r) => r.dialogs),
            new Promise<any[]>((resolve) => setTimeout(() => resolve([]), 5000)),
          ]);
          dialogIds = (Array.isArray(fetched) ? fetched : [])
            .map((d: any) => String(d?.rawId || String(d?.id || '').replace(/^tg_/, '')))
            .filter(Boolean);
        }
        const targetDialogIds = dialogIds
          .filter((idStr) => idStr && idStr !== '777000' && idStr !== '42777' && idStr !== String(connected.userId))
          .slice(0, 4);
        for (const idStr of targetDialogIds) {
          const synced = await syncTelegramUserChatMessages(connected.client, `tg_${idStr}`, 12, connected.userId);
          if (synced.length > 0) {
            cloudMsgs.push(...synced);
          }
        }
      } catch (err: any) {
        recordTelegramFloodWait(
          { accountId: cleanAccountId, userId: connected.userId, phone: connected.phone },
          err,
          'messages.GetDialogs'
        );
        console.warn('[Unified Evolution Corpus] Cloud dialog fetch non-fatal:', err?.message || err);
      }
    }
  }

  const merged = mergeUnifiedConversationMessages([dbMsgs, cloudMsgs, normalizedClient]);
  const distinctChatIds = new Set<string>();
  const allDialogueLines: string[] = [];
  const incrementalChatIds = new Set<string>();
  const incrementalDialogueLines: string[] = [];
  let maxMessageCreatedAt = Number(sinceCreatedAt) || 0;

  for (const m of merged) {
    const rawText = String(m.sttText || m.text || '').trim();
    if (!rawText || /^\[(语音|图片|视频|多媒体)消息\]$|^Voice Message$/i.test(rawText)) continue;
    const msgTs = Number(m.createdAt || 0);
    if (msgTs > maxMessageCreatedAt) {
      maxMessageCreatedAt = msgTs;
    }
    const line = `${m.sender === 'peer' ? '客户' : '我方'}: ${rawText}`;
    if (m.chatId) distinctChatIds.add(m.chatId);
    allDialogueLines.push(line);

    if (!sinceCreatedAt || msgTs === 0 || msgTs > sinceCreatedAt) {
      if (m.chatId) incrementalChatIds.add(m.chatId);
      incrementalDialogueLines.push(line);
    }
  }

  const validSampleTexts = Array.isArray(sampleTexts)
    ? sampleTexts.map((t: any) => String(t || '').trim()).filter(Boolean)
    : [];

  const chosenLines = sinceCreatedAt > 0 ? incrementalDialogueLines : allDialogueLines;
  const corpusText = [...chosenLines, ...validSampleTexts].join('\n').trim();
  const analyzedConversationsCount =
    (sinceCreatedAt > 0 ? incrementalChatIds.size : distinctChatIds.size) +
    (validSampleTexts.length > 0 ? 1 : 0);
  const corpusHash = corpusText ? sha256Hex(normalizeKnowledgeTextForHash(corpusText)) : '';

  return {
    corpusText,
    analyzedConversationsCount,
    totalMessagesCount: allDialogueLines.length,
    incrementalMessagesCount: incrementalDialogueLines.length,
    maxMessageCreatedAt,
    corpusHash,
  };
}

// 1.3 Fetch Chats List for active tenant/account
app.get('/api/chats', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    const effectiveAccountId = authContext?.effectiveAccountId || 'acc_1';
    const accVariants = getScopedAccountIdVariants(effectiveAccountId);
    const accPlaceholders = accVariants.map(() => '?').join(', ');

    // Query account-isolated profiles first, then merge legacy customer_profiles rows
    const [scopedRows, legacyRows] = await Promise.all([
      db.prepare(`
        SELECT chat_id, account_id, client_name, relationship_stage, total_messages_count, updated_at
        FROM account_customer_profiles
        WHERE account_id IN (${accPlaceholders})
        ORDER BY updated_at DESC
      `).all(...accVariants) as Promise<any[]>,
      db.prepare(`
        SELECT chat_id, account_id, client_name, relationship_stage, total_messages_count, updated_at
        FROM customer_profiles
        WHERE account_id IN (${accPlaceholders})
        ORDER BY updated_at DESC
      `).all(...accVariants) as Promise<any[]>,
    ]);

    const mergedProfilesMap = new Map<string, any>();
    for (const row of legacyRows || []) {
      const canonChatId = canonicalizeCustomerChatId(row.chat_id) || row.chat_id;
      const key = `${row.account_id}::${canonChatId}`;
      mergedProfilesMap.set(key, { ...row, chat_id: canonChatId });
    }
    for (const row of scopedRows || []) {
      const canonChatId = canonicalizeCustomerChatId(row.chat_id) || row.chat_id;
      const key = `${row.account_id}::${canonChatId}`;
      mergedProfilesMap.set(key, { ...row, chat_id: canonChatId });
    }
    const profiles = Array.from(mergedProfilesMap.values()).sort(
      (a, b) => Number(b?.updated_at || 0) - Number(a?.updated_at || 0)
    );

    // Load persisted per-chat language preferences scoped to this account
    const langPrefsMap = new Map<string, { sourceLang: string; targetLang: string; translationEnabled?: boolean }>();
    try {
      const langRows = (await db.prepare(`
        SELECT account_id, chat_id, source_lang, target_lang, translation_enabled
        FROM chat_language_prefs
        WHERE account_id IN (${accPlaceholders})
           OR (account_id = 'acc_telegram_bot' AND ? IN ('acc_telegram_bot', 'acc_1'))
      `).all(...accVariants, effectiveAccountId)) as any[];
      for (const lr of langRows || []) {
        const parsedEnabled =
          lr.translation_enabled === 1 || lr.translation_enabled === true
            ? true
            : lr.translation_enabled === 0 || lr.translation_enabled === false
              ? false
              : undefined;
        const scKey = `${lr.account_id}::${lr.chat_id}`;
        langPrefsMap.set(scKey, {
          sourceLang: lr.source_lang || 'Auto',
          targetLang: lr.target_lang || 'Auto',
          ...(parsedEnabled !== undefined ? { translationEnabled: parsedEnabled } : {}),
        });
        if (!langPrefsMap.has(lr.chat_id)) {
          langPrefsMap.set(lr.chat_id, {
            sourceLang: lr.source_lang || 'Auto',
            targetLang: lr.target_lang || 'Auto',
            ...(parsedEnabled !== undefined ? { translationEnabled: parsedEnabled } : {}),
          });
        }
      }
    } catch {}

    // Retrieve latest message for each chat strictly scoped to this account
    const chatsData = await Promise.all(
      profiles.map(async (p: any) => {
        const lastMsg = (await db.prepare(`
          SELECT text, translated_text, is_audio, timestamp, created_at, sender
          FROM messages
          WHERE chat_id = ? AND account_id = ?
          ORDER BY created_at DESC
          LIMIT 1
        `).get(p.chat_id, p.account_id)) as any;

        const isTgOfficial = p.chat_id.startsWith('tg_');
        const langPref = langPrefsMap.get(`${p.account_id}::${p.chat_id}`) || langPrefsMap.get(p.chat_id);
        return {
          id: p.chat_id,
          accountId: p.account_id,
          title: p.client_name || (isTgOfficial ? `Telegram 用户 (${p.chat_id.replace('tg_', '')})` : p.chat_id),
          avatarBg: isTgOfficial ? '#2481cc' : '#ec4899',
          avatarInitial: (p.client_name || 'TG').slice(0, 2).toUpperCase(),
          isGroup: false,
          isVerified: isTgOfficial,
          lastMessage: lastMsg?.is_audio ? '🎤 语音消息' : (lastMsg?.translated_text || lastMsg?.text || '暂无消息'),
          lastTime: lastMsg?.timestamp || '刚刚',
          ...(typeof lastMsg?.created_at === 'number' && lastMsg.created_at > 0
            ? { lastDate: Math.floor(lastMsg.created_at / 1000) }
            : {}),
          unreadCount: 0,
          sourceLang: langPref?.sourceLang || 'Auto',
          targetLang: langPref?.targetLang || 'Auto',
          ...(typeof langPref?.translationEnabled === 'boolean' ? { translationEnabled: langPref.translationEnabled } : {}),
          aiEnabled: true,
          aiMode: 'adaptive',
          typingDelayMin: 2,
          typingDelayMax: 5,
        };
      })
    );

    res.json(chatsData);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 1.4 Persist per-chat translation language preferences scoped to account + chatId
app.post('/api/chats/:chatId/language', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const { chatId } = req.params;
    const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
    }
    const effectiveAccountId = scope.accountId;
    const sourceLang = typeof req.body?.sourceLang === 'string' && req.body.sourceLang.trim()
      ? req.body.sourceLang.trim()
      : 'Auto';
    const targetLang = typeof req.body?.targetLang === 'string' && req.body.targetLang.trim()
      ? req.body.targetLang.trim()
      : 'Auto';
    const hasExplicitTranslationEnabled = 'translationEnabled' in (req.body || {});
    const translationEnabledParam: number | null | undefined = hasExplicitTranslationEnabled
      ? req.body?.translationEnabled === true
        ? 1
        : req.body?.translationEnabled === false
          ? 0
          : null
      : undefined;
    if (!chatId || !chatId.trim()) {
      return res.status(400).json({ ok: false, error: '缺少有效的会话 chatId' });
    }
    const now = Date.now();
    if (hasExplicitTranslationEnabled) {
      await db.prepare(`
        INSERT INTO chat_language_prefs (account_id, chat_id, source_lang, target_lang, translation_enabled, updated_at)
        VALUES (?, ?, ?, ?, ?, ?)
        ON CONFLICT(account_id, chat_id) DO UPDATE SET
          source_lang = excluded.source_lang,
          target_lang = excluded.target_lang,
          translation_enabled = excluded.translation_enabled,
          updated_at = excluded.updated_at
      `).run(effectiveAccountId, chatId.trim(), sourceLang, targetLang, translationEnabledParam ?? null, now);
    } else {
      await db.prepare(`
        INSERT INTO chat_language_prefs (account_id, chat_id, source_lang, target_lang, updated_at)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(account_id, chat_id) DO UPDATE SET
          source_lang = excluded.source_lang,
          target_lang = excluded.target_lang,
          updated_at = excluded.updated_at
      `).run(effectiveAccountId, chatId.trim(), sourceLang, targetLang, now);
    }

    res.json({
      ok: true,
      accountId: effectiveAccountId,
      chatId: chatId.trim(),
      sourceLang,
      targetLang,
      ...(hasExplicitTranslationEnabled ? { translationEnabled: req.body?.translationEnabled } : {}),
      updatedAt: now,
    });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err?.message || '保存会话语言配置失败' });
  }
});

// 2. Fetch Chat Messages from Database (Strict Tenant Filter)
app.get('/api/messages/:chatId', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const { chatId } = req.params;
    const authContext = (req as any).auth;
    const effectiveAccountId = authContext?.effectiveAccountId || 'acc_1';
    const isMaster = authContext?.session?.isMaster;

    const accVariants = getScopedAccountIdVariants(effectiveAccountId);
    const includeBotFallback = effectiveAccountId === 'acc_telegram_bot';
    if (includeBotFallback && !accVariants.includes('acc_telegram_bot')) {
      accVariants.push('acc_telegram_bot');
    }

    // Verify whether this chat belongs to effectiveAccountId
    const scopedProfile = await getScopedCustomerProfile(chatId, effectiveAccountId);
    if (!scopedProfile && !isMaster) {
      const canonChatId = canonicalizeCustomerChatId(chatId);
      const altId = canonChatId.startsWith('tg_') ? canonChatId.replace(/^tg_/, '') : `tg_${canonChatId}`;
      const chatCandidates = Array.from(new Set([canonChatId, altId, String(chatId || '').trim()].filter(Boolean)));
      const chatPh = chatCandidates.map(() => '?').join(', ');
      const foreignProfile =
        ((await db
          .prepare(`SELECT account_id FROM account_customer_profiles WHERE chat_id IN (${chatPh}) LIMIT 1`)
          .get(...chatCandidates)) as any) ||
        ((await db
          .prepare(`SELECT account_id FROM customer_profiles WHERE chat_id IN (${chatPh}) LIMIT 1`)
          .get(...chatCandidates)) as any);
      if (foreignProfile && !accVariants.includes(foreignProfile.account_id)) {
        return res.status(403).json({ error: '无权查看不属于当前账号的聊天记录' });
      }
    }

    const altChatId = chatId.startsWith('tg_') ? chatId.replace(/^tg_/, '') : `tg_${chatId}`;
    const accPlaceholders = accVariants.map(() => '?').join(', ');
    const rawLimit = Number(req.query.limit);
    const rawBeforeCreatedAt = Number(req.query.beforeCreatedAt);
    const hasPagination =
      (Number.isFinite(rawLimit) && rawLimit > 0) ||
      (Number.isFinite(rawBeforeCreatedAt) && rawBeforeCreatedAt > 0);
    const safeLimit = Number.isFinite(rawLimit) && rawLimit > 0 ? Math.min(200, Math.floor(rawLimit)) : 100;

    let rows: any[] = [];
    if (hasPagination) {
      const beforeClause =
        Number.isFinite(rawBeforeCreatedAt) && rawBeforeCreatedAt > 0 ? 'AND created_at < ?' : '';
      const queryArgs: any[] = [chatId, altChatId, ...accVariants];
      if (beforeClause) queryArgs.push(Math.floor(rawBeforeCreatedAt));
      queryArgs.push(safeLimit);

      const descRows = (await db.prepare(`
        SELECT 
          id, chat_id as chatId, account_id as accountId, sender, sender_name as senderName,
          sender_id as senderId,
          text, translated_text as translatedText, is_audio as isAudio, audio_duration as audioDuration,
          audio_url as audioUrl, stt_text as sttText, voice_tone as voiceTone,
          is_image as isImage, image_url as imageUrl, image_caption as imageCaption,
          is_video as isVideo, video_url as videoUrl, video_duration as videoDuration,
          is_file as isFile, file_name as fileName, file_size as fileSize, file_url as fileUrl,
          timestamp, created_at as createdAt, delivery_status as deliveryStatus,
          telegram_message_id as telegramMessageId,
          client_message_id as clientMessageId,
          queue_pause_reason as queuePauseReason,
          flood_wait_until as floodWaitUntil,
          reply_to_json as replyToJson,
          is_edited as isEdited,
          is_pinned as isPinned,
          forward_from as forwardFrom,
          reactions_json as reactionsJson,
          system_event_type as systemEventType
        FROM messages
        WHERE (chat_id = ? OR chat_id = ?) AND account_id IN (${accPlaceholders}) ${beforeClause}
        ORDER BY created_at DESC
        LIMIT ?
      `).all(...queryArgs)) as any[];
      rows = descRows.reverse();
    } else {
      rows = (await db.prepare(`
        SELECT 
          id, chat_id as chatId, account_id as accountId, sender, sender_name as senderName,
          sender_id as senderId,
          text, translated_text as translatedText, is_audio as isAudio, audio_duration as audioDuration,
          audio_url as audioUrl, stt_text as sttText, voice_tone as voiceTone,
          is_image as isImage, image_url as imageUrl, image_caption as imageCaption,
          is_video as isVideo, video_url as videoUrl, video_duration as videoDuration,
          is_file as isFile, file_name as fileName, file_size as fileSize, file_url as fileUrl,
          timestamp, created_at as createdAt, delivery_status as deliveryStatus,
          telegram_message_id as telegramMessageId,
          client_message_id as clientMessageId,
          queue_pause_reason as queuePauseReason,
          flood_wait_until as floodWaitUntil,
          reply_to_json as replyToJson,
          is_edited as isEdited,
          is_pinned as isPinned,
          forward_from as forwardFrom,
          reactions_json as reactionsJson,
          system_event_type as systemEventType
        FROM messages
        WHERE (chat_id = ? OR chat_id = ?) AND account_id IN (${accPlaceholders})
        ORDER BY created_at ASC
      `).all(chatId, altChatId, ...accVariants)) as any[];
    }

    const resignStoredMediaUrl = (rawUrl?: string, msgAcc?: string) => {
      if (!rawUrl || typeof rawUrl !== 'string') return rawUrl;
      if (rawUrl.startsWith('/api/messages/local-media/')) {
        return resignTelegramResourceUrl(rawUrl, msgAcc || effectiveAccountId) || rawUrl;
      }
      if (isSignedResourceUrlExpiring(rawUrl)) {
        return resignTelegramResourceUrl(rawUrl, msgAcc || effectiveAccountId) || rawUrl;
      }
      return rawUrl;
    };

    const formatted = rows.map((r: any) => {
      const { replyToJson, reactionsJson, ...rest } = r;
      const replyTo = replyToJson ? safeJsonParse(replyToJson, undefined) : undefined;
      const parsedReactions = parseStoredReactionsJson(reactionsJson);
      const cleanSenderId = r.senderId ? String(r.senderId).trim() : '';
      const senderAvatarUrl =
        r.sender !== 'me' && cleanSenderId && r.accountId && r.accountId !== 'acc_telegram_bot'
          ? signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(cleanSenderId)}`, r.accountId)
          : undefined;
      const senderRole: 'me' | 'peer' | 'system' =
        r.sender === 'me' ? 'me' : r.sender === 'system' ? 'system' : 'peer';
      return {
        ...rest,
        ...(cleanSenderId ? { senderId: cleanSenderId } : {}),
        ...(senderAvatarUrl ? { senderAvatarUrl } : {}),
        audioUrl: resignStoredMediaUrl(r.audioUrl, r.accountId),
        imageUrl: resignStoredMediaUrl(r.imageUrl, r.accountId),
        videoUrl: resignStoredMediaUrl(r.videoUrl, r.accountId),
        fileUrl: resignStoredMediaUrl(r.fileUrl, r.accountId),
        isAudio: Boolean(r.isAudio),
        isImage: Boolean(r.isImage),
        isVideo: Boolean(r.isVideo),
        isFile: Boolean(r.isFile),
        isEdited: Boolean(r.isEdited),
        isPinned: Boolean(r.isPinned),
        ...(replyTo ? { replyTo } : {}),
        ...(parsedReactions.reactions ? { reactions: parsedReactions.reactions } : {}),
        ...(parsedReactions.myReactions ? { myReactions: parsedReactions.myReactions } : {}),
        ...(r.forwardFrom ? { forwardFrom: r.forwardFrom } : {}),
        deliveryStatus: r.deliveryStatus || 'delivered',
        ...inferCallMetadataFromStoredRecord(r, senderRole),
        ...(r.systemEventType ? { systemEventType: r.systemEventType } : {}),
      };
    });

    // If local messages are empty, attempt real-time cloud sync from connected MTProto client
    if (formatted.length === 0) {
      const personalAccount = effectiveAccountId
        ? connectedUserClients.get(effectiveAccountId) ||
          Array.from(connectedUserClients.values()).find(
            (u) => u.userId === effectiveAccountId || u.phone === effectiveAccountId || `acc_tg_${u.userId}` === effectiveAccountId
          )
        : null;

      if (personalAccount && personalAccount.client) {
        try {
          const cloudMessages = await syncTelegramUserChatMessages(personalAccount.client, chatId, 30, personalAccount.userId);
          if (cloudMessages && cloudMessages.length > 0) {
            return res.json(cloudMessages);
          }
        } catch (e: any) {
          if (isTelegramSessionExpiredError(e)) {
            await markTelegramSessionExpired({
              accountId: effectiveAccountId,
              userId: personalAccount.userId,
              phone: personalAccount.phone,
              reason: formatTelegramError(e),
            });
            return res.status(401).json({
              ok: false,
              code: 'TELEGRAM_SESSION_EXPIRED',
              error: 'Telegram 登录会话已失效，请重新扫码或验证码登录',
            });
          }
          console.warn(`[Auto-Sync Cloud Messages Failed] chat ${chatId}:`, e.message);
        }
      }
    }

    res.json(formatted);
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// Serve disk-backed outbound media with HTTP Range streaming (zero RAM buffering)
app.get('/api/messages/local-media/:fileKey', async (req: Request, res: Response) => {
  try {
    if (!isAllowedClientOrigin(req)) {
      return res.status(403).send('Forbidden');
    }
    if (!verifySignedTelegramResourceRequest(req) && !(req as any).auth) {
      return res.status(401).send('Unauthorized');
    }

    const fileKey = String(req.params.fileKey || '').trim();
    const diskPath = resolveLocalMediaDiskPath(`/api/messages/local-media/${encodeURIComponent(fileKey)}`);
    if (!diskPath) {
      return res.status(404).send('Media not found');
    }

    const stat = await fs.promises.stat(diskPath);
    const total = stat.size;
    const mime = inferMediaMimeFromExt(diskPath);
    const isScriptableMime = isScriptableActiveMediaMime(mime);
    res.setHeader('Content-Type', mime);
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Content-Security-Policy', "default-src 'none'; sandbox");
    res.setHeader('Accept-Ranges', 'bytes');
    res.setHeader('Cache-Control', 'private, max-age=1800');
    if (isScriptableMime || req.query.download === '1' || req.query.download === 'true') {
      res.setHeader('Content-Disposition', `attachment; filename*=UTF-8''${encodeURIComponent(path.basename(diskPath))}`);
    }

    const rangeHeader = req.headers.range;
    if (rangeHeader && /^bytes=/i.test(rangeHeader)) {
      const match = rangeHeader.replace(/bytes=/i, '').split('-');
      const start = match[0] ? parseInt(match[0], 10) : 0;
      const end = match[1] ? Math.min(parseInt(match[1], 10), total - 1) : total - 1;
      if (!Number.isNaN(start) && !Number.isNaN(end) && start >= 0 && start <= end && start < total) {
        res.status(206);
        res.setHeader('Content-Range', `bytes ${start}-${end}/${total}`);
        res.setHeader('Content-Length', String(end - start + 1));
        const stream = fs.createReadStream(diskPath, { start, end });
        stream.on('error', () => {
          if (!res.headersSent) res.status(500).end();
          else res.destroy();
        });
        return stream.pipe(res);
      }
    }

    res.setHeader('Content-Length', String(total));
    const stream = fs.createReadStream(diskPath);
    stream.on('error', () => {
      if (!res.headersSent) res.status(500).end();
      else res.destroy();
    });
    return stream.pipe(res);
  } catch {
    return res.status(404).send('Media not found');
  }
});

const OUTBOUND_MEDIA_MAX_FETCH_BYTES = Math.min(TELEGRAM_MAX_MEDIA, 64 * 1024 * 1024);
const OUTBOUND_MEDIA_FETCH_TIMEOUT_MS = 15000;
const OUTBOUND_MEDIA_MAX_CONCURRENT_FETCHES = 4;

let activeOutboundMediaFetches = 0;
const outboundMediaFetchWaiters: Array<() => void> = [];

async function acquireOutboundMediaFetchSlot(): Promise<() => void> {
  if (activeOutboundMediaFetches >= OUTBOUND_MEDIA_MAX_CONCURRENT_FETCHES) {
    await new Promise<void>((resolve) => {
      outboundMediaFetchWaiters.push(resolve);
    });
  }
  activeOutboundMediaFetches += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    activeOutboundMediaFetches = Math.max(0, activeOutboundMediaFetches - 1);
    const next = outboundMediaFetchWaiters.shift();
    if (next) next();
  };
}

export interface OutboundMediaDnsAddress {
  address: string;
  family: number;
}

export interface OutboundMediaFetchOptions {
  timeoutMs?: number;
  maxBytes?: number;
  dnsLookup?: (hostname: string) => Promise<OutboundMediaDnsAddress[]>;
  allowHttpInProduction?: boolean;
  requestImpl?: (
    options: http.RequestOptions,
    callback?: (res: http.IncomingMessage) => void
  ) => http.ClientRequest;
}

function defaultOutboundDnsLookup(hostname: string): Promise<OutboundMediaDnsAddress[]> {
  return dns.lookup(hostname, { all: true }).then((results) =>
    results.map((r) => ({ address: r.address, family: r.family }))
  );
}

export async function validateOutboundMediaRemoteUrl(
  rawUrl: string,
  options?: {
    dnsLookup?: (hostname: string) => Promise<OutboundMediaDnsAddress[]>;
    allowHttpInProduction?: boolean;
  }
): Promise<{ parsedUrl: URL; pinnedAddress: OutboundMediaDnsAddress }> {
  let parsedUrl: URL;
  try {
    parsedUrl = new URL(rawUrl.trim());
  } catch {
    throw new Error('SSRF 安全拦截：无效的媒体 URL');
  }

  if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
    throw new Error(`SSRF 安全拦截：出站媒体仅允许 http/https 协议 (拒绝 ${parsedUrl.protocol})`);
  }
  if (isProduction && !options?.allowHttpInProduction && parsedUrl.protocol !== 'https:') {
    throw new Error(`SSRF 安全拦截：生产环境下出站媒体仅允许安全的 https:// 地址 (拒绝 ${parsedUrl.protocol})`);
  }
  if (parsedUrl.username || parsedUrl.password) {
    throw new Error('SSRF 安全拦截：禁止在媒体 URL 中携带认证凭据');
  }

  let hostname = parsedUrl.hostname.trim().toLowerCase().replace(/\.+$/, '');
  if (hostname.startsWith('[') && hostname.endsWith(']')) {
    hostname = hostname.slice(1, -1);
  }
  if (!hostname) {
    throw new Error('SSRF 安全拦截：媒体 URL 缺少有效主机名');
  }
  if (isAllowedLocalhostEndpoint(hostname) || hostname.endsWith('.localhost')) {
    throw new Error(`SSRF 安全拦截：禁止出站媒体请求访问本机回环地址 (${hostname})`);
  }

  const ipLiteralFamily = net.isIP(hostname);
  if (ipLiteralFamily) {
    if (isPrivateOrReservedIp(hostname)) {
      throw new Error(`SSRF 安全拦截：禁止出站媒体访问内网、回环或保留 IP 地址 (${hostname})`);
    }
    return {
      parsedUrl,
      pinnedAddress: { address: hostname, family: ipLiteralFamily },
    };
  }

  // Also guard non-canonical integer/hex/octal host strings that net.isIP doesn't recognize as standard dotted-quad
  if (/^(0x[0-9a-f]+|0[0-7]+|\d+)$/i.test(hostname)) {
    throw new Error(`SSRF 安全拦截：禁止非常规数字编码 IP 主机名 (${hostname})`);
  }

  const resolver = options?.dnsLookup || defaultOutboundDnsLookup;
  let resolvedAddrs: OutboundMediaDnsAddress[];
  try {
    resolvedAddrs = await resolver(hostname);
  } catch (err: any) {
    throw new Error(`SSRF 安全拦截：媒体域名解析失败 (${hostname}): ${err?.message || err}`);
  }

  if (!Array.isArray(resolvedAddrs) || resolvedAddrs.length === 0) {
    throw new Error(`SSRF 安全拦截：媒体域名未返回有效 IP (${hostname})`);
  }

  for (const addr of resolvedAddrs) {
    if (!addr?.address || isPrivateOrReservedIp(addr.address)) {
      throw new Error(`SSRF 安全拦截：禁止访问内网或非公网 IP 地址 (${hostname} -> ${addr?.address || 'unknown'})`);
    }
  }

  const primary = resolvedAddrs[0];
  const detectedFamily = net.isIP(primary.address) || (primary.family === 6 ? 6 : 4);
  return {
    parsedUrl,
    pinnedAddress: {
      address: primary.address,
      family: detectedFamily === 6 ? 6 : 4,
    },
  };
}

export async function safeOutboundMediaFetch(
  mediaUrl: string,
  options?: OutboundMediaFetchOptions
): Promise<Buffer> {
  const timeoutMs = Math.max(500, options?.timeoutMs ?? OUTBOUND_MEDIA_FETCH_TIMEOUT_MS);
  const maxBytes = Math.max(1, options?.maxBytes ?? OUTBOUND_MEDIA_MAX_FETCH_BYTES);

  const { parsedUrl, pinnedAddress } = await validateOutboundMediaRemoteUrl(mediaUrl, {
    dnsLookup: options?.dnsLookup,
    allowHttpInProduction: options?.allowHttpInProduction,
  });

  const releaseSlot = await acquireOutboundMediaFetchSlot();
  try {
    const rawHost = parsedUrl.hostname.trim();
    const cleanConnectHost =
      rawHost.startsWith('[') && rawHost.endsWith(']') ? rawHost.slice(1, -1) : rawHost;
    const tlsServername = net.isIP(cleanConnectHost) ? undefined : cleanConnectHost;

    const proxy = getConfiguredTelegramProxy();
    if (proxy) {
      // Tunnel through SOCKS using the already-validated pinned IP (prevents proxy-side DNS rebinding)
      const targetPort = parsedUrl.port
        ? Number(parsedUrl.port)
        : parsedUrl.protocol === 'https:'
          ? 443
          : 80;
      const isHttps = parsedUrl.protocol === 'https:';
      const { socket: rawSocket } = await SocksClient.createConnection({
        proxy: {
          host: proxy.ip,
          port: proxy.port,
          type: proxy.socksType,
          ...(proxy.username ? { userId: proxy.username } : {}),
          ...(proxy.password ? { password: proxy.password } : {}),
        },
        command: 'connect',
        destination: {
          host: pinnedAddress.address,
          port: targetPort,
        },
        timeout: timeoutMs,
      });

      return await new Promise<Buffer>((resolve, reject) => {
        let settled = false;
        let activeSocket: net.Socket | tls.TLSSocket = rawSocket;
        const finishError = (err: Error) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          try { activeSocket.destroy(); } catch {}
          try { rawSocket.destroy(); } catch {}
          reject(err);
        };
        const timer = setTimeout(() => {
          finishError(new Error(`拉取媒体资源超时 (${timeoutMs}ms)`));
        }, timeoutMs);

        const mod = isHttps ? https : http;
        const proxyAgent = new (isHttps ? https.Agent : http.Agent)({ keepAlive: false });
        (proxyAgent as any).createConnection = () => {
          activeSocket = isHttps
            ? tls.connect({
                socket: rawSocket,
                ...(tlsServername ? { servername: tlsServername } : {}),
              })
            : rawSocket;
          return activeSocket;
        };
        const req = mod.request(
          {
            hostname: cleanConnectHost,
            port: targetPort,
            path: `${parsedUrl.pathname}${parsedUrl.search}`,
            method: 'GET',
            headers: {
              Host: parsedUrl.host,
              Connection: 'close',
            },
            agent: proxyAgent,
          },
          (res) => {
            const status = Number(res.statusCode || 0);
            if (status >= 300 && status < 400) {
              res.resume();
              return finishError(new Error(`SSRF 安全拦截：禁止未经校验的 HTTP 重定向 (HTTP ${status})`));
            }
            if (status < 200 || status >= 300) {
              res.resume();
              return finishError(new Error(`拉取媒体资源失败 (HTTP ${status})`));
            }
            const contentLength = Number(res.headers['content-length'] || 0);
            if (Number.isFinite(contentLength) && contentLength > maxBytes) {
              res.destroy();
              return finishError(new Error(`媒体资源体积超过最大限制 (${maxBytes} bytes)`));
            }
            const chunks: Buffer[] = [];
            let total = 0;
            res.on('data', (chunk: Buffer) => {
              const bufChunk = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
              total += bufChunk.length;
              if (total > maxBytes) {
                res.destroy();
                finishError(new Error(`媒体资源体积超过最大限制 (${maxBytes} bytes)`));
                return;
              }
              chunks.push(bufChunk);
            });
            res.on('end', () => {
              if (settled) return;
              settled = true;
              clearTimeout(timer);
              resolve(Buffer.concat(chunks, total));
            });
            res.on('error', (err) => finishError(err));
          }
        );
        req.on('error', (err) => finishError(err));
        req.end();
      });
    }

    // Direct pinned-IP HTTP/HTTPS request (immune to DNS Rebinding; lookup never queries DNS again)
    const isHttps = parsedUrl.protocol === 'https:';
    const targetPort = parsedUrl.port ? Number(parsedUrl.port) : isHttps ? 443 : 80;
    const pinnedLookup = (
      _hostname: string,
      opts: any,
      callback: (...args: any[]) => void
    ) => {
      if (typeof opts === 'function') {
        return opts(null, pinnedAddress.address, pinnedAddress.family);
      }
      if (opts && opts.all) {
        return callback(null, [{ address: pinnedAddress.address, family: pinnedAddress.family }]);
      }
      return callback(null, pinnedAddress.address, pinnedAddress.family);
    };

    return await new Promise<Buffer>((resolve, reject) => {
      let settled = false;
      const reqFn = options?.requestImpl || (isHttps ? https.request : http.request);
      let reqRef: http.ClientRequest | null = null;
      const finishError = (err: Error) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        try { reqRef?.destroy(); } catch {}
        reject(err);
      };
      const timer = setTimeout(() => {
        finishError(new Error(`拉取媒体资源超时 (${timeoutMs}ms)`));
      }, timeoutMs);

      reqRef = reqFn(
        {
          hostname: cleanConnectHost,
          port: targetPort,
          path: `${parsedUrl.pathname}${parsedUrl.search}`,
          method: 'GET',
          headers: {
            Host: parsedUrl.host,
            Connection: 'close',
          },
          lookup: pinnedLookup as any,
          ...(isHttps && tlsServername ? { servername: tlsServername } : {}),
          agent: false,
        } as any,
        (res) => {
          const status = Number(res.statusCode || 0);
          if (status >= 300 && status < 400) {
            res.resume();
            return finishError(new Error(`SSRF 安全拦截：禁止未经校验的 HTTP 重定向 (HTTP ${status})`));
          }
          if (status < 200 || status >= 300) {
            res.resume();
            return finishError(new Error(`拉取媒体资源失败 (HTTP ${status})`));
          }
          const contentLength = Number(res.headers['content-length'] || 0);
          if (Number.isFinite(contentLength) && contentLength > maxBytes) {
            res.destroy();
            return finishError(new Error(`媒体资源体积超过最大限制 (${maxBytes} bytes)`));
          }

          const chunks: Buffer[] = [];
          let total = 0;
          res.on('data', (chunk: Buffer) => {
            const bufChunk = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
            total += bufChunk.length;
            if (total > maxBytes) {
              res.destroy();
              finishError(new Error(`媒体资源体积超过最大限制 (${maxBytes} bytes)`));
              return;
            }
            chunks.push(bufChunk);
          });
          res.on('end', () => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            resolve(Buffer.concat(chunks, total));
          });
          res.on('error', (err) => finishError(err));
        }
      );
      reqRef.on('error', (err) => finishError(err));
      reqRef.end();
    });
  } finally {
    releaseSlot();
  }
}

export async function resolveOutboundMediaSource(
  mediaUrl: string,
  localDiskPath?: string,
  label = '媒体'
): Promise<{ diskPath?: string; buffer?: Buffer; size: number }> {
  const safeLocalPath = resolveAllowedOutboundDiskPath(localDiskPath);
  if (safeLocalPath) {
    const stat = await fs.promises.stat(safeLocalPath);
    if (stat.size > 0) {
      return { diskPath: safeLocalPath, size: stat.size };
    }
  }
  const resolvedFromUrl = resolveLocalMediaDiskPath(mediaUrl);
  if (resolvedFromUrl) {
    const stat = await fs.promises.stat(resolvedFromUrl);
    if (stat.size > 0) {
      return { diskPath: resolvedFromUrl, size: stat.size };
    }
  }
  const buffer = await readMediaBufferStrict(mediaUrl, label);
  return { buffer, size: buffer.length };
}

export async function readMediaBufferStrict(
  mediaUrl: string,
  label: string,
  fetchOptions?: OutboundMediaFetchOptions
): Promise<Buffer> {
  if (!mediaUrl || typeof mediaUrl !== 'string') {
    throw new Error(`${label}地址为空`);
  }
  const trimmed = mediaUrl.trim();
  const resolvedLocal = resolveLocalMediaDiskPath(trimmed);
  if (resolvedLocal) {
    const buf = await fs.promises.readFile(resolvedLocal);
    if (!buf || buf.length === 0) throw new Error(`${label}数据为空`);
    return buf;
  }
  let buf: Buffer | null = null;
  if (/^data:/i.test(trimmed)) {
    const commaIdx = trimmed.indexOf(',');
    const base64Data = commaIdx >= 0 ? trimmed.slice(commaIdx + 1) : '';
    const maxBytes = fetchOptions?.maxBytes ?? OUTBOUND_MEDIA_MAX_FETCH_BYTES;
    if (Math.floor((base64Data.length * 3) / 4) > maxBytes) {
      throw new Error(`${label}数据体积超过最大限制`);
    }
    buf = Buffer.from(base64Data, 'base64');
  } else if (/^https?:\/\//i.test(trimmed)) {
    buf = await safeOutboundMediaFetch(trimmed, fetchOptions);
  } else {
    throw new Error(`不支持或非法的${label}资源路径，已拦截本地任意路径读取`);
  }
  if (!buf || buf.length === 0) {
    throw new Error(`${label}数据为空`);
  }
  return buf;
}

export interface OutboundDialogState {
  chatId: string;
  isPinned: boolean;
  isArchived: boolean;
  isMuted: boolean;
  unreadCount: number;
  readOutboxMaxId?: number;
  readInboxMaxId?: number;
  lastDate: number;
  lastMessage?: string;
  lastTime?: string;
}

async function syncOutboundTelegramDialogState(params: {
  connected: ConnectedTelegramUser;
  inputPeer: Api.TypeInputPeer;
  chatId: string;
  fallbackSummary: string;
  fallbackDateSec?: number;
}): Promise<OutboundDialogState | undefined> {
  const { connected, inputPeer, chatId, fallbackSummary, fallbackDateSec } = params;
  const rawChat = String(chatId || '').trim();
  const canonicalChatId = rawChat.startsWith('tg_') ? rawChat : `tg_${rawChat}`;
  const nowSec = Math.floor(Date.now() / 1000);
  const safeFallbackDate = Number(fallbackDateSec || 0) > 0 ? Number(fallbackDateSec) : nowSec;
  const formatTime = (sec: number) =>
    new Date(sec * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });

  try {
    const peerDialogs: any = await connected.client.invoke(
      new Api.messages.GetPeerDialogs({
        peers: [new Api.InputDialogPeer({ peer: inputPeer })],
      })
    );
    const d = Array.isArray(peerDialogs?.dialogs) ? peerDialogs.dialogs[0] : undefined;
    if (d) {
      const topMsgId = Number(d.topMessage || 0);
      const msgs: any[] = Array.isArray(peerDialogs?.messages) ? peerDialogs.messages : [];
      const topMsg = msgs.find((m: any) => Number(m?.id || 0) === topMsgId) || msgs[0];
      const lastDate = Number(topMsg?.date || 0) > 0 ? Number(topMsg.date) : safeFallbackDate;
      const lastMessage = topMsg ? summarizeTelegramDialogMedia(topMsg) : fallbackSummary;
      const lastTime = formatTime(lastDate);
      const notify = d.notifySettings;
      const isMuted = Boolean(
        notify?.silent ||
          (notify?.muteUntil !== undefined && notify?.muteUntil !== null && Number(notify.muteUntil) > nowSec)
      );
      const folderId = d.folderId === undefined || d.folderId === null ? 0 : Number(d.folderId);
      const dialogState: OutboundDialogState = {
        chatId: canonicalChatId,
        isPinned: Boolean(d.pinned),
        isArchived: folderId === 1,
        isMuted,
        unreadCount: Number(d.unreadCount || 0) || (d.unreadMark ? 1 : 0),
        ...(Number(d.readOutboxMaxId || 0) > 0 ? { readOutboxMaxId: Number(d.readOutboxMaxId) } : {}),
        ...(Number(d.readInboxMaxId || 0) > 0 ? { readInboxMaxId: Number(d.readInboxMaxId) } : {}),
        lastDate,
        lastMessage,
        lastTime,
      };

      patchConnectedDialogCache(
        connected,
        canonicalChatId,
        {
          lastMessage: dialogState.lastMessage,
          lastTime: dialogState.lastTime,
          lastDate: dialogState.lastDate,
          isPinned: dialogState.isPinned,
          isArchived: dialogState.isArchived,
          isMuted: dialogState.isMuted,
          unreadCount: dialogState.unreadCount,
          ...(dialogState.readOutboxMaxId !== undefined ? { readOutboxMaxId: dialogState.readOutboxMaxId } : {}),
          ...(dialogState.readInboxMaxId !== undefined ? { readInboxMaxId: dialogState.readInboxMaxId } : {}),
        },
        { invalidateCache: false }
      );
      return dialogState;
    }
  } catch (syncErr: any) {
    console.warn('[MTProto Outbound Dialog Sync Warning]:', formatTelegramError(syncErr));
  }

  const fallbackTime = formatTime(safeFallbackDate);
  patchConnectedDialogCache(
    connected,
    canonicalChatId,
    {
      lastMessage: fallbackSummary,
      lastTime: fallbackTime,
      lastDate: safeFallbackDate,
    },
    { invalidateCache: false }
  );
  const cachedDlg: any = Array.isArray(connected.dialogs)
    ? connected.dialogs.find(
        (item: any) =>
          item &&
          (String(item.id || '') === canonicalChatId ||
            String(item.rawId || '') === canonicalChatId.replace(/^tg_/, ''))
      )
    : undefined;
  return cachedDlg
    ? {
        chatId: canonicalChatId,
        isPinned: Boolean(cachedDlg.isPinned),
        isArchived: Boolean(cachedDlg.isArchived),
        isMuted: Boolean(cachedDlg.isMuted),
        unreadCount: Number(cachedDlg.unreadCount || 0),
        ...(cachedDlg.readOutboxMaxId ? { readOutboxMaxId: Number(cachedDlg.readOutboxMaxId) } : {}),
        ...(cachedDlg.readInboxMaxId ? { readInboxMaxId: Number(cachedDlg.readInboxMaxId) } : {}),
        lastDate: safeFallbackDate,
        lastMessage: fallbackSummary,
        lastTime: fallbackTime,
      }
    : undefined;
}

const TRUSTED_OUTBOUND_DISK_PATH = Symbol('trustedOutboundDiskPath');

function isSuspiciousLocalFilePathString(raw: string): boolean {
  const s = raw.trim();
  if (!s) return false;
  if (s.includes('\0')) return true;
  if (/^file:/i.test(s)) return true;
  if (s.startsWith('/') || s.startsWith('.') || s.startsWith('~/') || s.startsWith('\\\\') || s.includes('\\')) {
    return true;
  }
  if (/^[a-zA-Z]:[\\/]/.test(s)) {
    return true;
  }
  if ((s.includes('/') || s.includes('.')) && !/^[A-Za-z0-9+/=\s]+$/.test(s)) {
    return true;
  }
  return false;
}

async function validateOutboundMediaInputForBot(
  mediaInput: string,
  resolvedTrustedDiskPath: string | null,
  label: string
): Promise<{ ok: true; value: string } | { ok: false; error: string }> {
  if (resolvedTrustedDiskPath) {
    return { ok: true, value: resolvedTrustedDiskPath };
  }
  const trimmed = String(mediaInput || '').trim();
  if (!trimmed) {
    return { ok: false, error: `${label}缺少有效的媒体地址` };
  }
  const safeLocalUrlPath = resolveLocalMediaDiskPath(trimmed);
  if (safeLocalUrlPath) {
    return { ok: true, value: safeLocalUrlPath };
  }
  if (/^data:/i.test(trimmed)) {
    return { ok: true, value: trimmed };
  }
  if (/^https?:\/\//i.test(trimmed)) {
    try {
      await validateOutboundMediaRemoteUrl(trimmed);
      return { ok: true, value: trimmed };
    } catch (err: any) {
      return { ok: false, error: err?.message || `SSRF 安全拦截：非法的${label}远程地址` };
    }
  }
  return { ok: false, error: `安全拦截：不支持或非法的${label}媒体路径，已禁止访问本地文件系统` };
}

export async function isKnownContactOrGroupPeer(
  connected: ConnectedTelegramUser | undefined,
  chatId: string
): Promise<boolean> {
  const raw = String(chatId || '').trim();
  const clean = raw.replace(/^tg_/, '');
  if (!clean || clean === 'me' || clean === 'self' || clean === '777000' || clean === '42777') {
    return true;
  }
  if (isTelegramGroupChatId(raw, connected)) {
    return true;
  }
  if (connected && Array.isArray(connected.dialogs)) {
    const dlg: any = connected.dialogs.find(
      (d: any) => d && (String(d.id) === raw || String(d.id) === `tg_${clean}` || String(d.rawId || '') === clean)
    );
    if (dlg) {
      if (dlg.isGroup || dlg.isChannel || dlg.isContact || dlg.mutualContact) {
        return true;
      }
      if (dlg.isContact === false && !dlg.isGroup && !dlg.isChannel) {
        return false;
      }
    }
  }
  if (connected?.client && typeof (connected.client as any).getEntity === 'function') {
    try {
      const peerArg: any = /^-?\d+$/.test(clean) ? Number(clean) : clean;
      const entity: any = await (connected.client as any).getEntity(peerArg);
      if (entity) {
        if (
          entity.className === 'Chat' ||
          entity.className === 'Channel' ||
          entity.contact === true ||
          entity.mutualContact === true
        ) {
          return true;
        }
      }
    } catch {}
  }
  return false;
}

export async function deliverOutboundTelegramMessage(
  payload: any,
  effectiveAccountId: string,
  msgId: string
): Promise<{
  delivered: boolean;
  channel: 'mtproto' | 'bot' | 'local' | 'none';
  telegramMessageId?: number;
  dialogState?: OutboundDialogState;
  error?: string;
  sessionExpired?: boolean;
  floodWait?: boolean;
  peerFlood?: boolean;
  retryAfterSeconds?: number;
  floodWaitUntil?: number;
}> {
  const {
    chatId,
    sender,
    text,
    translatedText,
    isAudio = false,
    audioDuration = 0,
    audioUrl = '',
    sttText = '',
    isImage = false,
    imageUrl = '',
    imageCaption = '',
    isVideo = false,
    videoDuration = 0,
    videoUrl = '',
    isFile = false,
    fileName = '',
    fileUrl = '',
    replyTo,
    replyToMsgId,
  } = payload || {};

  // Only trust _localDiskPath when stamped by server multipart upload via unforgeable Symbol AND inside OUTBOUND_MEDIA_DIR
  const trustedDiskPath =
    payload && typeof payload === 'object' && typeof payload[TRUSTED_OUTBOUND_DISK_PATH] === 'string'
      ? resolveAllowedOutboundDiskPath(payload[TRUSTED_OUTBOUND_DISK_PATH])
      : null;
  const _localDiskPath = trustedDiskPath || undefined;

  const resolvedReplyToTgId =
    resolveTelegramMessageNumericId(replyTo?.id, replyTo?.telegramMessageId ?? replyToMsgId) || undefined;

  const isExplicitBotChannel = effectiveAccountId === 'acc_telegram_bot';
  const isTelegramChat = Boolean(chatId && (String(chatId).startsWith('tg_') || isExplicitBotChannel));
  if (sender !== 'me' || !isTelegramChat) {
    return { delivered: true, channel: 'local' };
  }

  try {
    const outText = text || translatedText || '';

    // 1. Explicit Bot channel (only when user explicitly selected acc_telegram_bot; never auto-fallback from personal MTProto)
    if (isExplicitBotChannel) {
      if (!process.env.TELEGRAM_BOT_TOKEN) {
        return { delivered: false, channel: 'bot', error: '未配置 TELEGRAM_BOT_TOKEN，Bot 通道无法发送' };
      }

      let botResult: any = null;
      let failDetail = 'Telegram Bot API 投递失败';
      const botOpts: TelegramSendOptions = {
        messageId: msgId,
        ...(resolvedReplyToTgId ? { replyToMessageId: resolvedReplyToTgId } : {}),
      };
      const BOT_MAX_UPLOAD_BYTES = 50 * 1024 * 1024;
      const diskPathForBot =
        trustedDiskPath ||
        resolveLocalMediaDiskPath(audioUrl || imageUrl || videoUrl || fileUrl);
      if (diskPathForBot) {
        const st = await fs.promises.stat(diskPathForBot).catch(() => null);
        if (st && st.size > BOT_MAX_UPLOAD_BYTES) {
          return {
            delivered: false,
            channel: 'bot',
            error: `Telegram Bot API 单文件上限 50MB（当前约 ${Math.round(st.size / (1024 * 1024))}MB），请切换个人号发送大文件`,
          };
        }
      }

      if (isAudio) {
        if (!audioUrl && !diskPathForBot) {
          return { delivered: false, channel: 'bot', error: '语音消息缺少音频地址，无法通过 Bot 发送' };
        }
        const validated = await validateOutboundMediaInputForBot(audioUrl, diskPathForBot, '语音');
        if (!validated.ok) {
          return { delivered: false, channel: 'bot', error: validated.error };
        }
        console.log(`[Telegram Outbound] Bot sending voice message to ${chatId} (${audioDuration}s)...`);
        botResult = await sendTelegramVoice(chatId, validated.value, sttText || text || translatedText, audioDuration, botOpts);
        failDetail = 'Telegram Bot API 语音发送失败（请检查音频转码或 Bot 权限）';
      } else if (isImage) {
        if (!imageUrl && !diskPathForBot) {
          return { delivered: false, channel: 'bot', error: '图片消息缺少图片地址，无法通过 Bot 发送' };
        }
        const validated = await validateOutboundMediaInputForBot(imageUrl, diskPathForBot, '图片');
        if (!validated.ok) {
          return { delivered: false, channel: 'bot', error: validated.error };
        }
        console.log(`[Telegram Outbound] Bot sending photo to ${chatId}...`);
        botResult = await sendTelegramPhoto(chatId, validated.value, text || imageCaption || translatedText, botOpts);
        failDetail = 'Telegram Bot API 图片发送失败';
      } else if (isVideo) {
        if (!videoUrl && !diskPathForBot) {
          return { delivered: false, channel: 'bot', error: '视频消息缺少视频地址，无法通过 Bot 发送' };
        }
        const validated = await validateOutboundMediaInputForBot(videoUrl, diskPathForBot, '视频');
        if (!validated.ok) {
          return { delivered: false, channel: 'bot', error: validated.error };
        }
        console.log(`[Telegram Outbound] Bot sending video to ${chatId} (${videoDuration}s)...`);
        botResult = await sendTelegramVideo(chatId, validated.value, text || translatedText, videoDuration, botOpts);
        failDetail = 'Telegram Bot API 视频发送失败';
      } else if (isFile) {
        if (!fileUrl && !diskPathForBot) {
          return { delivered: false, channel: 'bot', error: '文件消息缺少文件地址，无法通过 Bot 发送' };
        }
        const validated = await validateOutboundMediaInputForBot(fileUrl, diskPathForBot, '文件');
        if (!validated.ok) {
          return { delivered: false, channel: 'bot', error: validated.error };
        }
        console.log(`[Telegram Outbound] Bot sending document to ${chatId}: ${fileName}...`);
        botResult = await sendTelegramDocument(chatId, validated.value, fileName, text !== `[文件] ${fileName}` ? text : undefined, botOpts);
        failDetail = 'Telegram Bot API 文件发送失败';
      } else {
        if (!outText) {
          return { delivered: false, channel: 'bot', error: '消息内容为空，未能发送至 Telegram' };
        }
        console.log(`[Telegram Outbound] Bot sending text message to ${chatId}: "${outText.slice(0, 30)}..."`);
        botResult = await sendTelegramMessage(chatId, outText, botOpts);
      }

      if (botResult && botResult.ok !== false) {
        return {
          delivered: true,
          channel: 'bot',
          telegramMessageId: Number(botResult?.result?.message_id) || undefined,
        };
      }
      return { delivered: false, channel: 'bot', error: failDetail };
    }

    // 2. Personal MTProto account channel — strictly no silent Bot fallback when offline
    const personalAccount =
      connectedUserClients.get(effectiveAccountId) ||
      Array.from(connectedUserClients.values()).find(
        (u) => u.userId === effectiveAccountId || u.phone === effectiveAccountId || `acc_tg_${u.userId}` === effectiveAccountId
      );

    if (!personalAccount?.client) {
      const normalizedUid = effectiveAccountId.replace(/^acc_tg_/, '');
      let expiredInfo =
        recentlyExpiredAccounts.get(normalizedUid) ||
        recentlyExpiredAccounts.get(effectiveAccountId);
      if (!expiredInfo && normalizedUid) {
        try {
          const row = (await db
            .prepare('SELECT user_id, phone, is_active, expired_reason FROM telegram_user_sessions WHERE (user_id = ? OR phone = ?) AND is_active = 0 LIMIT 1')
            .get(normalizedUid, effectiveAccountId)) as any;
          if (row) {
            expiredInfo = {
              accountId: `acc_tg_${row.user_id || normalizedUid}`,
              userId: row.user_id || normalizedUid,
              phone: row.phone || undefined,
              reason: row.expired_reason || 'Telegram 登录会话已失效，请重新扫码或验证码登录',
              expiredAt: Date.now(),
            };
          }
        } catch {}
      }
      if (expiredInfo) {
        return {
          delivered: false,
          channel: 'mtproto',
          sessionExpired: true,
          error: expiredInfo.reason || 'Telegram 登录会话已失效，请重新扫码或验证码登录',
        };
      }
      return {
        delivered: false,
        channel: 'mtproto',
        error: '当前个人账号未在线连接 Telegram MTProto，消息未送达（已禁用跨通道 Bot 代发）',
      };
    }

    const floodCtx = {
      accountId: effectiveAccountId,
      userId: personalAccount.userId,
      phone: personalAccount.phone,
    };
    const activePeerFlood = getTelegramPeerFloodStatus(floodCtx);
    if (activePeerFlood && !(await isKnownContactOrGroupPeer(personalAccount, String(chatId)))) {
      return {
        delivered: false,
        channel: 'mtproto',
        peerFlood: true,
        error: activePeerFlood.reason,
      };
    }
    const activeFlood = getTelegramFloodCooldown(floodCtx);
    if (activeFlood) {
      return {
        delivered: false,
        channel: 'mtproto',
        floodWait: true,
        retryAfterSeconds: activeFlood.retryAfterSeconds,
        floodWaitUntil: activeFlood.floodWaitUntil,
        error: formatTelegramError({ errorMessage: `FLOOD_WAIT_${activeFlood.retryAfterSeconds}` }),
      };
    }

    const rawTgId = String(chatId).replace(/^tg_/, '');
    const { inputPeer: resolvedPeer } = await resolveTelegramInputPeer(
      personalAccount.client,
      String(chatId),
      personalAccount.userId,
      'P0'
    );

    if (isAudio) {
      if (!audioUrl && !_localDiskPath) {
        return { delivered: false, channel: 'mtproto', error: '语音消息缺少音频地址，无法发送至 Telegram' };
      }
      console.log(`[MTProto Outbound] Personal account sending native voice note to ${rawTgId} (${audioDuration > 0 ? `${audioDuration}s` : '未知时长'})...`);
      try {
        const source = await resolveOutboundMediaSource(audioUrl, _localDiskPath, '语音');
        const oggBuffer = await convertAudioToOggOpus(source.diskPath || source.buffer!);
        const voiceFile = new CustomFile('voice.ogg', oggBuffer.length, '', oggBuffer);
        const voiceEchoText = (sttText || text || '').trim() || '🎤 语音消息';
        markOutboundMessageSent(chatId, voiceEchoText, effectiveAccountId);
        const sentVoice: any = await scheduleTelegramRpc(effectiveAccountId, 'P0', 'sendFile.voice', () =>
          personalAccount.client.sendFile(resolvedPeer, {
            file: voiceFile,
            voiceNote: true,
            caption: sttText || text || undefined,
            ...(resolvedReplyToTgId ? { replyTo: resolvedReplyToTgId } : {}),
          })
        );
        const sentVoiceTgId = Number(sentVoice?.id) || undefined;
        if (sentVoiceTgId) markOutboundTelegramMessageIdSent(chatId, sentVoiceTgId, effectiveAccountId);
        const dialogState = await syncOutboundTelegramDialogState({
          connected: personalAccount,
          inputPeer: resolvedPeer,
          chatId: String(chatId),
          fallbackSummary: voiceEchoText,
          fallbackDateSec: Number(sentVoice?.date || 0) || undefined,
        });
        console.log(`[MTProto Outbound] Successfully delivered native OGG Opus voice note to ${rawTgId}`);
        return { delivered: true, channel: 'mtproto', telegramMessageId: sentVoiceTgId, dialogState };
      } catch (voiceErr: any) {
        const errMsg = formatTelegramError(voiceErr);
        console.error(`[MTProto Voice Send Error]:`, errMsg);
        const peerFloodEntry = recordTelegramPeerFlood(floodCtx, voiceErr, 'sendFile.voice');
        if (peerFloodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            peerFlood: true,
            error: peerFloodEntry.reason,
          };
        }
        const floodEntry = recordTelegramFloodWait(floodCtx, voiceErr, 'sendFile.voice');
        if (floodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            floodWait: true,
            retryAfterSeconds: floodEntry.retryAfterSeconds,
            floodWaitUntil: floodEntry.floodWaitUntil,
            error: `语音发送失败: ${errMsg}`,
          };
        }
        if (isTelegramSessionExpiredError(voiceErr)) {
          await markTelegramSessionExpired({
            accountId: effectiveAccountId,
            userId: personalAccount.userId,
            phone: personalAccount.phone,
            reason: errMsg,
          });
          return { delivered: false, channel: 'mtproto', sessionExpired: true, error: 'Telegram 登录会话已失效，请重新扫码或验证码登录' };
        }
        return { delivered: false, channel: 'mtproto', error: `语音发送失败: ${errMsg}` };
      }
    }

    if (isImage) {
      if (!imageUrl && !_localDiskPath) {
        return { delivered: false, channel: 'mtproto', error: '图片消息缺少图片地址，无法发送至 Telegram' };
      }
      console.log(`[MTProto Outbound] Personal account sending photo to ${rawTgId}...`);
      try {
        const source = await resolveOutboundMediaSource(imageUrl, _localDiskPath, '图片');
        const uploadExt = source.diskPath ? path.extname(source.diskPath) || '.jpg' : '.jpg';
        const uploadName = `photo${/^\.(jpg|jpeg|png|gif|webp)$/i.test(uploadExt) ? uploadExt : '.jpg'}`;
        const photoFile = source.diskPath
          ? new CustomFile(uploadName, source.size, source.diskPath)
          : new CustomFile(uploadName, source.buffer!.length, '', source.buffer);
        const isFileNameCaption = (s?: string) => {
          if (!s || typeof s !== 'string') return true;
          const trimmed = s.trim();
          if (!trimmed || trimmed.startsWith('[照片]')) return true;
          return /\.(jpg|jpeg|png|gif|webp|bmp|svg|heic)$/i.test(trimmed);
        };
        const explicitCaption = (!isFileNameCaption(text) ? text : undefined) ||
          (!isFileNameCaption(imageCaption) ? imageCaption : undefined) ||
          (!isFileNameCaption(translatedText) ? translatedText : undefined);

        const photoEchoText = (explicitCaption || '').trim() || '🖼️ 图片消息';
        markOutboundMessageSent(chatId, photoEchoText, effectiveAccountId);
        const sentPhoto: any = await scheduleTelegramRpc(effectiveAccountId, 'P0', 'sendFile.photo', () =>
          personalAccount.client.sendFile(resolvedPeer, {
            file: photoFile,
            caption: explicitCaption || undefined,
            ...(resolvedReplyToTgId ? { replyTo: resolvedReplyToTgId } : {}),
          })
        );
        const sentPhotoTgId = Number(sentPhoto?.id) || undefined;
        if (sentPhotoTgId) markOutboundTelegramMessageIdSent(chatId, sentPhotoTgId, effectiveAccountId);
        const dialogState = await syncOutboundTelegramDialogState({
          connected: personalAccount,
          inputPeer: resolvedPeer,
          chatId: String(chatId),
          fallbackSummary: photoEchoText,
          fallbackDateSec: Number(sentPhoto?.date || 0) || undefined,
        });
        console.log(`[MTProto Outbound] Successfully delivered photo to ${rawTgId}`);
        return { delivered: true, channel: 'mtproto', telegramMessageId: sentPhotoTgId, dialogState };
      } catch (photoErr: any) {
        const errMsg = formatTelegramError(photoErr);
        console.error(`[MTProto Photo Send Error]:`, errMsg);
        const peerFloodEntry = recordTelegramPeerFlood(floodCtx, photoErr, 'sendFile.photo');
        if (peerFloodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            peerFlood: true,
            error: peerFloodEntry.reason,
          };
        }
        const floodEntry = recordTelegramFloodWait(floodCtx, photoErr, 'sendFile.photo');
        if (floodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            floodWait: true,
            retryAfterSeconds: floodEntry.retryAfterSeconds,
            floodWaitUntil: floodEntry.floodWaitUntil,
            error: `图片发送失败: ${errMsg}`,
          };
        }
        if (isTelegramSessionExpiredError(photoErr)) {
          await markTelegramSessionExpired({
            accountId: effectiveAccountId,
            userId: personalAccount.userId,
            phone: personalAccount.phone,
            reason: errMsg,
          });
          return { delivered: false, channel: 'mtproto', sessionExpired: true, error: 'Telegram 登录会话已失效，请重新扫码或验证码登录' };
        }
        return { delivered: false, channel: 'mtproto', error: `图片发送失败: ${errMsg}` };
      }
    }

    if (isVideo) {
      if (!videoUrl && !_localDiskPath) {
        return { delivered: false, channel: 'mtproto', error: '视频消息缺少视频地址，无法发送至 Telegram' };
      }
      console.log(`[MTProto Outbound] Personal account sending video to ${rawTgId} (${videoDuration || 0}s)...`);
      try {
        const source = await resolveOutboundMediaSource(videoUrl, _localDiskPath, '视频');
        const uploadExt = source.diskPath ? path.extname(source.diskPath) || '.mp4' : '.mp4';
        const uploadName = `video${/^\.(mp4|mov|webm|mkv|avi|m4v)$/i.test(uploadExt) ? uploadExt : '.mp4'}`;
        const videoFile = source.diskPath
          ? new CustomFile(uploadName, source.size, source.diskPath)
          : new CustomFile(uploadName, source.buffer!.length, '', source.buffer);
        const isFileNameCaption = (s?: string) => {
          if (!s || typeof s !== 'string') return true;
          const trimmed = s.trim();
          if (!trimmed || trimmed.startsWith('[视频]')) return true;
          return /\.(mp4|mov|webm|mkv|avi|m4v)$/i.test(trimmed);
        };
        const explicitCaption = (!isFileNameCaption(text) ? text : undefined) ||
          (!isFileNameCaption(translatedText) ? translatedText : undefined);

        const videoEchoText = (explicitCaption || '').trim() || '🎬 视频';
        markOutboundMessageSent(chatId, videoEchoText, effectiveAccountId);
        const sentVideo: any = await scheduleTelegramRpc(effectiveAccountId, 'P0', 'sendFile.video', () =>
          personalAccount.client.sendFile(resolvedPeer, {
            file: videoFile,
            supportsStreaming: true,
            workers: source.size > 10 * 1024 * 1024 ? 4 : 1,
            caption: explicitCaption || undefined,
            ...(resolvedReplyToTgId ? { replyTo: resolvedReplyToTgId } : {}),
          })
        );
        const sentVideoTgId = Number(sentVideo?.id) || undefined;
        if (sentVideoTgId) markOutboundTelegramMessageIdSent(chatId, sentVideoTgId, effectiveAccountId);
        const dialogState = await syncOutboundTelegramDialogState({
          connected: personalAccount,
          inputPeer: resolvedPeer,
          chatId: String(chatId),
          fallbackSummary: videoEchoText,
          fallbackDateSec: Number(sentVideo?.date || 0) || undefined,
        });
        console.log(`[MTProto Outbound] Successfully delivered video to ${rawTgId}`);
        return { delivered: true, channel: 'mtproto', telegramMessageId: sentVideoTgId, dialogState };
      } catch (vidErr: any) {
        const errMsg = formatTelegramError(vidErr);
        console.error(`[MTProto Video Send Error]:`, errMsg);
        const peerFloodEntry = recordTelegramPeerFlood(floodCtx, vidErr, 'sendFile.video');
        if (peerFloodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            peerFlood: true,
            error: peerFloodEntry.reason,
          };
        }
        const floodEntry = recordTelegramFloodWait(floodCtx, vidErr, 'sendFile.video');
        if (floodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            floodWait: true,
            retryAfterSeconds: floodEntry.retryAfterSeconds,
            floodWaitUntil: floodEntry.floodWaitUntil,
            error: `视频发送失败: ${errMsg}`,
          };
        }
        if (isTelegramSessionExpiredError(vidErr)) {
          await markTelegramSessionExpired({
            accountId: effectiveAccountId,
            userId: personalAccount.userId,
            phone: personalAccount.phone,
            reason: errMsg,
          });
          return { delivered: false, channel: 'mtproto', sessionExpired: true, error: 'Telegram 登录会话已失效，请重新扫码或验证码登录' };
        }
        return { delivered: false, channel: 'mtproto', error: `视频发送失败: ${errMsg}` };
      }
    }

    if (isFile) {
      if (!fileUrl && !_localDiskPath) {
        return { delivered: false, channel: 'mtproto', error: '文件消息缺少文件地址，无法发送至 Telegram' };
      }
      console.log(`[MTProto Outbound] Personal account sending document to ${rawTgId}: ${fileName}...`);
      try {
        const source = await resolveOutboundMediaSource(fileUrl, _localDiskPath, '文件');
        const resolvedDocName = fileName || (source.diskPath ? path.basename(source.diskPath) : 'file.bin');
        const docFile = source.diskPath
          ? new CustomFile(resolvedDocName, source.size, source.diskPath)
          : new CustomFile(resolvedDocName, source.buffer!.length, '', source.buffer);
        const docCaption = text !== `[文件] ${fileName}` ? (text || undefined) : undefined;
        const fileEchoText = (docCaption || '').trim() || `📎 ${resolvedDocName || '文件附件'}`;
        markOutboundMessageSent(chatId, fileEchoText, effectiveAccountId);
        const sentDoc: any = await scheduleTelegramRpc(effectiveAccountId, 'P0', 'sendFile.document', () =>
          personalAccount.client.sendFile(resolvedPeer, {
            file: docFile,
            caption: docCaption,
            forceDocument: true,
            workers: source.size > 10 * 1024 * 1024 ? 4 : 1,
            ...(resolvedReplyToTgId ? { replyTo: resolvedReplyToTgId } : {}),
          })
        );
        const sentDocTgId = Number(sentDoc?.id) || undefined;
        if (sentDocTgId) markOutboundTelegramMessageIdSent(chatId, sentDocTgId, effectiveAccountId);
        const dialogState = await syncOutboundTelegramDialogState({
          connected: personalAccount,
          inputPeer: resolvedPeer,
          chatId: String(chatId),
          fallbackSummary: fileEchoText,
          fallbackDateSec: Number(sentDoc?.date || 0) || undefined,
        });
        console.log(`[MTProto Outbound] Successfully delivered document to ${rawTgId}`);
        return { delivered: true, channel: 'mtproto', telegramMessageId: sentDocTgId, dialogState };
      } catch (fileErr: any) {
        const errMsg = formatTelegramError(fileErr);
        console.error(`[MTProto File Send Error]:`, errMsg);
        const peerFloodEntry = recordTelegramPeerFlood(floodCtx, fileErr, 'sendFile.document');
        if (peerFloodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            peerFlood: true,
            error: peerFloodEntry.reason,
          };
        }
        const floodEntry = recordTelegramFloodWait(floodCtx, fileErr, 'sendFile.document');
        if (floodEntry) {
          return {
            delivered: false,
            channel: 'mtproto',
            floodWait: true,
            retryAfterSeconds: floodEntry.retryAfterSeconds,
            floodWaitUntil: floodEntry.floodWaitUntil,
            error: `文件发送失败: ${errMsg}`,
          };
        }
        if (isTelegramSessionExpiredError(fileErr)) {
          await markTelegramSessionExpired({
            accountId: effectiveAccountId,
            userId: personalAccount.userId,
            phone: personalAccount.phone,
            reason: errMsg,
          });
          return { delivered: false, channel: 'mtproto', sessionExpired: true, error: 'Telegram 登录会话已失效，请重新扫码或验证码登录' };
        }
        return { delivered: false, channel: 'mtproto', error: `文件发送失败: ${errMsg}` };
      }
    }

    if (!outText) {
      return { delivered: false, channel: 'mtproto', error: '消息内容为空，未能发送至 Telegram' };
    }

    console.log(`[MTProto Outbound] Personal account sending text message to ${rawTgId}: "${outText.slice(0, 30)}..."`);
    markOutboundMessageSent(chatId, outText, effectiveAccountId);
    const sentMsg: any = await scheduleTelegramRpc(effectiveAccountId, 'P0', 'messages.SendMessage', () =>
      personalAccount.client.sendMessage(resolvedPeer, {
        message: outText,
        ...(resolvedReplyToTgId ? { replyTo: resolvedReplyToTgId } : {}),
      })
    );
    const sentTextTgId = Number(sentMsg?.id) || undefined;
    if (sentTextTgId) markOutboundTelegramMessageIdSent(chatId, sentTextTgId, effectiveAccountId);
    const dialogState = await syncOutboundTelegramDialogState({
      connected: personalAccount,
      inputPeer: resolvedPeer,
      chatId: String(chatId),
      fallbackSummary: outText,
      fallbackDateSec: Number(sentMsg?.date || 0) || undefined,
    });
    return { delivered: true, channel: 'mtproto', telegramMessageId: sentTextTgId, dialogState };
  } catch (tgSyncErr: any) {
    const errMsg = formatTelegramError(tgSyncErr);
    console.warn(`[Telegram Outbound Push Error]:`, errMsg);
    if (effectiveAccountId !== 'acc_telegram_bot') {
      const peerFloodEntry = recordTelegramPeerFlood({ accountId: effectiveAccountId }, tgSyncErr, 'messages.SendMessage');
      if (peerFloodEntry) {
        return {
          delivered: false,
          channel: 'mtproto',
          peerFlood: true,
          error: peerFloodEntry.reason,
        };
      }
      const floodEntry = recordTelegramFloodWait({ accountId: effectiveAccountId }, tgSyncErr, 'messages.SendMessage');
      if (floodEntry) {
        return {
          delivered: false,
          channel: 'mtproto',
          floodWait: true,
          retryAfterSeconds: floodEntry.retryAfterSeconds,
          floodWaitUntil: floodEntry.floodWaitUntil,
          error: errMsg,
        };
      }
    }
    if (effectiveAccountId !== 'acc_telegram_bot' && isTelegramSessionExpiredError(tgSyncErr)) {
      await markTelegramSessionExpired({
        accountId: effectiveAccountId,
        reason: errMsg,
      });
      return {
        delivered: false,
        channel: 'mtproto',
        sessionExpired: true,
        error: 'Telegram 登录会话已失效，请重新扫码或验证码登录',
      };
    }
    return {
      delivered: false,
      channel: effectiveAccountId === 'acc_telegram_bot' ? 'bot' : 'mtproto',
      error: errMsg || 'Telegram 投递失败',
    };
  }
}

const OUTBOUND_MESSAGE_WHITELIST_KEYS = [
  'id',
  'clientMessageId',
  'chatId',
  'accountId',
  'sender',
  'senderName',
  'senderId',
  'senderAvatarUrl',
  'text',
  'translatedText',
  'timestamp',
  'createdAt',
  'replyTo',
  'replyToMsgId',
  'telegramMessageId',
  'deliveryStatus',
  'queuePauseReason',
  'floodWaitUntil',
  'asyncQueue',
  'isAudio',
  'audioDuration',
  'audioUrl',
  'sttText',
  'voiceName',
  'voiceTone',
  'isMasterVoice',
  'isImage',
  'imageUrl',
  'imageCaption',
  'isVideo',
  'videoDuration',
  'videoUrl',
  'isFile',
  'fileName',
  'fileSize',
  'fileUrl',
  'isEdited',
  'isPinned',
  'forwardFrom',
  'reactions',
  'myReactions',
] as const;

export function sanitizeOutboundMessageClientPayload(rawPayload: Record<string, any>): Record<string, any> {
  const clean: Record<string, any> = {};
  if (!rawPayload || typeof rawPayload !== 'object') {
    return clean;
  }
  for (const key of OUTBOUND_MESSAGE_WHITELIST_KEYS) {
    if (Object.prototype.hasOwnProperty.call(rawPayload, key) && rawPayload[key] !== undefined) {
      clean[key] = rawPayload[key];
    }
  }
  return clean;
}

function cloneOutboundPayloadPreservingDiskSymbol(
  basePayload: Record<string, any>,
  overrides?: Record<string, any>
): Record<string, any> {
  const next: Record<string, any> = {
    ...(basePayload || {}),
    ...(overrides || {}),
  };
  const symPath =
    basePayload && typeof basePayload === 'object' ? (basePayload as any)[TRUSTED_OUTBOUND_DISK_PATH] : undefined;
  if (typeof symPath === 'string' && symPath) {
    Object.defineProperty(next, TRUSTED_OUTBOUND_DISK_PATH, {
      value: symPath,
      enumerable: false,
      configurable: false,
      writable: false,
    });
  }
  return next;
}

export function applyUploadedMediaToMessagePayload(
  rawPayload: Record<string, any>,
  uploadedMedia: { diskPath: string; diskFileName: string; originalName: string; mimeType: string; size: number } | undefined,
  effectiveAccountId: string
): { payload: Record<string, any>; mediaUrl?: string } {
  const safePayload = sanitizeOutboundMessageClientPayload(rawPayload);
  const verifiedDiskPath = uploadedMedia?.diskPath
    ? resolveAllowedOutboundDiskPath(uploadedMedia.diskPath)
    : null;
  if (!uploadedMedia || !verifiedDiskPath) {
    return { payload: safePayload };
  }
  const mediaUrl = buildOutboundLocalMediaUrl(uploadedMedia.diskFileName, effectiveAccountId);
  const next: Record<string, any> = {
    ...safePayload,
    _localDiskPath: verifiedDiskPath,
  };
  Object.defineProperty(next, TRUSTED_OUTBOUND_DISK_PATH, {
    value: verifiedDiskPath,
    enumerable: false,
    configurable: false,
    writable: false,
  });
  if (next.isVideo) {
    next.videoUrl = mediaUrl;
  } else if (next.isImage) {
    next.imageUrl = mediaUrl;
  } else if (next.isAudio) {
    next.audioUrl = mediaUrl;
  } else {
    next.isFile = true;
    next.fileUrl = mediaUrl;
    if (!next.fileName && uploadedMedia.originalName) {
      next.fileName = uploadedMedia.originalName;
    }
    if (!next.fileSize) {
      next.fileSize =
        uploadedMedia.size >= 1024 * 1024
          ? `${(uploadedMedia.size / (1024 * 1024)).toFixed(1)} MB`
          : `${(uploadedMedia.size / 1024).toFixed(1)} KB`;
    }
  }
  return { payload: next, mediaUrl };
}

// ==================== PER-(ACCOUNT, CHAT) OUTBOUND FIFO SCHEDULER & IDEMPOTENCY ====================
export type OutboundDeliveryResult = Awaited<ReturnType<typeof deliverOutboundTelegramMessage>> & {
  deliveryStatus?: 'delivered' | 'failed' | 'pending' | 'paused';
  queuePauseReason?: string;
  clientMessageId?: string;
  duplicate?: boolean;
};

interface OutboundQueueItem {
  id: string;
  clientMessageId?: string;
  effectiveAccountId: string;
  accountKey: string;
  chatId: string;
  canonicalChatId: string;
  isGroup: boolean;
  isMedia: boolean;
  asyncQueue: boolean;
  payload: Record<string, any>;
  enqueuedAt: number;
  deliverFn?: typeof deliverOutboundTelegramMessage;
  skipPeerFloodCheck?: boolean;
  resolve: (result: OutboundDeliveryResult) => void;
}

interface OutboundChatQueueState {
  chatId: string;
  isGroup: boolean;
  inFlight: boolean;
  nextAllowedAt: number;
  items: OutboundQueueItem[];
}

interface OutboundAccountSchedulerState {
  accountKey: string;
  queues: Map<string, OutboundChatQueueState>;
  groupOrder: string[];
  groupCursor: number;
  mediaInFlight: boolean;
  nextAnyDispatchAt: number;
  nextGroupDispatchAt: number;
  floodWaitUntil: number;
  drainTimer: NodeJS.Timeout | null;
}

export interface OutboundClientIdempotencyRecord {
  id: string;
  clientMessageId: string;
  accountId: string;
  chatId: string;
  status: 'pending' | 'retrying' | 'paused' | 'delivered' | 'failed';
  telegramMessageId?: number;
  queuePauseReason?: string;
  floodWaitUntil?: number;
  error?: string;
  payload: Record<string, any>;
  updatedAt: number;
}

const outboundAccountSchedulers = new Map<string, OutboundAccountSchedulerState>();
const outboundClientMessageRecords = new Map<string, OutboundClientIdempotencyRecord>();
const MAX_OUTBOUND_CLIENT_RECORDS = 5000;

function randomIntBetween(min: number, max: number): number {
  const lo = Math.max(0, Math.floor(Math.min(min, max)));
  const hi = Math.max(lo, Math.floor(Math.max(min, max)));
  if (hi <= lo) return lo;
  return lo + Math.floor(Math.random() * (hi - lo + 1));
}

function canonicalizeSchedulerChatId(chatId: string): string {
  const clean = String(chatId || '').trim();
  if (!clean) return 'unknown';
  return clean.startsWith('tg_') || clean.startsWith('chat_') ? clean : `tg_${clean}`;
}

function getOutboundAccountSchedulerKey(effectiveAccountId: string): string {
  return (
    resolveTelegramAccountRuntimeKey({ accountId: effectiveAccountId }) ||
    String(effectiveAccountId || 'acc_1').trim() ||
    'acc_1'
  );
}

function recordOutboundClientMessageState(entry: OutboundClientIdempotencyRecord): void {
  if (!entry.clientMessageId) return;
  const key = `${entry.accountId}::${entry.clientMessageId}`;
  outboundClientMessageRecords.set(key, entry);
  while (outboundClientMessageRecords.size > MAX_OUTBOUND_CLIENT_RECORDS) {
    const oldest = outboundClientMessageRecords.keys().next().value;
    if (oldest === undefined) break;
    outboundClientMessageRecords.delete(oldest);
  }
}

export function clearOutboundSchedulerForTesting(): void {
  for (const state of outboundAccountSchedulers.values()) {
    if (state.drainTimer) clearTimeout(state.drainTimer);
  }
  outboundAccountSchedulers.clear();
  outboundClientMessageRecords.clear();
}

export function getOutboundSchedulerStats() {
  let queuedTotal = 0;
  let groupQueues = 0;
  let privateQueues = 0;
  for (const acc of outboundAccountSchedulers.values()) {
    for (const q of acc.queues.values()) {
      queuedTotal += q.items.length;
      if (q.isGroup) groupQueues += 1;
      else privateQueues += 1;
    }
  }
  return {
    accounts: outboundAccountSchedulers.size,
    queuedTotal,
    groupQueues,
    privateQueues,
    clientRecords: outboundClientMessageRecords.size,
  };
}

function getOrCreateOutboundAccountScheduler(accountKey: string): OutboundAccountSchedulerState {
  let state = outboundAccountSchedulers.get(accountKey);
  if (!state) {
    state = {
      accountKey,
      queues: new Map(),
      groupOrder: [],
      groupCursor: 0,
      mediaInFlight: false,
      nextAnyDispatchAt: 0,
      nextGroupDispatchAt: 0,
      floodWaitUntil: 0,
      drainTimer: null,
    };
    outboundAccountSchedulers.set(accountKey, state);
  }
  return state;
}

function emitOutboundReceiptUpdate(params: {
  id: string;
  clientMessageId?: string;
  chatId: string;
  accountId: string;
  deliveryStatus: 'pending' | 'delivered' | 'paused' | 'failed';
  telegramMessageId?: number;
  dialogState?: OutboundDialogState;
  queuePauseReason?: string;
  floodWaitUntil?: number;
  error?: string;
  peerFlood?: boolean;
}) {
  const now = Date.now();
  pushPendingLocalUpdate({
    id: `receipt_${params.id}_${now}_${Math.random().toString(36).slice(2, 6)}`,
    type: 'delivery_receipt',
    messageId: params.id,
    clientMessageId: params.clientMessageId,
    telegramMessageId: params.telegramMessageId,
    chatId: params.chatId,
    accountId: params.accountId,
    sender: 'me',
    senderName: '我方',
    text: params.error || params.queuePauseReason || '',
    timestamp: new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    createdAt: now,
    deliveryStatus: params.deliveryStatus,
    queuePauseReason: params.queuePauseReason,
    floodWaitUntil: params.floodWaitUntil,
    dialogState: params.dialogState,
    peerFloodRestricted: params.peerFlood || undefined,
    error: params.error,
  });
}

function emitAccountFloodStateUpdate(params: {
  accountId: string;
  floodWaitUntil: number;
  retryAfterSeconds: number;
  method?: string;
}) {
  const now = Date.now();
  pushPendingLocalUpdate({
    id: `flood_${params.accountId}_${now}_${Math.random().toString(36).slice(2, 6)}`,
    type: 'flood_state',
    chatId: '',
    accountId: params.accountId,
    sender: 'system',
    senderName: 'Telegram 系统',
    text: `触发限流，需等待 ${params.retryAfterSeconds}s`,
    timestamp: new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    createdAt: now,
    floodWaitUntil: params.floodWaitUntil,
    retryAfterSeconds: params.retryAfterSeconds,
    floodMethod: params.method,
  });
}

function emitAccountPeerFloodUpdate(params: {
  accountId: string;
  reason: string;
}) {
  const now = Date.now();
  pushPendingLocalUpdate({
    id: `peer_flood_${params.accountId}_${now}_${Math.random().toString(36).slice(2, 6)}`,
    type: 'peer_flood',
    chatId: '',
    accountId: params.accountId,
    sender: 'system',
    senderName: 'Telegram 系统',
    text: params.reason,
    timestamp: new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    createdAt: now,
    peerFloodRestricted: true,
    peerFloodReason: params.reason,
  });
}

async function persistOutboundStatusUpdate(params: {
  item: OutboundQueueItem;
  deliveryStatus: 'pending' | 'delivered' | 'paused' | 'failed';
  telegramMessageId?: number;
  queuePauseReason?: string | null;
  floodWaitUntil?: number | null;
}) {
  const { item, deliveryStatus, telegramMessageId, queuePauseReason, floodWaitUntil } = params;
  recordOutboundClientMessageState({
    id: item.id,
    clientMessageId: item.clientMessageId || '',
    accountId: item.effectiveAccountId,
    chatId: item.canonicalChatId,
    status: deliveryStatus,
    telegramMessageId,
    queuePauseReason: queuePauseReason || undefined,
    floodWaitUntil: floodWaitUntil || undefined,
    payload: item.payload,
    updatedAt: Date.now(),
  });
  if (!item.chatId) return;
  await upsertSyncedMessageToDb(
    cloneOutboundPayloadPreservingDiskSymbol(item.payload, {
      id: item.id,
      clientMessageId: item.clientMessageId,
      sender: item.payload?.sender || 'me',
      accountId: item.effectiveAccountId,
      deliveryStatus,
      queuePauseReason: queuePauseReason ?? null,
      floodWaitUntil: floodWaitUntil ?? null,
      telegramMessageId: telegramMessageId ?? item.payload?.telegramMessageId,
    }),
    String(item.chatId),
    item.effectiveAccountId,
    { priority: 'HIGH', source: 'outbound_scheduler' }
  ).catch(() => false);
}

async function pauseOutboundItem(
  item: OutboundQueueItem,
  reason: string,
  floodWaitUntil?: number
): Promise<OutboundDeliveryResult> {
  await persistOutboundStatusUpdate({
    item,
    deliveryStatus: 'paused',
    queuePauseReason: reason,
    floodWaitUntil: floodWaitUntil ?? null,
  });
  if (item.asyncQueue) {
    emitOutboundReceiptUpdate({
      id: item.id,
      clientMessageId: item.clientMessageId,
      chatId: item.canonicalChatId,
      accountId: item.effectiveAccountId,
      deliveryStatus: 'paused',
      queuePauseReason: reason,
      floodWaitUntil,
      error: reason,
    });
  }
  const result: OutboundDeliveryResult = {
    delivered: false,
    channel: 'mtproto',
    deliveryStatus: 'paused',
    queuePauseReason: reason,
    floodWait: Boolean(floodWaitUntil),
    floodWaitUntil,
    retryAfterSeconds: floodWaitUntil ? Math.max(1, Math.ceil((floodWaitUntil - Date.now()) / 1000)) : undefined,
    clientMessageId: item.clientMessageId,
    error: reason,
  };
  item.resolve(result);
  return result;
}

async function pauseExcessiveQueuedItemsForAccount(
  account: OutboundAccountSchedulerState,
  reason: string,
  floodWaitUntil?: number
): Promise<void> {
  const maxAgeMs = outboundRuntimeConfig.outboundMaxQueueAgeSec * 1000;
  const now = Date.now();
  const targetUntil = floodWaitUntil && floodWaitUntil > now ? floodWaitUntil : now;
  const waitSec = Math.max(0, Math.ceil((targetUntil - now) / 1000));
  const pauseAll = waitSec > outboundRuntimeConfig.floodWaitAutoWaitMaxSec;

  for (const q of account.queues.values()) {
    const keep: OutboundQueueItem[] = [];
    for (const qItem of q.items) {
      if (pauseAll || targetUntil - qItem.enqueuedAt > maxAgeMs) {
        await pauseOutboundItem(qItem, reason, floodWaitUntil);
      } else {
        keep.push(qItem);
      }
    }
    q.items = keep;
  }
}

function scheduleOutboundDrain(accountKey: string, delayMs = 0) {
  const account = outboundAccountSchedulers.get(accountKey);
  if (!account) return;
  if (account.drainTimer) {
    clearTimeout(account.drainTimer);
    account.drainTimer = null;
  }
  const hasQueued = Array.from(account.queues.values()).some((q) => !q.inFlight && q.items.length > 0);
  if (!hasQueued) return;
  account.drainTimer = setTimeout(() => {
    account.drainTimer = null;
    void drainOutboundAccountScheduler(accountKey);
  }, Math.max(0, delayMs));
}

async function executeQueuedOutboundItem(account: OutboundAccountSchedulerState, q: OutboundChatQueueState, item: OutboundQueueItem) {
  const now = Date.now();
  const ageSec = (now - item.enqueuedAt) / 1000;
  if (ageSec > outboundRuntimeConfig.outboundMaxQueueAgeSec) {
    q.inFlight = false;
    if (item.isMedia) account.mediaInFlight = false;
    await pauseOutboundItem(
      item,
      `排队等待超过 ${outboundRuntimeConfig.outboundMaxQueueAgeSec} 秒，已自动暂停以避免过时消息误发`
    );
    scheduleOutboundDrain(account.accountKey, 0);
    return;
  }

  try {
    const activeCooldown = getTelegramFloodCooldown({ accountId: item.effectiveAccountId });
    const effectiveFloodUntil = Math.max(account.floodWaitUntil || 0, activeCooldown?.floodWaitUntil || 0);
    if (effectiveFloodUntil > now) {
      const remainSec = Math.max(1, Math.ceil((effectiveFloodUntil - now) / 1000));
      const projectedAgeSec = (effectiveFloodUntil - item.enqueuedAt) / 1000;
      if (
        remainSec > outboundRuntimeConfig.floodWaitAutoWaitMaxSec ||
        projectedAgeSec > outboundRuntimeConfig.outboundMaxQueueAgeSec
      ) {
        q.inFlight = false;
        if (item.isMedia) account.mediaInFlight = false;
        const reason =
          remainSec > outboundRuntimeConfig.floodWaitAutoWaitMaxSec
            ? `Telegram 限流等待 ${remainSec}s（超过 ${outboundRuntimeConfig.floodWaitAutoWaitMaxSec}s 阈值），已暂停等待手动确认`
            : `预计限流后排队总时长将超过 ${outboundRuntimeConfig.outboundMaxQueueAgeSec}s，已暂停等待手动确认`;
        await pauseOutboundItem(item, reason, effectiveFloodUntil);
        await pauseExcessiveQueuedItemsForAccount(account, reason, effectiveFloodUntil);
        scheduleOutboundDrain(account.accountKey, 0);
        return;
      }
      // Within auto-wait threshold
      if (item.asyncQueue) {
        q.items.unshift(item);
        q.inFlight = false;
        if (item.isMedia) account.mediaInFlight = false;
        account.floodWaitUntil = effectiveFloodUntil;
        emitAccountFloodStateUpdate({
          accountId: item.effectiveAccountId,
          floodWaitUntil: effectiveFloodUntil,
          retryAfterSeconds: remainSec,
        });
        scheduleOutboundDrain(account.accountKey, effectiveFloodUntil - now);
        return;
      }
    }

    const deliverFn = item.deliverFn || deliverOutboundTelegramMessage;
    const res = await deliverFn(item.payload, item.effectiveAccountId, item.id);
    const doneAt = Date.now();

    if (res.peerFlood) {
      emitAccountPeerFloodUpdate({
        accountId: item.effectiveAccountId,
        reason: res.error || '触发 Telegram PEER_FLOOD 限制，已停止向陌生人/非联系人发送',
      });
      // Immediately fail any other queued non-contact private DMs for this account
      const conn = resolveConnectedTelegramUser(item.effectiveAccountId);
      for (const otherQ of account.queues.values()) {
        if (otherQ.isGroup || otherQ.items.length === 0) continue;
        const known = await isKnownContactOrGroupPeer(conn, otherQ.chatId);
        if (!known) {
          const cancelled = otherQ.items.splice(0);
          for (const cItem of cancelled) {
            await persistOutboundStatusUpdate({
              item: cItem,
              deliveryStatus: 'failed',
            });
            if (cItem.asyncQueue) {
              emitOutboundReceiptUpdate({
                id: cItem.id,
                clientMessageId: cItem.clientMessageId,
                chatId: cItem.canonicalChatId,
                accountId: cItem.effectiveAccountId,
                deliveryStatus: 'failed',
                peerFlood: true,
                error: res.error,
              });
            }
            cItem.resolve({
              delivered: false,
              channel: 'mtproto',
              deliveryStatus: 'failed',
              peerFlood: true,
              clientMessageId: cItem.clientMessageId,
              error: res.error,
            });
          }
        }
      }
      await persistOutboundStatusUpdate({
        item,
        deliveryStatus: 'failed',
      });
      if (item.asyncQueue) {
        emitOutboundReceiptUpdate({
          id: item.id,
          clientMessageId: item.clientMessageId,
          chatId: item.canonicalChatId,
          accountId: item.effectiveAccountId,
          deliveryStatus: 'failed',
          peerFlood: true,
          error: res.error,
        });
      }
      item.resolve({
        ...res,
        deliveryStatus: 'failed',
        clientMessageId: item.clientMessageId,
      });
      return;
    }

    if (res.floodWait) {
      const waitSec = Math.max(1, Number(res.retryAfterSeconds || 1));
      const floodUntil = res.floodWaitUntil || doneAt + waitSec * 1000;
      account.floodWaitUntil = Math.max(account.floodWaitUntil, floodUntil);
      const projectedAgeSec = (floodUntil - item.enqueuedAt) / 1000;
      const shouldPause =
        waitSec > outboundRuntimeConfig.floodWaitAutoWaitMaxSec ||
        projectedAgeSec > outboundRuntimeConfig.outboundMaxQueueAgeSec;

      emitAccountFloodStateUpdate({
        accountId: item.effectiveAccountId,
        floodWaitUntil: floodUntil,
        retryAfterSeconds: waitSec,
      });

      if (shouldPause) {
        const reason =
          waitSec > outboundRuntimeConfig.floodWaitAutoWaitMaxSec
            ? `Telegram 限流等待 ${waitSec}s（超过 ${outboundRuntimeConfig.floodWaitAutoWaitMaxSec}s 阈值），已暂停等待手动确认`
            : `预计限流后排队总时长将超过 ${outboundRuntimeConfig.outboundMaxQueueAgeSec}s，已暂停等待手动确认`;
        await pauseOutboundItem(item, reason, floodUntil);
        await pauseExcessiveQueuedItemsForAccount(account, reason, floodUntil);
        return;
      }

      if (item.asyncQueue) {
        // Auto-wait: keep message in front of its FIFO queue & update flood_wait_until
        q.items.unshift(item);
        await persistOutboundStatusUpdate({
          item,
          deliveryStatus: 'pending',
          floodWaitUntil: floodUntil,
        });
        emitOutboundReceiptUpdate({
          id: item.id,
          clientMessageId: item.clientMessageId,
          chatId: item.canonicalChatId,
          accountId: item.effectiveAccountId,
          deliveryStatus: 'pending',
          floodWaitUntil: floodUntil,
        });
        return;
      }

      // Synchronous non-async caller within threshold: return 429 floodWait immediately rather than blocking HTTP request
      await persistOutboundStatusUpdate({
        item,
        deliveryStatus: 'failed',
        floodWaitUntil: floodUntil,
      });
      item.resolve({
        ...res,
        deliveryStatus: 'failed',
        clientMessageId: item.clientMessageId,
      });
      return;
    }

    if (res.delivered) {
      if (q.isGroup) {
        const sameGroupDelay = randomIntBetween(
          outboundRuntimeConfig.sameGroupGapMinMs,
          outboundRuntimeConfig.sameGroupGapMaxMs
        );
        q.nextAllowedAt = Math.max(q.nextAllowedAt, doneAt + sameGroupDelay);
      }
      await persistOutboundStatusUpdate({
        item,
        deliveryStatus: 'delivered',
        telegramMessageId: res.telegramMessageId,
        queuePauseReason: null,
        floodWaitUntil: null,
      });
      if (item.asyncQueue) {
        emitOutboundReceiptUpdate({
          id: item.id,
          clientMessageId: item.clientMessageId,
          chatId: item.canonicalChatId,
          accountId: item.effectiveAccountId,
          deliveryStatus: 'delivered',
          telegramMessageId: res.telegramMessageId,
          dialogState: res.dialogState,
        });
      }
      item.resolve({
        ...res,
        deliveryStatus: 'delivered',
        clientMessageId: item.clientMessageId,
      });
      return;
    }

    await persistOutboundStatusUpdate({
      item,
      deliveryStatus: 'failed',
      queuePauseReason: null,
      floodWaitUntil: null,
    });
    if (item.asyncQueue) {
      emitOutboundReceiptUpdate({
        id: item.id,
        clientMessageId: item.clientMessageId,
        chatId: item.canonicalChatId,
        accountId: item.effectiveAccountId,
        deliveryStatus: 'failed',
        error: res.error,
      });
    }
    item.resolve({
      ...res,
      deliveryStatus: 'failed',
      clientMessageId: item.clientMessageId,
    });
  } finally {
    q.inFlight = false;
    if (item.isMedia) {
      account.mediaInFlight = false;
    }
    scheduleOutboundDrain(account.accountKey, 0);
  }
}

async function drainOutboundAccountScheduler(accountKey: string) {
  const account = outboundAccountSchedulers.get(accountKey);
  if (!account) return;
  const now = Date.now();

  if (account.floodWaitUntil > now) {
    scheduleOutboundDrain(accountKey, account.floodWaitUntil - now);
    return;
  }

  let pickedQueue: OutboundChatQueueState | null = null;
  let earliestWaitAt = Number.POSITIVE_INFINITY;

  const accountGateAt = account.nextAnyDispatchAt;

  // 1. Private chat priority preemption (zero per-chat artificial delay)
  for (const q of account.queues.values()) {
    if (q.isGroup || q.inFlight || q.items.length === 0) continue;
    const head = q.items[0];
    if (head.isMedia && account.mediaInFlight) continue;
    if (now >= accountGateAt) {
      pickedQueue = q;
      break;
    }
    earliestWaitAt = Math.min(earliestWaitAt, accountGateAt);
  }

  // 2. Round-robin across group chat queues when no private queue is eligible
  if (!pickedQueue && account.groupOrder.length > 0) {
    const totalGroups = account.groupOrder.length;
    for (let offset = 0; offset < totalGroups; offset++) {
      const idx = (account.groupCursor + offset) % totalGroups;
      const gKey = account.groupOrder[idx];
      const q = account.queues.get(gKey);
      if (!q || !q.isGroup || q.inFlight || q.items.length === 0) continue;
      const head = q.items[0];
      if (head.isMedia && account.mediaInFlight) continue;
      const readyAt = Math.max(q.nextAllowedAt, account.nextGroupDispatchAt, accountGateAt);
      if (now >= readyAt) {
        pickedQueue = q;
        account.groupCursor = (idx + 1) % totalGroups;
        break;
      }
      earliestWaitAt = Math.min(earliestWaitAt, readyAt);
    }
  }

  if (!pickedQueue) {
    if (Number.isFinite(earliestWaitAt) && earliestWaitAt > now) {
      scheduleOutboundDrain(accountKey, earliestWaitAt - now);
    }
    return;
  }

  const nextItem = pickedQueue.items.shift()!;
  pickedQueue.inFlight = true;
  if (nextItem.isMedia) {
    account.mediaInFlight = true;
  }

  const dispatchNow = Date.now();
  const minGap = randomIntBetween(
    outboundRuntimeConfig.accountMinGapMinMs,
    outboundRuntimeConfig.accountMinGapMaxMs
  );
  account.nextAnyDispatchAt = Math.max(account.nextAnyDispatchAt, dispatchNow + minGap);

  if (pickedQueue.isGroup) {
    const crossGroupGap = randomIntBetween(
      outboundRuntimeConfig.crossGroupGapMinMs,
      outboundRuntimeConfig.crossGroupGapMaxMs
    );
    account.nextGroupDispatchAt = Math.max(account.nextGroupDispatchAt, dispatchNow + crossGroupGap);
    const sameGroupDelay = randomIntBetween(
      outboundRuntimeConfig.sameGroupGapMinMs,
      outboundRuntimeConfig.sameGroupGapMaxMs
    );
    pickedQueue.nextAllowedAt = Math.max(pickedQueue.nextAllowedAt, dispatchNow + sameGroupDelay);
  }

  void executeQueuedOutboundItem(account, pickedQueue, nextItem);
  // Check immediately if another non-blocked queue (e.g. private chat / another group) can prepare its next timer
  scheduleOutboundDrain(accountKey, 1);
}

export async function enqueueOutboundDelivery(params: {
  id: string;
  clientMessageId?: string;
  effectiveAccountId: string;
  payload: Record<string, any>;
  asyncQueue?: boolean;
  bypassIdempotency?: boolean;
  deliverFn?: typeof deliverOutboundTelegramMessage;
}): Promise<
  | { queued: true; id: string; clientMessageId?: string; duplicate: boolean; deliveryStatus: 'pending' | 'paused' | 'delivered' | 'failed'; telegramMessageId?: number; queuePauseReason?: string; floodWaitUntil?: number }
  | { queued: false; result: OutboundDeliveryResult }
> {
  const { id, clientMessageId, effectiveAccountId, payload, asyncQueue = false, bypassIdempotency = false, deliverFn } = params;
  const cleanClientMsgId = String(clientMessageId || payload?.clientMessageId || '').trim() || undefined;
  const chatId = String(payload?.chatId || '').trim();
  const canonicalChatId = canonicalizeSchedulerChatId(chatId);
  const accountKey = getOutboundAccountSchedulerKey(effectiveAccountId);

  // 1. Idempotency check by (effectiveAccountId, clientMessageId)
  if (cleanClientMsgId && !bypassIdempotency) {
    const memKey = `${effectiveAccountId}::${cleanClientMsgId}`;
    const existingMem = outboundClientMessageRecords.get(memKey);
    if (existingMem && existingMem.status !== 'failed') {
      if (asyncQueue) {
        return {
          queued: true,
          id: existingMem.id,
          clientMessageId: cleanClientMsgId,
          duplicate: true,
          deliveryStatus: existingMem.status === 'retrying' ? 'pending' : existingMem.status,
          telegramMessageId: existingMem.telegramMessageId,
          queuePauseReason: existingMem.queuePauseReason,
          floodWaitUntil: existingMem.floodWaitUntil,
        };
      }
      if (existingMem.status === 'delivered') {
        return {
          queued: false,
          result: {
            delivered: true,
            channel: 'mtproto',
            telegramMessageId: existingMem.telegramMessageId,
            deliveryStatus: 'delivered',
            clientMessageId: cleanClientMsgId,
            duplicate: true,
          },
        };
      }
    }

    try {
      const accVariants = getScopedAccountIdVariants(effectiveAccountId);
      const placeholders = accVariants.map(() => '?').join(', ');
      const existingRow = (await db
        .prepare(
          `SELECT id, delivery_status, telegram_message_id, queue_pause_reason, flood_wait_until
           FROM messages
           WHERE account_id IN (${placeholders}) AND client_message_id = ?
           LIMIT 1`
        )
        .get(...accVariants, cleanClientMsgId)) as any;
      if (existingRow && existingRow.delivery_status && existingRow.delivery_status !== 'failed') {
        const statusVal = (existingRow.delivery_status === 'retrying' ? 'pending' : existingRow.delivery_status) as
          | 'pending'
          | 'paused'
          | 'delivered'
          | 'failed';
        if (asyncQueue) {
          return {
            queued: true,
            id: existingRow.id,
            clientMessageId: cleanClientMsgId,
            duplicate: true,
            deliveryStatus: statusVal,
            telegramMessageId: existingRow.telegram_message_id ?? undefined,
            queuePauseReason: existingRow.queue_pause_reason ?? undefined,
            floodWaitUntil: existingRow.flood_wait_until ?? undefined,
          };
        }
        if (statusVal === 'delivered') {
          return {
            queued: false,
            result: {
              delivered: true,
              channel: 'mtproto',
              telegramMessageId: existingRow.telegram_message_id ?? undefined,
              deliveryStatus: 'delivered',
              clientMessageId: cleanClientMsgId,
              duplicate: true,
            },
          };
        }
      }
    } catch {}
  }

  const isExplicitBot = effectiveAccountId === 'acc_telegram_bot';
  const isTgChat = Boolean(chatId && (chatId.startsWith('tg_') || isExplicitBot));
  if (payload?.sender !== 'me' || !isTgChat) {
    const localRes = await (deliverFn || deliverOutboundTelegramMessage)(payload, effectiveAccountId, id);
    if (asyncQueue) {
      return {
        queued: true,
        id,
        clientMessageId: cleanClientMsgId,
        duplicate: false,
        deliveryStatus: localRes.delivered ? 'delivered' : 'failed',
      };
    }
    return {
      queued: false,
      result: {
        ...localRes,
        deliveryStatus: localRes.delivered ? 'delivered' : 'failed',
        clientMessageId: cleanClientMsgId,
      },
    };
  }

  const conn = resolveConnectedTelegramUser(effectiveAccountId);
  const isGroup = isTelegramGroupChatId(canonicalChatId, conn);
  const isMedia = Boolean(payload?.isImage || payload?.isVideo || payload?.isAudio || payload?.isFile);
  const storedPayload = cloneOutboundPayloadPreservingDiskSymbol(payload, {
    id,
    clientMessageId: cleanClientMsgId,
    chatId: canonicalChatId,
    accountId: effectiveAccountId,
  });

  if (asyncQueue && chatId) {
    recordOutboundClientMessageState({
      id,
      clientMessageId: cleanClientMsgId || '',
      accountId: effectiveAccountId,
      chatId: canonicalChatId,
      status: 'pending',
      payload: storedPayload,
      updatedAt: Date.now(),
    });
    await upsertSyncedMessageToDb(
      cloneOutboundPayloadPreservingDiskSymbol(storedPayload, {
        deliveryStatus: 'pending',
        queuePauseReason: null,
        floodWaitUntil: null,
      }),
      canonicalChatId,
      effectiveAccountId,
      { priority: 'HIGH', source: 'outbound_enqueue' }
    ).catch(() => false);
  }

  const deliveryPromise = new Promise<OutboundDeliveryResult>((resolve) => {
    const account = getOrCreateOutboundAccountScheduler(accountKey);
    let q = account.queues.get(canonicalChatId);
    if (!q) {
      q = {
        chatId: canonicalChatId,
        isGroup,
        inFlight: false,
        nextAllowedAt: 0,
        items: [],
      };
      account.queues.set(canonicalChatId, q);
      if (isGroup && !account.groupOrder.includes(canonicalChatId)) {
        account.groupOrder.push(canonicalChatId);
      }
    }
    q.items.push({
      id,
      clientMessageId: cleanClientMsgId,
      effectiveAccountId,
      accountKey,
      chatId,
      canonicalChatId,
      isGroup,
      isMedia,
      asyncQueue,
      payload: storedPayload,
      enqueuedAt: Date.now(),
      deliverFn,
      resolve,
    });
    scheduleOutboundDrain(accountKey, 0);
  });

  if (asyncQueue) {
    void deliveryPromise;
    return {
      queued: true,
      id,
      clientMessageId: cleanClientMsgId,
      duplicate: false,
      deliveryStatus: 'pending',
    };
  }

  const finalResult = await deliveryPromise;
  return {
    queued: false,
    result: finalResult,
  };
}

// 3. Relay Message to Telegram & Persist to Unified Conversation Store (supports streaming multipart/form-data & lightweight text JSON)
app.post('/api/messages', requireTenantAuth, parseMultipartMessageUpload, async (req: Request, res: Response) => {
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
    if (!scope.ok) {
      return res.status(scope.status).json({ success: false, code: scope.code, error: scope.error });
    }
    const msgId = req.body?.id || `msg_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
    const clientMessageId =
      typeof req.body?.clientMessageId === 'string' && req.body.clientMessageId.trim()
        ? req.body.clientMessageId.trim()
        : undefined;
    const asyncQueue = req.body?.asyncQueue === true || req.body?.asyncQueue === 'true';
    const effectiveAccountId = scope.accountId;
    const uploadedMedia = (req as any).uploadedMedia;
    const { payload: outboundPayload, mediaUrl } = applyUploadedMediaToMessagePayload(
      req.body && typeof req.body === 'object' ? req.body : {},
      uploadedMedia,
      effectiveAccountId
    );

    const enqueued = await enqueueOutboundDelivery({
      id: msgId,
      clientMessageId,
      effectiveAccountId,
      payload: outboundPayload,
      asyncQueue,
    });

    if (enqueued.queued) {
      return res.status(202).json({
        success: true,
        queued: true,
        duplicate: enqueued.duplicate,
        id: enqueued.id,
        clientMessageId: enqueued.clientMessageId,
        telegramMessageId: enqueued.telegramMessageId,
        syncedToStore: true,
        localOnly: false,
        delivered: enqueued.deliveryStatus === 'delivered',
        deliveryStatus: enqueued.deliveryStatus,
        queuePauseReason: enqueued.queuePauseReason,
        floodWaitUntil: enqueued.floodWaitUntil,
        channel: effectiveAccountId === 'acc_telegram_bot' ? 'bot' : 'mtproto',
        ...(mediaUrl ? { mediaUrl } : {}),
        ...(outboundPayload.imageUrl ? { imageUrl: outboundPayload.imageUrl } : {}),
        ...(outboundPayload.videoUrl ? { videoUrl: outboundPayload.videoUrl } : {}),
        ...(outboundPayload.audioUrl ? { audioUrl: outboundPayload.audioUrl } : {}),
        ...(outboundPayload.fileUrl ? { fileUrl: outboundPayload.fileUrl } : {}),
      });
    }

    const deliveryResult = enqueued.result;
    const deliveryStatus = deliveryResult.deliveryStatus || (deliveryResult.delivered ? 'delivered' : 'failed');

    let syncedToStore = false;
    if (outboundPayload?.chatId) {
      syncedToStore = await upsertSyncedMessageToDb(
        cloneOutboundPayloadPreservingDiskSymbol(outboundPayload, {
          id: msgId,
          clientMessageId,
          accountId: effectiveAccountId,
          deliveryStatus,
          queuePauseReason: deliveryResult.queuePauseReason ?? null,
          floodWaitUntil: deliveryResult.floodWaitUntil ?? null,
          telegramMessageId: deliveryResult.telegramMessageId ?? outboundPayload?.telegramMessageId,
        }),
        String(outboundPayload.chatId),
        effectiveAccountId,
        { priority: 'HIGH', source: 'outbound_send' }
      );
    }

    res.status(deliveryResult.sessionExpired ? 401 : deliveryResult.floodWait ? 429 : 200).json({
      success: deliveryResult.delivered,
      id: msgId,
      clientMessageId,
      duplicate: Boolean(deliveryResult.duplicate),
      telegramMessageId: deliveryResult.telegramMessageId,
      ...(deliveryResult.dialogState ? { dialogState: deliveryResult.dialogState } : {}),
      syncedToStore,
      localOnly: false,
      delivered: deliveryResult.delivered,
      deliveryStatus,
      ...(deliveryResult.queuePauseReason ? { queuePauseReason: deliveryResult.queuePauseReason } : {}),
      channel: deliveryResult.channel,
      ...(mediaUrl ? { mediaUrl } : {}),
      ...(outboundPayload.imageUrl ? { imageUrl: outboundPayload.imageUrl } : {}),
      ...(outboundPayload.videoUrl ? { videoUrl: outboundPayload.videoUrl } : {}),
      ...(outboundPayload.audioUrl ? { audioUrl: outboundPayload.audioUrl } : {}),
      ...(outboundPayload.fileUrl ? { fileUrl: outboundPayload.fileUrl } : {}),
      ...(deliveryResult.sessionExpired ? { code: 'TELEGRAM_SESSION_EXPIRED' } : {}),
      ...(deliveryResult.peerFlood ? { code: 'TELEGRAM_PEER_FLOOD', peerFlood: true } : {}),
      ...(deliveryResult.floodWait
        ? {
            code: 'TELEGRAM_FLOOD_WAIT',
            retryAfterSeconds: deliveryResult.retryAfterSeconds,
            floodWaitUntil: deliveryResult.floodWaitUntil,
          }
        : {}),
      error: deliveryResult.error,
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// 3.1 Retry Delivery of a Failed Message (Unified payload + streaming multipart/form-data + DB sync)
app.post('/api/messages/:id/retry', requireTenantAuth, parseMultipartMessageUpload, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
    if (!scope.ok) {
      return res.status(scope.status).json({ success: false, code: scope.code, error: scope.error });
    }
    const authContext = (req as any).auth;
    const effectiveAccountId = scope.accountId;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const uploadedMedia = (req as any).uploadedMedia;

    const rawBody = req.body && typeof req.body === 'object' ? req.body : null;
    const clientMsg = rawBody && rawBody.chatId ? rawBody : null;
    const asyncQueue = Boolean(rawBody?.asyncQueue === true || rawBody?.asyncQueue === 'true');
    if (clientMsg) {
      if (!isMaster && clientMsg.accountId && clientMsg.accountId !== effectiveAccountId) {
        return res.status(403).json({ error: '无权操作不属于当前账号的消息记录' });
      }
      const targetAcc = clientMsg.accountId || effectiveAccountId;
      let mergedClientMsg: Record<string, any> = { ...clientMsg };
      if (
        !uploadedMedia &&
        !mergedClientMsg.audioUrl &&
        !mergedClientMsg.imageUrl &&
        !mergedClientMsg.videoUrl &&
        !mergedClientMsg.fileUrl
      ) {
        try {
          const existingRow = (await db
            .prepare(
              'SELECT account_id, client_message_id, audio_url, image_url, video_url, file_url, file_name, file_size FROM messages WHERE id = ?'
            )
            .get(id)) as any;
          if (
            existingRow &&
            (isMaster || !existingRow.account_id || existingRow.account_id === effectiveAccountId)
          ) {
            if (!mergedClientMsg.clientMessageId && existingRow.client_message_id) {
              mergedClientMsg.clientMessageId = existingRow.client_message_id;
            }
            if (existingRow.audio_url) mergedClientMsg.audioUrl = existingRow.audio_url;
            if (existingRow.image_url) mergedClientMsg.imageUrl = existingRow.image_url;
            if (existingRow.video_url) mergedClientMsg.videoUrl = existingRow.video_url;
            if (existingRow.file_url) mergedClientMsg.fileUrl = existingRow.file_url;
            if (!mergedClientMsg.fileName && existingRow.file_name) {
              mergedClientMsg.fileName = existingRow.file_name;
            }
            if (!mergedClientMsg.fileSize && existingRow.file_size) {
              mergedClientMsg.fileSize = existingRow.file_size;
            }
          }
        } catch {}
      }
      const { payload: outboundPayload, mediaUrl } = applyUploadedMediaToMessagePayload(
        mergedClientMsg,
        uploadedMedia,
        targetAcc
      );
      const enqueued = await enqueueOutboundDelivery({
        id,
        clientMessageId: outboundPayload.clientMessageId,
        effectiveAccountId: targetAcc,
        payload: { ...outboundPayload, sender: outboundPayload.sender || 'me' },
        asyncQueue,
        bypassIdempotency: true,
      });
      if (enqueued.queued) {
        return res.status(202).json({
          success: true,
          queued: true,
          id,
          clientMessageId: enqueued.clientMessageId,
          deliveryStatus: enqueued.deliveryStatus,
          ...(mediaUrl ? { mediaUrl } : {}),
          ...(outboundPayload.imageUrl ? { imageUrl: outboundPayload.imageUrl } : {}),
          ...(outboundPayload.videoUrl ? { videoUrl: outboundPayload.videoUrl } : {}),
          ...(outboundPayload.audioUrl ? { audioUrl: outboundPayload.audioUrl } : {}),
          ...(outboundPayload.fileUrl ? { fileUrl: outboundPayload.fileUrl } : {}),
        });
      }
      const retryResult = enqueued.result;
      const nextStatus = retryResult.deliveryStatus || (retryResult.delivered ? 'delivered' : 'failed');
      await upsertSyncedMessageToDb(
        cloneOutboundPayloadPreservingDiskSymbol(outboundPayload, {
          id,
          sender: outboundPayload.sender || 'me',
          accountId: targetAcc,
          deliveryStatus: nextStatus,
          queuePauseReason: retryResult.queuePauseReason ?? null,
          floodWaitUntil: retryResult.floodWaitUntil ?? null,
          telegramMessageId: retryResult.telegramMessageId ?? outboundPayload.telegramMessageId,
        }),
        String(outboundPayload.chatId),
        targetAcc,
        { priority: 'HIGH', source: 'retry_send' }
      );
      return res.status(retryResult.sessionExpired ? 401 : retryResult.floodWait ? 429 : 200).json({
        success: retryResult.delivered,
        delivered: retryResult.delivered,
        telegramMessageId: retryResult.telegramMessageId,
        ...(retryResult.dialogState ? { dialogState: retryResult.dialogState } : {}),
        deliveryStatus: nextStatus,
        ...(mediaUrl ? { mediaUrl } : {}),
        ...(outboundPayload.imageUrl ? { imageUrl: outboundPayload.imageUrl } : {}),
        ...(outboundPayload.videoUrl ? { videoUrl: outboundPayload.videoUrl } : {}),
        ...(outboundPayload.audioUrl ? { audioUrl: outboundPayload.audioUrl } : {}),
        ...(outboundPayload.fileUrl ? { fileUrl: outboundPayload.fileUrl } : {}),
        ...(retryResult.sessionExpired ? { code: 'TELEGRAM_SESSION_EXPIRED' } : {}),
        ...(retryResult.peerFlood ? { code: 'TELEGRAM_PEER_FLOOD', peerFlood: true } : {}),
        ...(retryResult.floodWait
          ? {
              code: 'TELEGRAM_FLOOD_WAIT',
              retryAfterSeconds: retryResult.retryAfterSeconds,
              floodWaitUntil: retryResult.floodWaitUntil,
            }
          : {}),
        error: retryResult.error,
        message: retryResult.delivered ? 'Message retry delivered' : (retryResult.error || 'Message retry failed'),
      });
    }

    const msg = (await db.prepare('SELECT * FROM messages WHERE id = ?').get(id)) as any;
    if (!msg) {
      return res.status(404).json({ error: 'Message not found' });
    }

    // Tenant isolation: if not master, message must belong to effectiveAccountId
    if (!isMaster && msg.account_id && msg.account_id !== effectiveAccountId) {
      return res.status(403).json({ error: '无权操作不属于当前账号的消息记录' });
    }

    if (isMaster) {
      await db.prepare('UPDATE messages SET delivery_status = ?, queue_pause_reason = NULL, flood_wait_until = NULL WHERE id = ?').run('retrying', id);
    } else {
      await db.prepare('UPDATE messages SET delivery_status = ?, queue_pause_reason = NULL, flood_wait_until = NULL WHERE id = ? AND account_id = ?').run('retrying', id, effectiveAccountId);
    }

    const dbBasePayload = {
      clientMessageId: msg.client_message_id || undefined,
      chatId: msg.chat_id,
      accountId: msg.account_id,
      sender: msg.sender || 'me',
      text: msg.text,
      translatedText: msg.translated_text,
      isAudio: Boolean(msg.is_audio),
      audioDuration: msg.audio_duration,
      audioUrl: msg.audio_url,
      sttText: msg.stt_text,
      isImage: Boolean(msg.is_image),
      imageUrl: msg.image_url,
      imageCaption: msg.image_caption,
      isVideo: Boolean(msg.is_video),
      videoDuration: msg.video_duration,
      videoUrl: msg.video_url,
      isFile: Boolean(msg.is_file),
      fileName: msg.file_name,
      fileSize: msg.file_size,
      fileUrl: msg.file_url,
      replyTo: msg.reply_to_json ? safeJsonParse(msg.reply_to_json, undefined) : undefined,
    };
    const { payload: dbOutboundPayload, mediaUrl: dbMediaUrl } = applyUploadedMediaToMessagePayload(
      dbBasePayload,
      uploadedMedia,
      msg.account_id || effectiveAccountId
    );

    const dbEnqueued = await enqueueOutboundDelivery({
      id,
      clientMessageId: dbOutboundPayload.clientMessageId,
      effectiveAccountId: msg.account_id || effectiveAccountId,
      payload: dbOutboundPayload,
      asyncQueue,
      bypassIdempotency: true,
    });
    if (dbEnqueued.queued) {
      return res.status(202).json({
        success: true,
        queued: true,
        id,
        clientMessageId: dbEnqueued.clientMessageId,
        deliveryStatus: dbEnqueued.deliveryStatus,
        ...(dbMediaUrl ? { mediaUrl: dbMediaUrl } : {}),
        ...(dbOutboundPayload.imageUrl ? { imageUrl: dbOutboundPayload.imageUrl } : {}),
        ...(dbOutboundPayload.videoUrl ? { videoUrl: dbOutboundPayload.videoUrl } : {}),
        ...(dbOutboundPayload.audioUrl ? { audioUrl: dbOutboundPayload.audioUrl } : {}),
        ...(dbOutboundPayload.fileUrl ? { fileUrl: dbOutboundPayload.fileUrl } : {}),
      });
    }
    const dbRetryResult = dbEnqueued.result;

    const nextStatus = dbRetryResult.deliveryStatus || (dbRetryResult.delivered ? 'delivered' : 'failed');
    try {
      await enqueueMessageDbWrite({
        priority: 'HIGH',
        kind: 'upsert',
        accountId: msg.account_id || effectiveAccountId,
        chatId: msg.chat_id,
        tgMsgIds: dbRetryResult.telegramMessageId ? [Number(dbRetryResult.telegramMessageId)] : [],
        msgId: id,
        exec: async () => {
          if (isMaster) {
            await db
              .prepare(
                `UPDATE messages SET
                   delivery_status = ?,
                   queue_pause_reason = ?,
                   flood_wait_until = ?,
                   telegram_message_id = COALESCE(?, telegram_message_id),
                   audio_url = CASE WHEN ? != '' THEN ? ELSE audio_url END,
                   image_url = CASE WHEN ? != '' THEN ? ELSE image_url END,
                   video_url = CASE WHEN ? != '' THEN ? ELSE video_url END,
                   file_url = CASE WHEN ? != '' THEN ? ELSE file_url END
                 WHERE id = ?`
              )
              .run(
                nextStatus,
                dbRetryResult.queuePauseReason ?? null,
                dbRetryResult.floodWaitUntil ?? null,
                dbRetryResult.telegramMessageId ?? null,
                dbOutboundPayload.audioUrl || '',
                dbOutboundPayload.audioUrl || '',
                dbOutboundPayload.imageUrl || '',
                dbOutboundPayload.imageUrl || '',
                dbOutboundPayload.videoUrl || '',
                dbOutboundPayload.videoUrl || '',
                dbOutboundPayload.fileUrl || '',
                dbOutboundPayload.fileUrl || '',
                id
              );
          } else {
            await db
              .prepare(
                `UPDATE messages SET
                   delivery_status = ?,
                   queue_pause_reason = ?,
                   flood_wait_until = ?,
                   telegram_message_id = COALESCE(?, telegram_message_id),
                   audio_url = CASE WHEN ? != '' THEN ? ELSE audio_url END,
                   image_url = CASE WHEN ? != '' THEN ? ELSE image_url END,
                   video_url = CASE WHEN ? != '' THEN ? ELSE video_url END,
                   file_url = CASE WHEN ? != '' THEN ? ELSE file_url END
                 WHERE id = ? AND account_id = ?`
              )
              .run(
                nextStatus,
                dbRetryResult.queuePauseReason ?? null,
                dbRetryResult.floodWaitUntil ?? null,
                dbRetryResult.telegramMessageId ?? null,
                dbOutboundPayload.audioUrl || '',
                dbOutboundPayload.audioUrl || '',
                dbOutboundPayload.imageUrl || '',
                dbOutboundPayload.imageUrl || '',
                dbOutboundPayload.videoUrl || '',
                dbOutboundPayload.videoUrl || '',
                dbOutboundPayload.fileUrl || '',
                dbOutboundPayload.fileUrl || '',
                id,
                effectiveAccountId
              );
          }
        },
      });
    } catch {}

    res.status(dbRetryResult.sessionExpired ? 401 : dbRetryResult.floodWait ? 429 : 200).json({
      success: dbRetryResult.delivered,
      delivered: dbRetryResult.delivered,
      telegramMessageId: dbRetryResult.telegramMessageId,
      ...(dbRetryResult.dialogState ? { dialogState: dbRetryResult.dialogState } : {}),
      deliveryStatus: nextStatus,
      ...(dbMediaUrl ? { mediaUrl: dbMediaUrl } : {}),
      ...(dbOutboundPayload.imageUrl ? { imageUrl: dbOutboundPayload.imageUrl } : {}),
      ...(dbOutboundPayload.videoUrl ? { videoUrl: dbOutboundPayload.videoUrl } : {}),
      ...(dbOutboundPayload.audioUrl ? { audioUrl: dbOutboundPayload.audioUrl } : {}),
      ...(dbOutboundPayload.fileUrl ? { fileUrl: dbOutboundPayload.fileUrl } : {}),
      ...(dbRetryResult.sessionExpired ? { code: 'TELEGRAM_SESSION_EXPIRED' } : {}),
      ...(dbRetryResult.peerFlood ? { code: 'TELEGRAM_PEER_FLOOD', peerFlood: true } : {}),
      ...(dbRetryResult.floodWait
        ? {
            code: 'TELEGRAM_FLOOD_WAIT',
            retryAfterSeconds: dbRetryResult.retryAfterSeconds,
            floodWaitUntil: dbRetryResult.floodWaitUntil,
          }
        : {}),
      error: dbRetryResult.error,
      message: dbRetryResult.delivered ? 'Message retry delivered' : (dbRetryResult.error || 'Message retry failed'),
    });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

// 3.1a Resume a paused outbound message (after FLOOD_WAIT > maxWait or queue age > maxAge)
app.post('/api/messages/:id/resume', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
    if (!scope.ok) {
      return res.status(scope.status).json({ success: false, code: scope.code, error: scope.error });
    }
    const authContext = (req as any).auth;
    const effectiveAccountId = scope.accountId;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const accVariants = getScopedAccountIdVariants(effectiveAccountId);

    const msg = (await db.prepare('SELECT * FROM messages WHERE id = ?').get(id)) as any;
    if (!msg) {
      return res.status(404).json({ success: false, error: 'Message not found' });
    }
    if (!isMaster && msg.account_id && !accVariants.includes(String(msg.account_id))) {
      return res.status(403).json({ success: false, error: '无权操作不属于当前账号的消息记录' });
    }

    const targetAccountId = String(msg.account_id || effectiveAccountId);
    const memRec = msg.client_message_id
      ? outboundClientMessageRecords.get(`${targetAccountId}::${msg.client_message_id}`)
      : undefined;

    const resumePayload = cloneOutboundPayloadPreservingDiskSymbol(
      memRec?.payload || {
        id: msg.id,
        clientMessageId: msg.client_message_id || undefined,
        chatId: msg.chat_id,
        accountId: targetAccountId,
        sender: msg.sender || 'me',
        text: msg.text,
        translatedText: msg.translated_text,
        isAudio: Boolean(msg.is_audio),
        audioDuration: msg.audio_duration,
        audioUrl: msg.audio_url,
        sttText: msg.stt_text,
        isImage: Boolean(msg.is_image),
        imageUrl: msg.image_url,
        imageCaption: msg.image_caption,
        isVideo: Boolean(msg.is_video),
        videoDuration: msg.video_duration,
        videoUrl: msg.video_url,
        isFile: Boolean(msg.is_file),
        fileName: msg.file_name,
        fileSize: msg.file_size,
        fileUrl: msg.file_url,
        replyTo: msg.reply_to_json ? safeJsonParse(msg.reply_to_json, undefined) : undefined,
      }
    );

    const asyncQueue = req.body?.asyncQueue !== false;
    const enqueued = await enqueueOutboundDelivery({
      id: msg.id,
      clientMessageId: msg.client_message_id || undefined,
      effectiveAccountId: targetAccountId,
      payload: resumePayload,
      asyncQueue,
      bypassIdempotency: true,
    });

    if (enqueued.queued) {
      return res.status(202).json({
        success: true,
        queued: true,
        id: msg.id,
        clientMessageId: msg.client_message_id || undefined,
        deliveryStatus: 'pending',
      });
    }
    return res.json({
      success: enqueued.result.delivered,
      delivered: enqueued.result.delivered,
      deliveryStatus: enqueued.result.deliveryStatus || (enqueued.result.delivered ? 'delivered' : 'failed'),
      telegramMessageId: enqueued.result.telegramMessageId,
      error: enqueued.result.error,
    });
  } catch (err: any) {
    return res.status(500).json({ success: false, error: err?.message || '继续发送失败' });
  }
});

// 3.1b Discard a paused/unsent outbound message from queue & DB
app.post('/api/messages/:id/discard', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
    if (!scope.ok) {
      return res.status(scope.status).json({ success: false, code: scope.code, error: scope.error });
    }
    const authContext = (req as any).auth;
    const effectiveAccountId = scope.accountId;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const accVariants = getScopedAccountIdVariants(effectiveAccountId);

    const msg = (await db.prepare('SELECT id, account_id, chat_id, client_message_id, delivery_status FROM messages WHERE id = ?').get(id)) as any;
    if (!msg) {
      return res.status(404).json({ success: false, error: 'Message not found' });
    }
    if (!isMaster && msg.account_id && !accVariants.includes(String(msg.account_id))) {
      return res.status(403).json({ success: false, error: '无权操作不属于当前账号的消息记录' });
    }
    if (msg.delivery_status === 'delivered') {
      return res.status(400).json({ success: false, error: '已成功送达的消息无法通过丢弃队列接口移除' });
    }

    const targetAccountId = String(msg.account_id || effectiveAccountId);
    const accountKey = getOutboundAccountSchedulerKey(targetAccountId);
    const scheduler = outboundAccountSchedulers.get(accountKey);
    if (scheduler) {
      for (const q of scheduler.queues.values()) {
        q.items = q.items.filter((qItem) => qItem.id !== id);
      }
    }
    if (msg.client_message_id) {
      outboundClientMessageRecords.delete(`${targetAccountId}::${msg.client_message_id}`);
    }

    await db.prepare('DELETE FROM messages WHERE id = ?').run(id);
    return res.json({ success: true, discarded: true, id, chatId: msg.chat_id });
  } catch (err: any) {
    return res.status(500).json({ success: false, error: err?.message || '丢弃消息失败' });
  }
});

// Helper: Build chat-scoped realtime Telegram message ID (prevents channel/supergroup message.id collisions)
export function buildTelegramRealtimeMessageId(userId: string, chatId: string, messageId: number | string): string {
  const cleanUser = String(userId || 'user').trim() || 'user';
  const rawChat = String(chatId || 'unknown').trim() || 'unknown';
  const canonicalChat = rawChat.startsWith('tg_') || rawChat.startsWith('chat_') ? rawChat : `tg_${rawChat}`;
  return `msg_tg_${cleanUser}_${canonicalChat}_${messageId}`;
}

export function extractEmbeddedChatIdFromMessageId(messageId?: string): string | null {
  const raw = String(messageId || '').trim();
  // Format: msg_tg_${userId}_${chatId}_${msgId} (supports chatId like tg_-100123, -100123, 12345, username)
  const match = raw.match(/^msg_tg_[^_]+_(.+)_(\d+)$/);
  if (!match) return null;
  const candidateChat = match[1].trim();
  if (!candidateChat) return null;
  return candidateChat.startsWith('tg_') || candidateChat.startsWith('chat_') ? candidateChat : `tg_${candidateChat}`;
}

export function isSameCanonicalChatId(chatIdA?: string, chatIdB?: string): boolean {
  const normA = String(chatIdA || '').trim().replace(/^tg_/, '');
  const normB = String(chatIdB || '').trim().replace(/^tg_/, '');
  return Boolean(normA && normB && normA === normB);
}

// Helper: Extract integer Telegram message ID from explicit field or known message ID formats
export function resolveTelegramMessageNumericId(messageId?: string, explicitTelegramMessageId?: number | string): number | null {
  if (explicitTelegramMessageId !== undefined && explicitTelegramMessageId !== null && explicitTelegramMessageId !== '') {
    const n = Number(explicitTelegramMessageId);
    if (Number.isInteger(n) && n > 0) return n;
  }
  const raw = String(messageId || '').trim();
  const cloudMatch = raw.match(/^tg_cloud_(\d+)(?:_|$)/);
  if (cloudMatch) return Number(cloudMatch[1]);
  const msgTgMatch = raw.match(/^msg_tg_(?:.+_)?(\d+)$/);
  if (msgTgMatch) return Number(msgTgMatch[1]);
  const tgNumericMatch = raw.match(/^tg_(\d+)_\d+$/);
  if (tgNumericMatch) return Number(tgNumericMatch[1]);
  return null;
}

// Helper: Resolve GramJS InputPeer and raw peer target from canonical chatId
async function resolveTelegramInputPeer(
  client: TelegramClient,
  rawChatId: string,
  selfUserId?: string,
  priority: TelegramRpcPriority = 'P1'
): Promise<{ inputPeer: Api.TypeInputPeer; rawPeer: any }> {
  const clean = String(rawChatId || '').replace(/^tg_/, '').trim();
  if (!clean || clean === 'me' || (selfUserId && clean === selfUserId)) {
    return { inputPeer: new Api.InputPeerSelf(), rawPeer: 'me' };
  }
  const rpcScope = selfUserId ? `acc_tg_${selfUserId}` : 'global';
  const rawPeer: any = /^-?\d+$/.test(clean) ? Number(clean) : clean;
  try {
    const inputPeer = await scheduleTelegramRpc(rpcScope, priority, 'resolveInputPeer', () =>
      client.getInputEntity(rawPeer)
    );
    return { inputPeer, rawPeer };
  } catch {
    // Refresh dialog entity cache once before failing (protected by FLOOD_WAIT breaker & in-flight dedup)
    await refreshDialogEntityCacheSafely(client, 60);
    try {
      const inputPeer = await scheduleTelegramRpc(rpcScope, priority, 'resolveInputPeer', () =>
        client.getInputEntity(rawPeer)
      );
      return { inputPeer, rawPeer };
    } catch {
      await refreshDialogEntityCacheSafely(client, 150, true);
      const inputPeer = await scheduleTelegramRpc(rpcScope, priority, 'resolveInputPeer', () =>
        client.getInputEntity(rawPeer)
      );
      return { inputPeer, rawPeer };
    }
  }
}

// 3.2 Delete Message by ID (Real Telegram Cloud Revoke + Strict chatId/accountId DB Cleanup)
app.delete('/api/messages/:id', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const authContext = (req as any).auth;
    const claimedAccountId = String((req.query.accountId as string) || (req.headers['x-account-id'] as string) || '').trim();
    const effectiveAccountId = authContext?.effectiveAccountId || claimedAccountId || 'acc_1';
    const isMaster = Boolean(authContext?.session?.isMaster);
    const requestedChatId = String((req.query.chatId as string) || '').trim();
    const accVariants = getScopedAccountIdVariants(effectiveAccountId);
    const enforceAccountScope = !isMaster || Boolean(claimedAccountId);

    const embeddedChatId = extractEmbeddedChatIdFromMessageId(id);
    if (requestedChatId && embeddedChatId && !isSameCanonicalChatId(requestedChatId, embeddedChatId)) {
      return res.status(403).json({
        success: false,
        deleted: false,
        error: '消息 ID 所属会话与当前请求 chatId 不一致，已阻止跨会话误删',
      });
    }

    const msg = (await db.prepare('SELECT * FROM messages WHERE id = ?').get(id)) as any;
    if (msg) {
      if (enforceAccountScope && msg.account_id && !accVariants.includes(String(msg.account_id))) {
        return res.status(403).json({
          success: false,
          deleted: false,
          error: '无权删除不属于当前账号的消息记录',
        });
      }
      if (requestedChatId && msg.chat_id && !isSameCanonicalChatId(requestedChatId, msg.chat_id)) {
        return res.status(403).json({
          success: false,
          deleted: false,
          error: '消息所属会话与当前请求 chatId 不一致，已阻止跨会话误删',
        });
      }
    }

    const chatId = requestedChatId || String(msg?.chat_id || embeddedChatId || '').trim();
    const explicitTgId = req.query.telegramMessageId as string | undefined;
    const tgMsgId = resolveTelegramMessageNumericId(id, explicitTgId ?? msg?.telegram_message_id);
    const revoke = req.query.revoke === 'false' || req.query.revoke === '0' ? false : true;
    const isLocalOnlyRequested = req.query.localOnly === 'true' || req.query.localOnly === '1';

    const isTelegramChat = Boolean(chatId.startsWith('tg_') || effectiveAccountId.startsWith('acc_tg_') || effectiveAccountId === 'acc_telegram_bot');
    const isLocalFailedOrDraft = Boolean(
      !tgMsgId && (isLocalOnlyRequested || msg?.delivery_status === 'failed' || msg?.delivery_status === 'pending' || String(id).startsWith('msg_'))
    );
    let cloudSynced = false;

    if (isTelegramChat && !isLocalFailedOrDraft) {
      if (!tgMsgId) {
        return res.status(400).json({
          success: false,
          deleted: false,
          error: '该消息缺少 Telegram 云端消息 ID，无法从 Telegram 服务器撤回删除',
        });
      }
      if (!chatId) {
        return res.status(400).json({
          success: false,
          deleted: false,
          error: '缺少有效的会话 chatId，无法确定要撤回的目标会话',
        });
      }

      if (effectiveAccountId === 'acc_telegram_bot' && process.env.TELEGRAM_BOT_TOKEN) {
        const cleanChatId = chatId.replace(/^tg_/, '');
        const botRes = await fetch(`https://api.telegram.org/bot${process.env.TELEGRAM_BOT_TOKEN}/deleteMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ chat_id: /^-?\d+$/.test(cleanChatId) ? Number(cleanChatId) : cleanChatId, message_id: tgMsgId }),
        });
        const botJson: any = await botRes.json();
        if (!botJson.ok) {
          return res.status(502).json({
            success: false,
            deleted: false,
            error: botJson.description || 'Telegram Bot 撤回消息失败（Bot 仅能撤回 48 小时内消息或需管理员删帖权限）',
          });
        }
        cloudSynced = true;
      } else {
        const connected = resolveConnectedTelegramUser(effectiveAccountId);
        if (!connected || !connected.client) {
          return res.status(400).json({
            success: false,
            deleted: false,
            error: '当前账号未在线连接 Telegram MTProto，无法从云端撤回删除消息',
          });
        }
        const { inputPeer } = await resolveTelegramInputPeer(connected.client, chatId, connected.userId, 'P0');
        await scheduleTelegramRpc(effectiveAccountId, 'P0', 'messages.DeleteMessages', () =>
          connected.client.deleteMessages(inputPeer, [tgMsgId], { revoke })
        );
        cloudSynced = true;
      }
    }

    let changes = 0;
    const altChatId = chatId ? (chatId.startsWith('tg_') ? chatId.replace(/^tg_/, '') : `tg_${chatId}`) : '';
    const accPlaceholders = accVariants.map(() => '?').join(', ');
    const isChannelChat = Boolean(chatId && (chatId.startsWith('tg_-100') || chatId.startsWith('-100')));

    changes = await enqueueMessageDbWrite<number>({
      priority: 'HIGH',
      kind: isChannelChat ? 'delete_channel' : 'delete_non_channel',
      accountId: effectiveAccountId,
      chatId,
      tgMsgIds: tgMsgId ? [tgMsgId] : [],
      msgId: id,
      exec: async () => {
        let totalDel = 0;
        if (msg) {
          const whereParts = ['id = ?'];
          const params: any[] = [id];
          if (chatId) {
            whereParts.push('(chat_id = ? OR chat_id = ?)');
            params.push(chatId, altChatId);
          }
          if (enforceAccountScope) {
            whereParts.push(`account_id IN (${accPlaceholders})`);
            params.push(...accVariants);
          }
          const result = await db.prepare(`DELETE FROM messages WHERE ${whereParts.join(' AND ')}`).run(...params);
          totalDel += (result as any)?.changes ?? 0;
        }
        if (tgMsgId && chatId) {
          const whereParts = ['(chat_id = ? OR chat_id = ?)', 'telegram_message_id = ?'];
          const params: any[] = [chatId, altChatId, tgMsgId];
          if (enforceAccountScope) {
            whereParts.push(`account_id IN (${accPlaceholders})`);
            params.push(...accVariants);
          }
          const result = await db.prepare(`DELETE FROM messages WHERE ${whereParts.join(' AND ')}`).run(...params);
          totalDel += (result as any)?.changes ?? 0;
        }
        return totalDel;
      },
    });

    res.json({ success: true, deleted: true, cloudSynced, revoke, id, changes });
  } catch (err: any) {
    res.status(500).json({ success: false, deleted: false, error: formatTelegramError(err) });
  }
});

// 3.5 Persist translatedText & sttText update (for inbound auto-translation, manual retranslation & voice STT)
app.patch('/api/messages/:id/translation', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const {
      translatedText,
      sttText,
      chatId: rawChatId,
      telegramMessageId: rawTgId,
      accountId: rawAccountId,
    } = req.body || {};
    const hasTranslatedText = typeof translatedText === 'string';
    const hasSttText = typeof sttText === 'string';
    if (!hasTranslatedText && !hasSttText) {
      return res.status(400).json({ ok: false, error: 'translatedText 或 sttText 至少需提供一项字符串' });
    }
    const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
    }
    const authContext = (req as any).auth;
    const effectiveAccountId = scope.accountId;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const enforceAccountScope = !isMaster || scope.isExplicit;
    const accVariants = getScopedAccountIdVariants(effectiveAccountId);
    if ((effectiveAccountId === 'acc_telegram_bot' || effectiveAccountId === 'acc_1') && !accVariants.includes('acc_telegram_bot')) {
      accVariants.push('acc_telegram_bot');
    }
    const accPlaceholders = accVariants.map(() => '?').join(', ');
    const chatId = typeof rawChatId === 'string' ? rawChatId.trim() : '';
    const altChatId = chatId ? (chatId.startsWith('tg_') ? chatId.replace(/^tg_/, '') : `tg_${chatId}`) : '';
    const tgMsgId =
      typeof rawTgId === 'number' && Number.isFinite(rawTgId)
        ? rawTgId
        : resolveTelegramMessageNumericId(id);

    const setClauses: string[] = [];
    const setValues: any[] = [];
    if (hasTranslatedText) {
      setClauses.push('translated_text = ?');
      setValues.push(translatedText);
    }
    if (hasSttText) {
      setClauses.push('stt_text = ?');
      setValues.push(sttText);
    }
    const setSql = setClauses.join(', ');

    const totalChanges = await enqueueMessageDbWrite<number>({
      priority: 'NORMAL',
      kind: 'stt',
      accountId: effectiveAccountId,
      chatId,
      tgMsgIds: tgMsgId ? [Number(tgMsgId)] : [],
      msgId: id,
      exec: async () => {
        let changesSum = 0;
        const idWhere = ['id = ?'];
        const idParams: any[] = [...setValues, id];
        if (chatId) {
          idWhere.push('(chat_id = ? OR chat_id = ?)');
          idParams.push(chatId, altChatId);
        }
        if (enforceAccountScope) {
          idWhere.push(`account_id IN (${accPlaceholders})`);
          idParams.push(...accVariants);
        }
        const idRes = await db.prepare(`UPDATE messages SET ${setSql} WHERE ${idWhere.join(' AND ')}`).run(...idParams);
        changesSum += Number((idRes as any)?.changes || 0);

        if (tgMsgId && chatId) {
          const tgWhere = ['(chat_id = ? OR chat_id = ?)', 'telegram_message_id = ?'];
          const tgParams: any[] = [...setValues, chatId, altChatId, tgMsgId];
          if (enforceAccountScope) {
            tgWhere.push(`account_id IN (${accPlaceholders})`);
            tgParams.push(...accVariants);
          }
          const tgRes = await db.prepare(`UPDATE messages SET ${setSql} WHERE ${tgWhere.join(' AND ')}`).run(...tgParams);
          changesSum += Number((tgRes as any)?.changes || 0);
        }
        return changesSum;
      },
    });

    res.json({ ok: true, updated: totalChanges > 0, changes: totalChanges });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err?.message || '更新译文或语音转写失败' });
  }
});

// 4. Fetch Customer Profile & Long-Term Memory (Canonical chatId + strictly account-scoped)
app.get('/api/customer/profile/:chatId', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const scope = resolveScopedAiAccountId(req);
    if (!scope.ok) return res.status(scope.status).json({ error: scope.error });
    const canonicalChatId = canonicalizeCustomerChatId(req.params.chatId);
    if (!canonicalChatId) {
      return res.status(400).json({ error: '缺少有效的客户会话 chatId' });
    }
    const effectiveAccountId = scope.accountId;
    let profile = await getScopedCustomerProfile(canonicalChatId, effectiveAccountId);
    const reqTitle =
      (typeof req.query.title === 'string' && req.query.title.trim()) ||
      (typeof req.query.clientName === 'string' && req.query.clientName.trim()) ||
      '';
    const dbMsgCount = await countScopedChatMessages(canonicalChatId, effectiveAccountId);

    if (!profile) {
      // Create a clean baseline profile without any fabricated attributes
      const now = Date.now();
      const defaultName = reqTitle || '新联系人';
      await upsertScopedCustomerProfile({
        chatId: canonicalChatId,
        accountId: effectiveAccountId,
        clientName: defaultName,
        relationshipStage: '尚未沟通',
        ageEstimate: '待分析',
        occupation: '待分析',
        locationTimezone: '待确认',
        toneStyle: '待沟通分析',
        likesInterests: JSON.stringify([]),
        dislikesTaboos: JSON.stringify([]),
        emotionalNeeds: '暂无记录（待真实沟通后提炼）',
        keyMemories: JSON.stringify([]),
        totalMessagesCount: dbMsgCount,
        lastAnalyzedAt: now,
        updatedAt: now,
      });

      profile = await getScopedCustomerProfile(canonicalChatId, effectiveAccountId);
    } else if (
      reqTitle &&
      (!profile.client_name ||
        ['新联系人', '联系人', '客户', 'VIP客户'].includes(String(profile.client_name).trim()))
    ) {
      profile = { ...profile, client_name: reqTitle };
      const accVariants = getScopedAccountIdVariants(effectiveAccountId);
      const accPh = accVariants.map(() => '?').join(', ');
      await db
        .prepare(`UPDATE account_customer_profiles SET client_name = ? WHERE account_id IN (${accPh}) AND chat_id = ?`)
        .run(reqTitle, ...accVariants, canonicalChatId)
        .catch(() => {});
    }

    const resolvedTotalMessagesCount = Math.max(Number(profile?.total_messages_count) || 0, dbMsgCount);
      res.json({
      chatId: canonicalChatId,
      accountId: profile.account_id || effectiveAccountId,
      clientName: profile.client_name,
      relationshipStage: profile.relationship_stage,
      ageEstimate: profile.age_estimate,
      occupation: profile.occupation,
      locationTimezone: profile.location_timezone,
      familyMaritalStatus: profile.family_marital_status || '',
      activeSchedule: profile.active_schedule || '',
      toneStyle: profile.tone_style,
      likesInterests: safeJsonParse(profile.likes_interests, []),
      dislikesTaboos: safeJsonParse(profile.dislikes_taboos, []),
      emotionalNeeds: profile.emotional_needs,
      financialProfile: profile.financial_profile || '',
      investmentAttitude: profile.investment_attitude || '',
      trustLevel: profile.trust_level || '',
      nextStepStrategy: profile.next_step_strategy || '',
      keyMemories: safeJsonParse(profile.key_memories, []),
      totalMessagesCount: resolvedTotalMessagesCount,
      lastAnalyzedAt: profile.last_analyzed_at,
      updatedAt: profile.updated_at,
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// 5. Update Customer Profile & Memory Manually (UPSERT with canonical chatId + account isolation)
app.post('/api/customer/profile/:chatId', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const scope = resolveScopedAiAccountId(req);
    if (!scope.ok) return res.status(scope.status).json({ error: scope.error });
    const canonicalChatId = canonicalizeCustomerChatId(req.params.chatId);
    if (!canonicalChatId) {
      return res.status(400).json({ error: '缺少有效的客户会话 chatId' });
    }
    const {
      clientName, relationshipStage, ageEstimate, occupation, locationTimezone,
      familyMaritalStatus, activeSchedule,
      toneStyle, likesInterests, dislikesTaboos, emotionalNeeds,
      financialProfile, investmentAttitude, trustLevel, nextStepStrategy,
      keyMemories
    } = req.body;
    const effectiveAccountId = scope.accountId;
    const bodyObj = req.body && typeof req.body === 'object' ? req.body : {};
    const hasField = (k: string) => Object.prototype.hasOwnProperty.call(bodyObj, k) && bodyObj[k] !== undefined;
    const existing = await getScopedCustomerProfile(canonicalChatId, effectiveAccountId);
    const dbMsgCount = await countScopedChatMessages(canonicalChatId, effectiveAccountId);

    const now = Date.now();
    await upsertScopedCustomerProfile({
      chatId: canonicalChatId,
      accountId: effectiveAccountId,
      clientName: hasField('clientName')
        ? String(clientName || '').trim() || existing?.client_name || 'VIP客户'
        : existing?.client_name || 'VIP客户',
      relationshipStage: hasField('relationshipStage')
        ? String(relationshipStage || '').trim() || existing?.relationship_stage || '初次结识'
        : existing?.relationship_stage || '初次结识',
      ageEstimate: hasField('ageEstimate') ? String(ageEstimate ?? '') : String(existing?.age_estimate ?? ''),
      occupation: hasField('occupation') ? String(occupation ?? '') : String(existing?.occupation ?? ''),
      locationTimezone: hasField('locationTimezone')
        ? String(locationTimezone ?? '')
        : String(existing?.location_timezone ?? ''),
      familyMaritalStatus: hasField('familyMaritalStatus')
        ? String(familyMaritalStatus ?? '')
        : String(existing?.family_marital_status ?? ''),
      activeSchedule: hasField('activeSchedule')
        ? String(activeSchedule ?? '')
        : String(existing?.active_schedule ?? ''),
      toneStyle: hasField('toneStyle') ? String(toneStyle ?? '') : String(existing?.tone_style ?? ''),
      likesInterests: hasField('likesInterests')
        ? JSON.stringify(Array.isArray(likesInterests) ? likesInterests : [])
        : typeof existing?.likes_interests === 'string'
          ? existing.likes_interests
          : '[]',
      dislikesTaboos: hasField('dislikesTaboos')
        ? JSON.stringify(Array.isArray(dislikesTaboos) ? dislikesTaboos : [])
        : typeof existing?.dislikes_taboos === 'string'
          ? existing.dislikes_taboos
          : '[]',
      emotionalNeeds: hasField('emotionalNeeds')
        ? String(emotionalNeeds ?? '')
        : String(existing?.emotional_needs ?? ''),
      financialProfile: hasField('financialProfile')
        ? String(financialProfile ?? '')
        : String(existing?.financial_profile ?? ''),
      investmentAttitude: hasField('investmentAttitude')
        ? String(investmentAttitude ?? '')
        : String(existing?.investment_attitude ?? ''),
      trustLevel: hasField('trustLevel')
        ? String(trustLevel ?? '')
        : String(existing?.trust_level ?? ''),
      nextStepStrategy: hasField('nextStepStrategy')
        ? String(nextStepStrategy ?? '')
        : String(existing?.next_step_strategy ?? ''),
      keyMemories: hasField('keyMemories')
        ? JSON.stringify(Array.isArray(keyMemories) ? keyMemories : [])
        : typeof existing?.key_memories === 'string'
          ? existing.key_memories
          : '[]',
      totalMessagesCount: Math.max(Number(existing?.total_messages_count) || 0, dbMsgCount),
      lastAnalyzedAt: 0,
      updatedAt: now,
    });

    res.json({ success: true, chatId: canonicalChatId, accountId: effectiveAccountId });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});

// 6. AI Deep Analysis: Extract Customer Persona & Key Memories while preserving manually curated memories/tags
app.post('/api/customer/analyze/:chatId', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const scope = resolveScopedAiAccountId(req);
    if (!scope.ok) return res.status(scope.status).json({ success: false, error: scope.error });
    const canonicalChatId = canonicalizeCustomerChatId(req.params.chatId);
    if (!canonicalChatId) {
      return res.status(400).json({ success: false, error: '缺少有效的客户会话 chatId' });
    }
    const { customConfig, messages: clientMessages, chatTitle } = req.body;
    const effectiveAccountId = scope.accountId;

    const existingProfile = await getScopedCustomerProfile(canonicalChatId, effectiveAccountId);

    const serverCustomCfg = await getServerCustomLlmConfig().catch(() => null);
    const effectiveAnalyzeConfig =
      customConfig && typeof customConfig === 'object'
        ? {
            ...(serverCustomCfg || {}),
            ...customConfig,
            enabled:
              typeof customConfig.enabled === 'boolean'
                ? customConfig.enabled
                : serverCustomCfg?.enabled !== false,
            explicitlyDisabled:
              typeof customConfig.enabled === 'boolean'
                ? !customConfig.enabled
                : Boolean(customConfig.explicitlyDisabled ?? serverCustomCfg?.explicitlyDisabled),
            baseUrl: (typeof customConfig.baseUrl === 'string' ? customConfig.baseUrl : (serverCustomCfg?.baseUrl || '')).trim(),
            apiKey: resolveSecretUpdate(customConfig.apiKey, serverCustomCfg?.apiKey, true),
            engineLicenseKey: resolveSecretUpdate(
              customConfig.engineLicenseKey,
              serverCustomCfg?.engineLicenseKey,
              true
            ),
            modelName:
              (customConfig.engineMode || serverCustomCfg?.engineMode) === 'custom'
                ? (typeof customConfig.modelName === 'string'
                    ? customConfig.modelName
                    : (serverCustomCfg?.modelName || '')
                  ).trim()
                : (customConfig.modelName && /^(gemini|gemma)/i.test(String(customConfig.modelName).trim())
                    ? String(customConfig.modelName).trim()
                    : 'gemini-4-hydrogen'),
          }
        : serverCustomCfg;

    if (
      effectiveAnalyzeConfig &&
      (effectiveAnalyzeConfig.enabled === false || effectiveAnalyzeConfig.explicitlyDisabled)
    ) {
      return res.status(400).json({
        success: false,
        error: '未配置可用的大模型（当前处于双关状态：官方大模型与自有密钥均已关闭），请先在「模型」开启任一引擎后再提炼全息记忆。',
      });
    }

    // Unify messages from DB cache, Telegram Official Cloud, and client real-time local state
    const resolved = await resolveUnifiedChatMessages({
      chatId: canonicalChatId,
      accountId: effectiveAccountId,
      clientMessages,
      limit: 50,
      syncCloud: true,
      persistClientMessages: true,
    });
    const messageList = resolved.messages.map((m) => {
      const rawText = String(m.text || '').trim();
      const sttText = String(m.sttText || '').trim();
      const imageCaption = String(m.imageCaption || '').trim();
      const translatedText = String(m.translatedText || '').trim();
      const isGenericVoicePlaceholder =
        !rawText ||
        rawText === 'Voice Message' ||
        rawText === 'Voice message' ||
        rawText === '[语音]' ||
        rawText === '🎤 语音消息';
      const isGenericImagePlaceholder =
        !rawText || rawText === 'Image' || rawText === '[图片]' || rawText === '📷 图片';
      let contentText = rawText;
      if (sttText && (isGenericVoicePlaceholder || m.isAudio)) {
        contentText = `[语音]: ${sttText}`;
      } else if (imageCaption && (isGenericImagePlaceholder || m.isImage)) {
        contentText = `[图片说明]: ${imageCaption}`;
      } else if (sttText) {
        contentText = `${rawText} [语音转写]: ${sttText}`;
      } else if (imageCaption) {
        contentText = `${rawText} [图片说明]: ${imageCaption}`;
      }
      if (translatedText && translatedText !== contentText && !contentText.includes(translatedText)) {
        contentText = contentText ? `${contentText} (译文: ${translatedText})` : translatedText;
      }
      return {
        sender: m.sender,
        sender_name: m.senderName || (m.sender === 'peer' ? (chatTitle || '客户') : '我方'),
        text: rawText,
        stt_text: sttText,
        effective_text: contentText.trim(),
      };
    });
    const dbTotalMsgCount = await countScopedChatMessages(canonicalChatId, effectiveAccountId);
    const actualMessageCount = Math.max(Number(existingProfile?.total_messages_count) || 0, dbTotalMsgCount, messageList.length);

    const now = Date.now();

    // If completely no messages exist (new contact), initialize/preserve existing manual profile without erasing manual memories
    if (messageList.length === 0) {
      const mergedEmpty = mergeCustomerProfileWithManualData({
        existingProfile,
        aiData: {
          clientName: chatTitle || '联系人',
          relationshipStage: '尚未沟通',
          ageEstimate: '待分析',
          occupation: '待分析',
          locationTimezone: '待确认',
          toneStyle: '暂无对话数据',
          likesInterests: [],
          dislikesTaboos: [],
          emotionalNeeds: '暂无足够对话记录',
          keyMemories: [],
        },
        fallbackName: chatTitle || '联系人',
        preserveOnSparse: true,
      });

      await upsertScopedCustomerProfile({
        chatId: canonicalChatId,
        accountId: effectiveAccountId,
        clientName: mergedEmpty.clientName,
        relationshipStage: mergedEmpty.relationshipStage,
        ageEstimate: mergedEmpty.ageEstimate,
        occupation: mergedEmpty.occupation,
        locationTimezone: mergedEmpty.locationTimezone,
        familyMaritalStatus: mergedEmpty.familyMaritalStatus,
        activeSchedule: mergedEmpty.activeSchedule,
        toneStyle: mergedEmpty.toneStyle,
        likesInterests: JSON.stringify(mergedEmpty.likesInterests),
        dislikesTaboos: JSON.stringify(mergedEmpty.dislikesTaboos),
        emotionalNeeds: mergedEmpty.emotionalNeeds,
        financialProfile: mergedEmpty.financialProfile,
        investmentAttitude: mergedEmpty.investmentAttitude,
        trustLevel: mergedEmpty.trustLevel,
        nextStepStrategy: mergedEmpty.nextStepStrategy,
        keyMemories: JSON.stringify(mergedEmpty.keyMemories),
        totalMessagesCount: actualMessageCount,
        lastAnalyzedAt: now,
        updatedAt: now,
      });

      return res.json({
        success: true,
        profile: {
          chatId: canonicalChatId,
          accountId: effectiveAccountId,
          ...mergedEmpty,
          totalMessagesCount: actualMessageCount,
          lastAnalyzedAt: now,
        },
        message: '当前会话暂无对话记录。已保留现有人工记录，真实沟通后系统将自动提炼补充全息画像与长效记忆。',
      });
    }

    // If conversation is too sparse (fewer than 2 messages or under 12 characters), preserve existing manual entries without AI hallucination
    const totalCharCount = messageList.reduce((acc, m) => acc + (m.effective_text || m.text || '').length, 0);
    if (messageList.length < 2 || totalCharCount < 12) {
      const mergedSparse = mergeCustomerProfileWithManualData({
        existingProfile,
        aiData: {
          clientName: chatTitle || '联系人',
          relationshipStage: '初次接触',
          ageEstimate: '未知',
          occupation: '未知',
          locationTimezone: '未提及',
          toneStyle: '初次沟通，待积累更多对话数据',
          likesInterests: [],
          dislikesTaboos: [],
          emotionalNeeds: '暂无足够对话记录',
          keyMemories: [],
        },
        fallbackName: chatTitle || '联系人',
        preserveOnSparse: true,
      });

      await upsertScopedCustomerProfile({
        chatId: canonicalChatId,
        accountId: effectiveAccountId,
        clientName: mergedSparse.clientName,
        relationshipStage: mergedSparse.relationshipStage,
        ageEstimate: mergedSparse.ageEstimate,
        occupation: mergedSparse.occupation,
        locationTimezone: mergedSparse.locationTimezone,
        familyMaritalStatus: mergedSparse.familyMaritalStatus,
        activeSchedule: mergedSparse.activeSchedule,
        toneStyle: mergedSparse.toneStyle,
        likesInterests: JSON.stringify(mergedSparse.likesInterests),
        dislikesTaboos: JSON.stringify(mergedSparse.dislikesTaboos),
        emotionalNeeds: mergedSparse.emotionalNeeds,
        financialProfile: mergedSparse.financialProfile,
        investmentAttitude: mergedSparse.investmentAttitude,
        trustLevel: mergedSparse.trustLevel,
        nextStepStrategy: mergedSparse.nextStepStrategy,
        keyMemories: JSON.stringify(mergedSparse.keyMemories),
        totalMessagesCount: actualMessageCount,
        lastAnalyzedAt: now,
        updatedAt: now,
      });

      return res.json({
        success: true,
        profile: {
          chatId: canonicalChatId,
          accountId: effectiveAccountId,
          ...mergedSparse,
          totalMessagesCount: actualMessageCount,
          lastAnalyzedAt: now,
        },
        message: '当前会话对话记录过少（少于2条），已保留人工记忆并初始化基础档案，待深入沟通后提炼。',
      });
    }

    const conversationTranscript = messageList.map((m) => {
      const sender = m.sender === 'peer' ? (m.sender_name || '客户') : '我方';
      const content = m.effective_text || m.text;
      return `${sender}: ${content}`;
    }).join('\n');

    const existingLikes = existingProfile ? safeJsonParse<string[]>(existingProfile.likes_interests, []) : [];
    const existingTaboos = existingProfile ? safeJsonParse<string[]>(existingProfile.dislikes_taboos, []) : [];
    const existingSummaryParts = existingProfile
      ? [
          !isPlaceholderProfileValue(existingProfile.relationship_stage) ? `关系阶段:${existingProfile.relationship_stage}` : '',
          !isPlaceholderProfileValue(existingProfile.age_estimate) ? `年龄:${existingProfile.age_estimate}` : '',
          !isPlaceholderProfileValue(existingProfile.occupation) ? `职业:${existingProfile.occupation}` : '',
          !isPlaceholderProfileValue(existingProfile.location_timezone) ? `地区/时区:${existingProfile.location_timezone}` : '',
          !isPlaceholderProfileValue(existingProfile.family_marital_status) ? `婚恋家庭:${existingProfile.family_marital_status}` : '',
          !isPlaceholderProfileValue(existingProfile.active_schedule) ? `作息:${existingProfile.active_schedule}` : '',
          !isPlaceholderProfileValue(existingProfile.tone_style) ? `性格语气:${existingProfile.tone_style}` : '',
          Array.isArray(existingLikes) && existingLikes.length > 0 ? `喜好话题:${existingLikes.join('、')}` : '',
          Array.isArray(existingTaboos) && existingTaboos.length > 0 ? `敏感雷区:${existingTaboos.join('、')}` : '',
          !isPlaceholderProfileValue(existingProfile.emotional_needs) ? `情感诉求:${existingProfile.emotional_needs}` : '',
          !isPlaceholderProfileValue(existingProfile.financial_profile) ? `经济背景:${existingProfile.financial_profile}` : '',
          !isPlaceholderProfileValue(existingProfile.investment_attitude) ? `投资态度:${existingProfile.investment_attitude}` : '',
          !isPlaceholderProfileValue(existingProfile.trust_level) ? `信任度:${existingProfile.trust_level}` : '',
          !isPlaceholderProfileValue(existingProfile.next_step_strategy) ? `既有策略:${existingProfile.next_step_strategy}` : '',
        ].filter(Boolean)
      : [];
    const existingProfileSummary = existingSummaryParts.join('；');

    const analysisPrompt = `作为客观严谨的客户画像与长期记忆提炼助手，请深度客观分析以下真实客户与我方的聊天历史（最近50条消息），服务于“交朋友 -> 情感升温 -> 深度信任 -> 投资探讨”的长周期私域沟通。
【严格规则 - 禁止任何假设与虚假编造】：
1. 只能提取对话中真实明确提及或明确体现的事实（含婚恋家庭、作息规律、收入经济线索、投资或副业态度）。未在对话中出现的年龄、职业、婚恋或时区必须返回"未知"或"未提及"，严禁擅自猜测或套用模板！
2. 喜好偏好(likesInterests)与敏感雷区(dislikesTaboos)若对话中未明确表达，必须返回空数组 []，严禁添加未讨论的假标签。
3. 关键记忆(keyMemories)必须基于真实对话中的事件或约定，若无明确约定则返回空数组 []。
4. 若对话使用外语（如土耳其语、英语等），请先理解其真实含义后再以简体中文输出提炼结果，不得因外语内容而遗漏分析。

请返回严格的 JSON 格式（不要包含任何 markdown 代码块或额外文字）：
{
  "clientName": "从聊天推断的真实称谓或称呼",
  "relationshipStage": "从五阶段中客观判断当前所处阶段：初识破冰 / 朋友熟络 / 情感升温 / 信任深化 / 投资切入",
  "ageEstimate": "对话中明确提及的年龄，未提及则填'未知'",
  "occupation": "对话中明确提及的职业或行业，未提及则填'未知'",
  "locationTimezone": "对话中明确提及的所在地或时区，未提及则填'未提及'",
  "familyMaritalStatus": "对话或备注中明确提及的婚恋/家庭状态（如：已婚有娃/单身/离异/独居），未提及则填'未知'",
  "activeSchedule": "从聊天时间与内容体现的作息空闲窗口（如：夜班/晚21点后活跃/周末休息），未体现则填'未提及'",
  "toneStyle": "客观分析得出的说话用词与沟通风格（如：热情话多 / 谨慎慢热 / 直接务实 / 情感细腻）",
  "likesInterests": ["真实聊到的具体兴趣、生活关注点或共同话题，无则空数组"],
  "dislikesTaboos": ["真实表达的反感情绪、拒绝话题或敏感雷区，无则空数组"],
  "emotionalNeeds": "真实的深层情感诉求与生活痛点（如缺陪伴/工作累/家庭开销压力/渴望认可），无则填'待进一步沟通交流'",
  "financialProfile": "对话中流露的经济实力、收入感受或资金压力线索，未提及则填'待进一步了解'",
  "investmentAttitude": "对副业/理财/投资的态度、过往经验或顾虑点，未提及则填'待观察'",
  "trustLevel": "结合互动主动度与倾诉深度评估：低（初识）/ 中（建立好感）/ 高（深度信任）",
  "nextStepStrategy": "基于当前关系阶段给出的1~2句下一步话题切入与推进建议（未到信任或投资阶段切勿强推）",
  "keyMemories": [
    { "id": "mem_1", "date": "日期或近期", "topic": "关键话题", "summary": "真实事实或约定简述", "emotion": "正常交流" }
  ]
}

当前联系人备注/昵称：${String(chatTitle || '客户').trim() || '客户'}（如备注中已含称谓/年龄/职业/婚恋/城市等明确信息可参考提取，未明确处仍填"未知"或"未提及"）
当前已录入的客户基准档案（若已有明确人工记录请保留并在此基础上补充深化，未矛盾时不要覆盖）：${existingProfileSummary || '暂无'}
真实聊天历史记录：
${conversationTranscript}`;

    let extractedData: any = null;
    let analysisErrorMsg = '';
    const bearerJwt = extractBearerToken(req);
    if (bearerJwt) {
      lastActiveUserJwt = bearerJwt;
    }

    const useCustomPriorityMemory = Boolean(
      effectiveAnalyzeConfig?.enabled && effectiveAnalyzeConfig?.engineMode === 'custom'
    );

    const effectiveLicenseKey =
      (typeof effectiveAnalyzeConfig?.engineLicenseKey === 'string' && effectiveAnalyzeConfig.engineLicenseKey.trim()) ||
      (typeof serverCustomCfg?.engineLicenseKey === 'string' &&
        !isMaskedSecretPlaceholder(serverCustomCfg.engineLicenseKey) &&
        serverCustomCfg.engineLicenseKey.trim()) ||
      (process.env.RAILWAY_BRAIN_KEY || '').trim() ||
      undefined;
    const effectiveUserJwt = bearerJwt || undefined;

    if (useCustomPriorityMemory) {
      const cleanCustomUrl = (effectiveAnalyzeConfig?.baseUrl || '').trim().replace(/\/+$/, '');
      const cleanCustomKey = sanitizeHttpHeaderValue(effectiveAnalyzeConfig?.apiKey);
      if (!cleanCustomUrl || isBuiltInCloudGatewayUrl(cleanCustomUrl)) {
        return res.status(400).json({
          success: false,
          error: '已开启「优先自有密钥回复」，请先在「模型 → 接入自有模型网关」填写有效的大模型接入网址 (Base URL)。',
        });
      }
      let isLocalCustomUrl = false;
      try {
        const parsed = new URL(cleanCustomUrl);
        isLocalCustomUrl = isAllowedLocalhostEndpoint(parsed.hostname);
      } catch {
        return res.status(400).json({
          success: false,
          error: '自有模型网关 Base URL 无效，请填写合法的 http:// 或 https:// 地址。',
        });
      }
      if (!cleanCustomKey && !isLocalCustomUrl) {
        return res.status(400).json({
          success: false,
          error: '已开启「优先自有密钥回复」，记忆提炼缺少 API 密钥，请在「模型 → 接入自有模型网关」填写 API 密钥。',
        });
      }

      const rawCustomModel = typeof effectiveAnalyzeConfig?.modelName === 'string' ? effectiveAnalyzeConfig.modelName.trim() : '';
      const inferredProto = inferGatewayProtocol(cleanCustomUrl, rawCustomModel, effectiveAnalyzeConfig?.protocol);
      if (inferredProto === 'gemini' && !cleanCustomUrl.includes(':generateContent') && !rawCustomModel) {
        return res.status(400).json({
          success: false,
          blocked: true,
          source: 'custom_llm_missing_model',
          error: '自有 Gemini 协议网关未填写模型型号 (Model Name)，已拦截空模型请求，请先在「模型」填写具体 Gemini 模型 ID。',
        });
      }
      const customModel = rawCustomModel || (inferredProto === 'anthropic' ? 'claude-3-5-sonnet-20241022' : 'gpt-4o-mini');
      try {
        const txt = await callCustomLlm({
          customConfig: {
            ...effectiveAnalyzeConfig,
            enabled: true,
            engineMode: 'custom',
            protocol: inferredProto,
            baseUrl: cleanCustomUrl,
            apiKey: cleanCustomKey,
            modelName: customModel,
            temperature: 0.1,
          },
          messages: [{ role: 'user', content: analysisPrompt }],
          temperature: 0.1,
          maxTokens: 2048,
          timeoutMs: 120000,
          maxRetries: 0,
          throwOnError: true,
          skipSync: true,
        });
        if (txt) {
          const parsedObj = extractFirstJsonObject(txt);
          if (parsedObj) {
            extractedData = parsedObj;
          } else {
            analysisErrorMsg = '自有模型网关返回内容未能解析为有效的客户画像 JSON';
          }
        } else {
          analysisErrorMsg = '自有模型网关未返回有效画像数据';
        }
      } catch (err: any) {
        analysisErrorMsg = err?.message || '自有模型网关记忆提炼请求失败';
        console.warn('[CustomerMemoryAnalysis Custom Gateway Error]:', analysisErrorMsg);
      }

      if (!extractedData) {
        return res.status(503).json({
          success: false,
          error: `客户全息记忆提炼失败（优先自有密钥模式）：${analysisErrorMsg || '未返回有效画像数据'}`,
        });
      }
    } else {
      // 未开启优先自有密钥模式时，客户全息记忆提炼严格走 HumanSense 云端引擎通道
      if (!effectiveUserJwt && !effectiveLicenseKey) {
        return res.status(401).json({
          success: false,
          error: '客户全息记忆提炼（HumanSense 云端引擎）未获取到会员授权令牌，请先登录会员账号。',
        });
      }

      try {
        const txt = await callCustomLlm({
          customConfig: {
            enabled: true,
            engineMode: 'cloud',
            protocol: 'openai',
            baseUrl: '',
            apiKey: '',
            modelName: 'gemini-4-hydrogen',
            temperature: 0.1,
            engineLicenseKey: effectiveLicenseKey,
          },
          messages: [{ role: 'user', content: analysisPrompt }],
          temperature: 0.1,
          maxTokens: 2048,
          timeoutMs: 120000,
          maxRetries: 0,
          userJwt: effectiveUserJwt,
          throwOnError: true,
          skipSync: true,
          extraPayload: { purpose: 'memory_extraction' },
        });
        if (txt) {
          const parsedObj = extractFirstJsonObject(txt);
          if (parsedObj) {
            extractedData = parsedObj;
          } else {
            analysisErrorMsg = 'HumanSense 云端引擎返回内容未能解析为有效的客户画像 JSON';
          }
        } else {
          analysisErrorMsg = 'HumanSense 云端引擎未返回有效画像数据';
        }
      } catch (err: any) {
        analysisErrorMsg = err?.message || 'HumanSense 云端引擎分析请求失败';
        console.warn('[CustomerMemoryAnalysis Cloud Engine Error]:', analysisErrorMsg);
      }

      if (!extractedData) {
        return res.status(503).json({
          success: false,
          error: `客户全息记忆提炼服务不可用（HumanSense 云端引擎）：${analysisErrorMsg || '未返回有效画像数据'}`,
        });
      }
    }

    // Merge AI-extracted insights with manually curated memories, tags, and attributes
    const hasManualOverride =
      Boolean(existingProfile) &&
      (Number(existingProfile?.updated_at ?? 0) > Number(existingProfile?.last_analyzed_at ?? 0) ||
        Number(existingProfile?.last_analyzed_at ?? 0) === 0);
    const mergedProfile = mergeCustomerProfileWithManualData({
      existingProfile,
      aiData: extractedData,
      fallbackName: chatTitle || '客户',
      preserveOnSparse: false,
      preserveManualScalars: hasManualOverride,
    });

    await upsertScopedCustomerProfile({
      chatId: canonicalChatId,
      accountId: effectiveAccountId,
      clientName: mergedProfile.clientName,
      relationshipStage: mergedProfile.relationshipStage,
      ageEstimate: mergedProfile.ageEstimate,
      occupation: mergedProfile.occupation,
      locationTimezone: mergedProfile.locationTimezone,
      familyMaritalStatus: mergedProfile.familyMaritalStatus,
      activeSchedule: mergedProfile.activeSchedule,
      toneStyle: mergedProfile.toneStyle,
      likesInterests: JSON.stringify(mergedProfile.likesInterests),
      dislikesTaboos: JSON.stringify(mergedProfile.dislikesTaboos),
      emotionalNeeds: mergedProfile.emotionalNeeds,
      financialProfile: mergedProfile.financialProfile,
      investmentAttitude: mergedProfile.investmentAttitude,
      trustLevel: mergedProfile.trustLevel,
      nextStepStrategy: mergedProfile.nextStepStrategy,
      keyMemories: JSON.stringify(mergedProfile.keyMemories),
      totalMessagesCount: actualMessageCount,
      lastAnalyzedAt: now,
      updatedAt: now,
    });

    res.json({
      success: true,
      profile: {
        chatId: canonicalChatId,
        accountId: effectiveAccountId,
        ...mergedProfile,
        totalMessagesCount: actualMessageCount,
        lastAnalyzedAt: now,
      },
    });
  } catch (error: any) {
    console.error('Customer analysis error:', error);
    res.status(500).json({ error: error.message });
  }
});

