export interface SystemProxyConfig {
  enabled: boolean;
  type: 'socks5' | 'socks4';
  host: string;
  port: number;
  username?: string;
  password?: string;
}

export interface AutoSystemProxyConfig {
  protocol: 'socks5' | 'socks4' | 'http' | 'https';
  host: string;
  port: number;
  username?: string;
  password?: string;
}

let cachedSystemProxyConfig: SystemProxyConfig | null = null;
let cachedElectronAutoSystemProxy: string | null = null;

export function parseSocksProxyEnvString(raw?: string | null): SystemProxyConfig | null {
  const val = String(raw || '').trim();
  if (!val) return null;
  try {
    const parsed = new URL(val);
    const proto = parsed.protocol.replace(':', '').toLowerCase();
    if (proto !== 'socks5' && proto !== 'socks4') return null;
    const host = parsed.hostname;
    const port = Number(parsed.port);
    if (!host || !Number.isInteger(port) || port < 1 || port > 65535) return null;
    return {
      enabled: true,
      type: proto,
      host,
      port,
      ...(parsed.username ? { username: decodeURIComponent(parsed.username) } : {}),
      ...(parsed.password ? { password: decodeURIComponent(parsed.password) } : {}),
    };
  } catch {
    return null;
  }
}

export function normalizeAndValidateProxyConfig(input: any): { ok: true; config: SystemProxyConfig } | { ok: false; error: string } {
  const enabled = Boolean(input?.enabled);
  const rawType = String(input?.type || 'socks5').toLowerCase().trim();
  const type = rawType === 'socks4' ? 'socks4' : 'socks5';
  const host = String(input?.host || '').trim();
  const port = Number(input?.port);
  const username = typeof input?.username === 'string' && input.username.trim() ? input.username.trim() : undefined;
  const password = typeof input?.password === 'string' && input.password.trim() ? input.password.trim() : undefined;

  if (!enabled) {
    return {
      ok: true,
      config: {
        enabled: false,
        type,
        host,
        port: Number.isInteger(port) && port >= 1 && port <= 65535 ? port : 1080,
        username,
        password,
      },
    };
  }

  if (rawType !== 'socks5' && rawType !== 'socks4') {
    return { ok: false, error: '当前仅支持 SOCKS5 / SOCKS4 代理协议' };
  }
  if (!host || /[\s\x00-\x1f\x7f/@?#\\]/.test(host) || host.includes('://')) {
    return { ok: false, error: '请输入有效的代理服务器地址（如 127.0.0.1）' };
  }
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return { ok: false, error: '请输入有效的代理端口（1 - 65535）' };
  }

  return {
    ok: true,
    config: {
      enabled: true,
      type,
      host,
      port,
      username,
      password,
    },
  };
}

export async function loadSystemProxyConfigFromDb(): Promise<SystemProxyConfig | null> {
  try {
    const row = (await db.prepare("SELECT value FROM system_config WHERE key = 'network_proxy'").get()) as any;
    if (row?.value) {
      const parsed = JSON.parse(String(row.value));
      const validated = normalizeAndValidateProxyConfig(parsed);
      if (validated.ok) {
        cachedSystemProxyConfig = validated.config;
        return cachedSystemProxyConfig;
      }
    }
  } catch {}
  const envProxy = parseSocksProxyEnvString(process.env.TG_SOCKS_PROXY);
  if (envProxy) {
    cachedSystemProxyConfig = envProxy;
    return envProxy;
  }
  cachedSystemProxyConfig = null;
  return null;
}

export async function saveSystemProxyConfigToDb(config: SystemProxyConfig): Promise<void> {
  await db
    .prepare("INSERT OR REPLACE INTO system_config (key, value, updated_at) VALUES ('network_proxy', ?, ?)")
    .run(JSON.stringify(config), Date.now());
  cachedSystemProxyConfig = config;
}

export function getConfiguredTelegramProxy():
  | { ip: string; port: number; socksType: 4 | 5; timeout?: number; username?: string; password?: string }
  | undefined {
  const active = cachedSystemProxyConfig || parseSocksProxyEnvString(process.env.TG_SOCKS_PROXY);
  if (!active || !active.enabled || !active.host || !active.port) {
    return undefined;
  }
  return {
    ip: active.host,
    port: active.port,
    socksType: active.type === 'socks4' ? 4 : 5,
    timeout: 15,
    ...(active.username ? { username: active.username } : {}),
    ...(active.password ? { password: active.password } : {}),
  };
}

export function parseAnyProxyEnvString(raw?: string | null): AutoSystemProxyConfig | null {
  const val = String(raw || '').trim();
  if (!val) return null;
  try {
    const normalized = /^[a-z0-9+.-]+:\/\//i.test(val) ? val : `http://${val}`;
    const parsed = new URL(normalized);
    let proto = parsed.protocol.replace(':', '').toLowerCase();
    if (proto === 'socks' || proto === 'socks5h') proto = 'socks5';
    if (proto === 'socks4a') proto = 'socks4';
    if (proto !== 'socks5' && proto !== 'socks4' && proto !== 'http' && proto !== 'https') {
      return null;
    }
    const host = parsed.hostname.replace(/^\[|\]$/g, '');
    const port = Number(parsed.port || (proto === 'https' ? 443 : proto === 'http' ? 8080 : 1080));
    if (!host || !Number.isInteger(port) || port < 1 || port > 65535) return null;
    return {
      protocol: proto as AutoSystemProxyConfig['protocol'],
      host,
      port,
      ...(parsed.username ? { username: decodeURIComponent(parsed.username) } : {}),
      ...(parsed.password ? { password: decodeURIComponent(parsed.password) } : {}),
    };
  } catch {
    return null;
  }
}

export function getAutoDetectedSystemProxy(): AutoSystemProxyConfig | null {
  if (process.env.NODE_ENV === 'test' || process.env.AIS_TEST_IMPORT === 'true') {
    return null;
  }
  const candidates = [
    cachedElectronAutoSystemProxy,
    process.env.HS_AUTO_SYSTEM_PROXY,
    process.env.ALL_PROXY,
    process.env.all_proxy,
    process.env.HTTPS_PROXY,
    process.env.https_proxy,
    process.env.HTTP_PROXY,
    process.env.http_proxy,
  ];
  for (const raw of candidates) {
    const parsed = parseAnyProxyEnvString(raw);
    if (parsed) return parsed;
  }
  return null;
}

async function isTcpEndpointReachable(host: string, port: number, timeoutMs = 800): Promise<boolean> {
  return await new Promise<boolean>((resolve) => {
    let done = false;
    const sock = new net.Socket();
    const finish = (ok: boolean) => {
      if (done) return;
      done = true;
      try {
        sock.destroy();
      } catch {}
      resolve(ok);
    };
    const timer = setTimeout(() => finish(false), timeoutMs);
    sock.once('connect', () => {
      clearTimeout(timer);
      finish(true);
    });
    sock.once('error', () => {
      clearTimeout(timer);
      finish(false);
    });
    try {
      sock.connect(port, host);
    } catch {
      clearTimeout(timer);
      finish(false);
    }
  });
}

async function openHttpConnectTunnelSocket(
  proxy: AutoSystemProxyConfig,
  targetHost: string,
  targetPort: number,
  timeoutMs = 8000
): Promise<net.Socket> {
  return await new Promise<net.Socket>((resolve, reject) => {
    let settled = false;
    const tlsServername = net.isIP(proxy.host) ? undefined : proxy.host;
    const baseSock =
      proxy.protocol === 'https'
        ? (tls.connect({
            host: proxy.host,
            port: proxy.port,
            ...(tlsServername ? { servername: tlsServername } : {}),
          }) as unknown as net.Socket)
        : net.connect({ host: proxy.host, port: proxy.port });

    let headerBuf = Buffer.alloc(0);
    const cleanupHandshakeListeners = () => {
      baseSock.removeListener('data', onData);
      baseSock.removeListener('close', onPrematureClose);
      baseSock.removeListener('end', onPrematureEnd);
    };
    const fail = (err: Error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      cleanupHandshakeListeners();
      try {
        baseSock.destroy();
      } catch {}
      reject(err);
    };
    const timer = setTimeout(
      () => fail(new Error(`HTTP proxy CONNECT timeout (${proxy.host}:${proxy.port})`)),
      timeoutMs
    );
    const onPrematureClose = () => fail(new Error(`HTTP proxy CONNECT closed (${proxy.host}:${proxy.port})`));
    const onPrematureEnd = () => fail(new Error(`HTTP proxy CONNECT ended (${proxy.host}:${proxy.port})`));

    baseSock.once('error', (err) => fail(err));
    baseSock.once('close', onPrematureClose);
    baseSock.once('end', onPrematureEnd);
    const connectEvent = proxy.protocol === 'https' ? 'secureConnect' : 'connect';
    baseSock.once(connectEvent, () => {
      const formattedHost = targetHost.includes(':') ? `[${targetHost}]` : targetHost;
      const authority = `${formattedHost}:${targetPort}`;
      const lines = [
        `CONNECT ${authority} HTTP/1.1`,
        `Host: ${authority}`,
        'Proxy-Connection: Keep-Alive',
      ];
      if (proxy.username || proxy.password) {
        const token = Buffer.from(`${proxy.username || ''}:${proxy.password || ''}`, 'utf8').toString('base64');
        lines.push(`Proxy-Authorization: Basic ${token}`);
      }
      lines.push('', '');
      baseSock.write(lines.join('\r\n'));
    });

    const onData = (chunk: Buffer) => {
      headerBuf = Buffer.concat([headerBuf, Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)]);
      const idx = headerBuf.indexOf('\r\n\r\n');
      if (idx === -1) {
        if (headerBuf.length > 16384) {
          fail(new Error('HTTP proxy CONNECT response header too large'));
        }
        return;
      }
      cleanupHandshakeListeners();
      const headerText = headerBuf.subarray(0, idx).toString('latin1');
      const statusMatch = headerText.match(/^HTTP\/\d\.\d\s+(\d{3})/i);
      const statusCode = statusMatch ? Number(statusMatch[1]) : 0;
      if (statusCode < 200 || statusCode >= 300) {
        fail(new Error(`HTTP proxy CONNECT rejected (HTTP ${statusCode})`));
        return;
      }
      const leftover = headerBuf.subarray(idx + 4);
      if (leftover.length > 0) {
        baseSock.pause();
        baseSock.unshift(leftover);
      }
      settled = true;
      clearTimeout(timer);
      resolve(baseSock);
    };
    baseSock.on('data', onData);
  });
}

function createHttpConnectNetworkSocketClass(httpProxy: AutoSystemProxyConfig) {
  return class HttpConnectPromisedNetSockets extends (PromisedNetSockets as any) {
    _connectCancelled = false;
    async connect(port: number, ip: string) {
      this._connectCancelled = false;
      this.stream = Buffer.alloc(0);
      const tunSock = await openHttpConnectTunnelSocket(httpProxy, ip, port, 8000);
      if (this._connectCancelled) {
        try {
          tunSock.destroy();
        } catch {}
        throw new Error('NetSocket was closed');
      }
      this.client = tunSock;
      this.canRead = new Promise((resolve) => {
        this.resolveRead = resolve;
      });
      this.closed = false;
      return await new Promise((resolve, reject) => {
        this.receive();
        this.client.resume?.();
        resolve(this);
        this.client.on('error', reject);
        this.client.on('close', () => {
          if (this.resolveRead) {
            this.resolveRead(false);
          }
          this.closed = true;
        });
      });
    }
    async close() {
      this._connectCancelled = true;
      return await super.close();
    }
  };
}

export type ResolvedEffectiveTelegramTransport =
  | {
      mode: 'socks';
      proxy: NonNullable<ReturnType<typeof getConfiguredTelegramProxy>>;
      source: 'manual' | 'auto_system';
    }
  | {
      mode: 'http';
      httpProxy: AutoSystemProxyConfig;
      source: 'auto_system';
    }
  | {
      mode: 'direct';
      source: 'direct';
    };

export async function resolveEffectiveTelegramTransport(
  manualProxyOverride?: ReturnType<typeof getConfiguredTelegramProxy>
): Promise<ResolvedEffectiveTelegramTransport> {
  const manual = manualProxyOverride !== undefined ? manualProxyOverride : getConfiguredTelegramProxy();
  if (manual) {
    return { mode: 'socks', proxy: manual, source: 'manual' };
  }
  const auto = getAutoDetectedSystemProxy();
  if (!auto) {
    return { mode: 'direct', source: 'direct' };
  }
  const alive = await isTcpEndpointReachable(auto.host, auto.port, 800);
  if (!alive) {
    return { mode: 'direct', source: 'direct' };
  }
  if (auto.protocol === 'socks4' || auto.protocol === 'socks5') {
    return {
      mode: 'socks',
      source: 'auto_system',
      proxy: {
        ip: auto.host,
        port: auto.port,
        socksType: auto.protocol === 'socks4' ? 4 : 5,
        timeout: 15,
        ...(auto.username ? { username: auto.username } : {}),
        ...(auto.password ? { password: auto.password } : {}),
      },
    };
  }
  return { mode: 'http', httpProxy: auto, source: 'auto_system' };
}

const TELEGRAM_OFFICIAL_INITIAL_DCS = [
  { dcId: 4, ip: '149.154.167.91', port: 443 },
  { dcId: 2, ip: '149.154.167.51', port: 443 },
  { dcId: 1, ip: '149.154.175.53', port: 443 },
] as const;

class ConnectionTCPObfuscated443 extends ConnectionTCPObfuscated {
  constructor(params: any) {
    super({
      ...params,
      port: params?.port === 80 ? 443 : params?.port || 443,
    });
  }
}

async function connectNewTelegramClientWithDcFallback(opts: {
  apiId: number;
  apiHash: string;
  label: string;
  registerGuard: (client: TelegramClient) => void;
}): Promise<TelegramClient> {
  const effectiveTransport = await resolveEffectiveTelegramTransport();

  const attemptTransportModes: ResolvedEffectiveTelegramTransport[] =
    effectiveTransport.source === 'auto_system'
      ? [effectiveTransport, { mode: 'direct', source: 'direct' }]
      : [effectiveTransport];

  let lastErr: any = null;
  for (const transport of attemptTransportModes) {
    const dcsToTry =
      effectiveTransport.source === 'auto_system'
        ? transport.source === 'direct'
          ? [TELEGRAM_OFFICIAL_INITIAL_DCS[0]]
          : TELEGRAM_OFFICIAL_INITIAL_DCS.slice(0, 2)
        : TELEGRAM_OFFICIAL_INITIAL_DCS;

    for (const dc of dcsToTry) {
      const stringSession = new StringSession('');
      stringSession.setDC(dc.dcId, dc.ip, dc.port);
      const client = new TelegramClient(stringSession, opts.apiId, opts.apiHash, {
        ...TELEGRAM_CLIENT_RETRY_OPTIONS,
        connectionRetries: 1,
        retryDelay: 500,
        useWSS: false,
        connection: ConnectionTCPObfuscated443,
        autoReconnect: true,
        ...TELEGRAM_DESKTOP_CLIENT_PARAMS,
        ...(transport.mode === 'socks'
          ? { proxy: transport.proxy }
          : transport.mode === 'http'
            ? { networkSocket: createHttpConnectNetworkSocketClass(transport.httpProxy) as any }
            : {}),
      });
      opts.registerGuard(client);
      try {
        await withTelegramTimeout(
          client.connect(),
          4000,
          '连接 Telegram 服务器超时，请检查网络或代理设置后重试'
        );
        return client;
      } catch (err: any) {
        lastErr = err;
        await destroyTelegramClientSafely(client);
        console.warn(
          `[Telegram Auth Connect] ${opts.label} DC${dc.dcId}(${dc.ip}:${dc.port}) via ${transport.mode}/${transport.source} failed: ${err?.message || err}`
        );
      }
    }
  }

  throw lastErr || new Error('连接 Telegram 服务器超时，请检查网络或代理设置后重试');
}

function getCloudCredsCacheKey(bearerToken?: string): string {
  if (!bearerToken || !bearerToken.trim()) return '__default__';
  return crypto.createHash('sha256').update(bearerToken.trim()).digest('hex').slice(0, 24);
}

export function getInMemoryTelegramApiCredentials(bearerToken?: string): InMemoryCloudTelegramCredentials | null {
  const now = Date.now();
  const key = getCloudCredsCacheKey(bearerToken);
  const entry = inMemoryCloudTelegramCreds.get(key) || (bearerToken ? null : inMemoryCloudTelegramCreds.get('__default__'));
  if (!entry) return null;
  if (now - entry.fetchedAt > CLOUD_CREDS_RAM_TTL_MS) {
    inMemoryCloudTelegramCreds.delete(key);
    return null;
  }
  return entry;
}

export function clearInMemoryTelegramApiCredentials(bearerToken?: string): void {
  if (bearerToken) {
    inMemoryCloudTelegramCreds.delete(getCloudCredsCacheKey(bearerToken));
  } else {
    inMemoryCloudTelegramCreds.clear();
  }
  clearOfflineGraceTelegramCredentials();
}

export async function purgePersistedTelegramApiCredentialsFromDb(): Promise<void> {
  try {
    await db.prepare("DELETE FROM system_config WHERE key = 'telegram_api_credentials'").run();
  } catch {}
  try {
    await db
      .prepare('UPDATE telegram_user_sessions SET api_id = NULL, api_hash = NULL WHERE api_id IS NOT NULL OR api_hash IS NOT NULL')
      .run();
  } catch {}
}

export async function fetchWithSystemProxySupport(
  urlStr: string,
  options: RequestInit = {},
  timeoutMs = 12000,
  pinnedOverride?: { address: string; family: 4 | 6 },
  socksConnectImpl: typeof SocksClient.createConnection = SocksClient.createConnection
): Promise<globalThis.Response> {
  const parsedUrl = new URL(urlStr);
  const rawHost = parsedUrl.hostname.trim();
  const cleanHost = rawHost.startsWith('[') && rawHost.endsWith(']') ? rawHost.slice(1, -1) : rawHost;
  const proxy = getConfiguredTelegramProxy();

  const runFetchWithCombinedTimeout = async (
    target: string,
    reqInit: RequestInit,
    ms: number
  ): Promise<globalThis.Response> => {
    const extSignal = reqInit.signal;
    if (!extSignal) {
      return await fetch(target, { ...reqInit, signal: AbortSignal.timeout(ms) });
    }
    const timeoutSig = AbortSignal.timeout(ms);
    if (typeof (AbortSignal as any).any === 'function') {
      return await fetch(target, {
        ...reqInit,
        signal: (AbortSignal as any).any([extSignal, timeoutSig]),
      });
    }
    const combinedController = new AbortController();
    const onExternalAbort = () => combinedController.abort((extSignal as any)?.reason);
    const onTimeoutAbort = () => combinedController.abort((timeoutSig as any)?.reason);
    if (extSignal.aborted) {
      combinedController.abort((extSignal as any)?.reason);
    } else {
      extSignal.addEventListener('abort', onExternalAbort, { once: true });
    }
    timeoutSig.addEventListener('abort', onTimeoutAbort, { once: true });
    try {
      return await fetch(target, { ...reqInit, signal: combinedController.signal });
    } catch (err) {
      extSignal.removeEventListener('abort', onExternalAbort);
      timeoutSig.removeEventListener('abort', onTimeoutAbort);
      throw err;
    }
  };

  // Never route local loopback traffic through external proxy
  if (isAllowedLocalhostEndpoint(cleanHost)) {
    return await runFetchWithCombinedTimeout(urlStr, options, timeoutMs);
  }

  let autoHttpProxy: AutoSystemProxyConfig | null = null;
  let effectiveSocksProxy = proxy;
  let usingAutoProxy = false;

  if (!effectiveSocksProxy) {
    const auto = getAutoDetectedSystemProxy();
    if (auto && (await isTcpEndpointReachable(auto.host, auto.port, 700))) {
      usingAutoProxy = true;
      if (auto.protocol === 'socks4' || auto.protocol === 'socks5') {
        effectiveSocksProxy = {
          ip: auto.host,
          port: auto.port,
          socksType: auto.protocol === 'socks4' ? 4 : 5,
          ...(auto.username ? { username: auto.username } : {}),
          ...(auto.password ? { password: auto.password } : {}),
        };
      } else {
        autoHttpProxy = auto;
      }
    } else {
      return await runFetchWithCombinedTimeout(urlStr, options, timeoutMs);
    }
  }

  const targetPort = parsedUrl.port
    ? Number(parsedUrl.port)
    : parsedUrl.protocol === 'https:'
      ? 443
      : 80;
  const isHttps = parsedUrl.protocol === 'https:';

  let rawSocket: net.Socket;
  try {
    if (effectiveSocksProxy) {
      const conn = await socksConnectImpl({
        proxy: {
          host: effectiveSocksProxy.ip,
          port: effectiveSocksProxy.port,
          type: effectiveSocksProxy.socksType,
          ...(effectiveSocksProxy.username ? { userId: effectiveSocksProxy.username } : {}),
          ...(effectiveSocksProxy.password ? { password: effectiveSocksProxy.password } : {}),
        },
        command: 'connect',
        destination: {
          host: pinnedOverride?.address || cleanHost,
          port: targetPort,
        },
        timeout: timeoutMs,
      });
      rawSocket = conn.socket;
    } else {
      rawSocket = await openHttpConnectTunnelSocket(
        autoHttpProxy!,
        pinnedOverride?.address || cleanHost,
        targetPort,
        timeoutMs
      );
    }
  } catch (tunnelErr) {
    if (usingAutoProxy) {
      return await runFetchWithCombinedTimeout(urlStr, options, timeoutMs);
    }
    throw tunnelErr;
  }

  const reqHeaders: Record<string, string> = {};
  if (options.headers) {
    const h = new Headers(options.headers);
    h.forEach((v, k) => {
      reqHeaders[k] = v;
    });
  }
  const bodyRaw =
    typeof options.body === 'string'
      ? Buffer.from(options.body, 'utf8')
      : Buffer.isBuffer(options.body)
        ? options.body
        : options.body instanceof Uint8Array
          ? Buffer.from(options.body)
          : options.body instanceof ArrayBuffer
            ? Buffer.from(options.body)
            : undefined;
  if (bodyRaw && !Object.keys(reqHeaders).some((k) => k.toLowerCase() === 'content-length')) {
    reqHeaders['Content-Length'] = String(bodyRaw.length);
  }
  if (!Object.keys(reqHeaders).some((k) => k.toLowerCase() === 'host')) {
    reqHeaders['Host'] = parsedUrl.host;
  }
  reqHeaders['Connection'] = 'close';

  return await new Promise<globalThis.Response>((resolve, reject) => {
    let settled = false;
    let activeSocket: net.Socket | tls.TLSSocket = rawSocket;
    let reqTimer: NodeJS.Timeout | null = null;
    const signal = options.signal;
    const onAbort = () => {
      const abortErr: any = new Error('The operation was aborted due to timeout');
      abortErr.name = 'TimeoutError';
      finishErr(abortErr);
    };
    const finishErr = (err: any) => {
      if (settled) return;
      settled = true;
      if (reqTimer) {
        clearTimeout(reqTimer);
        reqTimer = null;
      }
      if (signal) signal.removeEventListener('abort', onAbort);
      try {
        activeSocket.destroy();
      } catch {}
      try {
        rawSocket.destroy();
      } catch {}
      reject(err);
    };

    if (signal) {
      if (signal.aborted) {
        onAbort();
        return;
      }
      signal.addEventListener('abort', onAbort, { once: true });
    }

    reqTimer = setTimeout(() => {
      const tErr: any = new Error(`Request timeout (${timeoutMs}ms)`);
      tErr.name = 'TimeoutError';
      finishErr(tErr);
    }, timeoutMs);

    const mod = isHttps ? https : http;
    const tlsServername = net.isIP(cleanHost) ? undefined : cleanHost;
    const proxyAgent = new (isHttps ? https.Agent : http.Agent)({ keepAlive: false });
    (proxyAgent as any).createConnection = () => {
      activeSocket = isHttps
        ? tls.connect({
            socket: rawSocket,
            ...(tlsServername ? { servername: tlsServername } : {}),
          })
        : rawSocket;
      return activeSocket;
    };
    const req = mod.request(
      {
        hostname: cleanHost,
        port: targetPort,
        path: `${parsedUrl.pathname}${parsedUrl.search}`,
        method: options.method || 'GET',
        headers: reqHeaders,
        agent: proxyAgent,
      },
      (res) => {
        const chunks: Buffer[] = [];
        let resEnded = false;
        res.on('data', (chunk: Buffer) => chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)));
        res.on('end', () => {
          resEnded = true;
          if (reqTimer) {
            clearTimeout(reqTimer);
            reqTimer = null;
          }
          if (signal) signal.removeEventListener('abort', onAbort);
          if (settled) return;
          settled = true;
          const respHeaders = new Headers();
          for (const [k, v] of Object.entries(res.headers)) {
            if (Array.isArray(v)) {
              v.forEach((item) => respHeaders.append(k, item));
            } else if (typeof v === 'string') {
              respHeaders.set(k, v);
            }
          }
          const fullBuf = Buffer.concat(chunks);
          const status = res.statusCode || 502;
          const responseBody = status === 204 || status === 205 || status === 304 ? null : fullBuf;
          resolve(
            new Response(responseBody, {
              status,
              statusText: res.statusMessage || '',
              headers: respHeaders,
            })
          );
        });
        res.on('close', () => {
          if (!resEnded && !settled) {
            finishErr(new Error('Proxy upstream connection closed prematurely'));
          }
        });
        res.on('error', (err) => {
          finishErr(err);
        });
      }
    );

    req.on('error', (err) => {
      finishErr(err);
    });

    if (bodyRaw) {
      req.write(bodyRaw);
    }
    req.end();
  });
}

export async function fetchCloudAuthorizedTelegramCredentials(
  bearerToken: string
): Promise<ResolvedTelegramCredentials> {
  if (!bearerToken) {
    const errObj = {
      ok: false as const,
      source: 'none' as const,
      code: 'TELEGRAM_API_CREDENTIALS_REQUIRED',
      error: '尚未登录会员，无法自动分发 Telegram 接入凭据',
    };
    lastCloudCredsError = { code: errObj.code, error: errObj.error, at: Date.now() };
    return errObj;
  }
  try {
    const res = await fetchWithSystemProxySupport(
      `${CLOUD_AUTH_BASE_URL}/api/auth/telegram-credentials`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${bearerToken}`,
        },
        body: JSON.stringify({
          deviceId: getLocalMachineDeviceId(),
        }),
      },
      12000
    );
    const data = (await res.json().catch(() => ({}))) as any;
    const apiId = Number(data?.apiId);
    const apiHash = String(data?.apiHash || '').trim();
    if (!res.ok || !data?.ok || !Number.isInteger(apiId) || apiId <= 0 || !apiHash) {
      const code = String(data?.code || 'CLOUD_CREDENTIALS_UNAVAILABLE');
      const isAuthRejection =
        res.status === 401 ||
        res.status === 403 ||
        code === 'VIP_EXPIRED' ||
        code === 'DEVICE_MISMATCH' ||
        code === 'AUTH_SESSION_REVOKED' ||
        code === 'AUTH_SESSION_REQUIRED';
      if (isAuthRejection) {
        clearOfflineGraceTelegramCredentials();
      }
      const errObj = {
        ok: false as const,
        source: 'none' as const,
        code,
        error: data?.error || `云端授权分配接入凭据失败 (HTTP ${res.status})`,
      };
      lastCloudCredsError = { code: errObj.code, error: errObj.error, isAuthRejection, at: Date.now() };
      return errObj;
    }

    // Store in RAM + short-term hardware-fingerprint & valid-JWT encrypted grace cache (never in SQLite or sent to frontend)
    const record: InMemoryCloudTelegramCredentials = {
      apiId,
      apiHash,
      source: 'cloud_authorized',
      poolLabel: data?.poolLabel ? String(data.poolLabel) : undefined,
      fetchedAt: Date.now(),
    };
    inMemoryCloudTelegramCreds.set(getCloudCredsCacheKey(bearerToken), record);
    inMemoryCloudTelegramCreds.set('__default__', record);
    pruneInMemoryCloudTelegramCreds();
    writeOfflineGraceTelegramCredentials({
      bearerToken,
      apiId,
      apiHash,
      poolLabel: record.poolLabel,
    });
    lastCloudCredsError = null;

    return {
      ok: true,
      apiId,
      apiHash,
      source: 'cloud_authorized',
      poolLabel: record.poolLabel,
    };
  } catch (err: any) {
    const isTimeout = err?.name === 'TimeoutError' || /aborted|timeout/i.test(String(err?.message || ''));
    const errObj = {
      ok: false as const,
      source: 'none' as const,
      code: 'CLOUD_CREDENTIALS_UNAVAILABLE',
      error: isTimeout
        ? '连接云端授权中心超时（12s），请检查本机网络或代理后重试'
        : `连接云端授权中心获取接入凭据失败: ${err?.message || '网络异常'}`,
    };
    lastCloudCredsError = { code: errObj.code, error: errObj.error, isAuthRejection: false, at: Date.now() };
    return errObj;
  }
}

export async function ensureCloudTelegramCredentialsIfNeeded(bearerToken: string): Promise<void> {
  if (getInMemoryTelegramApiCredentials(bearerToken)) return;
  if (getEnvTelegramApiCredentials()) return;
  await resolveTelegramApiCredentials({ bearerToken });
}

export async function resolveTelegramApiCredentials(options: {
  reqApiId?: unknown;
  reqApiHash?: unknown;
  bearerToken?: string;
  forceCloudRefresh?: boolean;
}): Promise<ResolvedTelegramCredentials> {
  if (options.bearerToken) {
    if (!options.forceCloudRefresh) {
      const cachedMem = getInMemoryTelegramApiCredentials(options.bearerToken);
      if (cachedMem) {
        return {
          ok: true,
          apiId: cachedMem.apiId,
          apiHash: cachedMem.apiHash,
          source: cachedMem.source,
          isOfflineGrace: cachedMem.source === 'cloud_offline_grace',
          poolLabel: cachedMem.poolLabel,
        };
      }
    }
    const cloudRes = await fetchCloudAuthorizedTelegramCredentials(options.bearerToken);
    if (cloudRes.ok) {
      return cloudRes;
    }

    // Offline grace cache fallback when cloud auth server is temporarily unreachable/offline (never on auth rejection)
    if (!lastCloudCredsError?.isAuthRejection) {
      const grace = readOfflineGraceTelegramCredentials(options.bearerToken);
      if (grace) {
        const record: InMemoryCloudTelegramCredentials = {
          apiId: grace.apiId,
          apiHash: grace.apiHash,
          source: 'cloud_offline_grace',
          poolLabel: grace.poolLabel,
          fetchedAt: Date.now(),
        };
        inMemoryCloudTelegramCreds.set(getCloudCredsCacheKey(options.bearerToken), record);
        inMemoryCloudTelegramCreds.set('__default__', record);
        pruneInMemoryCloudTelegramCreds();
        return {
          ok: true,
          apiId: grace.apiId,
          apiHash: grace.apiHash,
          source: 'cloud_offline_grace',
          isOfflineGrace: true,
          poolLabel: grace.poolLabel,
        };
      }
    }

    const envFallback = getEnvTelegramApiCredentials();
    if (envFallback) {
      return {
        ok: true,
        apiId: envFallback.apiId,
        apiHash: envFallback.apiHash,
        source: 'env',
      };
    }
    return cloudRes;
  }

  const cachedDefault = !options.forceCloudRefresh ? getInMemoryTelegramApiCredentials() : null;
  if (cachedDefault) {
    return {
      ok: true,
      apiId: cachedDefault.apiId,
      apiHash: cachedDefault.apiHash,
      source: cachedDefault.source,
      isOfflineGrace: cachedDefault.source === 'cloud_offline_grace',
      poolLabel: cachedDefault.poolLabel,
    };
  }

  if (lastActiveUserJwt) {
    const graceFromLastJwt = readOfflineGraceTelegramCredentials(lastActiveUserJwt);
    if (graceFromLastJwt) {
      return {
        ok: true,
        apiId: graceFromLastJwt.apiId,
        apiHash: graceFromLastJwt.apiHash,
        source: 'cloud_offline_grace',
        isOfflineGrace: true,
        poolLabel: graceFromLastJwt.poolLabel,
      };
    }
  }

  const envCreds = getEnvTelegramApiCredentials();
  if (envCreds) {
    return {
      ok: true,
      apiId: envCreds.apiId,
      apiHash: envCreds.apiHash,
      source: 'env',
    };
  }

  return {
    ok: false,
    source: 'none',
    code: 'TELEGRAM_API_CREDENTIALS_REQUIRED',
    error: '云端暂未为当前会员分发可用的 Telegram 接入凭据，请确认已登录有效会员或联系管理员检查云端凭据池。',
  };
}

