app.post('/api/system/proxy', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, code: 'MASTER_REQUIRED', error: '权限不足：仅主账号会员有权修改全局网络代理' });
    }
    const existing = await loadSystemProxyConfigFromDb();
    const incomingPassword = typeof req.body?.password === 'string' ? req.body.password : undefined;
    const preserveExistingPassword =
      req.body?.preservePassword !== false && incomingPassword === undefined && existing?.password;

    const validated = normalizeAndValidateProxyConfig({
      enabled: req.body?.enabled,
      type: req.body?.type,
      host: req.body?.host,
      port: req.body?.port,
      username: req.body?.username,
      password: preserveExistingPassword ? existing?.password : incomingPassword,
    });
    if (!validated.ok) {
      return res.status(400).json({ ok: false, error: validated.error });
    }
    await saveSystemProxyConfigToDb(validated.config);
    let reconnecting = false;
    if (process.env.NODE_ENV !== 'test' && process.env.AIS_TEST_IMPORT !== 'true') {
      const bearerToken = extractBearerToken(req) || lastActiveUserJwt || undefined;
      const recoveryPlan = await triggerProxyChangeRecovery(bearerToken);
      reconnecting = recoveryPlan.triggered;
    }
    return res.json({
      ok: true,
      reconnecting,
      config: {
        enabled: validated.config.enabled,
        type: validated.config.type,
        host: validated.config.host,
        port: validated.config.port,
        username: validated.config.username || '',
        hasPassword: Boolean(validated.config.password),
      },
      message: validated.config.enabled
        ? `已保存 ${validated.config.type.toUpperCase()} 代理 (${validated.config.host}:${validated.config.port})，正自动重连活跃 Telegram 会话`
        : '已关闭内置代理并恢复直连，正自动重连活跃 Telegram 会话',
    });
  } catch (err: any) {
    return res.status(500).json({ ok: false, error: err?.message || '保存代理设置失败' });
  }
});

function parseSemverTuple(rawVersion: string): [number, number, number] {
  const clean = String(rawVersion || '')
    .trim()
    .replace(/^v/i, '')
    .split('-')[0]
    .split('+')[0];
  const parts = clean.split('.').map((n) => {
    const parsed = parseInt(n, 10);
    return Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
  });
  return [parts[0] || 0, parts[1] || 0, parts[2] || 0];
}

function compareSemver(a: string, b: string): number {
  const pa = parseSemverTuple(a);
  const pb = parseSemverTuple(b);
  for (let i = 0; i < 3; i++) {
    if (pa[i] > pb[i]) return 1;
    if (pa[i] < pb[i]) return -1;
  }
  return 0;
}

function readLocalAppVersion(): string {
  const candidates = [
    path.resolve(__dirname, 'package.json'),
    path.resolve(__dirname, '..', 'package.json'),
  ];
  for (const pkgPath of candidates) {
    try {
      if (fs.existsSync(pkgPath)) {
        const parsed = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
        if (parsed && typeof parsed.version === 'string' && parsed.version.trim()) {
          return parsed.version.trim();
        }
      }
    } catch {}
  }
  return '1.2.6';
}

// Lightweight GitHub Releases version check (portable & installer compatible)
app.get('/api/system/check-update', requireTenantAuth, async (_req: Request, res: Response) => {
  const currentVersion = readLocalAppVersion();
  const rawRepo = (process.env.GITHUB_UPDATE_REPO || '1988221as-cpu/telegram-aiapp').trim();
  const repo = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(rawRepo)
    ? rawRepo
    : '1988221as-cpu/telegram-aiapp';
  const fallbackReleaseUrl = `https://github.com/${repo}/releases`;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const ghToken = (process.env.GITHUB_TOKEN || '').trim();
    const ghRes = await fetch(`https://api.github.com/repos/${repo}/releases/latest`, {
      headers: {
        Accept: 'application/vnd.github+json',
        'User-Agent': 'HumanSense-Updater',
        ...(ghToken ? { Authorization: `Bearer ${ghToken}` } : {}),
      },
      signal: controller.signal,
    });

    if (ghRes.status === 404) {
      return res.json({
        ok: true,
        hasUpdate: false,
        currentVersion,
        latestVersion: currentVersion,
        noReleasesYet: true,
        releaseUrl: fallbackReleaseUrl,
        downloadUrl: fallbackReleaseUrl,
      });
    }

    if (!ghRes.ok) {
      return res.status(502).json({
        ok: false,
        currentVersion,
        error: `GitHub 版本检查请求失败 (HTTP ${ghRes.status})`,
      });
    }

    const release: any = await ghRes.json();
    const latestTag = String(release?.tag_name || release?.name || '').trim();
    const latestVersion = latestTag.replace(/^v/i, '') || currentVersion;
    const releaseUrl =
      typeof release?.html_url === 'string' && release.html_url.startsWith('https://')
        ? release.html_url
        : fallbackReleaseUrl;

    const assets: any[] = Array.isArray(release?.assets) ? release.assets : [];
    const exeAssets = assets.filter(
      (a) =>
        typeof a?.name === 'string' &&
        /\.exe$/i.test(a.name) &&
        !/^Uninstall/i.test(a.name) &&
        typeof a?.browser_download_url === 'string' &&
        a.browser_download_url.startsWith('https://')
    );
    const portableExe = exeAssets.find((a) => !/setup|installer/i.test(a.name));
    const installerExe = exeAssets.find((a) => /setup|installer/i.test(a.name));
    const latestYmlAsset = assets.find(
      (a) =>
        typeof a?.name === 'string' &&
        a.name.toLowerCase() === 'latest.yml' &&
        typeof a?.browser_download_url === 'string' &&
        a.browser_download_url.startsWith('https://')
    );
    const preferredAsset = portableExe || exeAssets[0] || null;
    const downloadUrl = preferredAsset?.browser_download_url || releaseUrl;

    const hasUpdate = Boolean(latestTag) && compareSemver(latestVersion, currentVersion) > 0;
    return res.json({
      ok: true,
      hasUpdate,
      currentVersion,
      latestVersion,
      tagName: latestTag || `v${latestVersion}`,
      releaseName: String(release?.name || latestTag || `v${latestVersion}`),
      releaseNotes: typeof release?.body === 'string' ? release.body.slice(0, 4000) : '',
      publishedAt: typeof release?.published_at === 'string' ? release.published_at : undefined,
      releaseUrl,
      downloadUrl,
      assetName: preferredAsset?.name || undefined,
      portableDownloadUrl: portableExe?.browser_download_url || undefined,
      portableAssetName: portableExe?.name || undefined,
      installerDownloadUrl: installerExe?.browser_download_url || undefined,
      installerAssetName: installerExe?.name || undefined,
      latestYmlUrl: latestYmlAsset?.browser_download_url || undefined,
    });
  } catch (err: any) {
    const isAbort = err?.name === 'AbortError';
    return res.status(504).json({
      ok: false,
      currentVersion,
      error: isAbort ? '连接 GitHub 检测更新超时，请稍后再试' : err?.message || '检查更新失败',
    });
  } finally {
    clearTimeout(timer);
  }
});

export interface ExpiredTelegramAccountInfo {
  accountId: string;
  userId?: string;
  phone?: string;
  reason: string;
  expiredAt: number;
}

export const recentlyExpiredAccounts = new Map<string, ExpiredTelegramAccountInfo>();

export function isTelegramSessionExpiredError(err: any): boolean {
  const msg = String(err?.errorMessage || err?.message || err || '').toUpperCase();
  return (
    msg.includes('AUTH_KEY_UNREGISTERED') ||
    msg.includes('AUTH_KEY_INVALID') ||
    msg.includes('AUTH_KEY_PERM_EMPTY') ||
    msg.includes('SESSION_REVOKED') ||
    msg.includes('SESSION_EXPIRED') ||
    msg.includes('USER_DEACTIVATED') ||
    msg.includes('AUTH_KEY_DUPLICATED')
  );
}

export interface TelegramTimeoutOptions {
  signal?: AbortSignal;
  onTimeout?: () => void | Promise<void>;
  onAbort?: () => void | Promise<void>;
}

const activeTimeoutCleanupCallbacks = new Set<() => void>();

export async function withTelegramTimeout<T>(
  promiseOrFactory: Promise<T> | ((ctx: { signal: AbortSignal }) => Promise<T>),
  timeoutMs = 15000,
  timeoutMessage = '连接 Telegram 服务器超时，请检查网络或代理设置后重试',
  options?: TelegramTimeoutOptions
): Promise<T> {
  const opStartedAt = Date.now();
  const controller = new AbortController();
  let timer: NodeJS.Timeout | null = null;
  let settled = false;
  let cleanupDone = false;

  const runCleanupOnce = (reason: 'timeout' | 'abort' | 'shutdown') => {
    if (cleanupDone) return;
    cleanupDone = true;
    try {
      const fn =
        reason === 'abort' && options?.onAbort
          ? options.onAbort
          : options?.onTimeout;
      const res = fn?.();
      if (res && typeof (res as Promise<void>).catch === 'function') {
        (res as Promise<void>).catch(() => {});
      }
    } catch {}
  };

  let targetPromise: Promise<T>;
  try {
    targetPromise =
      typeof promiseOrFactory === 'function'
        ? promiseOrFactory({ signal: controller.signal })
        : promiseOrFactory;
  } catch (syncErr) {
    recordWrappedRpcMetric(timeoutMessage, Date.now() - opStartedAt, false, syncErr, false);
    return Promise.reject(syncErr);
  }

  // Prevent UnhandledPromiseRejection if an underlying socket/connect rejects after timeout or abort
  targetPromise.catch(() => {});

  return await new Promise<T>((resolve, reject) => {
    const detachListeners = () => {
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      activeTimeoutCleanupCallbacks.delete(forceAbortOnShutdown);
      if (options?.signal) {
        options.signal.removeEventListener('abort', abortCleanup);
      }
    };

    const abortCleanup = () => {
      if (settled) return;
      settled = true;
      detachListeners();
      const abortErr = new Error('操作已取消');
      recordWrappedRpcMetric(timeoutMessage, Date.now() - opStartedAt, false, abortErr, false);
      controller.abort(abortErr);
      runCleanupOnce('abort');
      reject(abortErr);
    };

    const forceAbortOnShutdown = () => {
      if (settled) return;
      settled = true;
      detachListeners();
      const shutdownErr = new Error('服务正在关闭，连接任务已取消');
      recordWrappedRpcMetric(timeoutMessage, Date.now() - opStartedAt, false, shutdownErr, false);
      controller.abort(shutdownErr);
      runCleanupOnce('shutdown');
      reject(shutdownErr);
    };

    activeTimeoutCleanupCallbacks.add(forceAbortOnShutdown);

    if (options?.signal) {
      if (options.signal.aborted) {
        abortCleanup();
        return;
      }
      options.signal.addEventListener('abort', abortCleanup, { once: true });
    }

    timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      detachListeners();
      const timeoutErr = new Error(timeoutMessage);
      recordWrappedRpcMetric(timeoutMessage, Date.now() - opStartedAt, false, timeoutErr, true);
      controller.abort(timeoutErr);
      runCleanupOnce('timeout');
      reject(timeoutErr);
    }, timeoutMs);

    targetPromise.then(
      (val) => {
        if (settled) return;
        settled = true;
        detachListeners();
        recordWrappedRpcMetric(timeoutMessage, Date.now() - opStartedAt, true);
        resolve(val);
      },
      (err) => {
        if (settled) return;
        settled = true;
        detachListeners();
        recordWrappedRpcMetric(timeoutMessage, Date.now() - opStartedAt, false, err, false);
        reject(err);
      }
    );
  });
}

export async function probeTelegramTransportEndpoint(options: {
  proxy?: { ip: string; port: number; socksType: 4 | 5; username?: string; password?: string };
  targetHost?: string;
  targetPort?: number;
  connectTimeoutMs?: number;
  handshakeTimeoutMs?: number;
  signal?: AbortSignal;
}): Promise<void> {
  const proxy = options.proxy;
  if (!proxy) return;

  const connectTimeoutMs = options.connectTimeoutMs ?? 5000;
  const handshakeTimeoutMs = options.handshakeTimeoutMs ?? 7000;
  const targetHost = options.targetHost || '149.154.167.91';
  const targetPort = options.targetPort || 80;

  // Step 1: Direct TCP reachability check to SOCKS proxy port (supports AbortSignal + immediate socket destruction)
  const connectedTcpSocket = await new Promise<net.Socket>((resolve, reject) => {
    let settled = false;
    const sock = new net.Socket();
    let timer: NodeJS.Timeout | null = null;

    const detach = () => {
      if (timer) {
        clearTimeout(timer);
        timer = null;
      }
      options.signal?.removeEventListener('abort', onAbort);
      sock.removeAllListeners('connect');
      sock.removeAllListeners('error');
    };

    const fail = (err: Error) => {
      if (settled) return;
      settled = true;
      detach();
      try {
        sock.destroy();
      } catch {}
      reject(err);
    };

    const onAbort = () => fail(new TelegramNetworkError('proxy_timeout', '代理连接探测已取消'));
    if (options.signal?.aborted) {
      onAbort();
      return;
    }
    options.signal?.addEventListener('abort', onAbort, { once: true });

    timer = setTimeout(() => {
      fail(
        new TelegramNetworkError(
          'proxy_timeout',
          `代理连接超时（${proxy.ip}:${proxy.port} 在 ${Math.round(connectTimeoutMs / 1000)} 秒内无响应）`
        )
      );
    }, connectTimeoutMs);

    sock.once('connect', () => {
      if (settled) return;
      settled = true;
      detach();
      resolve(sock);
    });

    sock.once('error', (err: any) => {
      const code = String(err?.code || '');
      if (
        code === 'ECONNREFUSED' ||
        code === 'EHOSTUNREACH' ||
        code === 'ENETUNREACH' ||
        code === 'ENOTFOUND'
      ) {
        fail(
          new TelegramNetworkError(
            'proxy_timeout',
            `无法连接到代理服务器 ${proxy.ip}:${proxy.port} (${code})，请确认代理服务已开启`,
            err
          )
        );
        return;
      }
      fail(
        new TelegramNetworkError(
          'proxy_timeout',
          `代理 TCP 连接异常 (${err?.message || code || 'unknown'})`,
          err
        )
      );
    });

    try {
      sock.connect(proxy.port, proxy.ip);
    } catch (syncErr: any) {
      fail(
        new TelegramNetworkError(
          'proxy_timeout',
          `代理地址无效: ${syncErr?.message || proxy.ip}`,
          syncErr
        )
      );
    }
  });

  // Step 2: Explicit SOCKS4/5 handshake check reusing connectedTcpSocket so abort/timeout destroys FD immediately
  let socksSocket: net.Socket | null = connectedTcpSocket;
  let handshakeAbortedOrTimedOut = false;
  const destroySocksSocketSafely = () => {
    handshakeAbortedOrTimedOut = true;
    const s = socksSocket;
    socksSocket = null;
    try {
      s?.destroy();
    } catch {}
  };

  try {
    const rawHandshakePromise = SocksClient.createConnection({
      proxy: {
        host: proxy.ip,
        port: proxy.port,
        type: proxy.socksType,
        ...(proxy.username ? { userId: proxy.username } : {}),
        ...(proxy.password ? { password: proxy.password } : {}),
      },
      command: 'connect',
      timeout: handshakeTimeoutMs,
      existing_socket: connectedTcpSocket,
      destination: {
        host: targetHost,
        port: targetPort,
      },
    }).then((info) => {
      if (handshakeAbortedOrTimedOut) {
        try {
          info?.socket?.destroy();
        } catch {}
      } else {
        socksSocket = info?.socket || socksSocket;
      }
      return info;
    });

    const connInfo = await withTelegramTimeout(
      rawHandshakePromise,
      handshakeTimeoutMs + 500,
      `代理握手或目标建连超时 (${proxy.ip}:${proxy.port})`,
      {
        signal: options.signal,
        onTimeout: destroySocksSocketSafely,
        onAbort: destroySocksSocketSafely,
      }
    );
    socksSocket = connInfo?.socket || socksSocket;
  } catch (socksErr: any) {
    if (socksErr instanceof TelegramNetworkError) {
      throw socksErr;
    }
    const rawMsg = String(socksErr?.message || socksErr || '');
    const upper = rawMsg.toUpperCase();
    if (
      upper.includes('AUTHENTICATION') ||
      upper.includes('SOCKS') ||
      upper.includes('HANDSHAKE') ||
      upper.includes('NOT ALLOWED') ||
      upper.includes('UNSUPPORTED') ||
      upper.includes('FAILURE')
    ) {
      throw new TelegramNetworkError(
        'proxy_handshake',
        `SOCKS${proxy.socksType} 代理握手或认证失败（${rawMsg}）`,
        socksErr
      );
    }
    throw new TelegramNetworkError(
      'telegram_unreachable',
      `代理服务已连接，但无法经由代理抵达 Telegram 服务器 ${targetHost}:${targetPort}（${rawMsg}）`,
      socksErr
    );
  } finally {
    destroySocksSocketSafely();
  }
}

export async function markTelegramSessionExpired(opts: {
  accountId?: string;
  userId?: string;
  phone?: string;
  reason?: string;
}) {
  const { accountId, userId, phone, reason } = opts;
  const connected = resolveConnectedTelegramUser(accountId, phone, userId);
  let resolvedUserId =
    String(userId || '').trim() ||
    String(connected?.userId || '').trim() ||
    (accountId?.startsWith('acc_tg_')
      ? accountId.replace(/^acc_tg_/, '').trim()
      : accountId?.startsWith('tg_')
        ? accountId.replace(/^tg_/, '').trim()
        : accountId && !/^00\d+$/.test(accountId.trim()) && /^\d+$/.test(accountId.trim())
          ? accountId.trim()
          : '');
  let resolvedPhone = String(phone || '').trim() || String(connected?.phone || '').trim();
  if (
    !resolvedPhone &&
    accountId &&
    (accountId.trim().startsWith('+') || /^00\d+$/.test(accountId.trim()))
  ) {
    resolvedPhone = accountId.trim();
  }
  const inputNormPhone = resolvedPhone ? normalizePhoneNumber(resolvedPhone) : '';

  // 3-step uniqueness validation against telegram_user_sessions (PK: phone):
  // 1) lookup by user_id -> 2) lookup by normalized phone -> 3) cross-verify same row before single-row UPDATE
  let validatedDbRow: { phone: string; user_id: string | null } | null = null;
  let dbIdentityConflict = false;
  try {
    let uidRow: { phone: string; user_id: string | null } | null = null;
    let phoneRow: { phone: string; user_id: string | null } | null = null;

    if (resolvedUserId) {
      const uidMatches = (await db
        .prepare('SELECT phone, user_id FROM telegram_user_sessions WHERE user_id = ?')
        .all(resolvedUserId)) as Array<{ phone?: string; user_id?: string | null }>;
      if (uidMatches.length > 1) {
        dbIdentityConflict = true;
        console.error(
          `[Telegram Session Expire Error] Multiple DB rows found for user_id=${resolvedUserId}; aborting DB clear to protect accounts.`
        );
      } else if (uidMatches.length === 1 && uidMatches[0]?.phone) {
        uidRow = {
          phone: String(uidMatches[0].phone).trim(),
          user_id: uidMatches[0].user_id ? String(uidMatches[0].user_id).trim() : null,
        };
      }
    }

    const phoneCandidates = Array.from(new Set([resolvedPhone, inputNormPhone].filter(Boolean)));
    if (!dbIdentityConflict && phoneCandidates.length > 0) {
      const placeholders = phoneCandidates.map(() => '?').join(', ');
      const phoneMatches = (await db
        .prepare(`SELECT phone, user_id FROM telegram_user_sessions WHERE phone IN (${placeholders})`)
        .all(...phoneCandidates)) as Array<{ phone?: string; user_id?: string | null }>;
      if (phoneMatches.length > 1) {
        dbIdentityConflict = true;
        console.error(
          `[Telegram Session Expire Error] Multiple DB rows found for phone=[${phoneCandidates.join(', ')}]; aborting DB clear.`
        );
      } else if (phoneMatches.length === 1 && phoneMatches[0]?.phone) {
        phoneRow = {
          phone: String(phoneMatches[0].phone).trim(),
          user_id: phoneMatches[0].user_id ? String(phoneMatches[0].user_id).trim() : null,
        };
      }
    }

    if (!dbIdentityConflict) {
      if (uidRow && phoneRow) {
        const samePrimaryPhone = uidRow.phone === phoneRow.phone;
        const compatibleUid = !phoneRow.user_id || phoneRow.user_id === uidRow.user_id;
        if (!samePrimaryPhone || !compatibleUid) {
          dbIdentityConflict = true;
          console.error(
            `[Telegram Session Expire Error] Identity mismatch between user_id row (phone=${uidRow.phone}, uid=${uidRow.user_id}) and phone row (phone=${phoneRow.phone}, uid=${phoneRow.user_id}); aborting DB clear.`
          );
        } else {
          validatedDbRow = uidRow;
        }
      } else {
        validatedDbRow = uidRow || phoneRow;
      }
    }

    if (validatedDbRow && !dbIdentityConflict) {
      if (!resolvedUserId && validatedDbRow.user_id) resolvedUserId = validatedDbRow.user_id;
      if (!resolvedPhone && validatedDbRow.phone) resolvedPhone = validatedDbRow.phone;
    }
  } catch (lookupErr: any) {
    console.error('[Telegram Session Expire DB Lookup Error]:', lookupErr?.message || lookupErr);
  }

  const finalNormPhone = resolvedPhone ? normalizePhoneNumber(resolvedPhone) : inputNormPhone;
  const resolvedAccountId =
    resolvedUserId ? `acc_tg_${resolvedUserId}` : resolvedPhone || accountId || '';

  if (connected) {
    if (connected.userId) {
      connectedUserClients.delete(connected.userId);
      connectedUserClients.delete(`acc_tg_${connected.userId}`);
    }
    if (connected.phone) {
      connectedUserClients.delete(connected.phone);
    }
    if (connected.client) {
      await destroyTelegramClientSafely(connected.client);
    }
  }
  if (resolvedUserId) {
    connectedUserClients.delete(resolvedUserId);
    connectedUserClients.delete(`acc_tg_${resolvedUserId}`);
  }
  if (resolvedPhone) connectedUserClients.delete(resolvedPhone);
  if (finalNormPhone) connectedUserClients.delete(finalNormPhone);

  const runtimeKey = resolveTelegramAccountRuntimeKey({
    userId: resolvedUserId || undefined,
    phone: resolvedPhone || undefined,
    accountId: resolvedAccountId || undefined,
  });
  if (runtimeKey) {
    const rt = telegramAccountRuntimeStates.get(runtimeKey);
    if (rt) {
      rt.generationId += 1;
      rt.isAuthorized = false;
      rt.isRestoring = false;
      rt.isInitialConnecting = false;
      rt.lastErrorCategory = 'session_expired';
      rt.lastError = reason || 'Telegram 会话已失效或在其他设备注销';
      rt.offlineReason = rt.lastError;
    }
  }

  if (validatedDbRow && !dbIdentityConflict) {
    const expiredReasonText = reason || 'Telegram 会话已失效或在其他设备注销';
    try {
      if (validatedDbRow.user_id) {
        await db
          .prepare(
            "UPDATE telegram_user_sessions SET is_active = 0, session_string = '', expired_reason = ?, updated_at = ? WHERE phone = ? AND user_id = ?"
          )
          .run(expiredReasonText, Date.now(), validatedDbRow.phone, validatedDbRow.user_id);
      } else {
        await db
          .prepare(
            "UPDATE telegram_user_sessions SET is_active = 0, session_string = '', expired_reason = ?, updated_at = ? WHERE phone = ? AND (user_id IS NULL OR user_id = '')"
          )
          .run(expiredReasonText, Date.now(), validatedDbRow.phone);
      }
    } catch (updateErr: any) {
      console.error(
        `[Telegram Session Expire DB Update Error] Failed to mark session expired for phone=${validatedDbRow.phone}:`,
        updateErr?.message || updateErr
      );
    }
  }

  const key = resolvedUserId || resolvedPhone || resolvedAccountId;
  if (key) {
    recentlyExpiredAccounts.set(key, {
      accountId: resolvedAccountId || `acc_tg_${key}`,
      userId: resolvedUserId || undefined,
      phone: resolvedPhone || undefined,
      reason: reason || 'Telegram 会话已失效或在其他设备注销',
      expiredAt: Date.now(),
    });
    const now = Date.now();
    for (const [k, v] of recentlyExpiredAccounts.entries()) {
      if (now - v.expiredAt > 30 * 60 * 1000) {
        recentlyExpiredAccounts.delete(k);
      }
    }
  }
}

async function handleMtprotoRouteError(
  res: Response,
  err: any,
  ctx: { accountId?: string; userId?: string; phone?: string },
  statusWhenNotExpired = 400
) {
  const errMsg = formatTelegramError(err);
  const floodEntry = recordTelegramFloodWait(ctx, err, 'mtproto_route');
  if (floodEntry) {
    return res.status(429).json({
      ok: false,
      cloudSynced: false,
      code: 'TELEGRAM_FLOOD_WAIT',
      retryAfterSeconds: floodEntry.retryAfterSeconds,
      floodWaitUntil: floodEntry.floodWaitUntil,
      error: errMsg,
    });
  }
  if (isTelegramSessionExpiredError(err)) {
    await markTelegramSessionExpired({
      accountId: ctx.accountId,
      userId: ctx.userId,
      phone: ctx.phone,
      reason: errMsg,
    });
    return res.status(401).json({
      ok: false,
      cloudSynced: false,
      code: 'TELEGRAM_SESSION_EXPIRED',
      error: 'Telegram 登录会话已失效，请重新扫码或验证码登录',
    });
  }
  return res.status(statusWhenNotExpired).json({ ok: false, error: errMsg });
}

function clearExpiredAccountRecord(userId?: string, phone?: string) {
  if (userId) {
    recentlyExpiredAccounts.delete(userId);
    recentlyExpiredAccounts.delete(`acc_tg_${userId}`);
  }
  if (phone) {
    recentlyExpiredAccounts.delete(phone);
    recentlyExpiredAccounts.delete(normalizePhoneNumber(phone));
  }
  if (userId || phone) {
    const normPhone = phone ? normalizePhoneNumber(phone) : '';
    void db
      .prepare('UPDATE telegram_user_sessions SET expired_reason = NULL WHERE phone = ? OR phone = ? OR user_id = ?')
      .run(phone || '', normPhone || '', userId || '')
      .catch(() => {});
  }
}

export const TELEGRAM_DESKTOP_CLIENT_PARAMS = {
  deviceModel: 'HumanSense Desktop',
  systemVersion: 'Windows 11',
  appVersion: '4.16.8',
  langCode: 'zh-CN',
  systemLangCode: 'zh-CN',
} as const;

export async function getRegisteredTelegramAccountsSummary(): Promise<{
  totalUniqueCount: number;
  activePhones: Set<string>;
  activeUserIds: Set<string>;
}> {
  const rawEntries: Array<{ uid: string; phone: string }> = [];
  for (const u of connectedUserClients.values()) {
    const uid = u?.userId ? String(u.userId).trim() : '';
    const rawPhone = u?.phone ? String(u.phone).trim() : '';
    const phone = rawPhone ? normalizePhoneNumber(rawPhone) || rawPhone : '';
    if (uid || phone) {
      rawEntries.push({ uid, phone });
    }
  }

  try {
    const rows = (await db
      .prepare('SELECT phone, user_id FROM telegram_user_sessions WHERE is_active = 1')
      .all()) as any[];
    for (const r of rows || []) {
      const uid = r?.user_id ? String(r.user_id).trim() : '';
      const rawPhone = r?.phone ? String(r.phone).trim() : '';
      const phone = rawPhone ? normalizePhoneNumber(rawPhone) || rawPhone : '';
      if (uid || phone) {
        rawEntries.push({ uid, phone });
      }
    }
  } catch {}

  const phoneToUid = new Map<string, string>();
  for (const e of rawEntries) {
    if (e.uid && e.phone && !phoneToUid.has(e.phone)) {
      phoneToUid.set(e.phone, e.uid);
    }
  }

  const uniqueCanonical = new Set<string>();
  const activePhones = new Set<string>();
  const activeUserIds = new Set<string>();

  for (const e of rawEntries) {
    const resolvedUid = e.uid || (e.phone ? phoneToUid.get(e.phone) || '' : '');
    if (resolvedUid) activeUserIds.add(resolvedUid);
    if (e.phone) activePhones.add(e.phone);
    const canonical = resolvedUid ? `uid:${resolvedUid}` : `phone:${e.phone}`;
    if (canonical && canonical !== 'phone:') {
      uniqueCanonical.add(canonical);
    }
  }

  return {
    totalUniqueCount: uniqueCanonical.size,
    activePhones,
    activeUserIds,
  };
}

function configureTelegramClientErrorGuard(
  client: TelegramClient,
  context: string,
  meta?: { userId?: string; phone?: string; accountId?: string }
) {
  try {
    // GramJS LogLevel 'warn' still enables LogLevel.ERROR, which prints raw `Error: TIMEOUT` via console.error in _updateLoop.
    client.setLogLevel('none' as any);
    client.onError = async (err: any) => {
      if (meta && !isTelegramClientGenerationCurrent(client, meta)) {
        return;
      }
      const msg = String(err?.errorMessage || err?.message || err || '');
      if (isTelegramSessionExpiredError(err)) {
        console.warn(`[Telegram Client Session Expired] (${context}):`, msg);
        await markTelegramSessionExpired({
          accountId: meta?.accountId,
          userId: meta?.userId,
          phone: meta?.phone || (context.startsWith('+') ? context : undefined),
          reason: formatTelegramError(err),
        });
        return;
      }
      if (msg === 'TIMEOUT' || msg.includes('TIMEOUT') || msg.includes('Not connected')) {
        return;
      }
      console.warn(`[Telegram Client Warning] (${context}):`, msg);
    };
  } catch {}
}

function silenceGramJsSenderReconnect(client?: TelegramClient | null): void {
  const senderAny = (client as any)?._sender;
  if (!senderAny) return;
  try {
    senderAny.userDisconnected = true;
    senderAny._autoReconnect = false;
    senderAny._retries = 0;
    senderAny._reconnectRetries = 0;
    // Prevent already-queued GramJS sleep(1000).then(() => this._reconnect()) from resetting userDisconnected=false
    if (typeof senderAny.reconnect === 'function') {
      senderAny.reconnect = () => {};
    }
    if (typeof senderAny._reconnect === 'function') {
      senderAny._reconnect = async () => {};
    }
    senderAny._connection?.disconnect?.();
  } catch {}
}

export async function destroyTelegramClientSafely(
  client?: TelegramClient | null
): Promise<void> {
  if (!client) return;
  const anyClient = client as any;
  if (anyClient._tgProDestroyPromise) {
    return anyClient._tgProDestroyPromise;
  }
  // Mark userDisconnected & halt transport/reconnect timers immediately before async destroy
  silenceGramJsSenderReconnect(client);
  const destroyTask = (async () => {
    const innerDestroy = async () => {
      try {
        await client.destroy();
      } catch {
        try {
          await client.disconnect();
        } catch {}
      }
    };
    try {
      await Promise.race([
        innerDestroy(),
        new Promise<void>((resolve) => setTimeout(resolve, 3000).unref?.()),
      ]);
    } finally {
      try {
        anyClient._destroyed = true;
      } catch {}
    }
  })();
  anyClient._tgProDestroyPromise = destroyTask;
  return destroyTask;
}

// Helper to safely disconnect pending user client
async function cleanupPendingUserClient(phone: string) {
  const existing = activeUserClients.get(phone);
  if (existing) {
    if (existing.timeoutTimer) {
      clearTimeout(existing.timeoutTimer);
    }
    await destroyTelegramClientSafely(existing.client);
    activeUserClients.delete(phone);
  }
}

// Format raw Telegram errors into clear, actionable messages
export function formatTelegramError(err: any): string {
  const msg = String(err?.errorMessage || err?.message || '');
  const floodSecs = extractFloodWaitSeconds(err);
  if (floodSecs !== null) {
    const mins = Math.ceil(floodSecs / 60);
    return `请求过于频繁，Telegram 官方风控限制：请等待 ${mins} 分钟后再试 (${floodSecs} 秒)`;
  }
  if (isTelegramSessionExpiredError(err)) {
    return 'Telegram 登录会话已失效或在其他设备被注销，请重新登录该账号';
  }
  if (msg === 'TIMEOUT' || msg.includes('ETIMEDOUT') || msg.includes('ECONNREFUSED') || msg.includes('ENOTFOUND')) {
    return '连接 Telegram 服务器超时或网络异常，请检查网络或代理设置后重试';
  }
  if (msg.includes('PHONE_NUMBER_INVALID')) {
    return '手机号码格式无效，请输入正确的国际手机号码 (例如 +8613800000000)';
  }
  if (msg.includes('PHONE_NUMBER_BANNED')) {
    return '该手机号码已被 Telegram 官方封禁，无法登录';
  }
  if (msg.includes('PHONE_CODE_INVALID')) {
    return '验证码错误，请核对后重新输入';
  }
  if (msg.includes('PHONE_CODE_EXPIRED')) {
    return '验证码已过期，请重新获取';
  }
  if (msg.includes('PASSWORD_HASH_INVALID')) {
    return '当前两步验证密码错误，请核对后重新输入';
  }
  if (msg.includes('NEW_PASSWORD_BAD')) {
    return '新两步验证密码不符合 Telegram 安全要求（例如过于简单或与旧密码冲突），请更换更复杂的密码';
  }
  if (msg.includes('PASSWORD_EMPTY')) {
    return '两步验证密码不能为空';
  }
  if (msg.includes('SRP_ID_INVALID')) {
    return '两步验证安全会话已过期，请重新提交操作';
  }
  if (msg.includes('SRP_PASSWORD_CHANGED')) {
    return '账号两步验证密码已在其他设备变更，请刷新后重试';
  }
  if (msg.includes('EMAIL_INVALID')) {
    return '恢复邮箱格式无效，请输入真实可用的邮箱地址';
  }
  if (msg.includes('EMAIL_NOT_ALLOWED')) {
    return 'Telegram 暂不支持该域名邮箱作为恢复邮箱，请更换常用邮箱';
  }
  if (msg.includes('EMAIL_UNCONFIRMED')) {
    return '恢复邮箱尚未完成验证码确认，请输入发送至该邮箱的验证码或取消绑定';
  }
  if (msg.includes('EMAIL_HASH_EXPIRED')) {
    return '邮箱验证链接或验证码已过期，请点击重新发送验证码';
  }
  if (msg.includes('CODE_INVALID')) {
    return '邮箱验证码错误，请核对后重新输入';
  }
  if (msg.includes('CODE_EXPIRED')) {
    return '邮箱验证码已过期，请重新发送';
  }
  if (msg.includes('PASSWORD_RECOVERY_NA') || msg.includes('PASSWORD_RECOVERY_EXPIRED')) {
    return '未设置有效的恢复邮箱或恢复会话已过期';
  }
  if (msg.includes('SESSION_PASSWORD_NEEDED')) {
    return '该账号开启了两步验证，需要输入云端密码';
  }
  if (msg.includes('PREMIUM_ACCOUNT_REQUIRED') || msg.includes('PRIVACY_PREMIUM_REQUIRED')) {
    return '此高级隐私限制需当前账号具备 Telegram Premium 会员资格才能修改，其他通用安全设置可正常保存';
  }
  if (msg.includes('PRIVACY_KEY_INVALID')) {
    return '当前账号暂不支持修改该项隐私规则';
  }
  return msg || 'Telegram 请求失败，请检查网络或配置';
}

// Robust international phone number standardizer
export function normalizePhoneNumber(raw: string): string {
  if (!raw || typeof raw !== 'string') return '';
  let cleaned = raw.trim().replace(/[\s\-\(\)\.]/g, '');
  if (cleaned.startsWith('00')) {
    cleaned = '+' + cleaned.slice(2);
  }
  if (!cleaned.startsWith('+')) {
    cleaned = '+' + cleaned;
  }
  return '+' + cleaned.slice(1).replace(/\D/g, '');
}

// 18. Send Verification Code to Personal Telegram Account
app.post('/api/telegram/user/send-code', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权绑定或登录新 Telegram 账号' });
    }
    const { phone, apiId, apiHash } = req.body;
    if (!phone || typeof phone !== 'string') {
      return res.status(400).json({ ok: false, error: '请输入正确的国际格式手机号码 (例如: +8613800000000 或 +12125550123)' });
    }

    const cleanPhone = normalizePhoneNumber(phone);
    if (!cleanPhone || cleanPhone.length < 6) {
      return res.status(400).json({ ok: false, error: '手机号码格式无效，请输入正确的国际手机号码 (例如: +8613800000000 或 +12125550123)' });
    }

    const sendCodeCooldown = getTelegramFloodCooldown({ phone: cleanPhone });
    if (sendCodeCooldown) {
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: sendCodeCooldown.retryAfterSeconds,
        floodWaitUntil: sendCodeCooldown.floodWaitUntil,
        error: formatTelegramError({ errorMessage: `FLOOD_WAIT_${sendCodeCooldown.retryAfterSeconds}` }),
      });
    }

    const accountSummary = await getRegisteredTelegramAccountsSummary();
    if (
      hasReachedTelegramAccountLimit(accountSummary.totalUniqueCount) &&
      !connectedUserClients.has(cleanPhone) &&
      !accountSummary.activePhones.has(cleanPhone)
    ) {
      return res.status(400).json({
        ok: false,
        error: `已达到单机多账号关联上限（最多同时关联 ${MAX_TELEGRAM_ACCOUNTS} 个账号）。如需添加新账号，请先退出注销闲置账号。`,
      });
    }

    const resolvedCreds = await resolveTelegramApiCredentials({
      bearerToken: extractBearerToken(req),
    });
    if (!resolvedCreds.ok || !resolvedCreds.apiId || !resolvedCreds.apiHash) {
      return res.status(400).json({
        ok: false,
        code: resolvedCreds.code || 'TELEGRAM_API_CREDENTIALS_REQUIRED',
        error: resolvedCreds.error || '云端授权暂未分发 Telegram 接入凭据，请重新登录会员或联系管理员',
      });
    }
    const useApiId = resolvedCreds.apiId;
    const useApiHash = resolvedCreds.apiHash;

    // Disconnect existing client for this phone if any
    await cleanupPendingUserClient(cleanPhone);

    console.log(`[Telegram User Auth] Connecting to MTProto DC (443/obfuscated) for ${cleanPhone}...`);
    const client = await connectNewTelegramClientWithDcFallback({
      apiId: useApiId,
      apiHash: useApiHash,
      label: cleanPhone,
      registerGuard: (c) => configureTelegramClientErrorGuard(c, cleanPhone),
    });

    let sendResult: any;
    try {
      console.log(`[Telegram User Auth] Requesting official login code for ${cleanPhone}...`);
      try {
        sendResult = await withTelegramTimeout(
          client.invoke(
            new Api.auth.SendCode({
              phoneNumber: cleanPhone,
              apiId: useApiId,
              apiHash: useApiHash,
              settings: new Api.CodeSettings({}),
            })
          ),
          15000,
          '发送验证码请求超时，请检查网络后重试'
        );
      } catch (invokeErr: any) {
        if (invokeErr.errorMessage === 'AUTH_RESTART') {
          sendResult = await withTelegramTimeout(
            client.invoke(
              new Api.auth.SendCode({
                phoneNumber: cleanPhone,
                apiId: useApiId,
                apiHash: useApiHash,
                settings: new Api.CodeSettings({}),
              })
            ),
            15000,
            '发送验证码请求超时，请检查网络后重试'
          );
        } else {
          throw invokeErr;
        }
      }
    } catch (sendCodeErr) {
      await destroyTelegramClientSafely(client);
      throw sendCodeErr;
    }

    // Save session string representation so DC migration is preserved
    const sessionString = client.session.save() as unknown as string;
    const phoneCodeHash = sendResult.phoneCodeHash;

    // Auto timeout cleanup timer (10 minutes max for code entry)
    const timeoutTimer = setTimeout(() => {
      console.log(`[Telegram User Auth] Code verification timed out (10 mins) for ${cleanPhone}, releasing connection socket...`);
      cleanupPendingUserClient(cleanPhone);
    }, 10 * 60 * 1000);

    activeUserClients.set(cleanPhone, {
      client,
      phone: cleanPhone,
      phoneCodeHash,
      apiId: useApiId,
      apiHash: useApiHash,
      createdAt: Date.now(),
      timeoutTimer,
    });

    const typeObj = (sendResult.type as any) || {};
    const typeClassName = typeObj.className || typeObj.constructor?.name || '';
    const emailPattern = typeObj.emailPattern || '';

    let deliveryChannel = 'app';
    let deliveryNote = '';

    if (typeClassName.includes('SentCodeTypeApp')) {
      deliveryChannel = 'app';
      deliveryNote = '验证码已发送至您手机/电脑上已登录的官方 Telegram App（请查看官方服务通知「Telegram」会话，官方验证码不会发送到短信）';
    } else if (typeClassName.includes('SentCodeTypeEmailCode')) {
      deliveryChannel = 'email';
      deliveryNote = `验证码已发送至您的绑定邮箱 (${emailPattern || '关联邮箱'})，请查收邮件`;
    } else if (typeClassName.includes('SentCodeTypeSms')) {
      deliveryChannel = 'sms';
      deliveryNote = '验证码已通过国际短信发送至手机号码，请注意查收手机短信（跨国短信可能有 1-2 分钟延迟）';
    } else if (typeClassName.includes('SentCodeTypeCall') || typeClassName.includes('FlashCall')) {
      deliveryChannel = 'call';
      deliveryNote = '验证码将通过电话来电播报或来电号码后几位，请注意接听来电';
    } else if (typeClassName.includes('Fragment')) {
      deliveryChannel = 'fragment';
      deliveryNote = '该号码属于 Fragment 匿名号码，验证码已发送至 fragment.com';
    } else {
      deliveryChannel = typeClassName.toLowerCase().includes('sms') ? 'sms' : 'app';
      deliveryNote = `验证码已发送！方式: ${typeClassName || '官方通道'}`;
    }

    console.log(`[Telegram User Auth] Verification code successfully sent to ${cleanPhone} (DC: ${client.session.dcId}, Channel: ${deliveryChannel}, Type: ${typeClassName}, Source: ${resolvedCreds.source})!`);
    res.json({
      ok: true,
      message: deliveryNote,
      deliveryChannel,
      deliveryType: typeClassName,
      emailPattern,
      timeout: sendResult.timeout || 60,
      phone: cleanPhone,
      phoneCodeHash,
      isCodeViaApp: deliveryChannel === 'app',
      credentialSource: resolvedCreds.source,
    });
  } catch (err: any) {
    console.error('[Telegram User Auth SendCode Error]:', err);
    const cleanPhone = typeof req.body?.phone === 'string' ? normalizePhoneNumber(req.body.phone) : '';
    const floodEntry = cleanPhone ? recordTelegramFloodWait({ phone: cleanPhone }, err, 'auth.SendCode') : null;
    if (floodEntry) {
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: floodEntry.retryAfterSeconds,
        floodWaitUntil: floodEntry.floodWaitUntil,
        error: formatTelegramError(err),
      });
    }
    res.status(400).json({
      ok: false,
      error: formatTelegramError(err),
      code: err.code,
    });
  }
});

// 18.1 Resend Verification Code via SMS / Voice Call
app.post('/api/telegram/user/resend-code', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权执行验证码重发' });
    }
    const { phone } = req.body;
    if (!phone) {
      return res.status(400).json({ ok: false, error: '手机号码为必填项' });
    }
    const cleanPhone = normalizePhoneNumber(phone);
    const resendCooldown = getTelegramFloodCooldown({ phone: cleanPhone });
    if (resendCooldown) {
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: resendCooldown.retryAfterSeconds,
        floodWaitUntil: resendCooldown.floodWaitUntil,
        error: formatTelegramError({ errorMessage: `FLOOD_WAIT_${resendCooldown.retryAfterSeconds}` }),
      });
    }
    const userSession = activeUserClients.get(cleanPhone);
    if (!userSession || !userSession.client || !userSession.phoneCodeHash) {
      return res.status(400).json({ ok: false, code: 'TELEGRAM_AUTH_SESSION_EXPIRED', error: '会话已过期，请重新点击发送验证码' });
    }

    console.log(`[Telegram User Auth] Requesting resendCode for ${cleanPhone}...`);
    const resendResult = (await withTelegramTimeout(
      userSession.client.invoke(
        new Api.auth.ResendCode({
          phoneNumber: cleanPhone,
          phoneCodeHash: userSession.phoneCodeHash,
        })
      ),
      15000,
      '重发验证码请求超时，请检查网络后重试'
    )) as any;

    const resendType = resendResult?.type?.className || '';
    let deliveryNote = '重发请求已提交';
    let deliveryChannel = 'sms';
    if (resendType.includes('Sms')) {
      deliveryChannel = 'sms';
      deliveryNote = '已申请通过国际短信重发验证码，请查收手机短信';
    } else if (resendType.includes('Call')) {
      deliveryChannel = 'call';
      deliveryNote = '已申请通过电话呼叫播报验证码，请留意来电';
    }

    res.json({
      ok: true,
      message: deliveryNote,
      deliveryChannel,
      type: resendType,
      timeout: resendResult?.timeout || 60,
    });
  } catch (err: any) {
    console.error('[Telegram User Auth ResendCode Error]:', err);
    const cleanPhone = req.body?.phone ? normalizePhoneNumber(String(req.body.phone)) : '';
    const floodEntry = cleanPhone ? recordTelegramFloodWait({ phone: cleanPhone }, err, 'auth.ResendCode') : null;
    if (floodEntry) {
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: floodEntry.retryAfterSeconds,
        floodWaitUntil: floodEntry.floodWaitUntil,
        error: formatTelegramError(err),
      });
    }
    const errMsg = String(err?.errorMessage || err?.message || '');
    const isExpired = errMsg.includes('PHONE_CODE_EXPIRED') || isTelegramSessionExpiredError(err);
    if (isExpired && cleanPhone) {
      await cleanupPendingUserClient(cleanPhone);
    }
    res.status(400).json({
      ok: false,
      ...(isExpired ? { code: 'TELEGRAM_AUTH_SESSION_EXPIRED' } : {}),
      error: formatTelegramError(err),
    });
  }
});
// 18.1.1 Cancel Pending Code Verification Auth (Release socket connection immediately)
app.post('/api/telegram/user/cancel-auth', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权取消验证会话' });
    }
    const { phone } = req.body;
    if (phone) {
      const cleanPhone = normalizePhoneNumber(String(phone));
      await cleanupPendingUserClient(cleanPhone);
    }
    res.json({ ok: true, message: '已安全关闭未完成的验证连接' });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Cache active QR login sessions
interface QrSessionContext {
  client: TelegramClient;
  sessionId: string;
  token?: Buffer;
  qrUrl?: string;
  expires?: number;
  apiId: number;
  apiHash: string;
  isAuthorized: boolean;
  clientTransferred?: boolean;
  authorizedAt?: number;
  isScanned?: boolean;
  needsPassword?: boolean;
  needsPasswordAt?: number;
  passwordHint?: string;
  user?: any;
  error?: string;
  createdAt: number;
  pollTimer?: NodeJS.Timeout;
  passwordTimeoutTimer?: NodeJS.Timeout;
  isStopped?: boolean;
  pollErrorCount?: number;
}

export const QR_SESSION_UNSCANNED_STALE_MS = 45 * 1000;
export const QR_SESSION_MAX_WAIT_MS = 2 * 60 * 1000;
export const QR_SESSION_2FA_TIMEOUT_MS = 5 * 60 * 1000;
export const MAX_ACTIVE_QR_SESSIONS = 16;
export const activeQrSessions = new Map<string, QrSessionContext>();

export function armQrPasswordTimeout(
  sessionObj: QrSessionContext,
  timeoutMs: number = QR_SESSION_2FA_TIMEOUT_MS
): void {
  sessionObj.needsPassword = true;
  sessionObj.isScanned = true;
  sessionObj.needsPasswordAt = Date.now();
  if (sessionObj.pollTimer) {
    clearTimeout(sessionObj.pollTimer);
    sessionObj.pollTimer = undefined;
  }
  if (sessionObj.passwordTimeoutTimer) {
    clearTimeout(sessionObj.passwordTimeoutTimer);
  }
  sessionObj.passwordTimeoutTimer = setTimeout(() => {
    sessionObj.passwordTimeoutTimer = undefined;
    if (sessionObj.isAuthorized || sessionObj.clientTransferred) {
      activeQrSessions.delete(sessionObj.sessionId);
      return;
    }
    console.log(`[Telegram QR Auth] Session ${sessionObj.sessionId} 2FA password timed out, releasing socket...`);
    sessionObj.isStopped = true;
    sessionObj.error = '两步验证等待超时，请刷新二维码重新登录';
    void destroyTelegramClientSafely(sessionObj.client);
    activeQrSessions.delete(sessionObj.sessionId);
  }, timeoutMs);
  sessionObj.passwordTimeoutTimer.unref?.();
}

export function pruneExpiredQrSessions(now = Date.now()): number {
  let removed = 0;
  for (const [oldId, oldSession] of activeQrSessions.entries()) {
    if (oldSession.isAuthorized || oldSession.clientTransferred) {
      if (now - (oldSession.authorizedAt || oldSession.createdAt) > 15000) {
        if (oldSession.pollTimer) clearTimeout(oldSession.pollTimer);
        if (oldSession.passwordTimeoutTimer) clearTimeout(oldSession.passwordTimeoutTimer);
        activeQrSessions.delete(oldId);
        removed++;
      }
      continue;
    }
    if (oldSession.needsPassword) {
      const waitAnchor = oldSession.needsPasswordAt || oldSession.createdAt;
      if (now - waitAnchor >= QR_SESSION_2FA_TIMEOUT_MS || oldSession.isStopped) {
        if (oldSession.pollTimer) clearTimeout(oldSession.pollTimer);
        if (oldSession.passwordTimeoutTimer) clearTimeout(oldSession.passwordTimeoutTimer);
        oldSession.isStopped = true;
        void destroyTelegramClientSafely(oldSession.client);
        activeQrSessions.delete(oldId);
        removed++;
      }
      continue;
    }
    const isStaleUnscanned = now - oldSession.createdAt > QR_SESSION_UNSCANNED_STALE_MS && !oldSession.isScanned;
    if (isStaleUnscanned || now - oldSession.createdAt > QR_SESSION_MAX_WAIT_MS || oldSession.isStopped) {
      if (oldSession.pollTimer) clearTimeout(oldSession.pollTimer);
      if (oldSession.passwordTimeoutTimer) clearTimeout(oldSession.passwordTimeoutTimer);
      oldSession.isStopped = true;
      void destroyTelegramClientSafely(oldSession.client);
      activeQrSessions.delete(oldId);
      removed++;
    }
  }
  while (activeQrSessions.size > MAX_ACTIVE_QR_SESSIONS) {
    const oldestId = activeQrSessions.keys().next().value;
    if (!oldestId) break;
    const oldest = activeQrSessions.get(oldestId)!;
    if (oldest.pollTimer) clearTimeout(oldest.pollTimer);
    if (oldest.passwordTimeoutTimer) clearTimeout(oldest.passwordTimeoutTimer);
    oldest.isStopped = true;
    if (!oldest.isAuthorized && !oldest.clientTransferred) {
      void destroyTelegramClientSafely(oldest.client);
    }
    activeQrSessions.delete(oldestId);
    removed++;
  }
  return removed;
}

async function finishQrLogin(sessionObj: QrSessionContext, user: any) {
  console.log(`[Telegram QR Auth] User confirmed scan and authorized: ${user.firstName} (@${user.username || user.id})`);
  const sessionString = sessionObj.client.session.save() as unknown as string;
  const rawPhone = user.phone ? String(user.phone).trim() : '';
  const cleanPhone = rawPhone ? normalizePhoneNumber(rawPhone) : (user.username ? String(user.username).trim() : String(user.id));
  const now = Date.now();

  try {
    await db.execute(`
      CREATE TABLE IF NOT EXISTS telegram_user_sessions (
        phone TEXT PRIMARY KEY,
        session_string TEXT NOT NULL,
        user_id TEXT,
        username TEXT,
        first_name TEXT,
        api_id INTEGER DEFAULT NULL,
        api_hash TEXT DEFAULT NULL,
        is_active INTEGER DEFAULT 1,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
      )
    `);
  } catch {}

  // Deduplicate any stale row for the same Telegram user_id (e.g. un-normalized phone from earlier QR login)
  try {
    await db
      .prepare('DELETE FROM telegram_user_sessions WHERE user_id = ? AND phone != ?')
      .run(String(user.id), cleanPhone);
  } catch {}

  await db.prepare(`
    INSERT OR REPLACE INTO telegram_user_sessions (
      phone, session_string, user_id, username, first_name, api_id, api_hash, is_active, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, NULL, NULL, 1, ?, ?)
  `).run(
    cleanPhone,
    encryptSensitiveData(sessionString), // Encrypted with AES-256-GCM
    String(user.id),
    user.username || '',
    user.firstName || '',
    now,
    now
  );

  if (sessionObj.pollTimer) {
    clearTimeout(sessionObj.pollTimer);
    sessionObj.pollTimer = undefined;
  }
  if (sessionObj.passwordTimeoutTimer) {
    clearTimeout(sessionObj.passwordTimeoutTimer);
    sessionObj.passwordTimeoutTimer = undefined;
  }
  sessionObj.clientTransferred = true;
  sessionObj.authorizedAt = now;
  sessionObj.isAuthorized = true;
  sessionObj.needsPassword = false;
  sessionObj.isScanned = true;
  sessionObj.user = {
    id: String(user.id),
    firstName: user.firstName,
    lastName: user.lastName,
    username: user.username ? `@${user.username}` : '',
    phone: user.phone ? (user.phone.startsWith('+') ? user.phone : `+${user.phone}`) : cleanPhone,
    avatarUrl: signTelegramResourceUrl(
      `/api/telegram/user/avatar/${user.id}`,
      `acc_tg_${user.id}`
    ),
  };

  // Register in-memory connected user client session
  const qrProxyFingerprint = getTelegramProxyFingerprint(getConfiguredTelegramProxy());
  const userConnectedObj: ConnectedTelegramUser = {
    client: sessionObj.client,
    phone: cleanPhone,
    userId: String(user.id),
    username: user.username ? `@${user.username}` : '',
    firstName: user.firstName || 'Telegram 用户',
    lastName: user.lastName || '',
    avatarInitial: (user.firstName || 'TG').slice(0, 2).toUpperCase(),
    avatarBg: '#2481cc',
    apiId: sessionObj.apiId,
    apiHash: sessionObj.apiHash,
    connectedAt: now,
    proxyFingerprint: qrProxyFingerprint,
    dialogs: [],
  };

  connectedUserClients.set(String(user.id), userConnectedObj);
  connectedUserClients.set(cleanPhone, userConnectedObj);
  connectedUserClients.set(`acc_tg_${user.id}`, userConnectedObj);
  clearExpiredAccountRecord(String(user.id), cleanPhone);
  if (process.env.NODE_ENV !== 'test') {
    void fetchTelegramAvatarWithLimiting({
      cacheAccountScope: `acc_tg_${user.id}`,
      cleanId: String(user.id),
      candidates: [userConnectedObj],
    }).catch(() => {});
  }

  const qrRuntime = getOrCreateTelegramAccountRuntimeState({
    userId: String(user.id),
    phone: cleanPhone,
    accountId: `acc_tg_${user.id}`,
  });
  qrRuntime.generationId += 1;
  (sessionObj.client as any)._tgProGenerationId = qrRuntime.generationId;
  qrRuntime.isInitialConnecting = false;
  qrRuntime.isRestoring = false;
  qrRuntime.isAuthorized = true;
  qrRuntime.transportConnected = true;
  qrRuntime.senderIsReconnecting = false;
  qrRuntime.reconnectingSinceAt = null;
  qrRuntime.connectingSinceAt = null;
  qrRuntime.suspectedStuckWarningAt = null;
  qrRuntime.reconnectProbeFailures = 0;
  qrRuntime.lastConnectedAt = now;
  qrRuntime.retryCount = 0;
  qrRuntime.nextRetryAt = 0;
  qrRuntime.lastError = null;
  qrRuntime.lastErrorCategory = null;
  qrRuntime.offlineReason = null;
  qrRuntime.proxyFingerprint = qrProxyFingerprint;

  configureTelegramClientErrorGuard(sessionObj.client, cleanPhone, {
    userId: String(user.id),
    phone: cleanPhone,
    accountId: `acc_tg_${user.id}`,
  });
  attachTelegramConnectionStateTracker(sessionObj.client, {
    userId: String(user.id),
    phone: cleanPhone,
    accountId: `acc_tg_${user.id}`,
  });
  attachTelegramClientMessageListener(sessionObj.client, cleanPhone, String(user.id));

  // Asynchronously sync real dialogs into local memory via single-flight helper
  getOrFetchConnectedAccountDialogs(userConnectedObj, { limit: 150 })
    .then(({ dialogs }) => {
      console.log(`[Telegram QR Auth] Synced ${dialogs.length} real dialogs into memory for user ${user.id}`);
    })
    .catch((err) => {
      console.warn('[Telegram QR Auth] Dialog fetch note:', err.message);
    });
}

// 18.2 Request Telegram Official QR Code Login Token
app.post('/api/telegram/user/qr-token', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权发起扫码绑定新账号' });
    }
    const resolvedCreds = await resolveTelegramApiCredentials({
      bearerToken: extractBearerToken(req),
    });
    if (!resolvedCreds.ok || !resolvedCreds.apiId || !resolvedCreds.apiHash) {
      return res.status(400).json({
        ok: false,
        code: resolvedCreds.code || 'TELEGRAM_API_CREDENTIALS_REQUIRED',
        error: resolvedCreds.error || '云端授权暂未分发 Telegram 接入凭据，请重新登录会员或联系管理员',
      });
    }
    const useApiId = resolvedCreds.apiId;
    const useApiHash = resolvedCreds.apiHash;
    const accountSummary = await getRegisteredTelegramAccountsSummary();
    if (hasReachedTelegramAccountLimit(accountSummary.totalUniqueCount)) {
      return res.status(400).json({
        ok: false,
        error: `已达到单机多账号关联上限（最多同时关联 ${MAX_TELEGRAM_ACCOUNTS} 个账号）。如需添加新账号，请先退出注销闲置账号。`,
      });
    }
    const sessionId = 'qr_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);

    // Clean up stale QR sessions safely: NEVER destroy a client already transferred to connectedUserClients!
    pruneExpiredQrSessions(Date.now());

    const client = await connectNewTelegramClientWithDcFallback({
      apiId: useApiId,
      apiHash: useApiHash,
      label: sessionId,
      registerGuard: (c) => configureTelegramClientErrorGuard(c, sessionId),
    });
    let exportRes: any;
    try {
      // Export initial login token directly from MTProto
      exportRes = await withTelegramTimeout(
        client.invoke(
          new Api.auth.ExportLoginToken({
            apiId: useApiId,
            apiHash: useApiHash,
            exceptIds: [],
          })
        ),
        15000,
        '生成登录二维码超时，请检查网络后重试'
      );

      if (!(exportRes instanceof Api.auth.LoginToken)) {
        throw new Error('Telegram 未能返回有效的登录 Token');
      }
    } catch (qrInitErr) {
      await destroyTelegramClientSafely(client);
      throw qrInitErr;
    }

    const sessionObj: QrSessionContext = {
      client,
      sessionId,
      apiId: useApiId,
      apiHash: useApiHash,
      token: exportRes.token,
      expires: exportRes.expires,
      qrUrl: `tg://login?token=${exportRes.token.toString('base64url')}`,
      isAuthorized: false,
      createdAt: Date.now(),
      pollErrorCount: 0,
    };
    activeQrSessions.set(sessionId, sessionObj);

    console.log(`[Telegram QR Auth] Generated live QR token for session ${sessionId}, expires at ${exportRes.expires}`);

    // Active MTProto polling loop: checks every 2500ms (2.5s interval to prevent rate limit)
    const checkQrStatusLoop = async () => {
      if (sessionObj.isStopped || sessionObj.isAuthorized || sessionObj.clientTransferred) return;

      try {
        const checkRes = await client.invoke(
          new Api.auth.ExportLoginToken({
            apiId: sessionObj.apiId,
            apiHash: sessionObj.apiHash,
            exceptIds: [],
          })
        );
        sessionObj.pollErrorCount = 0;

        if (checkRes instanceof Api.auth.LoginToken) {
          // Token is alive and still waiting for mobile scan
          sessionObj.token = checkRes.token;
          sessionObj.expires = checkRes.expires;
          sessionObj.qrUrl = `tg://login?token=${checkRes.token.toString('base64url')}`;
        } else if (checkRes instanceof Api.auth.LoginTokenMigrateTo) {
          console.log(`[Telegram QR Auth] Session ${sessionId}: User scanned! Migrating to DC ${checkRes.dcId}...`);
          sessionObj.isScanned = true;
          await client._switchDC(checkRes.dcId);
          try {
            const importRes = await client.invoke(
              new Api.auth.ImportLoginToken({
                token: checkRes.token,
              })
            );
            if (importRes instanceof Api.auth.LoginTokenSuccess && (importRes.authorization as any)?.user) {
              await finishQrLogin(sessionObj, (importRes.authorization as any).user);
              return;
            }
          } catch (importErr: any) {
            if (importErr.errorMessage === 'SESSION_PASSWORD_NEEDED') {
              console.log(`[Telegram QR Auth] Session ${sessionId}: 2FA Password needed after DC migration`);
              armQrPasswordTimeout(sessionObj);
              try {
                const pwdInfo = await client.invoke(new Api.account.GetPassword());
                sessionObj.passwordHint = (pwdInfo as any).hint || '';
              } catch { /* ignore */ }
              return;
            }
            throw importErr;
          }
        } else if (checkRes instanceof Api.auth.LoginTokenSuccess && (checkRes.authorization as any)?.user) {
          console.log(`[Telegram QR Auth] Session ${sessionId}: User scanned and authorized successfully!`);
          sessionObj.isScanned = true;
          await finishQrLogin(sessionObj, (checkRes.authorization as any).user);
          return;
        }
      } catch (err: any) {
        if (err.errorMessage === 'SESSION_PASSWORD_NEEDED') {
          console.log(`[Telegram QR Auth] Session ${sessionId}: 2FA Password needed`);
          armQrPasswordTimeout(sessionObj);
          try {
            const pwdInfo = await client.invoke(new Api.account.GetPassword());
            sessionObj.passwordHint = (pwdInfo as any).hint || '';
          } catch { /* ignore */ }
          return;
        } else if (err.errorMessage === 'AUTH_TOKEN_EXPIRED') {
          console.log(`[Telegram QR Auth] Session ${sessionId}: Token expired, refreshing...`);
        } else {
          sessionObj.pollErrorCount = (sessionObj.pollErrorCount || 0) + 1;
          console.warn(`[Telegram QR Auth] Session ${sessionId} poll check note (${sessionObj.pollErrorCount}):`, err.message || err);
          if (sessionObj.pollErrorCount >= 8) {
            sessionObj.error = '与 Telegram 服务器通信持续异常，请检查网络或代理后刷新二维码';
            sessionObj.isStopped = true;
            if (sessionObj.pollTimer) clearTimeout(sessionObj.pollTimer);
            if (sessionObj.passwordTimeoutTimer) clearTimeout(sessionObj.passwordTimeoutTimer);
            if (!sessionObj.isAuthorized && !sessionObj.clientTransferred) {
              void destroyTelegramClientSafely(sessionObj.client);
            }
            activeQrSessions.delete(sessionId);
            return;
          }
        }
      }

      // Schedule next check if still active
      if (!sessionObj.isStopped && !sessionObj.isAuthorized && !sessionObj.clientTransferred && !sessionObj.needsPassword) {
        // Enforce 2 minutes maximum session wait time
        if (Date.now() - sessionObj.createdAt > QR_SESSION_MAX_WAIT_MS) {
          sessionObj.error = '二维码已超时（2分钟未扫码），已自动断开连接。请刷新重新获取。';
          sessionObj.isStopped = true;
          if (sessionObj.pollTimer) clearTimeout(sessionObj.pollTimer);
          if (sessionObj.passwordTimeoutTimer) clearTimeout(sessionObj.passwordTimeoutTimer);
          if (!sessionObj.isAuthorized && !sessionObj.clientTransferred) {
            void destroyTelegramClientSafely(sessionObj.client);
            activeQrSessions.delete(sessionId);
          }
          return;
        }
        sessionObj.pollTimer = setTimeout(checkQrStatusLoop, 2500);
      }
    };

    sessionObj.pollTimer = setTimeout(checkQrStatusLoop, 2500);

    res.json({
      ok: true,
      sessionId,
      qrUrl: sessionObj.qrUrl,
      expires: sessionObj.expires,
      expiresIn: sessionObj.expires ? Math.max(5, Math.floor(sessionObj.expires - Date.now() / 1000)) : 30,
      message: '请使用手机 Telegram App 扫码关联登录',
    });
  } catch (err: any) {
    console.error('[Telegram QR Auth Error]:', err);
    res.status(400).json({
      ok: false,
      error: formatTelegramError(err),
    });
  }
});

// 18.2.1 Immediately Cancel QR Session and Disconnect Socket (only if not yet authorized/transferred)
app.post('/api/telegram/user/cancel-qr', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权取消扫码会话' });
    }
    const { sessionId } = req.body;
    if (sessionId && activeQrSessions.has(sessionId)) {
      const sessionObj = activeQrSessions.get(sessionId)!;
      sessionObj.isStopped = true;
      if (sessionObj.pollTimer) {
        clearTimeout(sessionObj.pollTimer);
        sessionObj.pollTimer = undefined;
      }
      if (sessionObj.passwordTimeoutTimer) {
        clearTimeout(sessionObj.passwordTimeoutTimer);
        sessionObj.passwordTimeoutTimer = undefined;
      }
      if (!sessionObj.isAuthorized && !sessionObj.clientTransferred) {
        await destroyTelegramClientSafely(sessionObj.client);
      }
      activeQrSessions.delete(sessionId);
      console.log(`[Telegram QR Auth] Session ${sessionId} cancelled (transferred=${Boolean(sessionObj.clientTransferred)}).`);
    }
    res.json({ ok: true, message: '二维码轮询已终止' });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// 18.3 Check QR Code Scan & Authorization Status
app.get('/api/telegram/user/qr-status', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权查询扫码登录状态' });
    }
    const sessionId = req.query.sessionId as string;
    if (!sessionId || !activeQrSessions.has(sessionId)) {
      return res.status(400).json({ ok: false, error: '二维码已失效，请刷新重新获取' });
    }

    const session = activeQrSessions.get(sessionId)!;

    if (session.isAuthorized && session.user) {
      return res.json({
        ok: true,
        isAuthorized: true,
        user: session.user,
      });
    }

    if (session.needsPassword) {
      return res.json({
        ok: true,
        isAuthorized: false,
        needsPassword: true,
        passwordHint: session.passwordHint || '',
        message: '您的账号开启了 2FA 云端密码，请输入两步验证密码完成登录',
      });
    }

    if (session.error) {
      return res.json({
        ok: false,
        error: session.error,
      });
    }

    res.json({
      ok: true,
      isAuthorized: false,
      isScanned: session.isScanned || false,
      waitingForScan: !session.isScanned,
      qrUrl: session.qrUrl,
      expires: session.expires,
      expiresIn: session.expires ? Math.max(0, Math.floor(session.expires - Date.now() / 1000)) : 30,
    });
  } catch (err: any) {
    res.status(500).json({ ok: false, isAuthorized: false, error: err?.message || '二维码状态检测异常，请稍后重试' });
  }
});

// 18.4 Submit 2FA Password for QR Code Login (Protected with authAttemptLimiter)
app.post('/api/telegram/user/qr-password', requireTenantAuth, authAttemptLimiter, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权校验扫码两步密码' });
    }
    const { sessionId, password } = req.body;
    if (!sessionId || !activeQrSessions.has(sessionId)) {
      return res.status(400).json({ ok: false, error: '二维码会话已过期，请重新扫码' });
    }

    const session = activeQrSessions.get(sessionId)!;
    if (!session.needsPassword) {
      return res.status(400).json({ ok: false, error: '当前会话无需输入两步验证密码' });
    }
    if (Date.now() - (session.needsPasswordAt || session.createdAt) >= QR_SESSION_2FA_TIMEOUT_MS) {
      if (session.pollTimer) clearTimeout(session.pollTimer);
      if (session.passwordTimeoutTimer) clearTimeout(session.passwordTimeoutTimer);
      session.isStopped = true;
      if (!session.isAuthorized && !session.clientTransferred) {
        void destroyTelegramClientSafely(session.client);
      }
      activeQrSessions.delete(sessionId);
      return res.status(400).json({ ok: false, error: '两步验证会话已过期，请重新扫码' });
    }

    const cleanPwd = String(password || '').trim();
    if (!cleanPwd) {
      return res.status(400).json({ ok: false, error: '请输入两步验证密码' });
    }

    console.log(`[Telegram QR Auth] Checking 2FA password for session ${sessionId}...`);
    const pwdRes = await withTelegramTimeout(
      session.client.invoke(new Api.account.GetPassword()),
      15000,
      '两步验证请求超时，请检查网络后重试'
    );
    const pwdCheck = await computeCheck(pwdRes, cleanPwd);
    const authRes = await withTelegramTimeout(
      session.client.invoke(new Api.auth.CheckPassword({ password: pwdCheck })),
      15000,
      '两步验证密码校验超时，请检查网络后重试'
    );

    if (authRes && (authRes as any).user) {
      await finishQrLogin(session, (authRes as any).user);
      return res.json({
        ok: true,
        isAuthorized: true,
        user: session.user,
        message: '两步验证通过，账号已成功关联！',
      });
    }

    throw new Error('两步验证密码未能完成鉴权');
  } catch (err: any) {
    console.error(`[Telegram QR Auth] 2FA Password Error:`, err);
    res.status(400).json({
      ok: false,
      error: err.errorMessage === 'PASSWORD_HASH_INVALID' ? '两步验证密码错误，请检查后重新输入' : formatTelegramError(err),
    });
  }
});

// 19. Verify Code and Login Personal Telegram Account (Protected with authAttemptLimiter anti-brute-force)
app.post('/api/telegram/user/verify-code', requireTenantAuth, authAttemptLimiter, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    if (!authContext?.session?.isMaster || authContext.session.isBot || authContext.isBot) {
      return res.status(403).json({ ok: false, error: '权限不足：仅主账号会员有权校验验证码登录新账号' });
    }
    const { phone, code, password } = req.body;
    if (!phone || !code) {
      return res.status(400).json({ ok: false, error: '手机号和验证码为必填项' });
    }

    const cleanPhone = normalizePhoneNumber(phone);
    const userSession = activeUserClients.get(cleanPhone);
    if (!userSession || !userSession.client) {
      return res.status(400).json({ ok: false, code: 'TELEGRAM_AUTH_SESSION_EXPIRED', error: '会话已过期，请重新点击发送验证码' });
    }

    const { client, phoneCodeHash } = userSession;

    try {
      // If 2FA password was already requested on this active session, skip re-calling SignIn with single-use code
      if (!userSession.needsPassword) {
        console.log(`[Telegram User Auth] Signing in with code for ${cleanPhone}...`);
        await withTelegramTimeout(
          client.invoke(
            new Api.auth.SignIn({
              phoneNumber: cleanPhone,
              phoneCodeHash: phoneCodeHash || '',
              phoneCode: String(code).trim(),
            })
          ),
          15000,
          '验证码校验超时，请检查网络后重试'
        );
      }
    } catch (authErr: any) {
      if (authErr.errorMessage === 'SESSION_PASSWORD_NEEDED') {
        userSession.needsPassword = true;
        if (!password) {
          return res.status(200).json({
            ok: false,
            needsPassword: true,
            message: '该账号开启了两步验证 (2FA Cloud Password)，请输入您的云端两步密码',
          });
        }
      } else {
        throw authErr;
      }
    }

    if (userSession.needsPassword) {
      if (!password) {
        return res.status(200).json({
          ok: false,
          needsPassword: true,
          message: '该账号开启了两步验证 (2FA Cloud Password)，请输入您的云端两步密码',
        });
      }
      console.log(`[Telegram User Auth] Submitting 2FA Cloud password for ${cleanPhone}...`);
      const cleanPwd = String(password || '').trim();
      try {
        const pwdRes = await withTelegramTimeout(
          client.invoke(new Api.account.GetPassword()),
          15000,
          '获取两步验证参数超时，请重试'
        );
        const pwdCheck = await computeCheck(pwdRes, cleanPwd);
        await withTelegramTimeout(
          client.invoke(new Api.auth.CheckPassword({ password: pwdCheck })),
          15000,
          '两步验证校验超时，请重试'
        );
      } catch (pwdErr: any) {
        console.error('[Telegram User Auth] 2FA Password Check Error:', pwdErr);
        if (pwdErr.errorMessage === 'PASSWORD_HASH_INVALID') {
          return res.status(400).json({
            ok: false,
            needsPassword: true,
            error: '两步验证密码错误，请检查后重新输入',
          });
        }
        throw pwdErr;
      }
    }

    // Successfully logged in! Get logged in user details
    const me = (await withTelegramTimeout(client.getMe(), 15000, '读取账号信息超时，请重试')) as any;
    const sessionString = client.session.save() as unknown as string;

    const now = Date.now();
    try {
      await db.execute(`
        CREATE TABLE IF NOT EXISTS telegram_user_sessions (
          phone TEXT PRIMARY KEY,
          session_string TEXT NOT NULL,
          user_id TEXT,
          username TEXT,
          first_name TEXT,
          api_id INTEGER DEFAULT NULL,
          api_hash TEXT DEFAULT NULL,
          is_active INTEGER DEFAULT 1,
          created_at INTEGER NOT NULL,
          updated_at INTEGER NOT NULL
        )
      `);
    } catch {}

    try {
      await db
        .prepare('DELETE FROM telegram_user_sessions WHERE user_id = ? AND phone != ?')
        .run(String(me.id), cleanPhone);
    } catch {}

    await db.prepare(`
      INSERT OR REPLACE INTO telegram_user_sessions (
        phone, session_string, user_id, username, first_name, api_id, api_hash, is_active, created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, NULL, NULL, 1, ?, ?)
    `).run(
      cleanPhone,
      encryptSensitiveData(sessionString), // Encrypted with AES-256-GCM
      String(me.id),
      me.username || '',
      me.firstName || '',
      now,
      now
    );

    // Register in-memory connected user client session
    const phoneLoginProxyFingerprint = getTelegramProxyFingerprint(getConfiguredTelegramProxy());
    const userConnectedObj: ConnectedTelegramUser = {
      client,
      phone: cleanPhone,
      userId: String(me.id),
      username: me.username ? `@${me.username}` : '',
      firstName: me.firstName || 'Telegram 用户',
      lastName: me.lastName || '',
      avatarInitial: (me.firstName || 'TG').slice(0, 2).toUpperCase(),
      avatarBg: '#2481cc',
      apiId: userSession.apiId,
      apiHash: userSession.apiHash,
      connectedAt: now,
      proxyFingerprint: phoneLoginProxyFingerprint,
      dialogs: [],
    };

    connectedUserClients.set(String(me.id), userConnectedObj);
    connectedUserClients.set(cleanPhone, userConnectedObj);
    connectedUserClients.set(`acc_tg_${me.id}`, userConnectedObj);
    clearExpiredAccountRecord(String(me.id), cleanPhone);
    if (process.env.NODE_ENV !== 'test') {
      void fetchTelegramAvatarWithLimiting({
        cacheAccountScope: `acc_tg_${me.id}`,
        cleanId: String(me.id),
        candidates: [userConnectedObj],
      }).catch(() => {});
    }

    const phoneRuntime = getOrCreateTelegramAccountRuntimeState({
      userId: String(me.id),
      phone: cleanPhone,
      accountId: `acc_tg_${me.id}`,
    });
    phoneRuntime.generationId += 1;
    (client as any)._tgProGenerationId = phoneRuntime.generationId;
    phoneRuntime.isInitialConnecting = false;
    phoneRuntime.isRestoring = false;
    phoneRuntime.isAuthorized = true;
    phoneRuntime.transportConnected = true;
    phoneRuntime.senderIsReconnecting = false;
    phoneRuntime.reconnectingSinceAt = null;
    phoneRuntime.connectingSinceAt = null;
    phoneRuntime.suspectedStuckWarningAt = null;
    phoneRuntime.reconnectProbeFailures = 0;
    phoneRuntime.lastConnectedAt = now;
    phoneRuntime.retryCount = 0;
    phoneRuntime.nextRetryAt = 0;
    phoneRuntime.lastError = null;
    phoneRuntime.lastErrorCategory = null;
    phoneRuntime.offlineReason = null;
    phoneRuntime.proxyFingerprint = phoneLoginProxyFingerprint;

    configureTelegramClientErrorGuard(client, cleanPhone, {
      userId: String(me.id),
      phone: cleanPhone,
      accountId: `acc_tg_${me.id}`,
    });
    attachTelegramConnectionStateTracker(client, {
      userId: String(me.id),
      phone: cleanPhone,
      accountId: `acc_tg_${me.id}`,
    });
    attachTelegramClientMessageListener(client, cleanPhone, String(me.id));

    getOrFetchConnectedAccountDialogs(userConnectedObj, { limit: 150 })
      .then(({ dialogs }) => {
        console.log(`[Telegram User Auth] Synced ${dialogs.length} real dialogs into memory for user ${me.id}`);
      })
      .catch((err) => {
        console.warn('[Telegram User Auth] Dialog fetch note:', err.message);
      });

    if (userSession.timeoutTimer) clearTimeout(userSession.timeoutTimer);
    activeUserClients.delete(cleanPhone);

    console.log(`[Telegram User Auth] User successfully logged in: ${me.firstName} (@${me.username || me.id})`);

    res.json({
      ok: true,
      message: '个人真实电报账号授权登录成功！',
      user: {
        id: String(me.id),
        firstName: me.firstName,
        lastName: me.lastName,
        username: me.username ? `@${me.username}` : '',
        phone: cleanPhone,
        avatarUrl: signTelegramResourceUrl(
          `/api/telegram/user/avatar/${me.id}`,
          `acc_tg_${me.id}`
        ),
      },
    });
  } catch (err: any) {
    console.error('[Telegram User Auth Verify Error]:', err);
    const errMsg = String(err?.errorMessage || err?.message || '');
    const isExpired = errMsg.includes('PHONE_CODE_EXPIRED') || isTelegramSessionExpiredError(err);
    if (isExpired && req.body?.phone) {
      await cleanupPendingUserClient(normalizePhoneNumber(req.body.phone));
    }
    res.status(400).json({
      ok: false,
      ...(isExpired ? { code: 'TELEGRAM_AUTH_SESSION_EXPIRED' } : {}),
      error: formatTelegramError(err),
    });
  }
});

// 20. Check Real Telegram Personal Account Login Status
app.get('/api/telegram/user/status', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const bearerToken = extractBearerToken(req);
    const hasCredsInMemory = Boolean(getInMemoryTelegramApiCredentials(bearerToken) || getEnvTelegramApiCredentials());

    let sessionRows: any[] = [];
    try {
      sessionRows = (await db.prepare(`
        SELECT phone, user_id, username, first_name, is_active, updated_at
        FROM telegram_user_sessions
        WHERE is_active = 1
        ORDER BY updated_at DESC
      `).all()) as any[];
    } catch {
      sessionRows = [];
    }

    // Merge in-memory active clients with genuine MTProto transport state & per-account runtime state
    const inMemoryActiveList: any[] = [];
    const seenRuntimeKeys = new Set<string>();
    const seenUserIds = new Set<string>();

    for (const u of connectedUserClients.values()) {
      const uid = u.userId ? String(u.userId).trim() : '';
      const rawPhone = u.phone ? String(u.phone).trim() : '';
      const normPhone = rawPhone ? normalizePhoneNumber(rawPhone) || rawPhone : '';
      const canonicalId = uid ? `acc_tg_${uid}` : normPhone;
      const runtimeKey = resolveTelegramAccountRuntimeKey({
        userId: uid || undefined,
        phone: normPhone || undefined,
        accountId: canonicalId || undefined,
      });
      if (!runtimeKey || seenRuntimeKeys.has(runtimeKey)) continue;
      seenRuntimeKeys.add(runtimeKey);
      if (uid) seenUserIds.add(uid);

      const runtime = getOrCreateTelegramAccountRuntimeState({
        userId: uid || undefined,
        phone: normPhone || undefined,
        accountId: canonicalId,
      });
      syncAccountReconnectLifecycleMarkers(runtime, inspectGramJsClientState(u.client), Date.now());
      const snap = getTelegramAccountConnectionSnapshot(u, runtime);
      const reconnectingDurationMs =
        runtime.reconnectingSinceAt !== null ? Math.max(0, Date.now() - runtime.reconnectingSinceAt) : 0;
      inMemoryActiveList.push({
        id: canonicalId,
        phone: u.phone,
        userId: uid,
        username: u.username,
        firstName: u.firstName,
        ...(uid
          ? { avatarUrl: signTelegramResourceUrl(`/api/telegram/user/avatar/${uid}`, `acc_tg_${uid}`) }
          : {}),
        updatedAt: u.connectedAt,
        dialogsCount: u.dialogs.length,
        isInMemoryConnected: true,
        isConnected: snap.isConnected,
        isConnecting: snap.isConnecting,
        isReconnecting: snap.isReconnecting,
        reconnectSuspectedStuck: Boolean(runtime.suspectedStuckWarningAt !== null || reconnectingDurationMs >= 35_000),
        status: snap.phase,
        retryCount: runtime.retryCount,
        nextRetryAt: runtime.nextRetryAt,
        lastConnectedAt: runtime.lastConnectedAt,
        lastError: runtime.lastError,
        offlineReason: snap.offlineReason || undefined,
      });
    }

    const defaultOfflineReason = !hasCredsInMemory
      ? lastCloudCredsError?.error || '云端 Telegram 接入凭据尚未同步，请检查网络或代理后重试同步'
      : telegramSessionRestoreState.inProgress
        ? '正在后台恢复本地加密会话，请稍候...'
        : telegramSessionRestoreState.lastError || 'MTProto 连接尚未建立，请点击重新连接';

    for (const r of sessionRows) {
      const uid = r.user_id ? String(r.user_id).trim() : '';
      const rawPhone = r.phone ? String(r.phone).trim() : '';
      const normPhone = rawPhone ? normalizePhoneNumber(rawPhone) || rawPhone : '';
      const canonicalId = uid ? `acc_tg_${uid}` : normPhone;
      const runtimeKey = resolveTelegramAccountRuntimeKey({
        userId: uid || undefined,
        phone: normPhone || undefined,
        accountId: canonicalId || undefined,
      });
      if (!runtimeKey || seenRuntimeKeys.has(runtimeKey)) continue;
      seenRuntimeKeys.add(runtimeKey);
      if (uid) seenUserIds.add(uid);

      const runtime = getOrCreateTelegramAccountRuntimeState({
        userId: uid || undefined,
        phone: normPhone || undefined,
        accountId: canonicalId,
      });
      const snap = getTelegramAccountConnectionSnapshot(undefined, runtime);
      inMemoryActiveList.push({
        id: canonicalId,
        phone: r.phone,
        userId: uid,
        username: r.username ? `@${r.username}` : '',
        firstName: r.first_name,
        ...(uid
          ? { avatarUrl: signTelegramResourceUrl(`/api/telegram/user/avatar/${uid}`, `acc_tg_${uid}`) }
          : {}),
        updatedAt: r.updated_at,
        dialogsCount: 0,
        isInMemoryConnected: false,
        isConnected: false,
        isConnecting: snap.isConnecting,
        isReconnecting: snap.isReconnecting,
        status: snap.phase,
        retryCount: runtime.retryCount,
        nextRetryAt: runtime.nextRetryAt,
        lastConnectedAt: runtime.lastConnectedAt,
        lastError: runtime.lastError,
        offlineReason:
          snap.phase === 'offline'
            ? snap.offlineReason || defaultOfflineReason
            : snap.offlineReason || undefined,
      });
    }

    let expiredRows: any[] = [];
    try {
      expiredRows = (await db.prepare(`
        SELECT phone, user_id, expired_reason, updated_at
        FROM telegram_user_sessions
        WHERE is_active = 0 AND expired_reason IS NOT NULL AND TRIM(expired_reason) != ''
        ORDER BY updated_at DESC
      `).all()) as any[];
    } catch {
      expiredRows = [];
    }

    const expiredMap = new Map<string, ExpiredTelegramAccountInfo>();
    for (const row of expiredRows) {
      const uid = row.user_id ? String(row.user_id).trim() : '';
      const phone = row.phone ? String(row.phone).trim() : '';
      const accId = uid ? `acc_tg_${uid}` : phone;
      const rKey = resolveTelegramAccountRuntimeKey({
        userId: uid || undefined,
        phone: phone || undefined,
        accountId: accId || undefined,
      });
      if (accId && !(uid && seenUserIds.has(uid)) && !(rKey && seenRuntimeKeys.has(rKey))) {
        expiredMap.set(accId, {
          accountId: accId,
          userId: uid || undefined,
          phone: phone || undefined,
          reason: String(row.expired_reason || 'Telegram 登录会话已失效，请重新登录'),
          expiredAt: Number(row.updated_at) || Date.now(),
        });
      }
    }
    for (const exp of recentlyExpiredAccounts.values()) {
      const accId = exp.accountId || (exp.userId ? `acc_tg_${exp.userId}` : exp.phone || '');
      const rKey = resolveTelegramAccountRuntimeKey({
        userId: exp.userId,
        phone: exp.phone,
        accountId: accId || undefined,
      });
      if (accId && !(exp.userId && seenUserIds.has(exp.userId)) && !(rKey && seenRuntimeKeys.has(rKey))) {
        expiredMap.set(accId, exp);
      }
    }

    const authContext = (req as any).auth;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const lockedAccountId = String(authContext?.effectiveAccountId || authContext?.session?.accountId || '').trim();
    const scopedVariants = !isMaster && lockedAccountId ? getScopedAccountIdVariants(lockedAccountId) : [];
    const matchesLockedScope = (item: { accountId?: string; id?: string; userId?: string; phone?: string }) => {
      if (isMaster) return true;
      if (!lockedAccountId) return false;
      const candidates = [
        item.accountId,
        item.id,
        item.userId,
        item.userId ? `acc_tg_${item.userId}` : undefined,
        item.phone,
      ]
        .map((v) => String(v || '').trim())
        .filter(Boolean);
      return candidates.some((c) => c === lockedAccountId || scopedVariants.includes(c));
    };

    const scopedActiveUsers = inMemoryActiveList.filter(matchesLockedScope);
    const scopedExpiredAccounts = Array.from(expiredMap.values()).filter(matchesLockedScope);

    res.json({
      ok: true,
      hasActiveSession: scopedActiveUsers.some((u) => u.isConnected),
      activeUsers: scopedActiveUsers,
      expiredAccounts: scopedExpiredAccounts,
      credentialsConfigured: hasCredsInMemory,
      credentialsError: !hasCredsInMemory ? lastCloudCredsError?.error || null : null,
      isRestoringSessions: telegramSessionRestoreState.inProgress,
      restoreError: telegramSessionRestoreState.lastError,
    });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// 20.0.1 On-demand Reconnect for Persisted / Offline Telegram Sessions (and sync cloud creds if missing)
app.post('/api/telegram/user/reconnect', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const bearerToken = extractBearerToken(req);
    const forceCredsRefresh = Boolean(req.body?.forceCredsRefresh);
    const forceReconnect = Boolean(req.body?.forceReconnect);
    const targetAccountId = targetScope.accountId;
    const targetUserId = targetScope.userId;
    const targetPhoneRaw = targetScope.phone;
    const targetPhone = targetPhoneRaw
      ? normalizePhoneNumber(targetPhoneRaw) || targetPhoneRaw
      : targetAccountId.startsWith('+') || /^00\d+$/.test(targetAccountId)
        ? normalizePhoneNumber(targetAccountId) || targetAccountId
        : '';

    const creds = await resolveTelegramApiCredentials({
      bearerToken,
      forceCloudRefresh: forceCredsRefresh,
    });
    if (!creds.ok || !creds.apiId || !creds.apiHash) {
      return res.status(400).json({
        ok: false,
        code: creds.code || 'CLOUD_CREDENTIALS_UNAVAILABLE',
        error: creds.error || '未能从云端获取 Telegram 接入凭据，请检查网络后重试',
      });
    }

    const targetRuntimeKey =
      targetAccountId || targetUserId || targetPhone
        ? resolveTelegramAccountRuntimeKey({
            accountId: targetAccountId || undefined,
            userId: targetUserId || undefined,
            phone: targetPhone || undefined,
          })
        : '';
    const normTargetPhone = targetPhone ? normalizePhoneNumber(targetPhone) || targetPhone : '';
    for (const rt of telegramAccountRuntimeStates.values()) {
      const matchesTarget =
        (!targetAccountId && !targetUserId && !normTargetPhone) ||
        (targetAccountId && rt.accountId === targetAccountId) ||
        (targetRuntimeKey && rt.accountKey === targetRuntimeKey) ||
        (normTargetPhone && (rt.phone === normTargetPhone || rt.phone === targetPhone));
      if (matchesTarget) {
        rt.nextRetryAt = 0;
      }
    }

    await loadSystemProxyConfigFromDb();
    const reconnectTargetKeys = Array.from(
      new Set([targetRuntimeKey, normTargetPhone ? `phone:${normTargetPhone}` : ''].filter(Boolean))
    );
    const restoredCount = await restoreTelegramUserSessionsOnStartup(bearerToken, {
      forceReconnect,
      ...(reconnectTargetKeys.length > 0 ? { targetAccountKeys: reconnectTargetKeys } : {}),
      reason: 'manual_reconnect',
    });
    const activeOnlineCount = Array.from(connectedUserClients.values()).filter((u) => {
      const rt = telegramAccountRuntimeStates.get(
        resolveTelegramAccountRuntimeKey({ userId: u.userId, phone: u.phone })
      );
      return getTelegramAccountConnectionSnapshot(u, rt).isConnected;
    }).length;

    const hasTarget = Boolean(targetAccountId || targetUserId || normTargetPhone);
    let targetRuntime: TelegramAccountRuntimeState | undefined = targetRuntimeKey
      ? telegramAccountRuntimeStates.get(targetRuntimeKey)
      : undefined;
    if (!targetRuntime && hasTarget) {
      for (const rt of telegramAccountRuntimeStates.values()) {
        if (
          (targetAccountId && rt.accountId === targetAccountId) ||
          (targetRuntimeKey && rt.accountKey === targetRuntimeKey) ||
          (normTargetPhone && (rt.phone === normTargetPhone || rt.phone === targetPhone))
        ) {
          targetRuntime = rt;
          break;
        }
      }
    }
    const targetConn = hasTarget
      ? resolveConnectedTelegramUser(targetAccountId || undefined, normTargetPhone || undefined, targetUserId || undefined)
      : undefined;
    const targetIsOnline = Boolean(
      targetConn && getTelegramAccountConnectionSnapshot(targetConn, targetRuntime).isConnected
    );
    const targetError = hasTarget
      ? targetRuntime?.lastError || null
      : targetRuntime?.lastError || telegramSessionRestoreState.lastError;
    if (!(hasTarget && targetIsOnline) && targetError && restoredCount === 0 && (hasTarget || activeOnlineCount === 0)) {
      return res.status(502).json({
        ok: false,
        restoredCount,
        error: targetError,
      });
    }

    return res.json({
      ok: true,
      restoredCount,
      hasActiveSession: activeOnlineCount > 0,
      restoreError: telegramSessionRestoreState.lastError,
      message:
        restoredCount > 0
          ? `已成功恢复 ${restoredCount} 个 Telegram 账号连接`
          : activeOnlineCount > 0
            ? '所有已登录 Telegram 账号均处于在线状态'
            : '当前没有可恢复的离线账号',
    });
  } catch (err: any) {
    return res.status(500).json({ ok: false, error: err?.message || '重连 Telegram 会话失败' });
  }
});

// 20.1 Fetch Real Dialogs for Connected Telegram Personal Account
app.get('/api/telegram/user/dialogs', requireTenantAuth, async (req: Request, res: Response) => {
  const targetScope = resolveScopedTelegramTarget(req, {
    allowBot: false,
    rawPhone: req.query.phone,
  });
  if (!targetScope.ok) {
    return res.status(targetScope.status).json({ ok: false, code: targetScope.code, dialogs: [], error: targetScope.error });
  }
  const accountId = targetScope.accountId;
  const phone = targetScope.phone;
  let connected: ConnectedTelegramUser | undefined;
  try {
    if (accountId) {
      const normalized = accountId.replace(/^acc_tg_/, '');
      const exp = recentlyExpiredAccounts.get(normalized) || recentlyExpiredAccounts.get(accountId);
      if (exp) {
        return res.status(401).json({
          ok: false,
          code: 'TELEGRAM_SESSION_EXPIRED',
          dialogs: [],
          error: exp.reason || 'Telegram 登录会话已失效，请重新登录',
        });
      }
    }

    connected =
      (accountId ? connectedUserClients.get(accountId) : undefined) ||
      (phone ? connectedUserClients.get(phone) : undefined);

    if (!connected && accountId) {
      connected = Array.from(connectedUserClients.values()).find(
        (c) => c.userId === accountId || c.phone === accountId || `acc_tg_${c.userId}` === accountId
      );
    }

    // Strict multi-account isolation: only allow default fallback when neither accountId nor phone was requested AND strictly 1 account is connected
    if (!connected && !accountId && !phone && connectedUserClients.size > 0) {
      const uniqueConnected = Array.from(
        new Map(Array.from(connectedUserClients.values()).map((u) => [u.userId, u])).values()
      );
      if (uniqueConnected.length > 1) {
        return res.status(400).json({
          ok: false,
          dialogs: [],
          error: '多账号模式下必须指定 accountId',
        });
      }
      connected = uniqueConnected[0];
    }

    if (!connected || !connected.client) {
      return res.json({
        ok: false,
        dialogs: [],
        message: accountId ? `账号 ${accountId} 尚未连接或已离线` : '当前无活动的个人 Telegram 客户端会话',
      });
    }

    const effectiveAccId = accountId || (req as any).auth?.effectiveAccountId || `acc_tg_${connected.userId}`;
    const forceRefresh = req.query.force === '1' || req.query.force === 'true';

    // Account-level FLOOD_WAIT circuit breaker: never fire MTProto GetDialogs while cooling down
    const activeFlood = getTelegramFloodCooldown({
      accountId: effectiveAccId,
      userId: connected.userId,
      phone: connected.phone,
    });
    if (activeFlood) {
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: activeFlood.retryAfterSeconds,
        floodWaitUntil: activeFlood.floodWaitUntil,
        error: formatTelegramError({ errorMessage: `FLOOD_WAIT_${activeFlood.retryAfterSeconds}` }),
        dialogs: Array.isArray(connected.dialogs) ? connected.dialogs : [],
        userId: connected.userId,
        phone: connected.phone,
        isConnected: Boolean(connected.client.connected),
        fromCache: true,
      });
    }

    const dialogAccVariants = getScopedAccountIdVariants(effectiveAccId);
    const tgPrefAcc = `acc_tg_${connected.userId}`;
    if (!dialogAccVariants.includes(tgPrefAcc)) dialogAccVariants.push(tgPrefAcc);

    const loadDialogLangPrefs = async () => {
      const prefs = new Map<string, { sourceLang: string; targetLang: string; translationEnabled?: boolean }>();
      try {
        const ph = dialogAccVariants.map(() => '?').join(', ');
        const prefRows = (await db.prepare(`
          SELECT chat_id, source_lang, target_lang, translation_enabled
          FROM chat_language_prefs
          WHERE account_id IN (${ph})
        `).all(...dialogAccVariants)) as any[];
        for (const r of prefRows || []) {
          const parsedEnabled =
            r.translation_enabled === 1 || r.translation_enabled === true
              ? true
              : r.translation_enabled === 0 || r.translation_enabled === false
                ? false
                : undefined;
          prefs.set(r.chat_id, {
            sourceLang: r.source_lang || 'Auto',
            targetLang: r.target_lang || 'Auto',
            ...(parsedEnabled !== undefined ? { translationEnabled: parsedEnabled } : {}),
          });
        }
      } catch {}
      return prefs;
    };

    const { dialogs: rawDialogs, cached } = await getOrFetchConnectedAccountDialogs(connected, {
      force: forceRefresh,
      limit: 150,
    });
    const loadDialogCustomRemarks = async () => {
      const remarks = new Map<string, string>();
      try {
        const ph = dialogAccVariants.map(() => '?').join(', ');
        const rows = (await db.prepare(`
          SELECT chat_id, custom_title
          FROM chat_remarks
          WHERE account_id IN (${ph})
        `).all(...dialogAccVariants)) as any[];
        for (const r of rows || []) {
          if (r?.chat_id && typeof r?.custom_title === 'string' && r.custom_title.trim()) {
            remarks.set(String(r.chat_id), r.custom_title.trim());
          }
        }
      } catch {}
      return remarks;
    };

    const [dialogLangPrefs, dialogCustomRemarks] = await Promise.all([
      loadDialogLangPrefs(),
      loadDialogCustomRemarks(),
    ]);

    const dialogs = rawDialogs.map((d: any) => {
      const pref = dialogLangPrefs.get(d.id);
      const customTitle = dialogCustomRemarks.get(d.id) || dialogCustomRemarks.get(`tg_${d.rawId}`);
      return {
        ...d,
        ...(customTitle ? { title: customTitle, hasCustomRemark: true } : {}),
        ...(pref
          ? {
              sourceLang: pref.sourceLang,
              targetLang: pref.targetLang,
              ...(typeof pref.translationEnabled === 'boolean' ? { translationEnabled: pref.translationEnabled } : {}),
            }
          : {}),
      };
    });
    if (!cached) {
      connected.dialogs = dialogs;
      connected.dialogsFetchedAt = Date.now();
    }

    res.json({
      ok: true,
      dialogs,
      userId: connected.userId,
      phone: connected.phone,
      isConnected: Boolean(connected.client.connected),
      totalCount: dialogs.length,
      ...(cached ? { cached: true } : {}),
    });
  } catch (err: any) {
    const floodEntry = recordTelegramFloodWait(
      { accountId, userId: connected?.userId, phone: connected?.phone || phone },
      err,
      'messages.GetDialogs'
    );
    if (floodEntry) {
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: floodEntry.retryAfterSeconds,
        floodWaitUntil: floodEntry.floodWaitUntil,
        error: formatTelegramError(err),
        dialogs: Array.isArray(connected?.dialogs) ? connected.dialogs : [],
        fromCache: true,
      });
    }
    if (isTelegramSessionExpiredError(err)) {
      await markTelegramSessionExpired({
        accountId,
        userId: connected?.userId,
        phone: connected?.phone || phone,
        reason: formatTelegramError(err),
      });
      return res.status(401).json({
        ok: false,
        code: 'TELEGRAM_SESSION_EXPIRED',
        error: 'Telegram 登录会话已失效，请重新扫码或验证码登录',
        dialogs: [],
      });
    }
    res.status(500).json({ ok: false, error: formatTelegramError(err), dialogs: [] });
  }
});

// 20.1.1 Bounded LRU + TTL Cache for Telegram Avatars & Media (prevents memory OOM)
export const TELEGRAM_AVATAR_CACHE_TTL_MS = 60 * 60 * 1000; // 1 hour
export const TELEGRAM_AVATAR_CACHE_MAX_ENTRIES = 500;
export const TELEGRAM_AVATAR_CACHE_MAX_BYTES = 24 * 1024 * 1024; // 24 MB
export const TELEGRAM_AVATAR_CACHE_ITEM_MAX_BYTES = 2 * 1024 * 1024; // 2 MB

export const TELEGRAM_MEDIA_CACHE_TTL_MS = 30 * 60 * 1000; // 30 minutes
export const TELEGRAM_MEDIA_CACHE_MAX_BYTES = 128 * 1024 * 1024; // 128 MB budget
export const TELEGRAM_MEDIA_CACHE_MAX_ENTRIES = 256;
export const TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES = Math.max(
  1024 * 1024,
  Number(process.env.TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES) || 8 * 1024 * 1024
); // 8 MB single-file RAM threshold; larger files stream via iterDownload
export const TELEGRAM_MEDIA_STREAM_CHUNK_BYTES = 256 * 1024; // 256 KB (multiple of 4096 & 1MB divisor)

export class BoundedByteLruCache<T extends { buffer: Buffer; expiresAt: number }> {
  private map = new Map<string, T>();
  private _totalBytes = 0;
  readonly maxBytes: number;
  readonly maxEntries: number;
  readonly maxItemBytes: number;

  constructor(options: { maxBytes: number; maxEntries: number; maxItemBytes?: number }) {
    this.maxBytes = Math.max(1, options.maxBytes);
    this.maxEntries = Math.max(1, options.maxEntries);
    this.maxItemBytes = Math.max(1, options.maxItemBytes ?? options.maxBytes);
  }

  get size(): number {
    return this.map.size;
  }

  get totalBytes(): number {
    return this._totalBytes;
  }

  keys(): IterableIterator<string> {
    return this.map.keys();
  }

  pruneExpired(now = Date.now()): number {
    let removed = 0;
    for (const [k, v] of this.map.entries()) {
      if (v.expiresAt <= now) {
        this.map.delete(k);
        this._totalBytes = Math.max(0, this._totalBytes - v.buffer.length);
        removed++;
      }
    }
    return removed;
  }

  get(key: string, now = Date.now()): T | undefined {
    const entry = this.map.get(key);
    if (!entry) return undefined;
    if (entry.expiresAt <= now) {
      this.map.delete(key);
      this._totalBytes = Math.max(0, this._totalBytes - entry.buffer.length);
      return undefined;
    }
    // Refresh LRU recency (move to tail)
    this.map.delete(key);
    this.map.set(key, entry);
    return entry;
  }

  set(key: string, entry: T, now = Date.now()): boolean {
    this.pruneExpired(now);
    const itemBytes = Buffer.isBuffer(entry?.buffer) ? entry.buffer.length : 0;
    if (itemBytes <= 0 || itemBytes > this.maxItemBytes || itemBytes > this.maxBytes || entry.expiresAt <= now) {
      this.delete(key);
      return false;
    }

    const existing = this.map.get(key);
    if (existing) {
      this._totalBytes = Math.max(0, this._totalBytes - existing.buffer.length);
      this.map.delete(key);
    }

    while ((this._totalBytes + itemBytes > this.maxBytes || this.map.size >= this.maxEntries) && this.map.size > 0) {
      const oldestKey = this.map.keys().next().value;
      if (oldestKey === undefined) break;
      const oldest = this.map.get(oldestKey)!;
      this.map.delete(oldestKey);
      this._totalBytes = Math.max(0, this._totalBytes - oldest.buffer.length);
    }

    this.map.set(key, entry);
    this._totalBytes += itemBytes;
    return true;
  }

  delete(key: string): boolean {
    const existing = this.map.get(key);
    if (!existing) return false;
    this._totalBytes = Math.max(0, this._totalBytes - existing.buffer.length);
    return this.map.delete(key);
  }

  deleteByPrefix(prefix: string): number {
    if (!prefix) return 0;
    let removed = 0;
    for (const [k, v] of this.map.entries()) {
      if (k.startsWith(prefix)) {
        this.map.delete(k);
        this._totalBytes = Math.max(0, this._totalBytes - v.buffer.length);
        removed++;
      }
    }
    return removed;
  }

  clear(): void {
    this.map.clear();
    this._totalBytes = 0;
  }

  stats() {
    return {
      entries: this.map.size,
      totalBytes: this._totalBytes,
      maxBytes: this.maxBytes,
      maxEntries: this.maxEntries,
      maxItemBytes: this.maxItemBytes,
    };
  }
}

export const telegramAvatarCache = new BoundedByteLruCache<{
  buffer: Buffer;
  mime: string;
  expiresAt: number;
}>({
  maxBytes: TELEGRAM_AVATAR_CACHE_MAX_BYTES,
  maxEntries: TELEGRAM_AVATAR_CACHE_MAX_ENTRIES,
  maxItemBytes: TELEGRAM_AVATAR_CACHE_ITEM_MAX_BYTES,
});

export const telegramMediaCache = new BoundedByteLruCache<{
  buffer: Buffer;
  mime: string;
  fileName: string;
  expiresAt: number;
}>({
  maxBytes: TELEGRAM_MEDIA_CACHE_MAX_BYTES,
  maxEntries: TELEGRAM_MEDIA_CACHE_MAX_ENTRIES,
  maxItemBytes: TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES,
});

export function pruneServerRuntimeCaches(now = Date.now()) {
  const avatarRemoved = telegramAvatarCache.pruneExpired(now);
  const avatarNegativeRemoved = pruneAvatarNegativeCache(now);
  const senderCacheRemoved = pruneTelegramSenderCache(now);
  const mediaRemoved = telegramMediaCache.pruneExpired(now);
  const stickerRemoved = telegramStickerThumbCache.pruneExpired(now);
  const floodRemoved = pruneExpiredTelegramFloodCooldowns(now);
  const qrRemoved = pruneExpiredQrSessions(now);
  const changePhoneRemoved = prunePendingChangePhoneSessions(now);
  const callsRemoved = pruneActiveTelegramCalls(now);
  const jwtRemoved = pruneRevokedJwtTokens(now);
  const dedupRemoved = pruneOutboundAndMtprotoDedupCaches(now);
  const credsRemoved = pruneInMemoryCloudTelegramCreds(now);
  return {
    avatarRemoved,
    avatarNegativeRemoved,
    senderCacheRemoved,
    mediaRemoved,
    stickerRemoved,
    floodRemoved,
    qrRemoved,
    changePhoneRemoved,
    callsRemoved,
    jwtRemoved,
    ...dedupRemoved,
    credsRemoved,
  };
}

let telegramCacheCleanupInterval: NodeJS.Timeout | null = null;
function startTelegramCacheCleanupTimer(): void {
  if (telegramCacheCleanupInterval) return;
  telegramCacheCleanupInterval = setInterval(() => {
    pruneServerRuntimeCaches(Date.now());
  }, 5 * 60 * 1000);
  telegramCacheCleanupInterval.unref?.();
}

function stopTelegramCacheCleanupTimer(): void {
  if (telegramCacheCleanupInterval) {
    clearInterval(telegramCacheCleanupInterval);
    telegramCacheCleanupInterval = null;
  }
}

// ==================== AVATAR SINGLE-FLIGHT + BOUNDED CONCURRENCY + 4-TIER ERROR CACHE ====================
export const TELEGRAM_AVATAR_MAX_CONCURRENT = 2;
export const TELEGRAM_AVATAR_MAX_QUEUE = 32;
export const TELEGRAM_AVATAR_DISK_REFRESH_MS = 24 * 60 * 60 * 1000;
export const TELEGRAM_AVATAR_NO_PHOTO_NEGATIVE_TTL_MS = 5 * 60 * 1000;
export const TELEGRAM_AVATAR_RPC_ERROR_NEGATIVE_TTL_MS = 20 * 1000;
export const TELEGRAM_AVATAR_NEGATIVE_CACHE_MAX = 5000;
const telegramAvatarBgRefreshInFlight = new Set<string>();

function resolveAvatarDiskPath(cacheKey: string): string | null {
  const digest = crypto.createHash('sha256').update(cacheKey, 'utf8').digest('hex');
  const targetPath = path.resolve(AVATAR_CACHE_DIR, `${digest}.jpg`);
  if (!targetPath.startsWith(AVATAR_CACHE_DIR + path.sep)) return null;
  return targetPath;
}

let avatarCacheDirReady = false;

async function readAvatarFromDiskCacheAsync(
  cacheKey: string
): Promise<{ buffer: Buffer; mime: string; isStale: boolean } | null> {
  try {
    const filePath = resolveAvatarDiskPath(cacheKey);
    if (!filePath) return null;
    const stat = await fs.promises.stat(filePath);
    if (!stat.isFile() || stat.size <= 0) return null;
    const buffer = await fs.promises.readFile(filePath);
    if (!buffer || buffer.length <= 0) return null;
    const isStale = Date.now() - stat.mtimeMs > TELEGRAM_AVATAR_DISK_REFRESH_MS;
    return { buffer, mime: 'image/jpeg', isStale };
  } catch {
    return null;
  }
}

async function writeAvatarToDiskCacheAsync(cacheKey: string, buffer: Buffer): Promise<void> {
  let tmpPath = '';
  try {
    if (!buffer || buffer.length === 0) return;
    const filePath = resolveAvatarDiskPath(cacheKey);
    if (!filePath) return;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        if (!avatarCacheDirReady) {
          await fs.promises.mkdir(AVATAR_CACHE_DIR, { recursive: true });
          avatarCacheDirReady = true;
        }
        tmpPath = `${filePath}.${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2, 7)}.tmp`;
        await fs.promises.writeFile(tmpPath, buffer);
        await fs.promises.rename(tmpPath, filePath);
        tmpPath = '';
        return;
      } catch (err: any) {
        if (tmpPath) {
          await fs.promises.unlink(tmpPath).catch(() => {});
          tmpPath = '';
        }
        if (err?.code === 'ENOENT' && attempt === 0) {
          avatarCacheDirReady = false;
          continue;
        }
        throw err;
      }
    }
  } catch {
    if (tmpPath) {
      await fs.promises.unlink(tmpPath).catch(() => {});
    }
  }
}

async function deleteAvatarDiskCacheAsync(cacheKey: string): Promise<void> {
  try {
    const filePath = resolveAvatarDiskPath(cacheKey);
    if (filePath) {
      await fs.promises.unlink(filePath).catch(() => {});
    }
  } catch {}
}

function invalidateTelegramAvatarCacheEntries(userId: string, peerId: string, extraKeys: string[] = []): void {
  const cleanPeer = String(peerId || '').replace(/^tg_/, '').trim();
  const keys = new Set<string>(extraKeys.filter(Boolean));
  if (cleanPeer) {
    keys.add(cleanPeer);
    if (userId) {
      keys.add(`acc_tg_${userId}:${cleanPeer}`);
      keys.add(`${userId}:${cleanPeer}`);
    }
    keys.add(`shared:${cleanPeer}`);
  }
  for (const k of keys) {
    telegramAvatarCache.delete(k);
    void deleteAvatarDiskCacheAsync(k);
  }
}

interface AvatarNegativeEntry {
  reason: 'no_photo' | 'rpc_error';
  expiresAt: number;
}

interface AvatarFetchOutcome {
  status: 200 | 404 | 429 | 503;
  buffer?: Buffer;
  mime?: string;
  retryAfterSeconds?: number;
  errorType?: 'no_photo' | 'flood_wait' | 'timeout' | 'offline' | 'rpc_error' | 'queue_full';
}

const telegramAvatarNegativeCache = new Map<string, AvatarNegativeEntry>();
const telegramAvatarInFlight = new Map<string, Promise<AvatarFetchOutcome>>();

interface AvatarSlotWaiter {
  resolve: () => void;
  reject: (err: any) => void;
  signal?: AbortSignal;
  abortHandler?: () => void;
}
interface AvatarAccountLimiterState {
  active: number;
  waiters: AvatarSlotWaiter[];
}
const avatarAccountLimiters = new Map<string, AvatarAccountLimiterState>();
const avatarLimiterStats = {
  completedTotal: 0,
  rejectedQueueFullTotal: 0,
  abortedWaitersTotal: 0,
  negativeCacheHitsNoPhoto: 0,
  negativeCacheHitsRpcError: 0,
  singleFlightHitsTotal: 0,
};

export function clearAvatarNegativeCacheForPeer(userId: string, peerId: string): void {
  const cleanPeer = String(peerId || '').replace(/^tg_/, '').trim();
  if (!cleanPeer) return;
  for (const k of [cleanPeer, `acc_tg_${userId}:${cleanPeer}`, `${userId}:${cleanPeer}`, `shared:${cleanPeer}`]) {
    telegramAvatarNegativeCache.delete(k);
  }
}

export function clearAvatarCachesForTesting(): void {
  telegramAvatarNegativeCache.clear();
  telegramAvatarInFlight.clear();
  avatarAccountLimiters.clear();
  telegramAvatarCache.clear();
  telegramAvatarBgRefreshInFlight.clear();
  accountAvatarPrewarmLastAt.clear();
  accountAvatarPrewarmRunning.clear();
  if (process.env.NODE_ENV === 'test') {
    try {
      for (const name of fs.readdirSync(AVATAR_CACHE_DIR)) {
        if (name.endsWith('.jpg') || name.endsWith('.tmp')) {
          fs.unlinkSync(path.join(AVATAR_CACHE_DIR, name));
        }
      }
    } catch {}
  }
}

export function pruneAvatarNegativeCache(now = Date.now()): number {
  let removed = 0;
  for (const [k, entry] of telegramAvatarNegativeCache.entries()) {
    if (!entry || entry.expiresAt <= now) {
      telegramAvatarNegativeCache.delete(k);
      removed++;
    }
  }
  return removed;
}

function setAvatarNegativeCache(cacheKey: string, reason: 'no_photo' | 'rpc_error', now = Date.now()): void {
  const ttl =
    reason === 'no_photo'
      ? TELEGRAM_AVATAR_NO_PHOTO_NEGATIVE_TTL_MS
      : TELEGRAM_AVATAR_RPC_ERROR_NEGATIVE_TTL_MS;
  if (telegramAvatarNegativeCache.size >= TELEGRAM_AVATAR_NEGATIVE_CACHE_MAX) {
    pruneAvatarNegativeCache(now);
    while (telegramAvatarNegativeCache.size >= TELEGRAM_AVATAR_NEGATIVE_CACHE_MAX) {
      const oldest = telegramAvatarNegativeCache.keys().next().value;
      if (oldest === undefined) break;
      telegramAvatarNegativeCache.delete(oldest);
    }
  }
  telegramAvatarNegativeCache.set(cacheKey, { reason, expiresAt: now + ttl });
}

export function getAvatarNegativeCacheEntry(cacheKey: string, now = Date.now()): AvatarNegativeEntry | null {
  const entry = telegramAvatarNegativeCache.get(cacheKey);
  if (!entry) return null;
  if (entry.expiresAt <= now) {
    telegramAvatarNegativeCache.delete(cacheKey);
    return null;
  }
  return entry;
}

export function getAvatarLimiterStats() {
  let active = 0;
  let queued = 0;
  for (const state of avatarAccountLimiters.values()) {
    active += state.active;
    queued += state.waiters.length;
  }
  return {
    active,
    queued,
    inFlightSingleFlight: telegramAvatarInFlight.size,
    negativeCacheEntries: telegramAvatarNegativeCache.size,
    maxConcurrentPerAccount: TELEGRAM_AVATAR_MAX_CONCURRENT,
    maxQueuePerAccount: TELEGRAM_AVATAR_MAX_QUEUE,
    ...avatarLimiterStats,
  };
}

registerPerformanceQueueStatsProvider('avatarLimiter', getAvatarLimiterStats);

function acquireAvatarSlot(accountScope: string, signal?: AbortSignal): Promise<() => void> {
  if (signal?.aborted) {
    const err: any = new Error('Client aborted avatar request');
    err.code = 'AVATAR_ABORTED';
    return Promise.reject(err);
  }
  let state = avatarAccountLimiters.get(accountScope);
  if (!state) {
    state = { active: 0, waiters: [] };
    avatarAccountLimiters.set(accountScope, state);
  }

  const makeRelease = () => {
    let released = false;
    return () => {
      if (released) return;
      released = true;
      const st = avatarAccountLimiters.get(accountScope);
      if (!st) return;
      st.active = Math.max(0, st.active - 1);
      while (st.waiters.length > 0 && st.active < TELEGRAM_AVATAR_MAX_CONCURRENT) {
        const nextWaiter = st.waiters.shift()!;
        if (nextWaiter.signal && nextWaiter.abortHandler) {
          try {
            nextWaiter.signal.removeEventListener('abort', nextWaiter.abortHandler);
          } catch {}
        }
        if (nextWaiter.signal?.aborted) {
          avatarLimiterStats.abortedWaitersTotal += 1;
          const abortErr: any = new Error('Client aborted avatar request');
          abortErr.code = 'AVATAR_ABORTED';
          nextWaiter.reject(abortErr);
          continue;
        }
        st.active += 1;
        nextWaiter.resolve();
        break;
      }
      if (st.active === 0 && st.waiters.length === 0) {
        avatarAccountLimiters.delete(accountScope);
      }
    };
  };

  if (state.active < TELEGRAM_AVATAR_MAX_CONCURRENT) {
    state.active += 1;
    return Promise.resolve(makeRelease());
  }

  if (state.waiters.length >= TELEGRAM_AVATAR_MAX_QUEUE) {
    avatarLimiterStats.rejectedQueueFullTotal += 1;
    const err: any = new Error('Avatar download queue is full');
    err.code = 'AVATAR_QUEUE_FULL';
    return Promise.reject(err);
  }

  return new Promise<() => void>((resolve, reject) => {
    const waiter: AvatarSlotWaiter = {
      resolve: () => resolve(makeRelease()),
      reject,
      signal,
    };
    if (signal) {
      const onAbort = () => {
        const st = avatarAccountLimiters.get(accountScope);
        if (st) {
          const idx = st.waiters.indexOf(waiter);
          if (idx >= 0) {
            st.waiters.splice(idx, 1);
            if (st.active === 0 && st.waiters.length === 0) {
              avatarAccountLimiters.delete(accountScope);
            }
          }
        }
        avatarLimiterStats.abortedWaitersTotal += 1;
        const abortErr: any = new Error('Client aborted avatar request');
        abortErr.code = 'AVATAR_ABORTED';
        reject(abortErr);
      };
      waiter.abortHandler = onAbort;
      signal.addEventListener('abort', onAbort, { once: true });
    }
    state!.waiters.push(waiter);
  });
}

function classifyAvatarErrorKind(err: any): {
  kind: 'flood_wait' | 'no_photo' | 'timeout' | 'offline' | 'rpc_error' | 'queue_full';
  retryAfterSeconds?: number;
} {
  const floodSecs = extractFloodWaitSeconds(err);
  if (floodSecs !== null) {
    return { kind: 'flood_wait', retryAfterSeconds: floodSecs };
  }
  const code = String(err?.code || '').toUpperCase();
  const msg = String(err?.errorMessage || err?.message || err || '').toUpperCase();
  if (code === 'AVATAR_QUEUE_FULL' || code === 'TELEGRAM_RPC_QUEUE_FULL') {
    return { kind: 'queue_full', retryAfterSeconds: 3 };
  }
  if (
    msg.includes('USER_ID_INVALID') ||
    msg.includes('PEER_ID_INVALID') ||
    msg.includes('CHANNEL_INVALID') ||
    msg.includes('CHAT_ID_INVALID') ||
    msg.includes('USERNAME_NOT_OCCUPIED') ||
    msg.includes('CHANNEL_PRIVATE') ||
    msg.includes('USER_PRIVACY_RESTRICTED')
  ) {
    return { kind: 'no_photo' };
  }
  if (
    msg.includes('NOT CONNECTED') ||
    msg.includes('ECONNREFUSED') ||
    msg.includes('ECONNRESET') ||
    msg.includes('CLIENT ABORTED')
  ) {
    return { kind: 'offline', retryAfterSeconds: 5 };
  }
  if (msg.includes('TIMEOUT') || msg.includes('ETIMEDOUT') || msg.includes('超时')) {
    return { kind: 'timeout', retryAfterSeconds: 5 };
  }
  return { kind: 'rpc_error', retryAfterSeconds: 5 };
}

export async function fetchTelegramAvatarWithLimiting(opts: {
  cacheAccountScope: string;
  cleanId: string;
  candidates: ConnectedTelegramUser[];
  signal?: AbortSignal;
}): Promise<AvatarFetchOutcome> {
  const { cacheAccountScope, cleanId, candidates, signal } = opts;
  const cacheKey = `${cacheAccountScope}:${cleanId}`;
  const now = Date.now();
  const isSelfAvatar = candidates.some((c) => c?.userId && String(c.userId).trim() === cleanId);
  const lookupKeys = isSelfAvatar
    ? Array.from(new Set([cacheKey, `acc_tg_${cleanId}:${cleanId}`]))
    : [cacheKey];

  for (const lk of lookupKeys) {
    const cached = telegramAvatarCache.get(lk, now);
    if (cached) {
      return { status: 200, buffer: cached.buffer, mime: cached.mime };
    }
  }

  let diskHit: { buffer: Buffer; mime: string; isStale: boolean } | null = null;
  for (const lk of lookupKeys) {
    diskHit = await readAvatarFromDiskCacheAsync(lk);
    if (diskHit) break;
  }
  if (diskHit) {
    telegramAvatarCache.set(
      cacheKey,
      {
        buffer: diskHit.buffer,
        mime: diskHit.mime,
        expiresAt: now + TELEGRAM_AVATAR_CACHE_TTL_MS,
      },
      now
    );
    if (diskHit.isStale && candidates.length > 0 && !telegramAvatarBgRefreshInFlight.has(cacheKey)) {
      telegramAvatarBgRefreshInFlight.add(cacheKey);
      void (async () => {
        try {
          const peerBg: any = /^-?\d+$/.test(cleanId) ? Number(cleanId) : cleanId;
          const onlineCandidate = candidates.find((c) => c?.client?.connected);
          if (!onlineCandidate?.client) return;
          const fresh = await scheduleTelegramRpc(cacheAccountScope, 'P2', 'downloadProfilePhoto.bg', () =>
            withTelegramTimeout(
              onlineCandidate.client.downloadProfilePhoto(peerBg, { isBig: false }),
              8000,
              '后台刷新头像超时'
            )
          );
          if (fresh && Buffer.isBuffer(fresh) && fresh.length > 0) {
            const ts = Date.now();
            void writeAvatarToDiskCacheAsync(cacheKey, fresh);
            telegramAvatarCache.set(
              cacheKey,
              { buffer: fresh, mime: 'image/jpeg', expiresAt: ts + TELEGRAM_AVATAR_CACHE_TTL_MS },
              ts
            );
          } else {
            telegramAvatarCache.delete(cacheKey);
            void deleteAvatarDiskCacheAsync(cacheKey);
            setAvatarNegativeCache(cacheKey, 'no_photo', Date.now());
          }
        } catch {} finally {
          telegramAvatarBgRefreshInFlight.delete(cacheKey);
        }
      })();
    }
    return { status: 200, buffer: diskHit.buffer, mime: diskHit.mime };
  }

  const neg = getAvatarNegativeCacheEntry(cacheKey, now);
  if (neg) {
    if (neg.reason === 'no_photo') {
      avatarLimiterStats.negativeCacheHitsNoPhoto += 1;
      return { status: 404, errorType: 'no_photo' };
    }
    avatarLimiterStats.negativeCacheHitsRpcError += 1;
    return { status: 503, retryAfterSeconds: 5, errorType: 'rpc_error' };
  }

  const peer: any = /^-?\d+$/.test(cleanId) ? Number(cleanId) : cleanId;
  const primaryCandidate = candidates[0];
  if (primaryCandidate) {
    const activeFlood = getTelegramFloodCooldown(
      { accountId: cacheAccountScope, userId: primaryCandidate.userId, phone: primaryCandidate.phone },
      now
    );
    if (activeFlood) {
      return { status: 429, retryAfterSeconds: activeFlood.retryAfterSeconds, errorType: 'flood_wait' };
    }
  }

  const existingFlight = telegramAvatarInFlight.get(cacheKey);
  if (existingFlight) {
    avatarLimiterStats.singleFlightHitsTotal += 1;
    return await existingFlight;
  }

  let releaseSlot: (() => void) | null = null;
  if (!isSelfAvatar) {
    try {
      releaseSlot = await acquireAvatarSlot(cacheAccountScope, signal);
    } catch (slotErr: any) {
      if (slotErr?.code === 'AVATAR_ABORTED') {
        return { status: 503, retryAfterSeconds: 3, errorType: 'offline' };
      }
      return { status: 503, retryAfterSeconds: 3, errorType: 'queue_full' };
    }
  }

  // Re-check caches after acquiring queued slot in case single-flight resolved it meanwhile
  const cachedAfterWait = telegramAvatarCache.get(cacheKey, Date.now());
  if (cachedAfterWait) {
    releaseSlot?.();
    return { status: 200, buffer: cachedAfterWait.buffer, mime: cachedAfterWait.mime };
  }
  const negAfterWait = getAvatarNegativeCacheEntry(cacheKey, Date.now());
  if (negAfterWait) {
    releaseSlot?.();
    return negAfterWait.reason === 'no_photo'
      ? { status: 404, errorType: 'no_photo' }
      : { status: 503, retryAfterSeconds: 5, errorType: 'rpc_error' };
  }
  const existingFlightAfterWait = telegramAvatarInFlight.get(cacheKey);
  if (existingFlightAfterWait) {
    releaseSlot?.();
    avatarLimiterStats.singleFlightHitsTotal += 1;
    return await existingFlightAfterWait;
  }

  const downloadTask = (async (): Promise<AvatarFetchOutcome> => {
    try {
      let sawTransientTimeoutOrOffline: AvatarFetchOutcome | null = null;
      let sawRpcError = false;
      let sawNoPhotoSuccess = false;

      for (const connected of candidates) {
        if (!connected.client) continue;
        const floodCheck = getTelegramFloodCooldown({
          accountId: cacheAccountScope,
          userId: connected.userId,
          phone: connected.phone,
        });
        if (floodCheck) {
          return { status: 429, retryAfterSeconds: floodCheck.retryAfterSeconds, errorType: 'flood_wait' };
        }
        try {
          const photo = await scheduleTelegramRpc(cacheAccountScope, 'P2', 'downloadProfilePhoto', () =>
            withTelegramTimeout(
              connected.client.downloadProfilePhoto(peer, { isBig: false }),
              8000,
              '下载 Telegram 头像超时'
            )
          );
          if (photo && Buffer.isBuffer(photo) && photo.length > 0) {
            const finishTs = Date.now();
            void writeAvatarToDiskCacheAsync(cacheKey, photo);
            telegramAvatarCache.set(
              cacheKey,
              {
                buffer: photo,
                mime: 'image/jpeg',
                expiresAt: finishTs + TELEGRAM_AVATAR_CACHE_TTL_MS,
              },
              finishTs
            );
            telegramAvatarNegativeCache.delete(cacheKey);
            avatarLimiterStats.completedTotal += 1;
            return { status: 200, buffer: photo, mime: 'image/jpeg' };
          }
          // Connected client successfully answered with no profile photo
          sawNoPhotoSuccess = true;
        } catch (avatarErr: any) {
          const floodEntry = recordTelegramFloodWait(
            { accountId: cacheAccountScope, userId: connected.userId, phone: connected.phone },
            avatarErr,
            'downloadProfilePhoto'
          );
          if (floodEntry) {
            return {
              status: 429,
              retryAfterSeconds: floodEntry.retryAfterSeconds,
              errorType: 'flood_wait',
            };
          }
          const classified = classifyAvatarErrorKind(avatarErr);
          if (classified.kind === 'flood_wait') {
            return { status: 429, retryAfterSeconds: classified.retryAfterSeconds || 30, errorType: 'flood_wait' };
          }
          if (classified.kind === 'no_photo') {
            sawNoPhotoSuccess = true;
            continue;
          }
          if (
            classified.kind === 'timeout' ||
            classified.kind === 'offline' ||
            classified.kind === 'queue_full'
          ) {
            // NEVER negative-cache timeouts, disconnections, or backpressure!
            sawTransientTimeoutOrOffline = {
              status: 503,
              retryAfterSeconds: classified.retryAfterSeconds || 5,
              errorType: classified.kind,
            };
            continue;
          }
          sawRpcError = true;
        }
      }

      if (sawTransientTimeoutOrOffline) {
        return sawTransientTimeoutOrOffline;
      }
      if (sawNoPhotoSuccess && !sawRpcError) {
        setAvatarNegativeCache(cacheKey, 'no_photo', Date.now());
        return { status: 404, errorType: 'no_photo' };
      }
      if (sawRpcError) {
        setAvatarNegativeCache(cacheKey, 'rpc_error', Date.now());
        return { status: 503, retryAfterSeconds: 5, errorType: 'rpc_error' };
      }
      return { status: 404, errorType: 'no_photo' };
    } finally {
      telegramAvatarInFlight.delete(cacheKey);
      releaseSlot?.();
    }
  })();

  telegramAvatarInFlight.set(cacheKey, downloadTask);
  return await downloadTask;
}

const accountAvatarPrewarmLastAt = new Map<string, number>();
const accountAvatarPrewarmRunning = new Set<string>();
export const TELEGRAM_AVATAR_PREWARM_COOLDOWN_MS = 30 * 60 * 1000;

export async function prewarmAccountAvatarsOnce(
  connected: ConnectedTelegramUser,
  dialogs: any[],
  opts?: { maxDialogs?: number; delayMs?: number }
): Promise<{ warmed: number; skippedCached: number }> {
  const uid = String(connected?.userId || '').trim();
  if (!uid || !connected?.client) return { warmed: 0, skippedCached: 0 };
  const cacheAccountScope = `acc_tg_${uid}`;
  const maxDialogs = Math.max(1, Math.min(150, opts?.maxDialogs ?? 150));
  const stepDelayMs = opts?.delayMs ?? 80;

  const peerIds: string[] = [uid];
  const seen = new Set<string>([uid]);
  for (const d of (Array.isArray(dialogs) ? dialogs : []).slice(0, maxDialogs)) {
    const raw = String(d?.rawId || String(d?.id || '').replace(/^tg_/, '') || '').trim();
    if (!raw || seen.has(raw)) continue;
    seen.add(raw);
    peerIds.push(raw);
  }

  let warmed = 0;
  let skippedCached = 0;
  for (const cleanId of peerIds) {
    if (!connected.client?.connected) break;
    if (getTelegramFloodCooldown({ accountId: cacheAccountScope, userId: uid, phone: connected.phone })) {
      break;
    }
    const cacheKey = `${cacheAccountScope}:${cleanId}`;
    if (telegramAvatarCache.get(cacheKey, Date.now()) || (await readAvatarFromDiskCacheAsync(cacheKey))) {
      skippedCached += 1;
      continue;
    }
    if (getAvatarNegativeCacheEntry(cacheKey, Date.now())) {
      skippedCached += 1;
      continue;
    }
    const limiter = avatarAccountLimiters.get(cacheAccountScope);
    if (limiter && (limiter.active > 0 || limiter.waiters.length > 0)) {
      await new Promise((r) => setTimeout(r, 250));
    }
    const outcome = await fetchTelegramAvatarWithLimiting({
      cacheAccountScope,
      cleanId,
      candidates: [connected],
    });
    if (outcome.status === 429) break;
    if (outcome.status === 200) warmed += 1;
    if (stepDelayMs > 0) {
      await new Promise((r) => setTimeout(r, stepDelayMs));
    }
  }
  return { warmed, skippedCached };
}

export function scheduleAccountAvatarPrewarm(connected: ConnectedTelegramUser, dialogs: any[]): void {
  const uid = String(connected?.userId || '').trim();
  if (!uid || !connected?.client) return;
  const scope = `acc_tg_${uid}`;
  const now = Date.now();
  if (accountAvatarPrewarmRunning.has(scope)) return;
  const lastAt = accountAvatarPrewarmLastAt.get(scope) || 0;
  if (now - lastAt < TELEGRAM_AVATAR_PREWARM_COOLDOWN_MS) return;
  accountAvatarPrewarmLastAt.set(scope, now);
  accountAvatarPrewarmRunning.add(scope);
  void prewarmAccountAvatarsOnce(connected, dialogs)
    .catch(() => {})
    .finally(() => {
      accountAvatarPrewarmRunning.delete(scope);
    });
}

app.get('/api/telegram/user/avatar/:chatId', async (req: Request, res: Response) => {
  try {
    if (!isAllowedClientOrigin(req)) {
      return res.status(403).send('Forbidden');
    }
    if (!verifySignedTelegramResourceRequest(req) && !(req as any).auth) {
      return res.status(401).send('Unauthorized');
    }

    const { chatId } = req.params;
    const cleanId = chatId.replace(/^tg_/, '');
    const accountId = typeof req.query.accountId === 'string' ? req.query.accountId.trim() : '';

    const primaryConnected = accountId ? resolveConnectedTelegramUser(accountId) : undefined;
    const candidates: ConnectedTelegramUser[] = [];
    if (primaryConnected) {
      candidates.push(primaryConnected);
    } else if (!accountId) {
      const uniqueConnected = Array.from(
        new Map(Array.from(connectedUserClients.values()).map((u) => [u.userId, u])).values()
      );
      if (uniqueConnected.length > 1) {
        return res.status(400).send('accountId is required in multi-account mode');
      }
      if (uniqueConnected.length === 1) {
        candidates.push(uniqueConnected[0]);
      }
    }
    const cacheAccountScope = accountId || (candidates[0] ? `acc_tg_${candidates[0].userId}` : '');
    if (candidates.length === 0) {
      const fallbackScopes = accountId ? getScopedAccountIdVariants(accountId) : [];
      if (/^\d+$/.test(cleanId) && !fallbackScopes.includes(`acc_tg_${cleanId}`)) {
        fallbackScopes.push(`acc_tg_${cleanId}`);
      }
      for (const sc of fallbackScopes) {
        const k = `${sc}:${cleanId}`;
        const mem = telegramAvatarCache.get(k, Date.now());
        const hit = mem ? { buffer: mem.buffer, mime: mem.mime } : await readAvatarFromDiskCacheAsync(k);
        if (hit?.buffer) {
          res.setHeader('Content-Type', hit.mime || 'image/jpeg');
          res.setHeader('Cache-Control', 'private, max-age=604800');
          return res.send(hit.buffer);
        }
      }
      return res.status(404).send('Avatar not found');
    }

    const abortController = new AbortController();
    const onClose = () => {
      if (!res.writableEnded) {
        abortController.abort();
      }
    };
    req.on('close', onClose);
    res.once('close', onClose);

    try {
      const outcome = await fetchTelegramAvatarWithLimiting({
        cacheAccountScope,
        cleanId,
        candidates,
        signal: abortController.signal,
      });

      if (res.writableEnded) return;

      if (outcome.status === 200 && outcome.buffer) {
        res.setHeader('Content-Type', outcome.mime || 'image/jpeg');
        res.setHeader('Cache-Control', 'private, max-age=604800');
        return res.send(outcome.buffer);
      }
      if (outcome.status === 429) {
        res.setHeader('Retry-After', String(outcome.retryAfterSeconds || 30));
        res.setHeader('Cache-Control', 'no-store');
        return res.status(429).send('Rate limited');
      }
      if (outcome.status === 503) {
        res.setHeader('Retry-After', String(outcome.retryAfterSeconds || 5));
        res.setHeader('Cache-Control', 'no-store');
        return res.status(503).send('Avatar temporarily unavailable');
      }
      return res.status(404).send('Avatar not found');
    } finally {
      req.off('close', onClose);
      res.off('close', onClose);
    }
  } catch (err: any) {
    if (!res.writableEnded) {
      return res.status(503).send('Avatar temporarily unavailable');
    }
  }
});

// 20.1.2 Real Telegram Message Media Proxy Route (Photos, Videos, Voice/Audio, Stickers, Documents with Streaming HTTP Range)
export type ParsedHttpByteRange =
  | { kind: 'none' }
  | { kind: 'range'; start: number; end: number }
  | { kind: 'unsatisfiable' };

export function parseHttpByteRange(rangeHeader: string | undefined, totalSize: number): ParsedHttpByteRange {
  if (!rangeHeader || typeof rangeHeader !== 'string') return { kind: 'none' };
  const trimmed = rangeHeader.trim();
  if (!/^bytes=/i.test(trimmed)) return { kind: 'none' };
  const spec = trimmed.replace(/^bytes=/i, '').trim();
  if (!spec || spec.includes(',')) return { kind: 'none' };

  const match = /^(\d*)-(\d*)$/.exec(spec);
  if (!match) return { kind: 'unsatisfiable' };

  const [, startStr, endStr] = match;
  if (!startStr && !endStr) return { kind: 'unsatisfiable' };
  if (!Number.isFinite(totalSize) || totalSize <= 0) return { kind: 'unsatisfiable' };

  if (!startStr) {
    // Suffix byte range: bytes=-N (last N bytes)
    const suffixLen = Number(endStr);
    if (!Number.isFinite(suffixLen) || suffixLen <= 0) return { kind: 'unsatisfiable' };
    const start = Math.max(0, totalSize - suffixLen);
    return { kind: 'range', start, end: totalSize - 1 };
  }

  const start = Number(startStr);
  if (!Number.isFinite(start) || start < 0 || start >= totalSize) {
    return { kind: 'unsatisfiable' };
  }

  const end = endStr ? Math.min(Number(endStr), totalSize - 1) : totalSize - 1;
  if (!Number.isFinite(end) || end < start) {
    return { kind: 'unsatisfiable' };
  }

  return { kind: 'range', start, end };
}

function isScriptableActiveMediaMime(mime: string): boolean {
  const normalized = String(mime || '').toLowerCase().split(';')[0].trim();
  return (
    normalized === 'image/svg+xml' ||
    normalized === 'text/html' ||
    normalized === 'application/xhtml+xml' ||
    normalized === 'text/xml' ||
    normalized === 'application/xml' ||
    normalized === 'application/javascript' ||
    normalized === 'text/javascript'
  );
}

function applyMediaDownloadHeaders(res: Response, mime: string, fileName: string, forceDownload: boolean) {
  res.setHeader('Content-Type', mime);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Content-Security-Policy', "default-src 'none'; sandbox");
  res.setHeader('Accept-Ranges', 'bytes');
  res.setHeader('Cache-Control', 'private, max-age=1800');
  if (forceDownload || isScriptableActiveMediaMime(mime)) {
    const safeName = encodeURIComponent(fileName || 'telegram_file');
    res.setHeader('Content-Disposition', `attachment; filename*=UTF-8''${safeName}`);
  }
}

export function sendMediaBufferResponse(
  req: Request,
  res: Response,
  entry: { buffer: Buffer; mime: string; fileName: string },
  forceDownload: boolean
) {
  const { buffer, mime, fileName } = entry;
  const total = buffer.length;
  applyMediaDownloadHeaders(res, mime, fileName, forceDownload);

  const rangeResult = parseHttpByteRange(req.headers.range, total);
  if (rangeResult.kind === 'unsatisfiable') {
    res.status(416);
    res.setHeader('Content-Range', `bytes */${total}`);
    return res.end();
  }
  if (rangeResult.kind === 'range') {
    const { start, end } = rangeResult;
    res.status(206);
    res.setHeader('Content-Range', `bytes ${start}-${end}/${total}`);
    res.setHeader('Content-Length', String(end - start + 1));
    if (req.method === 'HEAD') return res.end();
    return res.send(buffer.subarray(start, end + 1));
  }

  res.setHeader('Content-Length', String(total));
  if (req.method === 'HEAD') return res.end();
  return res.send(buffer);
}

function extractPhotoSizeBytes(sizeObj: any): number {
  if (!sizeObj) return 0;
  if (typeof sizeObj.size === 'number' && sizeObj.size > 0) return sizeObj.size;
  if (Array.isArray(sizeObj.sizes) && sizeObj.sizes.length > 0) {
    const maxS = Math.max(...sizeObj.sizes.map((n: any) => Number(n) || 0));
    if (maxS > 0) return maxS;
  }
  if (sizeObj.bytes && typeof sizeObj.bytes.length === 'number') {
    return sizeObj.bytes.length;
  }
  return 0;
}

export function extractTelegramMediaMeta(msg: any, tgMsgId: number, wantThumb: boolean) {
  const media = msg?.media;
  const doc: any = media?.document || media?.webpage?.document || null;
  const photo: any = media?.photo || media?.webpage?.photo || null;
  const attrs: any[] = Array.isArray(doc?.attributes) ? doc.attributes : [];
  const filenameAttr = attrs.find((a) => a.className === 'DocumentAttributeFilename');
  const audioAttr = attrs.find((a) => a.className === 'DocumentAttributeAudio');
  const videoAttr = attrs.find((a) => a.className === 'DocumentAttributeVideo');
  const stickerAttr = attrs.find((a) => a.className === 'DocumentAttributeSticker');

  let bestThumb: any = null;
  if (wantThumb && doc && Array.isArray(doc.thumbs) && doc.thumbs.length > 0) {
    const validThumbs = doc.thumbs.filter(
      (t: any) => t && t.className !== 'PhotoPathSize' && t.className !== 'PhotoSizeEmpty'
    );
    bestThumb = validThumbs[validThumbs.length - 1] || null;
  } else if (wantThumb && photo && Array.isArray(photo.sizes) && photo.sizes.length > 0) {
    const validSizes = photo.sizes.filter(
      (s: any) => s && s.className !== 'PhotoPathSize' && s.className !== 'PhotoSizeEmpty'
    );
    bestThumb =
      validSizes.find((s: any) => String(s?.type || '').toLowerCase() === 'm') ||
      validSizes.find((s: any) => String(s?.type || '').toLowerCase() === 'x') ||
      validSizes[Math.min(1, Math.max(0, validSizes.length - 1))] ||
      validSizes[validSizes.length - 1] ||
      null;
  }

  let mime = bestThumb ? (doc ? 'image/webp' : 'image/jpeg') : String(doc?.mimeType || '').trim();
  let fileName = String(filenameAttr?.fileName || '').trim();

  if (!mime) {
    if (msg?.photo || media?.className === 'MessageMediaPhoto' || photo) {
      mime = 'image/jpeg';
    } else if (audioAttr) {
      mime = 'audio/ogg';
    } else if (videoAttr) {
      mime = 'video/mp4';
    } else if (stickerAttr) {
      mime = 'image/webp';
    } else {
      mime = 'application/octet-stream';
    }
  }

  if (!fileName) {
    if (mime === 'image/jpeg') fileName = `tg_photo_${tgMsgId}.jpg`;
    else if (mime === 'image/webp') fileName = `tg_sticker_${tgMsgId}.webp`;
    else if (mime.startsWith('video/')) fileName = `tg_video_${tgMsgId}.mp4`;
    else if (mime.startsWith('audio/')) fileName = `tg_audio_${tgMsgId}.ogg`;
    else fileName = `tg_file_${tgMsgId}`;
  }

  let knownSize = 0;
  if (bestThumb) {
    knownSize = extractPhotoSizeBytes(bestThumb);
  } else if (doc && doc.size !== undefined && doc.size !== null) {
    const parsedSize = typeof doc.size?.toJSNumber === 'function'
      ? doc.size.toJSNumber()
      : Number(doc.size?.toString?.() ?? doc.size);
    if (Number.isFinite(parsedSize) && parsedSize > 0) {
      knownSize = parsedSize;
    }
  } else if (photo && Array.isArray(photo.sizes)) {
    const sizes = [...photo.sizes, ...(Array.isArray(photo.videoSizes) ? photo.videoSizes : [])].filter(
      (s: any) => s && s.className !== 'PhotoPathSize' && s.className !== 'PhotoSizeEmpty'
    );
    if (sizes.length > 0) {
      knownSize = Math.max(...sizes.map(extractPhotoSizeBytes));
    }
  }

  return { doc, photo, bestThumb, mime, fileName, knownSize };
}

function waitForResponseDrainOrClose(res: Response): Promise<void> {
  if (res.destroyed || res.writableEnded) return Promise.resolve();
  return new Promise<void>((resolve) => {
    const done = () => {
      res.off('drain', done);
      res.off('close', done);
      res.off('error', done);
      resolve();
    };
    res.once('drain', done);
    res.once('close', done);
    res.once('error', done);
  });
}

export async function streamTelegramMediaViaIterDownload(params: {
  client: any;
  fileTarget: any;
  dcId?: number;
  msgData?: [any, number];
  totalSize: number;
  mime: string;
  fileName: string;
  forceDownload: boolean;
  req: Request;
  res: Response;
  thresholdBytes?: number;
  onSmallComplete?: (buffer: Buffer) => void;
}): Promise<'sent' | 'unsatisfiable' | 'empty'> {
  const {
    client,
    fileTarget,
    dcId,
    msgData,
    totalSize,
    mime,
    fileName,
    forceDownload,
    req,
    res,
    thresholdBytes = TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES,
    onSmallComplete,
  } = params;

  let clientAborted = Boolean(req.destroyed || res.destroyed);
  const onAbort = () => {
    clientAborted = true;
  };
  req.on('close', onAbort);
  res.on('close', onAbort);

  let iter: any = null;
  let headersCommitted = false;

  try {
    // Unknown-size fallback: buffer only up to thresholdBytes, then spill directly to streaming HTTP response
    if (totalSize <= 0) {
      const requestSize = TELEGRAM_MEDIA_STREAM_CHUNK_BYTES;
      iter = client.iterDownload({
        file: fileTarget,
        offset: returnBigInt(0),
        requestSize,
        chunkSize: requestSize,
        ...(dcId !== undefined ? { dcId } : {}),
        ...(msgData ? { msgData } : {}),
      });

      const smallChunks: Buffer[] = [];
      let bufferedBytes = 0;
      let spilledToStream = false;

      for await (const rawChunk of iter) {
        if (clientAborted || res.destroyed || res.writableEnded) break;
        const chunk = Buffer.isBuffer(rawChunk) ? rawChunk : Buffer.from(rawChunk);
        if (chunk.length === 0) continue;

        if (!spilledToStream) {
          if (bufferedBytes + chunk.length <= thresholdBytes) {
            smallChunks.push(chunk);
            bufferedBytes += chunk.length;
            continue;
          }
          // Threshold exceeded: flush accumulated chunks and stream remaining chunks without buffering
          spilledToStream = true;
          applyMediaDownloadHeaders(res, mime, fileName, forceDownload);
          res.setHeader('Accept-Ranges', 'none');
          res.status(200);
          headersCommitted = true;

          for (const prevChunk of smallChunks) {
            if (clientAborted || res.destroyed || res.writableEnded) break;
            const ok = res.write(prevChunk);
            if (!ok && !clientAborted && !res.destroyed) {
              await waitForResponseDrainOrClose(res);
            }
          }
          smallChunks.length = 0;
          bufferedBytes = 0;
        }

        if (clientAborted || res.destroyed || res.writableEnded) break;
        const ok = res.write(chunk);
        if (!ok && !clientAborted && !res.destroyed) {
          await waitForResponseDrainOrClose(res);
        }
      }

      if (clientAborted) return 'sent';

      if (!spilledToStream) {
        if (bufferedBytes === 0) return 'empty';
        const fullBuf = Buffer.concat(smallChunks, bufferedBytes);
        smallChunks.length = 0;
        if (onSmallComplete) onSmallComplete(fullBuf);
        sendMediaBufferResponse(req, res, { buffer: fullBuf, mime, fileName }, forceDownload);
        headersCommitted = true;
        return 'sent';
      }

      if (!res.writableEnded && !res.destroyed) {
        res.end();
      }
      return 'sent';
    }

    // Known-size path: true HTTP Range + offset-aligned GramJS iterDownload streaming
    const rangeResult = parseHttpByteRange(req.headers.range, totalSize);
    if (rangeResult.kind === 'unsatisfiable') {
      res.status(416);
      res.setHeader('Content-Range', `bytes */${totalSize}`);
      res.end();
      return 'unsatisfiable';
    }

    const isRange = rangeResult.kind === 'range';
    const start = isRange ? rangeResult.start : 0;
    const end = isRange ? rangeResult.end : totalSize - 1;
    const bytesToSend = end - start + 1;

    if (req.method === 'HEAD') {
      applyMediaDownloadHeaders(res, mime, fileName, forceDownload);
      if (isRange) {
        res.status(206);
        res.setHeader('Content-Range', `bytes ${start}-${end}/${totalSize}`);
      } else {
        res.status(200);
      }
      res.setHeader('Content-Length', String(bytesToSend));
      res.end();
      return 'sent';
    }

    // Pick power-of-2 MTProto chunk size (64KB for small probe ranges, 256KB for large streams)
    const requestSize = bytesToSend <= 64 * 1024 ? 64 * 1024 : TELEGRAM_MEDIA_STREAM_CHUNK_BYTES;
    const alignedOffset = Math.floor(start / requestSize) * requestSize;
    const skipFromFirstChunk = start - alignedOffset;
    const totalNeededFromAligned = end - alignedOffset + 1;
    const chunkLimit = Math.ceil(totalNeededFromAligned / requestSize);

    iter = client.iterDownload({
      file: fileTarget,
      offset: returnBigInt(alignedOffset),
      requestSize,
      chunkSize: requestSize,
      limit: chunkLimit,
      fileSize: returnBigInt(totalSize),
      ...(dcId !== undefined ? { dcId } : {}),
      ...(msgData ? { msgData } : {}),
    });

    let skip = skipFromFirstChunk;
    let remaining = bytesToSend;

    for await (const rawChunk of iter) {
      if (clientAborted || res.destroyed || res.writableEnded) break;
      const chunk = Buffer.isBuffer(rawChunk) ? rawChunk : Buffer.from(rawChunk);
      if (chunk.length === 0) continue;

      let sliceStart = 0;
      if (skip > 0) {
        if (skip >= chunk.length) {
          skip -= chunk.length;
          continue;
        }
        sliceStart = skip;
        skip = 0;
      }

      const available = chunk.length - sliceStart;
      const take = Math.min(available, remaining);
      if (take <= 0) break;

      const outSlice =
        sliceStart === 0 && take === chunk.length
          ? chunk
          : chunk.subarray(sliceStart, sliceStart + take);

      if (!headersCommitted) {
        applyMediaDownloadHeaders(res, mime, fileName, forceDownload);
        if (isRange) {
          res.status(206);
          res.setHeader('Content-Range', `bytes ${start}-${end}/${totalSize}`);
        } else {
          res.status(200);
        }
        res.setHeader('Content-Length', String(bytesToSend));
        headersCommitted = true;
      }

      const canContinue = res.write(outSlice);
      remaining -= outSlice.length;

      if (!canContinue && remaining > 0 && !clientAborted && !res.destroyed) {
        await waitForResponseDrainOrClose(res);
      }
      if (remaining <= 0) break;
    }

    if (!headersCommitted) {
      return clientAborted ? 'sent' : 'empty';
    }

    if (remaining > 0 && !res.destroyed) {
      // Upstream ended before declared Content-Length: destroy cleanly so client detects truncation
      res.destroy();
    } else if (!res.writableEnded && !res.destroyed) {
      res.end();
    }
    return 'sent';
  } catch (err) {
    if (headersCommitted) {
      if (!res.destroyed) res.destroy();
      return 'sent';
    }
    throw err;
  } finally {
    req.off('close', onAbort);
    res.off('close', onAbort);
    if (iter && typeof iter.close === 'function') {
      await iter.close().catch(() => {});
    }
  }
}

export const TELEGRAM_MEDIA_DISK_CACHE_DIR = path.resolve(dbDir, 'telegram_media_cache');
export const TELEGRAM_MEDIA_MAX_CONCURRENT_PER_ACCOUNT = 2;
try {
  fs.mkdirSync(TELEGRAM_MEDIA_DISK_CACHE_DIR, { recursive: true });
} catch {}

interface TelegramMediaInFlightResult {
  kind: 'entry' | 'flood' | 'not_found';
  entry?: { buffer: Buffer; mime: string; fileName: string; expiresAt: number };
  floodWaitEntry?: TelegramFloodCooldownEntry;
}

const telegramMediaInFlight = new Map<string, Promise<TelegramMediaInFlightResult>>();
const mediaAccountActiveDownloads = new Map<string, number>();

function getMediaAccountSlotScope(accountScope: string): string {
  return resolveTelegramAccountRuntimeKey({ accountId: accountScope }) || accountScope || 'global';
}

function acquireMediaDownloadSlot(accountScope: string): boolean {
  const key = getMediaAccountSlotScope(accountScope);
  const current = mediaAccountActiveDownloads.get(key) || 0;
  if (current >= TELEGRAM_MEDIA_MAX_CONCURRENT_PER_ACCOUNT) {
    return false;
  }
  mediaAccountActiveDownloads.set(key, current + 1);
  return true;
}

function releaseMediaDownloadSlot(accountScope: string): void {
  const key = getMediaAccountSlotScope(accountScope);
  const current = mediaAccountActiveDownloads.get(key) || 0;
  if (current <= 1) {
    mediaAccountActiveDownloads.delete(key);
  } else {
    mediaAccountActiveDownloads.set(key, current - 1);
  }
}

export function getTelegramMediaDiskCachePath(cacheKey: string): { binPath: string; metaPath: string } | null {
  const digest = crypto.createHash('sha256').update(cacheKey, 'utf8').digest('hex');
  const binPath = path.resolve(TELEGRAM_MEDIA_DISK_CACHE_DIR, `${digest}.bin`);
  const metaPath = path.resolve(TELEGRAM_MEDIA_DISK_CACHE_DIR, `${digest}.meta.json`);
  if (
    !binPath.startsWith(TELEGRAM_MEDIA_DISK_CACHE_DIR + path.sep) ||
    !metaPath.startsWith(TELEGRAM_MEDIA_DISK_CACHE_DIR + path.sep)
  ) {
    return null;
  }
  return { binPath, metaPath };
}

let mediaDiskCacheDirReady = false;
let mediaDiskPruneInFlight: Promise<{ totalBytes: number; evictedCount: number }> | null = null;
let lastMediaDiskPruneAt = 0;

export function readTelegramMediaFromDiskCache(
  cacheKey: string
): { buffer: Buffer; mime: string; fileName: string } | null {
  try {
    const paths = getTelegramMediaDiskCachePath(cacheKey);
    if (!paths || !fs.existsSync(paths.binPath) || !fs.existsSync(paths.metaPath)) return null;
    const stat = fs.statSync(paths.binPath);
    if (!stat.isFile() || stat.size <= 0) return null;
    const meta = safeJsonParse<{ mime?: string; fileName?: string } | null>(
      fs.readFileSync(paths.metaPath, 'utf8'),
      null
    );
    if (!meta || !meta.mime) return null;
    const buffer = fs.readFileSync(paths.binPath);
    if (!buffer || buffer.length <= 0) return null;
    const nowDate = new Date();
    try {
      fs.utimesSync(paths.binPath, nowDate, nowDate);
      fs.utimesSync(paths.metaPath, nowDate, nowDate);
    } catch {}
    return {
      buffer,
      mime: String(meta.mime),
      fileName: String(meta.fileName || 'telegram_media'),
    };
  } catch {
    return null;
  }
}

export async function readTelegramMediaFromDiskCacheAsync(
  cacheKey: string
): Promise<{ buffer: Buffer; mime: string; fileName: string } | null> {
  try {
    const paths = getTelegramMediaDiskCachePath(cacheKey);
    if (!paths) return null;
    const [stat, metaRaw] = await Promise.all([
      fs.promises.stat(paths.binPath),
      fs.promises.readFile(paths.metaPath, 'utf8'),
    ]);
    if (!stat.isFile() || stat.size <= 0) return null;
    const meta = safeJsonParse<{ mime?: string; fileName?: string } | null>(metaRaw, null);
    if (!meta || !meta.mime) return null;
    const buffer = await fs.promises.readFile(paths.binPath);
    if (!buffer || buffer.length <= 0) return null;
    const nowDate = new Date();
    void Promise.all([
      fs.promises.utimes(paths.binPath, nowDate, nowDate).catch(() => {}),
      fs.promises.utimes(paths.metaPath, nowDate, nowDate).catch(() => {}),
    ]);
    return {
      buffer,
      mime: String(meta.mime),
      fileName: String(meta.fileName || 'telegram_media'),
    };
  } catch {
    return null;
  }
}

export function enforceTelegramMediaDiskCacheLimit(
  maxBytes = outboundRuntimeConfig.mediaDiskCacheMaxBytes
): { totalBytes: number; evictedCount: number } {
  let totalBytes = 0;
  let evictedCount = 0;
  try {
    if (!fs.existsSync(TELEGRAM_MEDIA_DISK_CACHE_DIR)) {
      return { totalBytes: 0, evictedCount: 0 };
    }
    const entries: Array<{ digest: string; binPath: string; metaPath: string; size: number; mtimeMs: number }> = [];
    for (const name of fs.readdirSync(TELEGRAM_MEDIA_DISK_CACHE_DIR)) {
      if (!name.endsWith('.bin')) continue;
      const digest = name.slice(0, -4);
      const binPath = path.join(TELEGRAM_MEDIA_DISK_CACHE_DIR, name);
      const metaPath = path.join(TELEGRAM_MEDIA_DISK_CACHE_DIR, `${digest}.meta.json`);
      try {
        const st = fs.statSync(binPath);
        if (!st.isFile()) continue;
        totalBytes += st.size;
        entries.push({ digest, binPath, metaPath, size: st.size, mtimeMs: st.mtimeMs });
      } catch {}
    }
    if (totalBytes <= maxBytes) {
      return { totalBytes, evictedCount };
    }
    entries.sort((a, b) => a.mtimeMs - b.mtimeMs);
    for (const item of entries) {
      if (totalBytes <= maxBytes) break;
      try {
        if (fs.existsSync(item.binPath)) fs.unlinkSync(item.binPath);
      } catch {}
      try {
        if (fs.existsSync(item.metaPath)) fs.unlinkSync(item.metaPath);
      } catch {}
      totalBytes = Math.max(0, totalBytes - item.size);
      evictedCount += 1;
    }
  } catch {}
  return { totalBytes, evictedCount };
}

export async function enforceTelegramMediaDiskCacheLimitAsync(
  maxBytes = outboundRuntimeConfig.mediaDiskCacheMaxBytes,
  force = false
): Promise<{ totalBytes: number; evictedCount: number }> {
  const now = Date.now();
  if (!force && mediaDiskPruneInFlight) {
    return await mediaDiskPruneInFlight;
  }
  if (!force && now - lastMediaDiskPruneAt < 10_000) {
    return { totalBytes: 0, evictedCount: 0 };
  }
  const run = (async () => {
    let totalBytes = 0;
    let evictedCount = 0;
    try {
      const names = await fs.promises.readdir(TELEGRAM_MEDIA_DISK_CACHE_DIR).catch(() => null);
      if (!names) {
        return { totalBytes: 0, evictedCount: 0 };
      }
      const entries: Array<{ digest: string; binPath: string; metaPath: string; size: number; mtimeMs: number }> = [];
      for (const name of names) {
        if (!name.endsWith('.bin')) continue;
        const digest = name.slice(0, -4);
        const binPath = path.join(TELEGRAM_MEDIA_DISK_CACHE_DIR, name);
        const metaPath = path.join(TELEGRAM_MEDIA_DISK_CACHE_DIR, `${digest}.meta.json`);
        try {
          const st = await fs.promises.stat(binPath);
          if (!st.isFile()) continue;
          totalBytes += st.size;
          entries.push({ digest, binPath, metaPath, size: st.size, mtimeMs: st.mtimeMs });
        } catch {}
      }
      lastMediaDiskPruneAt = Date.now();
      if (totalBytes <= maxBytes) {
        return { totalBytes, evictedCount };
      }
      entries.sort((a, b) => a.mtimeMs - b.mtimeMs);
      for (const item of entries) {
        if (totalBytes <= maxBytes) break;
        await Promise.all([
          fs.promises.unlink(item.binPath).catch(() => {}),
          fs.promises.unlink(item.metaPath).catch(() => {}),
        ]);
        totalBytes = Math.max(0, totalBytes - item.size);
        evictedCount += 1;
      }
    } catch {}
    return { totalBytes, evictedCount };
  })();
  mediaDiskPruneInFlight = run;
  try {
    return await run;
  } finally {
    if (mediaDiskPruneInFlight === run) {
      mediaDiskPruneInFlight = null;
    }
  }
}

export function writeTelegramMediaToDiskCache(
  cacheKey: string,
  entry: { buffer: Buffer; mime: string; fileName: string }
): boolean {
  try {
    if (!entry?.buffer || entry.buffer.length <= 0 || entry.buffer.length > TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES) {
      return false;
    }
    const paths = getTelegramMediaDiskCachePath(cacheKey);
    if (!paths) return false;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      const tmpBin = `${paths.binPath}.${process.pid}.${Date.now()}.tmp`;
      const tmpMeta = `${paths.metaPath}.${process.pid}.${Date.now()}.tmp`;
      try {
        if (!mediaDiskCacheDirReady) {
          fs.mkdirSync(TELEGRAM_MEDIA_DISK_CACHE_DIR, { recursive: true });
          mediaDiskCacheDirReady = true;
        }
        fs.writeFileSync(tmpBin, entry.buffer);
        fs.writeFileSync(tmpMeta, JSON.stringify({ mime: entry.mime, fileName: entry.fileName }), 'utf8');
        fs.renameSync(tmpBin, paths.binPath);
        fs.renameSync(tmpMeta, paths.metaPath);
        enforceTelegramMediaDiskCacheLimit(outboundRuntimeConfig.mediaDiskCacheMaxBytes);
        return true;
      } catch (err: any) {
        try { fs.unlinkSync(tmpBin); } catch {}
        try { fs.unlinkSync(tmpMeta); } catch {}
        if (err?.code === 'ENOENT' && attempt === 0) {
          mediaDiskCacheDirReady = false;
          continue;
        }
        throw err;
      }
    }
    return false;
  } catch {
    return false;
  }
}

export async function writeTelegramMediaToDiskCacheAsync(
  cacheKey: string,
  entry: { buffer: Buffer; mime: string; fileName: string }
): Promise<boolean> {
  let tmpBin = '';
  let tmpMeta = '';
  try {
    if (!entry?.buffer || entry.buffer.length <= 0 || entry.buffer.length > TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES) {
      return false;
    }
    const paths = getTelegramMediaDiskCachePath(cacheKey);
    if (!paths) return false;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        if (!mediaDiskCacheDirReady) {
          await fs.promises.mkdir(TELEGRAM_MEDIA_DISK_CACHE_DIR, { recursive: true });
          mediaDiskCacheDirReady = true;
        }
        const nonce = `${process.pid}.${Date.now()}.${Math.random().toString(36).slice(2, 7)}`;
        tmpBin = `${paths.binPath}.${nonce}.tmp`;
        tmpMeta = `${paths.metaPath}.${nonce}.tmp`;
        await Promise.all([
          fs.promises.writeFile(tmpBin, entry.buffer),
          fs.promises.writeFile(tmpMeta, JSON.stringify({ mime: entry.mime, fileName: entry.fileName }), 'utf8'),
        ]);
        await Promise.all([
          fs.promises.rename(tmpBin, paths.binPath),
          fs.promises.rename(tmpMeta, paths.metaPath),
        ]);
        tmpBin = '';
        tmpMeta = '';
        void enforceTelegramMediaDiskCacheLimitAsync(outboundRuntimeConfig.mediaDiskCacheMaxBytes);
        return true;
      } catch (err: any) {
        if (tmpBin) { await fs.promises.unlink(tmpBin).catch(() => {}); tmpBin = ''; }
        if (tmpMeta) { await fs.promises.unlink(tmpMeta).catch(() => {}); tmpMeta = ''; }
        if (err?.code === 'ENOENT' && attempt === 0) {
          mediaDiskCacheDirReady = false;
          continue;
        }
        throw err;
      }
    }
    return false;
  } catch {
    if (tmpBin) await fs.promises.unlink(tmpBin).catch(() => {});
    if (tmpMeta) await fs.promises.unlink(tmpMeta).catch(() => {});
    return false;
  }
}

export function clearTelegramMediaCachesForTesting(): void {
  telegramMediaCache.clear();
  telegramMediaInFlight.clear();
  mediaAccountActiveDownloads.clear();
  lastMediaDiskPruneAt = 0;
  mediaDiskPruneInFlight = null;
  if (process.env.NODE_ENV === 'test') {
    try {
      for (const name of fs.readdirSync(TELEGRAM_MEDIA_DISK_CACHE_DIR)) {
        if (name.endsWith('.bin') || name.endsWith('.meta.json') || name.endsWith('.tmp')) {
          fs.unlinkSync(path.join(TELEGRAM_MEDIA_DISK_CACHE_DIR, name));
        }
      }
    } catch {}
  }
}

app.get('/api/telegram/user/media/:chatId/:msgId', async (req: Request, res: Response) => {
  try {
    if (!isAllowedClientOrigin(req)) {
      return res.status(403).send('Forbidden');
    }
    if (!verifySignedTelegramResourceRequest(req) && !(req as any).auth) {
      return res.status(401).send('Unauthorized');
    }

    const { chatId, msgId } = req.params;
    const tgMsgId = Number(msgId);
    if (!Number.isInteger(tgMsgId) || tgMsgId <= 0) {
      return res.status(400).send('Invalid message ID');
    }

    const accountId = typeof req.query.accountId === 'string' ? req.query.accountId.trim() : '';
    const forceDownload = req.query.download === '1' || req.query.download === 'true';
    const wantThumb = req.query.thumb === '1' || req.query.thumb === 'true';
    const cleanChatId = String(chatId || '').replace(/^tg_/, '');

    const primaryConnected = accountId ? resolveConnectedTelegramUser(accountId) : undefined;
    const candidates: ConnectedTelegramUser[] = [];
    if (primaryConnected) {
      candidates.push(primaryConnected);
    } else if (!accountId) {
      const uniqueConnected = Array.from(
        new Map(Array.from(connectedUserClients.values()).map((u) => [u.userId, u])).values()
      );
      if (uniqueConnected.length > 1) {
        return res.status(400).send('accountId is required in multi-account mode');
      }
      if (uniqueConnected.length === 1) {
        candidates.push(uniqueConnected[0]);
      }
    }

    if (candidates.length === 0) {
      return res.status(404).send('No active Telegram client connected');
    }

    const cacheAccountScope = accountId || `acc_tg_${candidates[0].userId}`;
    const cacheKey = `${cacheAccountScope}:${cleanChatId}:${tgMsgId}${wantThumb ? ':thumb' : ''}`;
    const now = Date.now();

    const cached = telegramMediaCache.get(cacheKey, now);
    if (cached) {
      return sendMediaBufferResponse(req, res, cached, forceDownload);
    }

    const diskCached = await readTelegramMediaFromDiskCacheAsync(cacheKey);
    if (diskCached) {
      telegramMediaCache.set(
        cacheKey,
        { ...diskCached, expiresAt: Date.now() + TELEGRAM_MEDIA_CACHE_TTL_MS },
        Date.now()
      );
      return sendMediaBufferResponse(req, res, diskCached, forceDownload);
    }

    // Single-flight deduplication for concurrent requests of the exact same media key
    const existingInFlight = telegramMediaInFlight.get(cacheKey);
    if (existingInFlight) {
      const sharedOutcome = await existingInFlight;
      if (sharedOutcome.kind === 'entry' && sharedOutcome.entry) {
        return sendMediaBufferResponse(req, res, sharedOutcome.entry, forceDownload);
      }
      if (sharedOutcome.kind === 'flood' && sharedOutcome.floodWaitEntry) {
        res.setHeader('Retry-After', String(sharedOutcome.floodWaitEntry.retryAfterSeconds));
        return res.status(429).json({
          ok: false,
          code: 'TELEGRAM_FLOOD_WAIT',
          retryAfterSeconds: sharedOutcome.floodWaitEntry.retryAfterSeconds,
          floodWaitUntil: sharedOutcome.floodWaitEntry.floodWaitUntil,
          error: formatTelegramError({ errorMessage: `FLOOD_WAIT_${sharedOutcome.floodWaitEntry.retryAfterSeconds}` }),
        });
      }
      return res.status(404).send('Media not found');
    }

    if (!acquireMediaDownloadSlot(cacheAccountScope)) {
      res.setHeader('Retry-After', '2');
      return res.status(503).json({
        ok: false,
        code: 'MEDIA_DOWNLOAD_BUSY',
        retryAfterSeconds: 2,
        error: '媒体下载通道繁忙，请稍后重试',
      });
    }

    let slotReleased = false;
    const safeReleaseSlot = () => {
      if (!slotReleased) {
        slotReleased = true;
        releaseMediaDownloadSlot(cacheAccountScope);
      }
    };

    try {
      let floodWaitEntry: TelegramFloodCooldownEntry | null = null;
      for (const candidate of candidates) {
        if (!candidate.client) continue;
        const candCooldown = getTelegramFloodCooldown({
          accountId: cacheAccountScope,
          userId: candidate.userId,
          phone: candidate.phone,
        });
        if (candCooldown) {
          floodWaitEntry = {
            accountKey: cacheAccountScope,
            retryAfterSeconds: candCooldown.retryAfterSeconds,
            floodWaitUntil: candCooldown.floodWaitUntil,
            recordedAt: Date.now(),
          };
          continue;
        }
        try {
          const { inputPeer } = await resolveTelegramInputPeer(candidate.client, chatId, candidate.userId, 'P2');
          const msgs = await scheduleTelegramRpc(cacheAccountScope, 'P2', 'media.getMessages', () =>
            candidate.client.getMessages(inputPeer, { ids: [tgMsgId] })
          );
          const msg: any = msgs?.[0];
          if (!msg || !msg.media) continue;

          const { doc, bestThumb, mime, fileName, knownSize } = extractTelegramMediaMeta(msg, tgMsgId, wantThumb);

          // Large files (> threshold) or unknown-size documents stream via iterDownload with true HTTP Range (never buffer whole file in RAM)
          const shouldStreamMedia =
            !wantThumb &&
            ((Boolean(doc) && (knownSize > TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES || knownSize === 0)) ||
              knownSize > TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES);

          if (shouldStreamMedia) {
            const streamStatus = await streamTelegramMediaViaIterDownload({
              client: candidate.client,
              fileTarget: doc || msg.media,
              dcId: doc?.dcId ?? msg.media?.photo?.dcId,
              msgData: [inputPeer, tgMsgId],
              totalSize: knownSize,
              mime,
              fileName,
              forceDownload,
              req,
              res,
              thresholdBytes: TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES,
              onSmallComplete: (fullBuf) => {
                const entry = {
                  buffer: fullBuf,
                  mime,
                  fileName,
                  expiresAt: Date.now() + TELEGRAM_MEDIA_CACHE_TTL_MS,
                };
                telegramMediaCache.set(cacheKey, entry, Date.now());
                void writeTelegramMediaToDiskCacheAsync(cacheKey, entry);
              },
            });
            if (streamStatus === 'sent' || streamStatus === 'unsatisfiable') {
              return;
            }
            continue;
          }

          const docByteSize = doc?.size != null
            ? Number(typeof doc.size?.toJSNumber === 'function' ? doc.size.toJSNumber() : doc.size)
            : 0;
          if (wantThumb && doc && !bestThumb && docByteSize > TELEGRAM_MEDIA_STREAM_THRESHOLD_BYTES) {
            continue;
          }

          // Small files (<= threshold), photos, and native PhotoSize/doc thumbnails: single-flight download + P2 scheduling + disk cache
          const downloadPromise = (async (): Promise<TelegramMediaInFlightResult> => {
            try {
              let downloaded: Buffer | undefined;
              if (wantThumb && bestThumb) {
                downloaded = (await scheduleTelegramRpc(cacheAccountScope, 'P2', 'downloadMedia.thumb', () =>
                  candidate.client.downloadMedia(doc || msg.media, { thumb: bestThumb })
                )) as Buffer;
              }
              if (!downloaded || !Buffer.isBuffer(downloaded) || downloaded.length === 0) {
                downloaded = (await scheduleTelegramRpc(cacheAccountScope, 'P2', 'downloadMedia.full', () =>
                  candidate.client.downloadMedia(msg.media, {})
                )) as Buffer;
              }
              if (!downloaded || !Buffer.isBuffer(downloaded) || downloaded.length === 0) {
                return { kind: 'not_found' };
              }
              const entry = {
                buffer: downloaded,
                mime,
                fileName,
                expiresAt: Date.now() + TELEGRAM_MEDIA_CACHE_TTL_MS,
              };
              telegramMediaCache.set(cacheKey, entry, Date.now());
              void writeTelegramMediaToDiskCacheAsync(cacheKey, entry);
              return { kind: 'entry', entry };
            } catch (dlErr: any) {
              const recorded = recordTelegramFloodWait(
                { accountId: cacheAccountScope, userId: candidate.userId, phone: candidate.phone },
                dlErr,
                'downloadMedia'
              );
              if (recorded) {
                return { kind: 'flood', floodWaitEntry: recorded };
              }
              throw dlErr;
            }
          })();

          telegramMediaInFlight.set(cacheKey, downloadPromise);
          const outcome = await downloadPromise.finally(() => {
            if (telegramMediaInFlight.get(cacheKey) === downloadPromise) {
              telegramMediaInFlight.delete(cacheKey);
            }
          });

          if (outcome.kind === 'entry' && outcome.entry) {
            return sendMediaBufferResponse(req, res, outcome.entry, forceDownload);
          }
          if (outcome.kind === 'flood' && outcome.floodWaitEntry) {
            floodWaitEntry = outcome.floodWaitEntry;
            continue;
          }
          continue;
        } catch (mediaErr: any) {
          const recorded = recordTelegramFloodWait(
            { accountId: cacheAccountScope, userId: candidate.userId, phone: candidate.phone },
            mediaErr,
            'downloadMedia'
          );
          if (recorded) {
            floodWaitEntry = recorded;
          }
          if (res.headersSent) {
            if (!res.destroyed) res.destroy();
            return;
          }
          // Try next candidate client if peer doesn't belong to this session
        }
      }

      if (!res.headersSent) {
        if (floodWaitEntry) {
          res.setHeader('Retry-After', String(floodWaitEntry.retryAfterSeconds));
          return res.status(429).json({
            ok: false,
            code: 'TELEGRAM_FLOOD_WAIT',
            retryAfterSeconds: floodWaitEntry.retryAfterSeconds,
            floodWaitUntil: floodWaitEntry.floodWaitUntil,
            error: formatTelegramError({ errorMessage: `FLOOD_WAIT_${floodWaitEntry.retryAfterSeconds}` }),
          });
        }
        return res.status(404).send('Media not found');
      }
    } finally {
      safeReleaseSlot();
    }
  } catch {
    if (!res.headersSent) {
      return res.status(404).send('Media not found');
    } else if (!res.destroyed) {
      res.destroy();
    }
  }
});

// 20.2 List all active connected in-memory user accounts
app.get('/api/telegram/user/active-accounts', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const lockedAccountId = String(authContext?.effectiveAccountId || authContext?.session?.accountId || '').trim();
    const scopedVariants = !isMaster && lockedAccountId ? getScopedAccountIdVariants(lockedAccountId) : [];
    const matchesLockedScope = (item: { accountId?: string; id?: string; userId?: string; phone?: string }) => {
      if (isMaster) return true;
      if (!lockedAccountId) return false;
      const candidates = [
        item.accountId,
        item.id,
        item.userId,
        item.userId ? `acc_tg_${item.userId}` : undefined,
        item.phone,
      ]
        .map((v) => String(v || '').trim())
        .filter(Boolean);
      return candidates.some((c) => c === lockedAccountId || scopedVariants.includes(c));
    };

    const unique = new Map<string, any>();
    for (const u of connectedUserClients.values()) {
      const uid = u.userId ? String(u.userId).trim() : '';
      const normPhone = u.phone ? normalizePhoneNumber(u.phone) || u.phone : '';
      const canonicalId = uid ? `acc_tg_${uid}` : normPhone;
      const dedupKey = uid || normPhone;
      if (!dedupKey || unique.has(dedupKey)) continue;
      if (!matchesLockedScope({ id: canonicalId, userId: uid, phone: u.phone })) continue;
      const runtime = telegramAccountRuntimeStates.get(
        resolveTelegramAccountRuntimeKey({ userId: uid || undefined, phone: normPhone || undefined })
      );
      const snap = getTelegramAccountConnectionSnapshot(u, runtime);
      unique.set(dedupKey, {
        id: canonicalId,
        userId: uid,
        name: `${u.firstName || ''} ${u.lastName || ''}`.trim() || 'Telegram 账号',
        username: u.username || (uid ? `@user_${uid.slice(-4)}` : normPhone),
        phone: u.phone,
        avatarBg: u.avatarBg,
        avatarInitial: u.avatarInitial,
        avatarUrl: uid
          ? signTelegramResourceUrl(`/api/telegram/user/avatar/${uid}`, `acc_tg_${uid}`)
          : undefined,
        connectedAt: u.connectedAt,
        dialogsCount: u.dialogs.length,
        isConnected: snap.isConnected,
        status: snap.status,
      });
    }
    res.json({
      ok: true,
      accounts: Array.from(unique.values()),
      expiredAccounts: Array.from(recentlyExpiredAccounts.values()).filter(matchesLockedScope),
    });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// 20.2.1 Persistent Account Meta (Remark & Group Assignment) & Account Groups
app.get('/api/telegram/user/accounts/meta', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const authContext = (req as any).auth;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const lockedAccountId = String(authContext?.effectiveAccountId || authContext?.session?.accountId || '').trim();
    const allowedSet = !isMaster && lockedAccountId ? new Set(getScopedAccountIdVariants(lockedAccountId)) : null;
    const metaRows = (await db
      .prepare(`SELECT account_id, remark, group_id, updated_at FROM telegram_account_meta`)
      .all()) as any[];
    const groupRows = (await db
      .prepare(`SELECT id, name, color, collapsed, sort_order FROM telegram_account_groups ORDER BY sort_order ASC, updated_at ASC`)
      .all()) as any[];
    const meta: Record<string, { remark?: string; groupId?: string; updatedAt?: number }> = {};
    for (const r of metaRows || []) {
      const aid = String(r.account_id || '').trim();
      if (!aid || (allowedSet && !allowedSet.has(aid))) continue;
      meta[aid] = {
        ...(typeof r.remark === 'string' && r.remark.trim() ? { remark: r.remark.trim() } : {}),
        ...(typeof r.group_id === 'string' && r.group_id.trim() ? { groupId: r.group_id.trim() } : {}),
        updatedAt: Number(r.updated_at || 0),
      };
    }
    const groups = (groupRows || []).map((g) => ({
      id: String(g.id),
      name: String(g.name),
      ...(g.color ? { color: String(g.color) } : {}),
      collapsed: Boolean(g.collapsed),
    }));
    return res.json({ ok: true, meta, groups });
  } catch (err: any) {
    return res.status(500).json({ ok: false, error: err?.message || '读取账号备注与分组失败' });
  }
});

app.put('/api/telegram/user/accounts/meta', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const now = Date.now();
    const authContext = (req as any).auth;
    const isMaster = Boolean(authContext?.session?.isMaster);
    const { accountId: rawAccountId, remark, groupId, groups } = req.body || {};
    if (Array.isArray(groups) && !isMaster) {
      return res.status(403).json({ ok: false, error: '仅主控管理员可修改账号分组配置' });
    }
    let targetId = '';
    if (typeof rawAccountId === 'string' && rawAccountId.trim()) {
      const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
      if (!scope.ok) {
        return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
      }
      targetId = scope.accountId || rawAccountId.trim();
    }
    const runTx = db.transaction(async () => {
      if (targetId) {
        const nextRemark = remark === undefined ? undefined : (typeof remark === 'string' ? remark.trim() || null : null);
        const nextGroupId = groupId === undefined ? undefined : (typeof groupId === 'string' ? groupId.trim() || null : null);
        await db
          .prepare(`
            INSERT INTO telegram_account_meta (account_id, remark, group_id, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(account_id) DO UPDATE SET
              remark = COALESCE(?, telegram_account_meta.remark),
              group_id = COALESCE(?, telegram_account_meta.group_id),
              updated_at = excluded.updated_at
          `)
          .run(
            targetId,
            nextRemark !== undefined ? nextRemark : null,
            nextGroupId !== undefined ? nextGroupId : null,
            now,
            nextRemark !== undefined ? nextRemark : null,
            nextGroupId !== undefined ? nextGroupId : null
          );
        if (remark === '' || remark === null) {
          await db.prepare(`UPDATE telegram_account_meta SET remark = NULL, updated_at = ? WHERE account_id = ?`).run(now, targetId);
        }
        if (groupId === '' || groupId === null) {
          await db.prepare(`UPDATE telegram_account_meta SET group_id = NULL, updated_at = ? WHERE account_id = ?`).run(now, targetId);
        }
      }
      if (Array.isArray(groups)) {
        await db.prepare(`DELETE FROM telegram_account_groups`).run();
        for (let i = 0; i < groups.length; i++) {
          const g = groups[i];
          if (!g?.id || !g?.name) continue;
          await db
            .prepare(`
              INSERT INTO telegram_account_groups (id, name, color, collapsed, sort_order, updated_at)
              VALUES (?, ?, ?, ?, ?, ?)
            `)
            .run(String(g.id), String(g.name).trim().slice(0, 24), g.color ? String(g.color) : null, g.collapsed ? 1 : 0, i, now);
        }
      }
    });
    await runTx();
    return res.json({ ok: true });
  } catch (err: any) {
    return res.status(500).json({ ok: false, error: err?.message || '保存账号备注与分组失败' });
  }
});

// 20.3 Disconnect / Logout Telegram User Account
app.post('/api/telegram/user/disconnect', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    const { forceLocalOnly } = req.body || {};
    const targetClient = resolveConnectedTelegramUser(accountId, phone, userId);
    const p = phone || targetClient?.phone;
    const normPhone = p ? normalizePhoneNumber(p) : '';
    const uid = userId || targetClient?.userId || (accountId?.startsWith('acc_tg_') ? String(accountId).replace(/^acc_tg_/, '') : '');

    let cloudLoggedOut = false;

    if (targetClient && targetClient.client) {
      console.log(`[Telegram User Auth] Invoking native auth.LogOut on Telegram Cloud for user ${targetClient.userId} (@${targetClient.username})...`);
      try {
        await withTelegramTimeout(
          targetClient.client.invoke(new Api.auth.LogOut()),
          10000,
          'Telegram 云端注销超时'
        );
        cloudLoggedOut = true;
        console.log(`[Telegram User Auth] Native auth.LogOut confirmed by Telegram Cloud for user ${targetClient.userId}`);
      } catch (logoutErr: any) {
        if (isTelegramSessionExpiredError(logoutErr)) {
          cloudLoggedOut = true;
        } else {
          console.warn(`[Telegram User Auth] Native auth.LogOut failed:`, logoutErr?.message || logoutErr);
          if (!forceLocalOnly) {
            return res.status(502).json({
              ok: false,
              cloudLoggedOut: false,
              canForceLocal: true,
              error: `云端注销失败（${formatTelegramError(logoutErr)}），请检查网络后重试或确认仅清除本地记录`,
            });
          }
        }
      }
      await destroyTelegramClientSafely(targetClient.client);
      connectedUserClients.delete(targetClient.userId);
      connectedUserClients.delete(targetClient.phone);
      connectedUserClients.delete(normalizePhoneNumber(targetClient.phone));
      connectedUserClients.delete(`acc_tg_${targetClient.userId}`);
      telegramAvatarCache.deleteByPrefix(`acc_tg_${targetClient.userId}:`);
      telegramMediaCache.deleteByPrefix(`acc_tg_${targetClient.userId}:`);
    } else if (p || uid) {
      // Account not in RAM — check if DB still holds an active encrypted session and revoke it on Telegram Cloud
      try {
        const storedRow = (await db
          .prepare('SELECT phone, session_string, user_id FROM telegram_user_sessions WHERE (phone = ? OR phone = ? OR user_id = ?) AND is_active = 1 LIMIT 1')
          .get(p || '', normPhone || '', uid || '')) as any;

        if (storedRow?.session_string) {
          const decrypted = decryptSensitiveData(storedRow.session_string);
          const creds = await resolveTelegramApiCredentials({ bearerToken: extractBearerToken(req) });
          if (decrypted && creds.ok && creds.apiId && creds.apiHash) {
            const effectiveTransport = await resolveEffectiveTelegramTransport();
            const tempClient = new TelegramClient(new StringSession(decrypted), creds.apiId, creds.apiHash, {
              connectionRetries: 2,
              reconnectRetries: 0,
              useWSS: false,
              connection: ConnectionTCPObfuscated443,
              autoReconnect: false,
              ...TELEGRAM_DESKTOP_CLIENT_PARAMS,
              ...(effectiveTransport.mode === 'socks'
                ? { proxy: effectiveTransport.proxy }
                : effectiveTransport.mode === 'http'
                  ? { networkSocket: createHttpConnectNetworkSocketClass(effectiveTransport.httpProxy) as any }
                  : {}),
            });
            configureTelegramClientErrorGuard(tempClient, `logout_${storedRow.phone || uid}`);
            try {
              await withTelegramTimeout(tempClient.connect(), 10000, '连接 Telegram 云端注销超时');
              await withTelegramTimeout(tempClient.invoke(new Api.auth.LogOut()), 10000, 'Telegram 云端注销超时');
              cloudLoggedOut = true;
            } catch (tempErr: any) {
              if (isTelegramSessionExpiredError(tempErr)) {
                cloudLoggedOut = true;
              } else if (!forceLocalOnly) {
                await destroyTelegramClientSafely(tempClient);
                return res.status(502).json({
                  ok: false,
                  cloudLoggedOut: false,
                  canForceLocal: true,
                  error: `离线会话云端注销失败（${formatTelegramError(tempErr)}），请检查网络后重试或确认仅清除本地记录`,
                });
              }
            } finally {
              await destroyTelegramClientSafely(tempClient);
            }
          }
        }
      } catch {}
    }

    clearExpiredAccountRecord(uid, p);

    if (p || uid) {
      try {
        await db.prepare('DELETE FROM telegram_user_sessions WHERE phone = ? OR phone = ? OR user_id = ?').run(p || '', normPhone || '', uid || '');
      } catch {}
    }

    // Purge any queued real-time updates belonging to the logged-out account
    const targetAccountIds = new Set<string>(
      [accountId, uid, uid ? `acc_tg_${uid}` : '', p, normPhone].filter(Boolean) as string[]
    );
    if (targetAccountIds.size > 0 && pendingLocalUpdates.length > 0) {
      for (let i = pendingLocalUpdates.length - 1; i >= 0; i--) {
        if (targetAccountIds.has(pendingLocalUpdates[i].accountId)) {
          pendingLocalUpdates.splice(i, 1);
        }
      }
      deletePendingLocalUpdatesByAccountsInDb(Array.from(targetAccountIds));
    }

    res.json({
      ok: true,
      cloudLoggedOut,
      message: cloudLoggedOut
        ? 'Telegram 账号已在云端安全注销 (auth.LogOut) 并彻底清除本地会话'
        : '已断开连接并彻底清除本地 Telegram 会话记录',
    });
  } catch (err: any) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// 20.3.1 Update Telegram User Profile & Username via MTProto (account.UpdateProfile / account.UpdateUsername)
app.post('/api/telegram/user/update-profile', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, cloudSynced: false, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const { name, username, bio } = req.body || {};

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);

    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        cloudSynced: false,
        error: '当前账号未在线连接 Telegram MTProto，无法同步云端个人资料，请先连接登录该账号。',
      });
    }

    const cleanName = typeof name === 'string' ? name.trim() : '';
    const nameParts = cleanName ? cleanName.split(/\s+/) : [];
    const firstName = nameParts[0] || connected.firstName || 'Telegram';
    const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : cleanName ? '' : (connected.lastName || '');
    const cleanBio = typeof bio === 'string' ? bio.trim() : undefined;

    await connected.client.invoke(
      new Api.account.UpdateProfile({
        firstName,
        lastName,
        ...(cleanBio !== undefined ? { about: cleanBio } : {}),
      })
    );

    connected.firstName = firstName;
    connected.lastName = lastName;
    if (cleanName) {
      connected.avatarInitial = cleanName.slice(0, 2).toUpperCase();
    }

    if (typeof username === 'string') {
      const normalizedNewUsername = username.trim().replace(/^@/, '');
      const currentUsername = (connected.username || '').replace(/^@/, '');
      if (normalizedNewUsername !== currentUsername) {
        try {
          await connected.client.invoke(
            new Api.account.UpdateUsername({
              username: normalizedNewUsername,
            })
          );
          connected.username = normalizedNewUsername ? `@${normalizedNewUsername}` : '';
        } catch (userErr: any) {
          const msg = String(userErr?.errorMessage || userErr?.message || userErr || '用户名更新失败');
          if (!msg.includes('USERNAME_NOT_MODIFIED')) {
            return res.status(400).json({
              ok: false,
              cloudSynced: false,
              profileUpdated: true,
              error: msg.includes('USERNAME_OCCUPIED')
                ? '该用户名已被其他 Telegram 用户占用'
                : msg.includes('USERNAME_INVALID')
                  ? '用户名格式无效（仅支持 5-32 位字母、数字与下划线）'
                  : `用户名云端同步失败: ${msg}`,
            });
          }
        }
      }
    }

    try {
      await db.prepare(
        'UPDATE telegram_user_sessions SET first_name = ?, username = ?, updated_at = ? WHERE user_id = ? OR phone = ?'
      ).run(
        `${connected.firstName} ${connected.lastName}`.trim(),
        (connected.username || '').replace(/^@/, ''),
        Date.now(),
        connected.userId,
        connected.phone
      );
    } catch {}

    return res.json({
      ok: true,
      cloudSynced: true,
      profile: {
        name: `${connected.firstName || ''} ${connected.lastName || ''}`.trim(),
        username: connected.username,
        bio: cleanBio ?? '',
        phone: connected.phone,
      },
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 500);
  }
});

// 20.3.1a Upload Official Telegram Profile Avatar (photos.UploadProfilePhoto)
app.post('/api/telegram/user/upload-avatar', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const imageDataUrl = (req.body?.imageDataUrl as string) || '';

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        error: '当前账号未在线连接 Telegram MTProto，无法上传云端头像。',
      });
    }

    const match = imageDataUrl.match(/^data:(image\/(?:png|jpeg|jpg|webp));base64,(.+)$/i);
    if (!match) {
      return res.status(400).json({
        ok: false,
        error: '头像格式无效，请上传 PNG、JPG 或 WEBP 图片文件。',
      });
    }

    const mime = match[1].toLowerCase();
    const ext = mime.includes('png') ? 'png' : mime.includes('webp') ? 'webp' : 'jpg';
    const imgBuf = Buffer.from(match[2], 'base64');
    if (!imgBuf || imgBuf.length === 0) {
      return res.status(400).json({ ok: false, error: '头像图片内容为空' });
    }

    const customFile = new CustomFile(`avatar_${connected.userId}.${ext}`, imgBuf.length, '', imgBuf);
    const uploadedFile = await connected.client.uploadFile({
      file: customFile,
      workers: 1,
    });

    await connected.client.invoke(
      new Api.photos.UploadProfilePhoto({
        file: uploadedFile,
      })
    );

    const extraAvatarKeys: string[] = [];
    if (connected.username) {
      const cleanUname = connected.username.replace(/^@/, '');
      extraAvatarKeys.push(cleanUname, `acc_tg_${connected.userId}:${cleanUname}`);
    }
    invalidateTelegramAvatarCacheEntries(connected.userId, connected.userId, extraAvatarKeys);

    return res.json({
      ok: true,
      cloudSynced: true,
      avatarUrl: signTelegramResourceUrl(
        `/api/telegram/user/avatar/${connected.userId}?t=${Date.now()}`,
        `acc_tg_${connected.userId}`
      ),
      message: 'Telegram 官方头像已上传并同步至云端',
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 500);
  }
});

// 20.3.1b Official Change Phone Number (account.SendChangePhoneCode / account.ChangePhone)
export const CHANGE_PHONE_SESSION_TTL_MS = 10 * 60 * 1000;
export const MAX_PENDING_CHANGE_PHONE_SESSIONS = 100;
export const pendingChangePhoneSessions = new Map<string, {
  userId: string;
  newPhone: string;
  phoneCodeHash: string;
  createdAt: number;
}>();

export function prunePendingChangePhoneSessions(now = Date.now()): number {
  let removed = 0;
  for (const [uid, entry] of pendingChangePhoneSessions.entries()) {
    if (!entry || now - entry.createdAt >= CHANGE_PHONE_SESSION_TTL_MS) {
      pendingChangePhoneSessions.delete(uid);
      removed++;
    }
  }
  while (pendingChangePhoneSessions.size > MAX_PENDING_CHANGE_PHONE_SESSIONS) {
    const oldestUid = pendingChangePhoneSessions.keys().next().value;
    if (oldestUid === undefined) break;
    pendingChangePhoneSessions.delete(oldestUid);
    removed++;
  }
  return removed;
}

app.post('/api/telegram/user/change-phone/send-code', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const rawNewPhone = (req.body?.newPhone as string) || '';

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto，无法发送换绑验证码。' });
    }

    const cleanNewPhone = normalizePhoneNumber(rawNewPhone);
    if (!cleanNewPhone || cleanNewPhone.length < 6) {
      return res.status(400).json({ ok: false, error: '请输入正确的新手机号码（含国际区号，如 +8613800000000）。' });
    }

    const sent: any = await connected.client.invoke(
      new Api.account.SendChangePhoneCode({
        phoneNumber: cleanNewPhone,
        settings: new Api.CodeSettings({}),
      })
    );

    const now = Date.now();
    prunePendingChangePhoneSessions(now);
    pendingChangePhoneSessions.set(connected.userId, {
      userId: connected.userId,
      newPhone: cleanNewPhone,
      phoneCodeHash: sent.phoneCodeHash,
      createdAt: now,
    });
    prunePendingChangePhoneSessions(now);

    return res.json({
      ok: true,
      newPhone: cleanNewPhone,
      phoneCodeHash: sent.phoneCodeHash,
      message: `换绑验证码已发送至新号码 ${cleanNewPhone} 对应的终端/短信，请查收并输入确认。`,
    });
  } catch (err: any) {
    const msg = String(err?.errorMessage || err?.message || '');
    if (msg.includes('PHONE_NUMBER_OCCUPIED')) {
      return res.status(400).json({ ok: false, error: '该新手机号已被其他 Telegram 账号占用，无法换绑。' });
    }
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 400);
  }
});

app.post('/api/telegram/user/change-phone/confirm', requireTenantAuth, authAttemptLimiter, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const code = String(req.body?.code || '').trim();
    const rawNewPhone = (req.body?.newPhone as string) || '';

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto，无法完成手机号换绑。' });
    }

    prunePendingChangePhoneSessions();
    const pending = pendingChangePhoneSessions.get(connected.userId);
    const cleanNewPhone = normalizePhoneNumber(rawNewPhone || pending?.newPhone || '');
    const phoneCodeHash = String(req.body?.phoneCodeHash || pending?.phoneCodeHash || '').trim();

    if (!cleanNewPhone || !phoneCodeHash || !code) {
      return res.status(400).json({ ok: false, error: '换绑会话不完整或已过期，请重新发送验证码。' });
    }

    const oldPhone = connected.phone;
    const updatedUser: any = await connected.client.invoke(
      new Api.account.ChangePhone({
        phoneNumber: cleanNewPhone,
        phoneCodeHash,
        phoneCode: code,
      })
    );

    const verifiedPhone = updatedUser?.phone
      ? (String(updatedUser.phone).startsWith('+') ? String(updatedUser.phone) : `+${updatedUser.phone}`)
      : cleanNewPhone;

    connected.phone = verifiedPhone;
    if (oldPhone && oldPhone !== verifiedPhone) {
      connectedUserClients.delete(oldPhone);
    }
    connectedUserClients.set(verifiedPhone, connected);
    pendingChangePhoneSessions.delete(connected.userId);

    try {
      await db.prepare(
        'UPDATE telegram_user_sessions SET phone = ?, updated_at = ? WHERE user_id = ? OR phone = ?'
      ).run(verifiedPhone, Date.now(), connected.userId, oldPhone);
    } catch {}

    return res.json({
      ok: true,
      cloudSynced: true,
      phone: verifiedPhone,
      message: `Telegram 官方绑定手机号已成功变更为 ${verifiedPhone}`,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 400);
  }
});

export type TelegramPrivacyRuleKey =
  | 'status'
  | 'phone'
  | 'addedByPhone'
  | 'profilePhoto'
  | 'bio'
  | 'forwards'
  | 'calls'
  | 'p2p'
  | 'chatInvite'
  | 'voiceMessages';

export interface ParsedPrivacyExceptionUser {
  id: string;
  name: string;
  username?: string;
}

export interface ParsedPrivacyRuleDetail {
  mode: 'everybody' | 'contacts' | 'nobody';
  summary: string;
  allowUsers: ParsedPrivacyExceptionUser[];
  disallowUsers: ParsedPrivacyExceptionUser[];
}

function createInputPrivacyKey(key: TelegramPrivacyRuleKey): Api.TypeInputPrivacyKey {
  switch (key) {
    case 'status':
      return new Api.InputPrivacyKeyStatusTimestamp();
    case 'phone':
      return new Api.InputPrivacyKeyPhoneNumber();
    case 'addedByPhone':
      return new Api.InputPrivacyKeyAddedByPhone();
    case 'profilePhoto':
      return new Api.InputPrivacyKeyProfilePhoto();
    case 'bio':
      return new Api.InputPrivacyKeyAbout();
    case 'forwards':
      return new Api.InputPrivacyKeyForwards();
    case 'calls':
      return new Api.InputPrivacyKeyPhoneCall();
    case 'p2p':
      return new Api.InputPrivacyKeyPhoneP2P();
    case 'chatInvite':
      return new Api.InputPrivacyKeyChatInvite();
    case 'voiceMessages':
      return new Api.InputPrivacyKeyVoiceMessages();
  }
}

const VALID_PRIVACY_KEYS: TelegramPrivacyRuleKey[] = [
  'status',
  'phone',
  'addedByPhone',
  'profilePhoto',
  'bio',
  'forwards',
  'calls',
  'p2p',
  'chatInvite',
  'voiceMessages',
];

function serializeTwoFactorState(pwdObj: any) {
  return {
    hasPassword: Boolean(pwdObj?.hasPassword),
    hint: pwdObj?.hint || '',
    hasRecovery: Boolean(pwdObj?.hasRecovery),
    emailUnconfirmedPattern: pwdObj?.emailUnconfirmedPattern || '',
    pendingResetDate: Number(pwdObj?.pendingResetDate || 0),
  };
}

// Helper: parse Telegram privacy rules to canonical mode + custom exception users
export function parsePrivacyRulesToMode(rules: any[], users?: any[]): ParsedPrivacyRuleDetail {
  const list = Array.isArray(rules) ? rules : [];
  const userMap = new Map<string, ParsedPrivacyExceptionUser>();
  if (Array.isArray(users)) {
    for (const u of users) {
      if (!u || u.id === undefined || u.id === null) continue;
      const uid = String(u.id);
      const displayName = `${u.firstName || ''} ${u.lastName || ''}`.trim() || (u.username ? `@${u.username}` : `用户 ${uid}`);
      userMap.set(uid, {
        id: uid,
        name: displayName,
        username: u.username ? `@${u.username}` : undefined,
      });
    }
  }

  let mode: 'everybody' | 'contacts' | 'nobody' = 'nobody';
  let baseSummary = '自定义规则';
  let foundBase = false;
  const allowUsers: ParsedPrivacyExceptionUser[] = [];
  const disallowUsers: ParsedPrivacyExceptionUser[] = [];
  const seenAllow = new Set<string>();
  const seenDisallow = new Set<string>();
  let allowChatCount = 0;
  let disallowChatCount = 0;
  let hasAllowCloseFriends = false;
  let hasAllowPremium = false;
  let hasAllowBots = false;
  let hasDisallowBots = false;
  let hasDisallowContacts = false;

  for (const r of list) {
    const cls = r?.className || r?.constructor?.name || '';
    if (!foundBase && cls === 'PrivacyValueAllowAll') {
      mode = 'everybody';
      baseSummary = '所有人可见';
      foundBase = true;
    } else if (!foundBase && cls === 'PrivacyValueAllowContacts') {
      mode = 'contacts';
      baseSummary = '仅我的联系人可见';
      foundBase = true;
    } else if (!foundBase && cls === 'PrivacyValueDisallowAll') {
      mode = 'nobody';
      baseSummary = '没有人可见';
      foundBase = true;
    } else if (cls === 'PrivacyValueAllowUsers' && Array.isArray(r?.users)) {
      for (const rawId of r.users) {
        const uid = String(rawId);
        if (seenAllow.has(uid)) continue;
        seenAllow.add(uid);
        allowUsers.push(userMap.get(uid) || { id: uid, name: `用户 ${uid}` });
      }
    } else if (cls === 'PrivacyValueDisallowUsers' && Array.isArray(r?.users)) {
      for (const rawId of r.users) {
        const uid = String(rawId);
        if (seenDisallow.has(uid)) continue;
        seenDisallow.add(uid);
        disallowUsers.push(userMap.get(uid) || { id: uid, name: `用户 ${uid}` });
      }
    } else if (cls === 'PrivacyValueAllowChatParticipants' && Array.isArray(r?.chats)) {
      allowChatCount += r.chats.length;
    } else if (cls === 'PrivacyValueDisallowChatParticipants' && Array.isArray(r?.chats)) {
      disallowChatCount += r.chats.length;
    } else if (cls === 'PrivacyValueAllowCloseFriends') {
      hasAllowCloseFriends = true;
    } else if (cls === 'PrivacyValueAllowPremium') {
      hasAllowPremium = true;
    } else if (cls === 'PrivacyValueAllowBots') {
      hasAllowBots = true;
    } else if (cls === 'PrivacyValueDisallowBots') {
      hasDisallowBots = true;
    } else if (cls === 'PrivacyValueDisallowContacts') {
      hasDisallowContacts = true;
    }
  }

  const extraTags: string[] = [];
  if (allowUsers.length > 0) extraTags.push(`+${allowUsers.length} 始终允许`);
  if (disallowUsers.length > 0) extraTags.push(`-${disallowUsers.length} 永不允许`);
  if (allowChatCount > 0) extraTags.push(`+${allowChatCount} 个允许群组`);
  if (disallowChatCount > 0) extraTags.push(`-${disallowChatCount} 个禁止群组`);
  if (hasAllowCloseFriends) extraTags.push('+密友');
  if (hasAllowPremium) extraTags.push('+Premium 会员');
  if (hasAllowBots) extraTags.push('+机器人');
  if (hasDisallowBots) extraTags.push('-机器人');
  if (hasDisallowContacts) extraTags.push('-联系人');
  const summary = extraTags.length > 0 ? `${baseSummary}（${extraTags.join(' / ')}）` : baseSummary;

  return { mode, summary, allowUsers, disallowUsers };
}

export function extractPreservedExtraInputPrivacyRules(
  existingRules: any[] = [],
  targetMode: string = 'nobody'
): Api.TypeInputPrivacyRule[] {
  const preserved: Api.TypeInputPrivacyRule[] = [];
  if (!Array.isArray(existingRules)) return preserved;
  for (const r of existingRules) {
    const cls = r?.className || r?.constructor?.name || '';
    if (cls === 'PrivacyValueAllowChatParticipants' && targetMode !== 'everybody' && Array.isArray(r?.chats)) {
      const chats = r.chats.filter((id: any) => id !== undefined && id !== null);
      if (chats.length > 0) preserved.push(new Api.InputPrivacyValueAllowChatParticipants({ chats }));
    } else if (cls === 'PrivacyValueDisallowChatParticipants' && targetMode !== 'nobody' && Array.isArray(r?.chats)) {
      const chats = r.chats.filter((id: any) => id !== undefined && id !== null);
      if (chats.length > 0) preserved.push(new Api.InputPrivacyValueDisallowChatParticipants({ chats }));
    } else if (cls === 'PrivacyValueAllowCloseFriends' && targetMode !== 'everybody') {
      preserved.push(new Api.InputPrivacyValueAllowCloseFriends());
    } else if (cls === 'PrivacyValueAllowPremium' && targetMode !== 'everybody') {
      preserved.push(new Api.InputPrivacyValueAllowPremium());
    } else if (cls === 'PrivacyValueAllowBots' && targetMode !== 'everybody') {
      preserved.push(new Api.InputPrivacyValueAllowBots());
    } else if (cls === 'PrivacyValueDisallowBots' && targetMode !== 'nobody') {
      preserved.push(new Api.InputPrivacyValueDisallowBots());
    } else if (cls === 'PrivacyValueDisallowContacts' && targetMode === 'everybody') {
      preserved.push(new Api.InputPrivacyValueDisallowContacts());
    }
  }
  return preserved;
}

export function buildPrivacyInputRules(
  mode: string,
  allowUsers: Api.TypeInputUser[] = [],
  disallowUsers: Api.TypeInputUser[] = [],
  preservedExtraRules: Api.TypeInputPrivacyRule[] = []
): Api.TypeInputPrivacyRule[] {
  const rules: Api.TypeInputPrivacyRule[] = [];
  if (Array.isArray(allowUsers) && allowUsers.length > 0) {
    rules.push(new Api.InputPrivacyValueAllowUsers({ users: allowUsers }));
  }
  if (Array.isArray(disallowUsers) && disallowUsers.length > 0) {
    rules.push(new Api.InputPrivacyValueDisallowUsers({ users: disallowUsers }));
  }
  if (Array.isArray(preservedExtraRules) && preservedExtraRules.length > 0) {
    rules.push(...preservedExtraRules);
  }
  if (mode === 'everybody') {
    rules.push(new Api.InputPrivacyValueAllowAll());
  } else if (mode === 'contacts') {
    rules.push(new Api.InputPrivacyValueAllowContacts());
  } else {
    rules.push(new Api.InputPrivacyValueDisallowAll());
  }
  return rules;
}

function extractDialogFilterTitle(rawTitle: any): string {
  if (typeof rawTitle === 'string') return rawTitle;
  if (rawTitle && typeof rawTitle.text === 'string') return rawTitle.text;
  return '未命名分组';
}

function serializeInputPeerToChatId(peer: any, selfUserId?: string): string {
  if (!peer) return '';
  if (peer.userId !== undefined) return `tg_${String(peer.userId)}`;
  if (peer.chatId !== undefined) return `tg_-${String(peer.chatId)}`;
  if (peer.channelId !== undefined) return `tg_-100${String(peer.channelId)}`;
  if (peer.className === 'InputPeerSelf' && selfUserId) return `tg_${String(selfUserId)}`;
  return '';
}

function serializeDialogFilter(f: any, selfUserId?: string) {
  const toIdList = (arr: any): string[] =>
    Array.isArray(arr) ? arr.map((p: any) => serializeInputPeerToChatId(p, selfUserId)).filter(Boolean) : [];
  return {
    id: Number(f.id),
    title: extractDialogFilterTitle(f.title),
    emoticon: f.emoticon || '',
    color: typeof f.color === 'number' ? f.color : undefined,
    contacts: Boolean(f.contacts),
    nonContacts: Boolean(f.nonContacts),
    groups: Boolean(f.groups),
    broadcasts: Boolean(f.broadcasts),
    bots: Boolean(f.bots),
    excludeMuted: Boolean(f.excludeMuted),
    excludeRead: Boolean(f.excludeRead),
    excludeArchived: Boolean(f.excludeArchived),
    pinnedCount: Array.isArray(f.pinnedPeers) ? f.pinnedPeers.length : 0,
    includeCount: Array.isArray(f.includePeers) ? f.includePeers.length : 0,
    excludeCount: Array.isArray(f.excludePeers) ? f.excludePeers.length : 0,
    pinnedPeerIds: toIdList(f.pinnedPeers),
    includePeerIds: toIdList(f.includePeers),
    excludePeerIds: toIdList(f.excludePeers),
    isChatlist: (f.className || '').includes('DialogFilterChatlist'),
  };
}

// 20.3.1c Fetch Complete Official Telegram Account Settings via MTProto
app.get('/api/telegram/user/settings', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.query.phone,
      rawUserId: req.query.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        error: '当前账号未在线连接 Telegram MTProto，无法拉取官方云端设置。请先在多账号管理器中登录/重连该账号。',
      });
    }

    const client = connected.client;

    const settled = await Promise.allSettled([
      client.invoke(new Api.users.GetFullUser({ id: new Api.InputUserSelf() })),
      client.invoke(new Api.account.GetPassword()),
      client.invoke(new Api.account.GetAuthorizations()),
      client.invoke(new Api.account.GetNotifySettings({ peer: new Api.InputNotifyUsers() })),
      client.invoke(new Api.account.GetNotifySettings({ peer: new Api.InputNotifyChats() })),
      client.invoke(new Api.account.GetNotifySettings({ peer: new Api.InputNotifyBroadcasts() })),
      client.invoke(new Api.messages.GetDialogFilters()),
      client.invoke(new Api.account.GetGlobalPrivacySettings()),
      client.invoke(new Api.account.GetAccountTTL()),
      ...VALID_PRIVACY_KEYS.map((k) => client.invoke(new Api.account.GetPrivacy({ key: createInputPrivacyKey(k) }))),
    ]);

    const [
      fullUserSettled,
      passwordSettled,
      authorizationsSettled,
      usersNotifySettled,
      chatsNotifySettled,
      broadcastsNotifySettled,
      dialogFiltersSettled,
      globalPrivacySettled,
      accountTtlSettled,
      ...privacySettledList
    ] = settled;

    // If core MTProto connection failed completely across profile/password/sessions, surface real Telegram error
    if (
      fullUserSettled.status === 'rejected' &&
      passwordSettled.status === 'rejected' &&
      authorizationsSettled.status === 'rejected'
    ) {
      return await handleMtprotoRouteError(
        res,
        passwordSettled.reason || fullUserSettled.reason,
        {
          accountId,
          userId: connected.userId,
          phone: connected.phone,
        },
        500
      );
    }

    const fullUserRes = fullUserSettled.status === 'fulfilled' ? fullUserSettled.value : null;
    const passwordRes = passwordSettled.status === 'fulfilled' ? passwordSettled.value : null;
    const authorizationsRes = authorizationsSettled.status === 'fulfilled' ? authorizationsSettled.value : null;
    const usersNotifyRes = usersNotifySettled.status === 'fulfilled' ? usersNotifySettled.value : null;
    const chatsNotifyRes = chatsNotifySettled.status === 'fulfilled' ? chatsNotifySettled.value : null;
    const broadcastsNotifyRes = broadcastsNotifySettled.status === 'fulfilled' ? broadcastsNotifySettled.value : null;
    const dialogFiltersRes = dialogFiltersSettled.status === 'fulfilled' ? dialogFiltersSettled.value : null;
    const globalPrivacyRes = globalPrivacySettled.status === 'fulfilled' ? (globalPrivacySettled.value as any) : null;
    const accountTtlRes = accountTtlSettled.status === 'fulfilled' ? (accountTtlSettled.value as any) : null;

    const meUser: any = Array.isArray((fullUserRes as any)?.users)
      ? (fullUserRes as any).users.find((u: any) => u?.self || String(u?.id) === connected.userId) || (fullUserRes as any).users[0]
      : null;
    const fullUserObj: any = (fullUserRes as any)?.fullUser || {};

    if (meUser) {
      connected.firstName = meUser.firstName || connected.firstName;
      connected.lastName = meUser.lastName || '';
      connected.username = meUser.username ? `@${meUser.username}` : '';
      if (meUser.phone) {
        connected.phone = String(meUser.phone).startsWith('+') ? String(meUser.phone) : `+${meUser.phone}`;
      }
    }

    const privacyRules: Partial<Record<TelegramPrivacyRuleKey, ParsedPrivacyRuleDetail>> = {};
    VALID_PRIVACY_KEYS.forEach((key, idx) => {
      const item = privacySettledList[idx];
      if (item && item.status === 'fulfilled') {
        const val: any = item.value;
        privacyRules[key] = parsePrivacyRulesToMode(val?.rules, val?.users);
      }
    });

    const statusPrivacy = privacyRules.status || { mode: 'nobody' as const, summary: '未获取', allowUsers: [], disallowUsers: [] };
    const phonePrivacy = privacyRules.phone || { mode: 'nobody' as const, summary: '未获取', allowUsers: [], disallowUsers: [] };

    const authList = Array.isArray((authorizationsRes as any)?.authorizations)
      ? (authorizationsRes as any).authorizations.map((a: any) => ({
          hash: String(a.hash),
          current: Boolean(a.current),
          officialApp: Boolean(a.officialApp),
          deviceModel: a.deviceModel || 'Unknown Device',
          platform: a.platform || '',
          systemVersion: a.systemVersion || '',
          appName: a.appName || 'Telegram',
          appVersion: a.appVersion || '',
          dateCreated: Number(a.dateCreated || 0),
          dateActive: Number(a.dateActive || 0),
          ip: a.ip || '',
          country: a.country || '',
          region: a.region || '',
        }))
      : [];

    const nowSec = Math.floor(Date.now() / 1000);
    const parseNotify = (n: any) => {
      const muteUntil = Number(n?.muteUntil || 0);
      const isMuted = Boolean(n?.silent) || (muteUntil > nowSec);
      return {
        enabled: !isMuted,
        silent: Boolean(n?.silent),
        muteUntil,
        showPreviews: n?.showPreviews !== false,
      };
    };

    const rawFilters: any[] = Array.isArray((dialogFiltersRes as any)?.filters)
      ? (dialogFiltersRes as any).filters
      : Array.isArray(dialogFiltersRes)
        ? (dialogFiltersRes as any)
        : [];
    const folders = rawFilters
      .filter((f: any) => f && f.className !== 'DialogFilterDefault' && typeof f.id === 'number')
      .map((f: any) => serializeDialogFilter(f, connected.userId));

    return res.json({
      ok: true,
      cloudSynced: true,
      profile: {
        userId: connected.userId,
        name: `${connected.firstName || ''} ${connected.lastName || ''}`.trim() || 'Telegram 用户',
        username: connected.username || '',
        phone: connected.phone || '',
        bio: fullUserObj?.about || '',
        hasAvatar: Boolean(fullUserObj?.profilePhoto || meUser?.photo),
        avatarUrl: signTelegramResourceUrl(
          `/api/telegram/user/avatar/${connected.userId}`,
          `acc_tg_${connected.userId}`
        ),
      },
      twoFactor: passwordRes ? serializeTwoFactorState(passwordRes) : undefined,
      privacy: {
        lastSeen: statusPrivacy.mode,
        lastSeenSummary: statusPrivacy.summary,
        phoneNumber: phonePrivacy.mode,
        phoneNumberSummary: phonePrivacy.summary,
      },
      privacyRules,
      globalPrivacy: globalPrivacyRes
        ? {
            archiveAndMuteNewNoncontactPeers: Boolean(globalPrivacyRes.archiveAndMuteNewNoncontactPeers),
            keepArchivedUnmuted: Boolean(globalPrivacyRes.keepArchivedUnmuted),
            keepArchivedFolders: Boolean(globalPrivacyRes.keepArchivedFolders),
            hideReadMarks: Boolean(globalPrivacyRes.hideReadMarks),
            newNoncontactPeersRequirePremium: Boolean(globalPrivacyRes.newNoncontactPeersRequirePremium),
          }
        : undefined,
      accountTtlDays: accountTtlRes && typeof accountTtlRes.days === 'number' ? Number(accountTtlRes.days) : undefined,
      sessions: authorizationsRes ? authList : undefined,
      notifications:
        usersNotifyRes || chatsNotifyRes || broadcastsNotifyRes
          ? {
              users: parseNotify(usersNotifyRes),
              chats: parseNotify(chatsNotifyRes),
              broadcasts: parseNotify(broadcastsNotifyRes),
            }
          : undefined,
      folders: dialogFiltersRes ? folders : undefined,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 500);
  }
});

