// 20.3.1e-3 Update Official Telegram Account Self-Destruct Inactivity TTL (account.SetAccountTTL)
app.post('/api/telegram/user/settings/account-ttl', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const days = Number(req.body?.days);

    if (!Number.isInteger(days) || days < 30 || days > 730) {
      return res.status(400).json({ ok: false, error: '账号自动注销周期必须为 30 至 730 天之间的整数' });
    }

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto，无法修改账号自毁周期。' });
    }

    await connected.client.invoke(
      new Api.account.SetAccountTTL({
        ttl: new Api.AccountDaysTTL({ days }),
      })
    );

    return res.json({
      ok: true,
      cloudSynced: true,
      accountTtlDays: days,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 400);
  }
});

// 20.3.1f Terminate Official Active Telegram Session(s) (account.ResetAuthorization / auth.ResetAuthorizations)
app.post('/api/telegram/user/settings/sessions/terminate', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const { hash, terminateAllOthers } = req.body || {};

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto，无法注销远程设备。' });
    }

    if (terminateAllOthers) {
      await connected.client.invoke(new Api.auth.ResetAuthorizations());
    } else if (hash !== undefined && hash !== null && String(hash).trim() !== '') {
      await connected.client.invoke(
        new Api.account.ResetAuthorization({
          hash: BigInt(String(hash).trim()) as any,
        })
      );
    } else {
      return res.status(400).json({ ok: false, error: '请提供要注销的设备会话标识 hash' });
    }

    const authRes: any = await connected.client.invoke(new Api.account.GetAuthorizations());
    const sessions = Array.isArray(authRes?.authorizations)
      ? authRes.authorizations.map((a: any) => ({
          hash: String(a.hash),
          current: Boolean(a.current),
          officialApp: Boolean(a.officialApp),
          deviceModel: a.deviceModel || 'Unknown Device',
          platform: a.platform || '',
          systemVersion: a.systemVersion || '',
          appName: a.appName || 'Telegram',
          appVersion: a.appVersion || '',
          dateCreated: Number(a.dateCreated || 0),
          dateActive: Number(a.dateActive || 0),
          ip: a.ip || '',
          country: a.country || '',
          region: a.region || '',
        }))
      : [];

    return res.json({
      ok: true,
      cloudSynced: true,
      sessions,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 400);
  }
});

// 20.3.1g Update Official Telegram Notification Settings (account.UpdateNotifySettings)
app.post('/api/telegram/user/settings/notifications', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const scope: 'users' | 'chats' | 'broadcasts' | 'both' | 'all' = req.body?.scope || 'both';
    const enabled = Boolean(req.body?.enabled);
    const previewText = req.body?.previewText !== false;
    const preserveEnabled = Boolean(req.body?.preserveEnabled);

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto，无法同步云端通知设置。' });
    }

    const nowSecCheck = Math.floor(Date.now() / 1000);
    const targetPeers: Api.TypeInputNotifyPeer[] = [];
    if (scope === 'users' || scope === 'both' || scope === 'all') {
      targetPeers.push(new Api.InputNotifyUsers());
    }
    if (scope === 'chats' || scope === 'both' || scope === 'all') {
      targetPeers.push(new Api.InputNotifyChats());
    }
    if (scope === 'broadcasts' || scope === 'all') {
      targetPeers.push(new Api.InputNotifyBroadcasts());
    }

    for (const notifyPeer of targetPeers) {
      let peerEnabled = enabled;
      if (preserveEnabled) {
        try {
          const cur: any = await connected.client.invoke(new Api.account.GetNotifySettings({ peer: notifyPeer }));
          const curMute = Number(cur?.muteUntil || 0);
          peerEnabled = !(Boolean(cur?.silent) || curMute > nowSecCheck);
        } catch {}
      }
      await connected.client.invoke(
        new Api.account.UpdateNotifySettings({
          peer: notifyPeer,
          settings: new Api.InputPeerNotifySettings({
            showPreviews: previewText,
            silent: !peerEnabled,
            muteUntil: peerEnabled ? 0 : 2147483647,
          }),
        })
      );
    }

    const [usersNotifyRes, chatsNotifyRes, broadcastsNotifyRes] = await Promise.all([
      connected.client.invoke(new Api.account.GetNotifySettings({ peer: new Api.InputNotifyUsers() })),
      connected.client.invoke(new Api.account.GetNotifySettings({ peer: new Api.InputNotifyChats() })),
      connected.client.invoke(new Api.account.GetNotifySettings({ peer: new Api.InputNotifyBroadcasts() })),
    ]);

    const nowSec = Math.floor(Date.now() / 1000);
    const parseNotify = (n: any) => {
      const muteUntil = Number(n?.muteUntil || 0);
      const isMuted = Boolean(n?.silent) || (muteUntil > nowSec);
      return {
        enabled: !isMuted,
        silent: Boolean(n?.silent),
        muteUntil,
        showPreviews: n?.showPreviews !== false,
      };
    };

    return res.json({
      ok: true,
      cloudSynced: true,
      notifications: {
        users: parseNotify(usersNotifyRes),
        chats: parseNotify(chatsNotifyRes),
        broadcasts: parseNotify(broadcastsNotifyRes),
      },
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 400);
  }
});

// 20.3.1h Create/Update Official Telegram Dialog Folder (messages.UpdateDialogFilter)
app.post('/api/telegram/user/settings/folders', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const folder = req.body?.filter;

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto，无法操作云端对话文件夹。' });
    }

    const cleanTitle = String(folder?.title || '').trim();
    if (!cleanTitle) {
      return res.status(400).json({ ok: false, error: '文件夹名称不能为空' });
    }

    const existingRes: any = await connected.client.invoke(new Api.messages.GetDialogFilters());
    const rawFilters: any[] = Array.isArray(existingRes?.filters)
      ? existingRes.filters
      : Array.isArray(existingRes)
        ? existingRes
        : [];

    let targetId = Number(folder?.id || 0);
    const existingObj = targetId >= 2 ? rawFilters.find((f: any) => Number(f?.id) === targetId) : null;
    if (!targetId || targetId < 2) {
      const usedIds = new Set(rawFilters.map((f: any) => Number(f?.id || 0)));
      targetId = 2;
      while (usedIds.has(targetId) && targetId < 255) targetId += 1;
    }

    const resolveFilterPeers = async (peerIds: any, fallbackPeers: any[]) => {
      if (!Array.isArray(peerIds)) return Array.isArray(fallbackPeers) ? fallbackPeers : [];
      const resolved: any[] = [];
      const seen = new Set<string>();
      for (const rawId of peerIds) {
        const cid = String(rawId || '').trim();
        if (!cid || seen.has(cid)) continue;
        seen.add(cid);
        try {
          const { inputPeer } = await resolveTelegramInputPeer(connected.client, cid, connected.userId);
          if (inputPeer) resolved.push(inputPeer);
        } catch {}
      }
      return resolved;
    };

    const pinnedPeers = await resolveFilterPeers(folder?.pinnedPeerIds, existingObj?.pinnedPeers);
    const includePeers = await resolveFilterPeers(folder?.includePeerIds, existingObj?.includePeers);
    const excludePeers = await resolveFilterPeers(folder?.excludePeerIds, existingObj?.excludePeers);
    const isExistingChatlist = Boolean(
      existingObj && String(existingObj.className || '').includes('DialogFilterChatlist')
    );

    const tlFilter = isExistingChatlist
      ? new Api.DialogFilterChatlist({
          id: targetId,
          hasMyInvites: Boolean(existingObj?.hasMyInvites),
          title: new Api.TextWithEntities({ text: cleanTitle.slice(0, 12), entities: [] }),
          emoticon: folder?.emoticon ?? existingObj?.emoticon,
          color: folder?.color ?? existingObj?.color,
          pinnedPeers,
          includePeers,
        })
      : new Api.DialogFilter({
          id: targetId,
          title: new Api.TextWithEntities({ text: cleanTitle.slice(0, 12), entities: [] }),
          emoticon: folder?.emoticon ?? existingObj?.emoticon,
          color: folder?.color ?? existingObj?.color,
          contacts: Boolean(folder?.contacts),
          nonContacts: Boolean(folder?.nonContacts),
          groups: Boolean(folder?.groups),
          broadcasts: Boolean(folder?.broadcasts),
          bots: Boolean(folder?.bots),
          excludeMuted: Boolean(folder?.excludeMuted),
          excludeRead: Boolean(folder?.excludeRead),
          excludeArchived: Boolean(folder?.excludeArchived),
          pinnedPeers,
          includePeers,
          excludePeers,
        });

    await connected.client.invoke(
      new Api.messages.UpdateDialogFilter({
        id: targetId,
        filter: tlFilter,
      })
    );

    const updatedRes: any = await connected.client.invoke(new Api.messages.GetDialogFilters());
    const updatedRaw: any[] = Array.isArray(updatedRes?.filters)
      ? updatedRes.filters
      : Array.isArray(updatedRes)
        ? updatedRes
        : [];
    const folders = updatedRaw
      .filter((f: any) => f && f.className !== 'DialogFilterDefault' && typeof f.id === 'number')
      .map((f: any) => serializeDialogFilter(f, connected.userId));

    return res.json({
      ok: true,
      cloudSynced: true,
      folders,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 400);
  }
});

// 20.3.1h2 Reorder Official Telegram Dialog Folders (messages.UpdateDialogFiltersOrder)
app.post('/api/telegram/user/settings/folders/order', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  let scopedPhone = '';
  let scopedUserId = '';
  try {
    const targetScope = resolveScopedTelegramTarget(req, {
      allowBot: false,
      rawPhone: req.body?.phone,
      rawUserId: req.body?.userId,
    });
    if (!targetScope.ok) {
      return res.status(targetScope.status).json({ ok: false, code: targetScope.code, error: targetScope.error });
    }
    const accountId = targetScope.accountId;
    const phone = targetScope.phone;
    const userId = targetScope.userId;
    scopedAccountId = accountId;
    scopedPhone = phone;
    scopedUserId = userId;
    const rawOrder = Array.isArray(req.body?.order) ? req.body.order : [];
    const customOrder = rawOrder.map((n: any) => Number(n)).filter((n: number) => Number.isInteger(n) && n >= 2);

    if (customOrder.length === 0) {
      return res.status(400).json({ ok: false, error: '文件夹排序参数不能为空' });
    }

    const connected = resolveConnectedTelegramUser(accountId, phone, userId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto，无法调整云端文件夹顺序。' });
    }

    const existingRes: any = await connected.client.invoke(new Api.messages.GetDialogFilters());
    const existingRaw: any[] = Array.isArray(existingRes?.filters)
      ? existingRes.filters
      : Array.isArray(existingRes)
        ? existingRes
        : [];
    const hasDefault = existingRaw.some((f: any) => f?.className === 'DialogFilterDefault' || Number(f?.id) === 0);
    const orderPayload = hasDefault ? [0, ...customOrder] : customOrder;

    await connected.client.invoke(
      new Api.messages.UpdateDialogFiltersOrder({
        order: orderPayload,
      })
    );

    const updatedRes: any = await connected.client.invoke(new Api.messages.GetDialogFilters());
    const updatedRaw: any[] = Array.isArray(updatedRes?.filters)
      ? updatedRes.filters
      : Array.isArray(updatedRes)
        ? updatedRes
        : [];
    const folders = updatedRaw
      .filter((f: any) => f && f.className !== 'DialogFilterDefault' && typeof f.id === 'number')
      .map((f: any) => serializeDialogFilter(f, connected.userId));

    return res.json({
      ok: true,
      cloudSynced: true,
      folders,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
      phone: scopedPhone,
      userId: scopedUserId,
    }, 400);
  }
});

