function resolveStickerEnglishAlias(rawQuery: string): string | null {
  const lower = rawQuery.trim().toLowerCase();
  if (!lower) return null;
  for (const entry of STICKER_ZH_TO_EN_ALIASES) {
    if (entry.zh.some((kw) => lower === kw || lower.includes(kw))) {
      return entry.en;
    }
  }
  return null;
}

function resolveStickerSearchEmoticons(rawQuery: string): string[] {
  const q = rawQuery.trim();
  if (!q) return [];
  const results: string[] = [];
  const addUnique = (em: string) => {
    const clean = String(em || '').trim();
    if (clean && !results.includes(clean)) results.push(clean);
  };
  const emojiMatches = q.match(/\p{Extended_Pictographic}/gu);
  if (emojiMatches) {
    for (const em of emojiMatches) addUnique(em);
  }
  const lower = q.toLowerCase();
  for (const entry of STICKER_KEYWORD_TO_EMOJI) {
    if (entry.keywords.some((kw) => lower === kw || lower.includes(kw))) {
      for (const em of entry.emojis) addUnique(em);
    }
  }
  return results;
}

// Cache official Telegram emoji keywords dictionaries (messages.GetEmojiKeywords) per language
const EMOJI_KEYWORDS_CACHE_TTL_MS = 6 * 60 * 60 * 1000;
const telegramEmojiKeywordsCache = new Map<
  string,
  {
    fetchedAt: number;
    exact: Map<string, string[]>;
    entries: Array<{ keyword: string; emoticons: string[] }>;
  }
>();
const telegramEmojiKeywordsInFlight = new Map<string, Promise<void>>();

async function loadTelegramEmojiKeywordsForLang(client: TelegramClient, langCode: string): Promise<void> {
  const normalizedLang = langCode.trim().toLowerCase();
  if (!normalizedLang) return;
  const cached = telegramEmojiKeywordsCache.get(normalizedLang);
  if (cached && Date.now() - cached.fetchedAt < EMOJI_KEYWORDS_CACHE_TTL_MS) {
    return;
  }
  const existingFlight = telegramEmojiKeywordsInFlight.get(normalizedLang);
  if (existingFlight) {
    await existingFlight;
    return;
  }
  const job = (async () => {
    try {
      const diff: any = await client.invoke(
        new Api.messages.GetEmojiKeywords({
          langCode: normalizedLang,
        })
      );
      const rawKeywords: any[] = Array.isArray(diff?.keywords) ? diff.keywords : [];
      const exact = new Map<string, string[]>();
      const entries: Array<{ keyword: string; emoticons: string[] }> = [];
      for (const item of rawKeywords) {
        const kw = String(item?.keyword || '').trim().toLowerCase();
        const emoticons: string[] = Array.isArray(item?.emoticons)
          ? item.emoticons.map((e: any) => String(e || '').trim()).filter(Boolean)
          : [];
        if (!kw || emoticons.length === 0) continue;
        const prev = exact.get(kw);
        if (prev) {
          for (const em of emoticons) {
            if (!prev.includes(em)) prev.push(em);
          }
        } else {
          exact.set(kw, [...emoticons]);
          entries.push({ keyword: kw, emoticons: exact.get(kw)! });
        }
      }
      telegramEmojiKeywordsCache.set(normalizedLang, {
        fetchedAt: Date.now(),
        exact,
        entries,
      });
    } catch {
      // Cache empty result briefly so unsupported lang codes don't re-hit every keystroke
      if (!telegramEmojiKeywordsCache.has(normalizedLang)) {
        telegramEmojiKeywordsCache.set(normalizedLang, {
          fetchedAt: Date.now(),
          exact: new Map(),
          entries: [],
        });
      }
    } finally {
      telegramEmojiKeywordsInFlight.delete(normalizedLang);
    }
  })();
  telegramEmojiKeywordsInFlight.set(normalizedLang, job);
  await job;
}

async function resolveCloudEmojiKeywords(client: TelegramClient, rawQuery: string): Promise<string[]> {
  const lower = rawQuery.trim().toLowerCase();
  if (!lower) return [];
  const hasCjk = /[\u4e00-\u9fff]/.test(lower);
  const langs = hasCjk ? ['zh-hans', 'zh', 'en'] : ['en', 'zh-hans'];
  await Promise.all(langs.map((lang) => loadTelegramEmojiKeywordsForLang(client, lang)));

  const matched: string[] = [];
  const addEmoticon = (em: string) => {
    if (em && !matched.includes(em) && matched.length < 4) {
      matched.push(em);
    }
  };

  for (const lang of langs) {
    const dict = telegramEmojiKeywordsCache.get(lang);
    if (!dict) continue;
    const exactList = dict.exact.get(lower);
    if (exactList) {
      for (const em of exactList) addEmoticon(em);
    }
  }
  if (matched.length === 0 && lower.length >= 2) {
    for (const lang of langs) {
      const dict = telegramEmojiKeywordsCache.get(lang);
      if (!dict) continue;
      for (const entry of dict.entries) {
        if (entry.keyword.includes(lower) || (entry.keyword.length >= 2 && lower.includes(entry.keyword))) {
          for (const em of entry.emoticons) addEmoticon(em);
          if (matched.length >= 3) break;
        }
      }
      if (matched.length >= 3) break;
    }
  }
  return matched;
}

function mapTelegramStickerDocToItem(
  doc: any,
  userId: string,
  fallbackSet: { id: string; accessHash: string; shortName: string },
  docEmojiMap?: Map<string, string>
) {
  if (!doc || !doc.id || !doc.accessHash) return null;
  cacheTelegramStickerDoc(userId, doc);

  const attrs: any[] = Array.isArray(doc.attributes) ? doc.attributes : [];
  const stickerAttr = attrs.find((a) => a.className === 'DocumentAttributeSticker');
  const attrSet = stickerAttr?.stickerset;
  const setId = String(attrSet?.id ?? (fallbackSet.id || '0')) || '0';
  const setAccessHash = String(attrSet?.accessHash ?? (fallbackSet.accessHash || '0')) || '0';
  const shortName = String(attrSet?.shortName ?? fallbackSet.shortName ?? '');

  const mimeType = String(doc.mimeType || 'image/webp');
  const docId = String(doc.id);
  const queryParams = new URLSearchParams({
    accountId: `acc_tg_${userId}`,
    setAccessHash,
  });
  if (shortName) queryParams.set('shortName', shortName);

  return {
    docId,
    accessHash: String(doc.accessHash),
    fileReferenceBase64: Buffer.isBuffer(doc.fileReference)
      ? doc.fileReference.toString('base64')
      : '',
    setId,
    setAccessHash,
    shortName,
    emoji: String(stickerAttr?.alt || docEmojiMap?.get(docId) || '✨'),
    mimeType,
    isAnimated: mimeType.includes('tgsticker'),
    isVideo: mimeType.includes('webm'),
    thumbUrl: signTelegramResourceUrl(
      `/api/telegram/user/sticker/${encodeURIComponent(setId)}/${encodeURIComponent(docId)}?${queryParams.toString()}`
    ),
  };
}

async function fetchTelegramStickerPackBySet(
  client: TelegramClient,
  userId: string,
  s: any,
  maxStickers = 32
): Promise<any | null> {
  if (!s?.id || s?.accessHash === undefined || s?.accessHash === null) return null;
  try {
    const setRes: any = await client.invoke(
      new Api.messages.GetStickerSet({
        stickerset: new Api.InputStickerSetID({
          id: s.id,
          accessHash: s.accessHash,
        }),
        hash: 0,
      })
    );
    const setObj: any = setRes?.set || s;
    const docs: any[] = Array.isArray(setRes?.documents) ? setRes.documents : [];
    const emojiPacks: any[] = Array.isArray(setRes?.packs) ? setRes.packs : [];

    const docEmojiMap = new Map<string, string>();
    for (const ep of emojiPacks) {
      const emoticon = String(ep?.emoticon || '').trim();
      if (!emoticon) continue;
      for (const did of Array.isArray(ep?.documents) ? ep.documents : []) {
        if (!docEmojiMap.has(String(did))) {
          docEmojiMap.set(String(did), emoticon);
        }
      }
    }

    const fallbackSet = {
      id: String(setObj.id),
      accessHash: String(setObj.accessHash),
      shortName: String(setObj.shortName || ''),
    };

    const stickers = docs
      .filter((doc) => doc && doc.id && doc.accessHash)
      .slice(0, maxStickers)
      .map((doc) => mapTelegramStickerDocToItem(doc, userId, fallbackSet, docEmojiMap))
      .filter(Boolean);

    if (stickers.length === 0) return null;

    return {
      id: String(setObj.id),
      accessHash: String(setObj.accessHash),
      shortName: String(setObj.shortName || ''),
      title: String(setObj.title || setObj.shortName || 'Telegram Sticker Pack'),
      count: Number(setObj.count || stickers.length),
      stickers,
    };
  } catch {
    return null;
  }
}

async function fetchStickerPacksInBatches(
  client: TelegramClient,
  userId: string,
  sets: any[],
  maxStickers = 32,
  batchSize = 4
): Promise<any[]> {
  const packs: any[] = [];
  for (let i = 0; i < sets.length; i += batchSize) {
    const chunk = sets.slice(i, i + batchSize);
    const results = await Promise.all(
      chunk.map((s) => fetchTelegramStickerPackBySet(client, userId, s, maxStickers))
    );
    for (const pack of results) {
      if (pack) packs.push(pack);
    }
  }
  return packs;
}

app.get('/api/telegram/user/stickers', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, packs: [], error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        packs: [],
        error: '当前账号未在线连接 Telegram MTProto，无法拉取官方贴纸库',
      });
    }

    const client = connected.client;
    const allRes: any = await client.invoke(new Api.messages.GetAllStickers({ hash: returnBigInt(0) }));
    const installedSets: any[] = Array.isArray(allRes?.sets) ? allRes.sets : [];

    const seenSetIds = new Set<string>();
    const combinedSets: any[] = [];
    for (const s of installedSets) {
      const sid = String(s?.id || '');
      if (sid && !seenSetIds.has(sid)) {
        seenSetIds.add(sid);
        combinedSets.push(s);
      }
    }

    // Supplement with official Telegram featured sticker packs so users always have a rich default catalog
    try {
      const featuredRes: any = await client.invoke(
        new Api.messages.GetFeaturedStickers({ hash: returnBigInt(0) })
      );
      const featuredSets: any[] = Array.isArray(featuredRes?.sets) ? featuredRes.sets : [];
      for (const covered of featuredSets) {
        const rawSet = covered?.set || covered;
        const sid = String(rawSet?.id || '');
        if (sid && !seenSetIds.has(sid)) {
          seenSetIds.add(sid);
          combinedSets.push(rawSet);
        }
      }
    } catch {
      // ignore featured stickers fetch error and fall back to installed packs
    }

    if (combinedSets.length === 0) {
      return res.json({ ok: true, packs: [] });
    }

    const limitSets = combinedSets.slice(0, 18);
    const packs = await fetchStickerPacksInBatches(client, connected.userId, limitSets, 32, 4);

    return res.json({ ok: true, packs });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 400);
  }
});

// 20.3.1v2 Global Cloud Search Official Telegram Stickers & Sticker Sets
// Combines:
//   1) messages.SearchStickers (Telegram official global sticker search across all public packs)
//   2) messages.SearchStickerSets (official public sticker sets by title/shortName)
//   3) messages.GetEmojiKeywords + built-in multilingual map -> messages.GetStickers (emoji sticker search)
app.get('/api/telegram/user/stickers/search', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, packs: [], error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const q = String(req.query.q || '').trim();
    if (!q) {
      return res.json({ ok: true, packs: [] });
    }

    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        packs: [],
        error: '当前账号未在线连接 Telegram MTProto，无法搜索云端贴纸',
      });
    }

    const client = connected.client;
    const packs: any[] = [];
    const seenSetIds = new Set<string>();
    const existingDocIds = new Set<string>();

    const isDirectEmoji = /^\s*[\p{Extended_Pictographic}\uFE0F\u200D]+\s*$/u.test(q);
    const englishAlias = resolveStickerEnglishAlias(q);
    const searchLangs = /[\u4e00-\u9fff]/.test(q)
      ? ['zh-hans', 'zh-hant', 'zh', 'en']
      : ['en', 'zh-hans', 'zh'];

    const searchGlobalStickers = async (queryTerm: string, langs: string[], emoticon = '', limit = 48) => {
      try {
        const found: any = await client.invoke(
          new Api.messages.SearchStickers({
            emojis: false,
            q: queryTerm,
            emoticon,
            langCode: langs,
            offset: 0,
            limit,
            hash: returnBigInt(0),
          })
        );
        return Array.isArray(found?.stickers) ? found.stickers : [];
      } catch {
        return [];
      }
    };

    const searchStickerSets = async (queryTerm: string) => {
      try {
        const searchRes: any = await client.invoke(
          new Api.messages.SearchStickerSets({
            excludeFeatured: false,
            q: queryTerm,
            hash: returnBigInt(0),
          })
        );
        return Array.isArray(searchRes?.sets) ? searchRes.sets : [];
      } catch {
        return [];
      }
    };

    // Run primary global sticker search, public pack search, and official cloud emoji keyword lookup in parallel
    const [primaryGlobalDocs, primaryFoundSets, cloudEmoticons] = await Promise.all([
      searchGlobalStickers(isDirectEmoji ? '' : q, searchLangs, isDirectEmoji ? q.trim() : '', 48),
      searchStickerSets(q),
      resolveCloudEmojiKeywords(client, q),
    ]);

    const candidateEmoticons: string[] = [];
    for (const em of [...resolveStickerSearchEmoticons(q), ...cloudEmoticons]) {
      if (em && !candidateEmoticons.includes(em)) candidateEmoticons.push(em);
    }

    // Supplement with English alias global search (for Chinese queries when global packs are tagged in EN)
    // and GetStickers by matched official emoticons
    const [aliasGlobalDocs, aliasFoundSets, ...emojiStickersLists] = await Promise.all([
      englishAlias && englishAlias.toLowerCase() !== q.toLowerCase() && primaryGlobalDocs.length < 24
        ? searchGlobalStickers(englishAlias, ['en', 'zh-hans', 'zh'], '', 36)
        : Promise.resolve([]),
      englishAlias && englishAlias.toLowerCase() !== q.toLowerCase() && primaryFoundSets.length < 4
        ? searchStickerSets(englishAlias)
        : Promise.resolve([]),
      ...candidateEmoticons.slice(0, 2).map(async (emoticon) => {
        try {
          const emojiRes: any = await client.invoke(
            new Api.messages.GetStickers({
              emoticon,
              hash: returnBigInt(0),
            })
          );
          return {
            emoticon,
            docs: Array.isArray(emojiRes?.stickers) ? emojiRes.stickers : [],
          };
        } catch {
          return { emoticon, docs: [] as any[] };
        }
      }),
    ]);

    // 1. Collect global stickers returned by messages.SearchStickers
    const globalStickerItems: any[] = [];
    for (const doc of [...primaryGlobalDocs, ...aliasGlobalDocs]) {
      if (!doc || !doc.id || !doc.accessHash) continue;
      const docIdStr = String(doc.id);
      if (existingDocIds.has(docIdStr)) continue;
      const item = mapTelegramStickerDocToItem(doc, connected.userId, {
        id: '0',
        accessHash: '0',
        shortName: '',
      });
      if (item) {
        existingDocIds.add(docIdStr);
        globalStickerItems.push(item);
        if (globalStickerItems.length >= 60) break;
      }
    }
    if (globalStickerItems.length > 0) {
      packs.push({
        id: `cloud_global_${q}`,
        accessHash: '0',
        shortName: 'cloud_global',
        title: `全网搜索「${q}」`,
        count: globalStickerItems.length,
        stickers: globalStickerItems,
      });
    }

    // 2. Collect public Telegram sticker sets matched by SearchStickerSets
    const candidateSets: any[] = [];
    for (const covered of [...primaryFoundSets, ...aliasFoundSets]) {
      const rawSet = covered?.set || covered;
      const sid = String(rawSet?.id || '');
      if (sid && !seenSetIds.has(sid)) {
        seenSetIds.add(sid);
        candidateSets.push(rawSet);
      }
    }
    if (candidateSets.length > 0) {
      const fetched = await fetchStickerPacksInBatches(
        client,
        connected.userId,
        candidateSets.slice(0, 8),
        24,
        4
      );
      for (const pack of fetched) {
        const dedupedStickers = (pack.stickers || []).filter((st: any) => {
          const did = String(st?.docId || '');
          if (!did || existingDocIds.has(did)) return false;
          existingDocIds.add(did);
          return true;
        });
        if (dedupedStickers.length > 0) {
          packs.push({
            ...pack,
            stickers: dedupedStickers,
          });
        }
      }
    }

    // 3. Collect emoticon cloud stickers from messages.GetStickers
    for (const { emoticon, docs } of emojiStickersLists) {
      const emojiStickers = docs
        .filter((doc: any) => doc && doc.id && doc.accessHash && !existingDocIds.has(String(doc.id)))
        .slice(0, 28)
        .map((doc: any) =>
          mapTelegramStickerDocToItem(doc, connected.userId, {
            id: '0',
            accessHash: '0',
            shortName: '',
          })
        )
        .filter(Boolean);

      for (const st of emojiStickers) {
        existingDocIds.add(String(st.docId));
      }

      if (emojiStickers.length > 0) {
        packs.push({
          id: `cloud_emoji_${emoticon}`,
          accessHash: '0',
          shortName: `cloud_emoji_${emoticon}`,
          title: `${emoticon} 云端关联贴纸`,
          count: emojiStickers.length,
          stickers: emojiStickers,
        });
      }
    }

    return res.json({ ok: true, packs });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 400);
  }
});

// 20.3.1w Proxy Official Telegram Sticker Preview / Image from MTProto
app.get('/api/telegram/user/sticker/:setId/:docId', async (req: Request, res: Response) => {
  try {
    if (!isAllowedClientOrigin(req)) {
      return res.status(403).send('Forbidden');
    }
    if (!verifySignedTelegramResourceRequest(req) && !(req as any).auth) {
      return res.status(401).send('Unauthorized');
    }

    const { setId, docId } = req.params;
    const setAccessHash = String(req.query.setAccessHash || '');
    const shortName = String(req.query.shortName || '').trim();
    const accountId = typeof req.query.accountId === 'string' ? req.query.accountId.trim() : '';

    const primaryConnected = accountId ? resolveConnectedTelegramUser(accountId) : undefined;
    const candidates: ConnectedTelegramUser[] = [];
    if (primaryConnected) {
      candidates.push(primaryConnected);
    } else if (!accountId) {
      const uniqueConnected = Array.from(
        new Map(Array.from(connectedUserClients.values()).map((u) => [u.userId, u])).values()
      );
      if (uniqueConnected.length > 1) {
        return res.status(400).send('accountId is required in multi-account mode');
      }
      if (uniqueConnected.length === 1) {
        candidates.push(uniqueConnected[0]);
      }
    }
    if (candidates.length === 0) {
      return res.status(404).send('No active Telegram client connected');
    }

    const cacheAccountScope = accountId || `acc_tg_${candidates[0].userId}`;
    const cacheKey = `${cacheAccountScope}:${setId}:${docId}`;
    const now = Date.now();

    const cached = telegramStickerThumbCache.get(cacheKey, now);
    if (cached) {
      res.setHeader('Content-Type', cached.mime);
      res.setHeader('Cache-Control', 'private, max-age=3600');
      return res.send(cached.buffer);
    }

    for (const candidate of candidates) {
      if (!candidate.client) continue;
      try {
        let doc: any = getCachedTelegramStickerDoc(candidate.userId, docId);
        if (!doc && setId && setId !== '0' && setAccessHash && setAccessHash !== '0') {
          const setRes: any = await candidate.client.invoke(
            new Api.messages.GetStickerSet({
              stickerset: new Api.InputStickerSetID({
                id: returnBigInt(setId),
                accessHash: returnBigInt(setAccessHash),
              }),
              hash: 0,
            })
          );
          doc = (Array.isArray(setRes?.documents) ? setRes.documents : []).find(
            (d: any) => String(d?.id) === String(docId)
          );
        }
        if (!doc && shortName) {
          const setRes: any = await candidate.client.invoke(
            new Api.messages.GetStickerSet({
              stickerset: new Api.InputStickerSetShortName({ shortName }),
              hash: 0,
            })
          );
          doc = (Array.isArray(setRes?.documents) ? setRes.documents : []).find(
            (d: any) => String(d?.id) === String(docId)
          );
        }
        if (!doc) continue;

        const mimeType = String(doc.mimeType || '').toLowerCase();
        let buffer: Buffer | undefined;
        let outMime = 'image/webp';

        if (!mimeType || mimeType === 'image/webp' || mimeType === 'image/png' || mimeType === 'image/jpeg') {
          buffer = (await candidate.client.downloadMedia(doc, {})) as Buffer;
          outMime = mimeType || 'image/webp';
        } else if (Array.isArray(doc.thumbs) && doc.thumbs.length > 0) {
          const validThumbs = doc.thumbs.filter((t: any) => t && t.className !== 'PhotoPathSize');
          const bestThumb = validThumbs[validThumbs.length - 1];
          if (bestThumb) {
            buffer = (await candidate.client.downloadMedia(doc, { thumb: bestThumb })) as Buffer;
            outMime = 'image/webp';
          }
        }

        if (buffer && Buffer.isBuffer(buffer) && buffer.length > 0) {
          telegramStickerThumbCache.set(
            cacheKey,
            {
              buffer,
              mime: outMime,
              expiresAt: now + 3600 * 1000,
            },
            now
          );
          res.setHeader('Content-Type', outMime);
          res.setHeader('Cache-Control', 'private, max-age=3600');
          return res.send(buffer);
        }
      } catch {
        // try next candidate
      }
    }

    return res.status(404).send('Sticker not found');
  } catch {
    return res.status(404).send('Sticker not found');
  }
});

// 20.3.1x Send Real Official Telegram Sticker via messages.SendMedia
app.post('/api/telegram/user/send-sticker', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const {
      chatId,
      docId,
      accessHash,
      fileReferenceBase64,
      setId,
      setAccessHash,
      shortName,
      replyToMsgId,
      emoji,
      packTitle,
      thumbUrl,
      isVideo: reqIsVideo,
      replyTo,
      id: clientMsgId,
    } = req.body || {};

    if (!chatId || !docId || !accessHash) {
      return res.status(400).json({ ok: false, error: '目标会话与官方贴纸文档参数不能为空' });
    }

    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        error: '当前账号未在线连接 Telegram MTProto，无法发送官方贴纸',
      });
    }

    const client = connected.client;
    const effectiveAccountId = `acc_tg_${connected.userId}`;
    const canonicalChatId =
      String(chatId).startsWith('tg_') || String(chatId).startsWith('chat_') ? String(chatId) : `tg_${chatId}`;
    const cleanEmoji = String(emoji || '').trim();
    const stickerFallbackText = cleanEmoji ? `${cleanEmoji} [贴纸]` : '🖼️ 贴纸';
    markOutboundMessageSent(canonicalChatId, stickerFallbackText, effectiveAccountId);
    if (stickerFallbackText !== '🖼️ 贴纸') {
      markOutboundMessageSent(canonicalChatId, '🖼️ 贴纸', effectiveAccountId);
    }

    const { inputPeer } = await resolveTelegramInputPeer(client, chatId, connected.userId);

    const invokeSendSticker = async (fileRefBuf: Buffer) => {
      return await client.invoke(
        new Api.messages.SendMedia({
          peer: inputPeer,
          ...(replyToMsgId
            ? { replyTo: new Api.InputReplyToMessage({ replyToMsgId: Number(replyToMsgId) }) }
            : {}),
          media: new Api.InputMediaDocument({
            id: new Api.InputDocument({
              id: returnBigInt(String(docId)),
              accessHash: returnBigInt(String(accessHash)),
              fileReference: fileRefBuf,
            }),
          }),
          message: '',
          randomId: generateRandomLong(),
        })
      );
    };

    let updates: any;
    try {
      updates = await invokeSendSticker(Buffer.from(String(fileReferenceBase64 || ''), 'base64'));
    } catch (sendErr: any) {
      const msg = String(sendErr?.errorMessage || sendErr?.message || '');
      const cleanShortName = typeof shortName === 'string' ? shortName.trim() : '';
      if (
        msg.includes('FILE_REFERENCE_EXPIRED') &&
        ((setId && setId !== '0' && setAccessHash && setAccessHash !== '0') || cleanShortName)
      ) {
        const refreshedSet: any = await client.invoke(
          new Api.messages.GetStickerSet({
            stickerset:
              setId && setId !== '0' && setAccessHash && setAccessHash !== '0'
                ? new Api.InputStickerSetID({
                    id: returnBigInt(String(setId)),
                    accessHash: returnBigInt(String(setAccessHash)),
                  })
                : new Api.InputStickerSetShortName({ shortName: cleanShortName }),
            hash: 0,
          })
        );
        const refreshedDoc: any = (Array.isArray(refreshedSet?.documents) ? refreshedSet.documents : []).find(
          (d: any) => String(d?.id) === String(docId)
        );
        if (!refreshedDoc || !Buffer.isBuffer(refreshedDoc.fileReference)) {
          throw sendErr;
        }
        updates = await invokeSendSticker(refreshedDoc.fileReference);
      } else {
        throw sendErr;
      }
    }

    let telegramMessageId: number | undefined;
    let sentMessageObj: any = null;
    if (typeof updates?.id === 'number') {
      telegramMessageId = updates.id;
    } else if (Array.isArray(updates?.updates)) {
      for (const u of updates.updates) {
        if (typeof u?.id === 'number' && u.className === 'UpdateMessageID') {
          telegramMessageId = u.id;
        }
        if (typeof u?.message?.id === 'number') {
          telegramMessageId = u.message.id;
          sentMessageObj = u.message;
          break;
        }
      }
    }

    if (telegramMessageId) {
      markOutboundTelegramMessageIdSent(canonicalChatId, telegramMessageId, effectiveAccountId);
    }

    const now = Date.now();
    const savedMsgId =
      typeof clientMsgId === 'string' && clientMsgId.trim()
        ? clientMsgId.trim()
        : telegramMessageId
          ? buildTelegramRealtimeMessageId(connected.userId, canonicalChatId, telegramMessageId)
          : `msg_sticker_${now}_${Math.random().toString(36).slice(2, 6)}`;

    const signedMediaUrl = telegramMessageId
      ? signTelegramResourceUrl(
          `/api/telegram/user/media/${encodeURIComponent(canonicalChatId)}/${telegramMessageId}?accountId=${encodeURIComponent(effectiveAccountId)}`
        )
      : '';
    const extracted = sentMessageObj ? extractTelegramMediaFields(sentMessageObj, canonicalChatId, effectiveAccountId) : null;
    const isVideoSticker = extracted ? extracted.isVideo : Boolean(reqIsVideo);
    const isImageSticker = extracted ? extracted.isImage : !isVideoSticker;
    const resolvedText = extracted?.text || stickerFallbackText;
    const resolvedImageUrl = extracted?.imageUrl || (isImageSticker ? (String(thumbUrl || '').trim() || signedMediaUrl) : '');
    const resolvedVideoUrl = extracted?.videoUrl || (isVideoSticker ? signedMediaUrl : '');
    const resolvedCaption = packTitle && cleanEmoji ? `${cleanEmoji} · ${packTitle}` : resolvedText;

    await upsertSyncedMessageToDb(
      {
        id: savedMsgId,
        telegramMessageId,
        chatId: canonicalChatId,
        accountId: effectiveAccountId,
        sender: 'me',
        senderName: '我方',
        text: resolvedText,
        isImage: isImageSticker,
        imageUrl: resolvedImageUrl,
        imageCaption: resolvedCaption,
        isVideo: isVideoSticker,
        videoUrl: resolvedVideoUrl,
        replyTo: replyTo || undefined,
        timestamp: new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
        createdAt: now,
        deliveryStatus: 'delivered',
      },
      canonicalChatId,
      effectiveAccountId
    );

    return res.json({
      ok: true,
      cloudSynced: true,
      deliveryStatus: 'delivered',
      id: savedMsgId,
      telegramMessageId,
      text: resolvedText,
      imageUrl: resolvedImageUrl || undefined,
      videoUrl: resolvedVideoUrl || undefined,
      isImage: isImageSticker,
      isVideo: isVideoSticker,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 400);
  }
});

export function resolveScopedTelegramTarget(
  req: Request,
  options?: { allowBot?: boolean; rawPhone?: unknown; rawUserId?: unknown }
):
  | { ok: true; accountId: string; isExplicit: boolean; isMaster: boolean; phone: string; userId: string }
  | { ok: false; status: number; code: string; error: string } {
  const scope = resolveScopedAccountFromRequest(req, { allowBot: options?.allowBot ?? false });
  if (!scope.ok) return scope;
  const isMaster = Boolean((req as any).auth?.session?.isMaster);
  const rawPhone = typeof options?.rawPhone === 'string' ? options.rawPhone.trim() : '';
  const rawUserId = typeof options?.rawUserId === 'string' ? options.rawUserId.trim() : '';

  if (!isMaster) {
    const expectedUid = scope.accountId.startsWith('acc_tg_') ? scope.accountId.replace(/^acc_tg_/, '').trim() : '';
    if (rawUserId && rawUserId !== scope.accountId && (!expectedUid || rawUserId !== expectedUid)) {
      return {
        ok: false,
        status: 403,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `无权跨账号操作目标用户 (${rawUserId})`,
      };
    }
    if (rawPhone) {
      const boundConn = resolveConnectedTelegramUser(scope.accountId);
      if (boundConn) {
        const normReqPhone = normalizePhoneNumber(rawPhone) || rawPhone;
        const normBoundPhone = boundConn.phone ? normalizePhoneNumber(boundConn.phone) || boundConn.phone : '';
        if (rawPhone !== boundConn.phone && normReqPhone !== normBoundPhone) {
          return {
            ok: false,
            status: 403,
            code: 'ACCOUNT_SCOPE_FORBIDDEN',
            error: '无权通过手机号跨账号操作其他会话',
          };
        }
      } else if (!expectedUid) {
        return {
          ok: false,
          status: 403,
          code: 'ACCOUNT_SCOPE_FORBIDDEN',
          error: '当前子账号未绑定个人 Telegram 账号，禁止通过手机号指定会话',
        };
      }
    }
    return {
      ok: true,
      accountId: scope.accountId,
      isExplicit: scope.isExplicit,
      isMaster: false,
      phone: '',
      userId: expectedUid,
    };
  }

  return {
    ok: true,
    accountId: scope.isExplicit ? scope.accountId : '',
    isExplicit: scope.isExplicit,
    isMaster: true,
    phone: rawPhone,
    userId: rawUserId,
  };
}

// Helper to resolve connected MTProto client by accountId / phone / userId
export function resolveConnectedTelegramUser(
  accountId?: string,
  phone?: string,
  userId?: string
): ConnectedTelegramUser | undefined {
  const rawAcc = String(accountId || '').trim();
  const rawPhone = String(phone || '').trim();
  const normPhone = rawPhone ? normalizePhoneNumber(rawPhone) : '';
  const accNormPhone =
    rawAcc.startsWith('phone:')
      ? normalizePhoneNumber(rawAcc.slice(6).trim())
      : rawAcc.startsWith('+') || /^00\d+$/.test(rawAcc)
        ? normalizePhoneNumber(rawAcc)
        : '';
  const rawUid =
    String(userId || '').trim() ||
    (rawAcc.startsWith('uid:')
      ? rawAcc.slice(4).trim()
      : rawAcc.startsWith('acc_tg_')
        ? rawAcc.replace(/^acc_tg_/, '').trim()
        : rawAcc.startsWith('tg_')
          ? rawAcc.replace(/^tg_/, '').trim()
          : !accNormPhone && /^\d+$/.test(rawAcc)
            ? rawAcc
            : '');

  let connected: ConnectedTelegramUser | undefined =
    (rawAcc ? connectedUserClients.get(rawAcc) : undefined) ||
    (rawPhone ? connectedUserClients.get(rawPhone) : undefined) ||
    (normPhone ? connectedUserClients.get(normPhone) : undefined) ||
    (accNormPhone ? connectedUserClients.get(accNormPhone) : undefined) ||
    (rawUid ? connectedUserClients.get(rawUid) : undefined) ||
    (rawUid ? connectedUserClients.get(`acc_tg_${rawUid}`) : undefined);

  if (!connected && (rawAcc || rawPhone || rawUid)) {
    connected = Array.from(connectedUserClients.values()).find(
      (u) =>
        (rawAcc &&
          (u.userId === rawAcc ||
            (rawUid && u.userId === rawUid) ||
            u.phone === rawAcc ||
            (accNormPhone && normalizePhoneNumber(u.phone) === accNormPhone) ||
            `acc_tg_${u.userId}` === rawAcc ||
            `tg_${u.userId}` === rawAcc)) ||
        (rawPhone && (u.phone === rawPhone || (normPhone && normalizePhoneNumber(u.phone) === normPhone))) ||
        (rawUid && u.userId === rawUid)
    );
  }
  return connected;
}

async function resolveTelegramInputUser(client: TelegramClient, peerRef: string): Promise<Api.InputUser | null> {
  const clean = String(peerRef || '').trim();
  if (!clean) return null;
  const candidates: any[] = [];
  const stripped = clean.replace(/^tg_/, '').replace(/^chat_contact_/, '');
  const isNumericId = /^-?\d+$/.test(stripped);
  if (isNumericId) {
    candidates.push(Number(stripped));
  }
  if (clean.startsWith('@')) {
    candidates.push(clean.slice(1));
  } else {
    candidates.push(clean);
  }
  const cleanLower = clean.replace(/^@/, '').toLowerCase();

  const matchUserFromList = (users: any[]): Api.InputUser | null => {
    for (const u of users) {
      if (!u || u.id === undefined) continue;
      const uidStr = String(u.id);
      const uname = typeof u.username === 'string' ? u.username.toLowerCase() : '';
      if ((isNumericId && uidStr === stripped) || (cleanLower && uname && uname === cleanLower)) {
        if (u.accessHash !== undefined && u.accessHash !== null) {
          return new Api.InputUser({
            userId: u.id,
            accessHash: u.accessHash,
          });
        }
      }
    }
    return null;
  };

  const tryResolve = async (): Promise<Api.InputUser | null> => {
    for (const cand of candidates) {
      try {
        const inputEntity = await client.getInputEntity(cand);
        if (inputEntity instanceof Api.InputUser) return inputEntity;
        if (inputEntity instanceof Api.InputPeerUser) {
          return new Api.InputUser({
            userId: inputEntity.userId,
            accessHash: inputEntity.accessHash,
          });
        }
      } catch {}
    }
    return null;
  };

  const direct = await tryResolve();
  if (direct) return direct;

  // Fallback 1: refresh contacts entity cache and scan returned users directly
  try {
    const contactsRes: any = await client.invoke(new Api.contacts.GetContacts({ hash: BigInt(0) as any }));
    const matched = matchUserFromList(Array.isArray(contactsRes?.users) ? contactsRes.users : []);
    if (matched) return matched;
  } catch {}
  const afterContacts = await tryResolve();
  if (afterContacts) return afterContacts;

  // Fallback 2: scan Telegram cloud blacklist so deleted-chat strangers can still be unblocked after restart
  try {
    let offset = 0;
    const pageLimit = 100;
    for (let page = 0; page < 10; page++) {
      const blockedRes: any = await client.invoke(
        new Api.contacts.GetBlocked({ offset, limit: pageLimit })
      );
      const users: any[] = Array.isArray(blockedRes?.users) ? blockedRes.users : [];
      const matched = matchUserFromList(users);
      if (matched) return matched;
      if (users.length < pageLimit) break;
      offset += pageLimit;
    }
  } catch {}
  const afterBlocked = await tryResolve();
  if (afterBlocked) return afterBlocked;

  // Fallback 3: resolve public @username via contacts.ResolveUsername
  if (!isNumericId && cleanLower) {
    try {
      const resolved: any = await client.invoke(
        new Api.contacts.ResolveUsername({ username: cleanLower })
      );
      const matched = matchUserFromList(Array.isArray(resolved?.users) ? resolved.users : []);
      if (matched) return matched;
    } catch {}
  }

  // Fallback 4: refresh recent dialogs entity cache (protected by FLOOD_WAIT breaker & in-flight dedup)
  try {
    await refreshDialogEntityCacheSafely(client, 80);
  } catch {}
  return await tryResolve();
}

async function fetchAllBlockedUsers(client: TelegramClient): Promise<{
  users: any[];
  blockedIdSet: Set<string>;
}> {
  const userMap = new Map<string, any>();
  const blockedIdSet = new Set<string>();
  const pageLimit = 100;
  let offset = 0;

  for (let page = 0; page < 10; page++) {
    const blockedRes: any = await client.invoke(
      new Api.contacts.GetBlocked({
        offset,
        limit: pageLimit,
      })
    );
    const users: any[] = Array.isArray(blockedRes?.users) ? blockedRes.users : [];
    const peers: any[] = Array.isArray(blockedRes?.blocked) ? blockedRes.blocked : [];
    for (const bp of peers) {
      if (bp?.peerId?.userId !== undefined) {
        blockedIdSet.add(String(bp.peerId.userId));
      }
    }
    for (const u of users) {
      if (u && u.id !== undefined) {
        const uid = String(u.id);
        userMap.set(uid, u);
        if (peers.length === 0) {
          blockedIdSet.add(uid);
        }
      }
    }
    const totalCount = typeof blockedRes?.count === 'number' ? blockedRes.count : undefined;
    offset += peers.length > 0 ? peers.length : users.length;
    if (users.length === 0 && peers.length === 0) break;
    if (totalCount !== undefined && offset >= totalCount) break;
    if (peers.length < pageLimit && users.length < pageLimit) break;
  }

  return {
    users: Array.from(userMap.values()),
    blockedIdSet,
  };
}

function pickAvatarBg(idStr: string): string {
  const palette = ['#2481cc', '#7bc862', '#e17076', '#a695e7', '#65aadd', '#ee7aae', '#6ec9cb', '#faa774'];
  let sum = 0;
  for (let i = 0; i < idStr.length; i++) sum += idStr.charCodeAt(i);
  return palette[sum % palette.length];
}

function mapTelegramUserToContact(
  u: any,
  ownerUserId?: string,
  options?: { isBlocked?: boolean; isContact?: boolean }
) {
  const uid = String(u.id);
  const fullName = `${u.firstName || ''} ${u.lastName || ''}`.trim() || (u.username ? `@${u.username}` : `TG_${uid}`);
  const uStatus = formatTelegramUserStatus(u);

  return {
    id: `tg_${uid}`,
    name: fullName,
    phone: u.phone ? (String(u.phone).startsWith('+') ? String(u.phone) : `+${u.phone}`) : undefined,
    username: u.username ? `@${u.username}` : undefined,
    avatarUrl: signTelegramResourceUrl(
      `/api/telegram/user/avatar/${encodeURIComponent(uid)}`,
      ownerUserId ? `acc_tg_${ownerUserId}` : ''
    ),
    avatarBg: pickAvatarBg(uid),
    avatarInitial: (fullName.slice(0, 2) || 'TG').toUpperCase(),
    status: uStatus.isOnline ? ('online' as const) : ('offline' as const),
    statusText: uStatus.statusText,
    ...(typeof options?.isBlocked === 'boolean' ? { isBlocked: options.isBlocked } : {}),
    ...(typeof options?.isContact === 'boolean' ? { isContact: options.isContact } : { isContact: Boolean(u.contact) }),
  };
}

// 20.3.2 Sync real contacts from Telegram Cloud MTProto (contacts.GetContacts + contacts.GetBlocked)
app.get('/api/telegram/user/contacts', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, cloudSynced: false, contacts: [], error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.json({
        ok: false,
        cloudSynced: false,
        contacts: [],
        error: '当前账号未在线连接 Telegram MTProto，请先登录后再同步云端通讯录',
      });
    }

    const [contactsSettled, blockedSettled] = await Promise.allSettled([
      connected.client.invoke(new Api.contacts.GetContacts({ hash: BigInt(0) as any })),
      fetchAllBlockedUsers(connected.client),
    ]);

    if (contactsSettled.status === 'rejected') {
      throw contactsSettled.reason;
    }

    const result: any = contactsSettled.value;
    const blockedIdSet =
      blockedSettled.status === 'fulfilled' ? blockedSettled.value.blockedIdSet : new Set<string>();

    const users: any[] = Array.isArray(result?.users) ? result.users : [];
    const contacts = users
      .filter((u) => u && !u.deleted && !u.self && String(u.id) !== connected.userId)
      .map((u) =>
        mapTelegramUserToContact(u, connected.userId, {
          isBlocked: blockedIdSet.has(String(u.id)),
          isContact: true,
        })
      );

    return res.json({ ok: true, cloudSynced: true, contacts });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 500);
  }
});

// 20.3.2.1 Search global Telegram users & contacts via MTProto (contacts.Search + contacts.ResolvePhone)
app.get('/api/telegram/user/contacts/search', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, contacts: [], error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const q = typeof req.query.q === 'string' ? req.query.q.trim() : '';
    if (!q) {
      return res.json({ ok: true, contacts: [] });
    }
    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        contacts: [],
        error: '当前账号未在线连接 Telegram MTProto，无法执行云端用户搜索',
      });
    }

    const compactPhone = q.replace(/[\s\-\(\)\.]/g, '');
    const isInternationalPhoneQuery = /^(\+|00)\d{6,15}$/.test(compactPhone);

    const [searchSettled, phoneSettled, blockedSettled] = await Promise.allSettled([
      connected.client.invoke(
        new Api.contacts.Search({
          q: q.replace(/^@/, ''),
          limit: 20,
        })
      ),
      isInternationalPhoneQuery
        ? connected.client.invoke(
            new Api.contacts.ResolvePhone({
              phone: normalizePhoneNumber(compactPhone),
            })
          )
        : Promise.resolve(null),
      fetchAllBlockedUsers(connected.client),
    ]);

    if (searchSettled.status === 'rejected' && (!isInternationalPhoneQuery || phoneSettled.status === 'rejected')) {
      throw searchSettled.reason;
    }

    const searchUsers: any[] =
      searchSettled.status === 'fulfilled' && Array.isArray((searchSettled.value as any)?.users)
        ? (searchSettled.value as any).users
        : [];
    const phoneUsers: any[] =
      phoneSettled.status === 'fulfilled' && Array.isArray((phoneSettled.value as any)?.users)
        ? (phoneSettled.value as any).users
        : [];
    const blockedIdSet =
      blockedSettled.status === 'fulfilled' ? blockedSettled.value.blockedIdSet : new Set<string>();

    const seen = new Set<string>();
    const combinedUsers = [...phoneUsers, ...searchUsers];
    const contacts = combinedUsers
      .filter((u) => {
        if (!u || u.deleted || u.self || String(u.id) === connected.userId) return false;
        const uid = String(u.id);
        if (seen.has(uid)) return false;
        seen.add(uid);
        return true;
      })
      .map((u) =>
        mapTelegramUserToContact(u, connected.userId, {
          isContact: Boolean(u.contact),
          isBlocked: blockedIdSet.has(String(u.id)),
        })
      );

    return res.json({ ok: true, cloudSynced: true, contacts });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 500);
  }
});

// 20.3.2.2 Fetch real Telegram Blacklist / Blocked Users via MTProto (contacts.GetBlocked paginated)
app.get('/api/telegram/user/contacts/blocked', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, blocked: [], error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        blocked: [],
        error: '当前账号未在线连接 Telegram MTProto，无法拉取黑名单列表',
      });
    }

    const { users, blockedIdSet } = await fetchAllBlockedUsers(connected.client);
    const blocked = users
      .filter((u) => u && !u.deleted && (blockedIdSet.size === 0 || blockedIdSet.has(String(u.id))))
      .map((u) => mapTelegramUserToContact(u, connected.userId, { isBlocked: true }));

    return res.json({ ok: true, cloudSynced: true, blocked });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 500);
  }
});

// 20.3.3 Add/Import real contact to Telegram Cloud MTProto (contacts.ImportContacts / contacts.AddContact)
app.post('/api/telegram/user/contacts/add', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, cloudSynced: false, error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const { name, phone, username, chatId } = req.body || {};
    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        cloudSynced: false,
        error: '当前账号未在线连接 Telegram MTProto，无法添加至云端通讯录。请先登录个人 Telegram 账号。',
      });
    }

    const cleanName = typeof name === 'string' ? name.trim() : '';
    const nameParts = cleanName ? cleanName.split(/\s+/) : ['Telegram'];
    const firstName = nameParts[0] || 'Telegram';
    const lastName = nameParts.slice(1).join(' ');
    const cleanPhone = typeof phone === 'string' ? phone.trim() : '';
    const cleanUsername = typeof username === 'string' ? username.trim().replace(/^@/, '') : '';
    const cleanChatId = typeof chatId === 'string' ? chatId.trim() : '';

    if (!cleanPhone && !cleanUsername && !cleanChatId) {
      return res.status(400).json({
        ok: false,
        cloudSynced: false,
        error: '同步至 Telegram 云端通讯录需要提供目标会话 ID、手机号或 @用户名',
      });
    }

    if (cleanPhone) {
      const compactPhone = cleanPhone.replace(/[\s\-\(\)\.]/g, '');
      if (!/^(\+|00)\d{6,15}$/.test(compactPhone)) {
        return res.status(400).json({
          ok: false,
          cloudSynced: false,
          error: '手机号必须包含国际区号（例如 +8613800000000）',
        });
      }
    }

    let resolvedUser: any = null;

    if (cleanPhone) {
      const normalized = normalizePhoneNumber(cleanPhone) || cleanPhone;
      const importRes: any = await connected.client.invoke(
        new Api.contacts.ImportContacts({
          contacts: [
            new Api.InputPhoneContact({
              clientId: BigInt(Date.now()) as any,
              phone: normalized,
              firstName,
              lastName,
            }),
          ],
        })
      );
      if (Array.isArray(importRes?.users) && importRes.users.length > 0) {
        resolvedUser = importRes.users[0];
      }
    }

    if (!resolvedUser && cleanUsername) {
      try {
        const inputUser = await resolveTelegramInputUser(connected.client, cleanUsername);
        if (inputUser) {
          const addRes: any = await connected.client.invoke(
            new Api.contacts.AddContact({
              id: inputUser,
              firstName,
              lastName,
              phone: cleanPhone || '',
              addPhonePrivacyException: false,
            })
          );
          if (Array.isArray(addRes?.users) && addRes.users.length > 0) {
            resolvedUser = addRes.users[0];
          } else {
            resolvedUser = await connected.client.getEntity(cleanUsername);
          }
        }
      } catch (uErr: any) {
        if (!cleanChatId) {
          return res.status(400).json({
            ok: false,
            cloudSynced: false,
            error: `无法通过用户名 @${cleanUsername} 添加联系人: ${uErr?.message || '用户不存在'}`,
          });
        }
      }
    }

    if (!resolvedUser && cleanChatId) {
      try {
        const inputUser = await resolveTelegramInputUser(connected.client, cleanChatId);
        if (inputUser) {
          const addRes: any = await connected.client.invoke(
            new Api.contacts.AddContact({
              id: inputUser,
              firstName,
              lastName,
              phone: cleanPhone || '',
              addPhonePrivacyException: false,
            })
          );
          if (Array.isArray(addRes?.users) && addRes.users.length > 0) {
            resolvedUser = addRes.users[0];
          } else {
            resolvedUser = await connected.client.getEntity(inputUser);
          }
        }
      } catch (cErr: any) {
        return res.status(400).json({
          ok: false,
          cloudSynced: false,
          error: `无法添加该会话用户至云端通讯录: ${formatTelegramError(cErr)}`,
        });
      }
    }

    if (!resolvedUser) {
      return res.status(404).json({
        ok: false,
        cloudSynced: false,
        error: cleanChatId
          ? '无法定位该 Telegram 用户，暂未能添加至云端通讯录'
          : '该手机号尚未注册 Telegram，或对方隐私设置禁止通过手机号匹配添加（可尝试填写对方 @用户名）',
      });
    }

    const contact = mapTelegramUserToContact(resolvedUser, connected.userId, { isContact: true });
    return res.json({ ok: true, cloudSynced: true, contact });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 500);
  }
});

// 20.3.3.1 Delete contact from Telegram Cloud MTProto (contacts.DeleteContacts)
app.post('/api/telegram/user/contacts/delete', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const chatId = req.body?.chatId;
    if (!chatId) {
      return res.status(400).json({ ok: false, error: '联系人 ID 为必填项' });
    }
    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto' });
    }
    const inputUser = await resolveTelegramInputUser(connected.client, String(chatId));
    if (!inputUser) {
      return res.status(400).json({ ok: false, error: '未能解析该联系人的 Telegram 输入用户对象' });
    }
    await connected.client.invoke(
      new Api.contacts.DeleteContacts({
        id: [inputUser],
      })
    );
    return res.json({ ok: true, cloudSynced: true });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 500);
  }
});

