// 20.3.4 Create real group / supergroup on Telegram Cloud MTProto
app.post('/api/telegram/user/create-group', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, cloudSynced: false, error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const title = typeof req.body?.title === 'string' ? req.body.title.trim() : '';
    const memberPeers: Array<{ id?: string; username?: string; phone?: string }> = Array.isArray(req.body?.memberPeers)
      ? req.body.memberPeers
      : [];

    if (!title) {
      return res.status(400).json({ ok: false, cloudSynced: false, error: '群组名称不能为空' });
    }

    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        cloudSynced: false,
        error: '当前账号未在线连接 Telegram MTProto，无法在云端创建真实群组',
      });
    }

    const resolvedInputUsers: Api.InputUser[] = [];
    for (const peer of memberPeers) {
      let inputUser: Api.InputUser | null = null;
      if (peer.username) inputUser = await resolveTelegramInputUser(connected.client, peer.username);
      if (!inputUser && peer.id && /^tg_-?\d+$/.test(peer.id)) {
        inputUser = await resolveTelegramInputUser(connected.client, peer.id);
      }
      if (!inputUser && peer.phone) {
        inputUser = await resolveTelegramInputUser(connected.client, peer.phone);
      }
      if (inputUser) resolvedInputUsers.push(inputUser);
    }

    let rawDialogId = '';
    let invitedCount = 0;
    if (resolvedInputUsers.length > 0) {
      const createRes: any = await connected.client.invoke(
        new Api.messages.CreateChat({
          users: resolvedInputUsers,
          title,
        })
      );
      const chatObj = createRes?.updates?.chats?.[0] || createRes?.chats?.[0];
      if (!chatObj?.id) {
        throw new Error('Telegram 云端未返回新群组 ID');
      }
      rawDialogId = chatObj.className === 'Channel' ? `-100${chatObj.id}` : `-${chatObj.id}`;
      invitedCount = resolvedInputUsers.length;
    } else {
      const superRes: any = await connected.client.invoke(
        new Api.channels.CreateChannel({
          megagroup: true,
          title,
          about: '',
        })
      );
      const chObj = superRes?.chats?.[0];
      if (!chObj?.id) {
        throw new Error('Telegram 云端未返回新超级群组 ID');
      }
      rawDialogId = `-100${chObj.id}`;
    }

    const chat = {
      id: `tg_${rawDialogId}`,
      accountId: `acc_tg_${connected.userId}`,
      title,
      avatarUrl: signTelegramResourceUrl(
        `/api/telegram/user/avatar/${encodeURIComponent(rawDialogId)}`,
        `acc_tg_${connected.userId}`
      ),
      avatarBg: pickAvatarBg(rawDialogId),
      avatarInitial: title.slice(0, 2).toUpperCase(),
      isGroup: true,
      memberCount: invitedCount + 1,
      lastMessage: invitedCount > 0 ? `已在 Telegram 云端建群并邀请 ${invitedCount} 位成员` : '已在 Telegram 云端创建超级群组',
      lastTime: '刚刚',
      unreadCount: 0,
      sourceLang: 'Auto',
      targetLang: 'Auto',
    };

    return res.json({ ok: true, cloudSynced: true, invitedCount, chat });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 500);
  }
});

// 20.3.5 Create real broadcast channel on Telegram Cloud MTProto
app.post('/api/telegram/user/create-channel', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, cloudSynced: false, error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const title = typeof req.body?.title === 'string' ? req.body.title.trim() : '';
    const description = typeof req.body?.description === 'string' ? req.body.description.trim() : '';
    const channelType = req.body?.channelType === 'private' ? 'private' : 'public';
    const customLink = typeof req.body?.customLink === 'string' ? req.body.customLink.trim() : '';

    if (!title) {
      return res.status(400).json({ ok: false, cloudSynced: false, error: '频道名称不能为空' });
    }

    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        cloudSynced: false,
        error: '当前账号未在线连接 Telegram MTProto，无法在云端创建真实频道',
      });
    }

    const createRes: any = await connected.client.invoke(
      new Api.channels.CreateChannel({
        broadcast: true,
        title,
        about: description,
      })
    );
    const createdChannel = createRes?.chats?.[0];
    if (!createdChannel?.id) {
      throw new Error('Telegram 云端未返回新频道 ID');
    }

    const rawDialogId = `-100${createdChannel.id}`;
    let finalUsername: string | undefined;
    let usernameWarning: string | undefined;

    if (channelType === 'public' && customLink) {
      const cleanUsername = customLink
        .replace(/^https?:\/\/t\.me\//i, '')
        .replace(/^t\.me\//i, '')
        .replace(/^@/, '')
        .trim();
      if (cleanUsername) {
        try {
          await connected.client.invoke(
            new Api.channels.UpdateUsername({
              channel: new Api.InputChannel({
                channelId: createdChannel.id,
                accessHash: createdChannel.accessHash,
              }),
              username: cleanUsername,
            })
          );
          finalUsername = `@${cleanUsername}`;
        } catch (uErr: any) {
          const msg = String(uErr?.message || uErr || '');
          usernameWarning = msg.includes('USERNAME_OCCUPIED')
            ? `频道已在云端创建，但公开链接 @${cleanUsername} 已被占用`
            : msg.includes('USERNAME_INVALID')
              ? `频道已在云端创建，但公开链接 @${cleanUsername} 格式无效`
              : msg.includes('CHANNELS_ADMIN_PUBLIC_TOO_MUCH')
                ? '频道已在云端创建，但该账号名下公开频道数量已达 Telegram 上限'
                : `频道已在云端创建，但设置公开链接失败: ${msg}`;
        }
      }
    }

    const chat = {
      id: `tg_${rawDialogId}`,
      accountId: `acc_tg_${connected.userId}`,
      title,
      avatarUrl: signTelegramResourceUrl(
        `/api/telegram/user/avatar/${encodeURIComponent(rawDialogId)}`,
        `acc_tg_${connected.userId}`
      ),
      avatarBg: pickAvatarBg(rawDialogId),
      avatarInitial: title.slice(0, 2).toUpperCase(),
      isGroup: false,
      isChannel: true,
      description,
      username: finalUsername,
      memberCount: 1,
      lastMessage: '已在 Telegram 云端创建频道，可立即发布广播消息',
      lastTime: '刚刚',
      unreadCount: 0,
      sourceLang: 'Auto',
      targetLang: 'Auto',
    };

    return res.json({ ok: true, cloudSynced: true, chat, usernameWarning });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 500);
  }
});

function parseTelegramInviteOrPublicLink(rawInput: string):
  | { kind: 'invite'; hash: string; url: string }
  | { kind: 'public'; username: string; url: string }
  | null {
  const trimmed = String(rawInput || '').trim();
  if (!trimmed) return null;

  // 1. tg://join?invite=HASH or tg://resolve?domain=USERNAME
  if (/^tg:\/\//i.test(trimmed)) {
    try {
      const u = new URL(trimmed);
      const host = u.hostname.toLowerCase();
      if (host === 'join') {
        const invite = (u.searchParams.get('invite') || '').trim();
        if (invite) return { kind: 'invite', hash: invite, url: `https://t.me/+${invite}` };
      }
      if (host === 'resolve') {
        const domain = (u.searchParams.get('domain') || '').trim().replace(/^@/, '');
        if (domain && /^[a-zA-Z0-9_]{4,64}$/.test(domain)) {
          return { kind: 'public', username: domain, url: `https://t.me/${domain}` };
        }
      }
    } catch {
      return null;
    }
    return null;
  }

  // 2. https://t.me/+HASH / t.me/joinchat/HASH / t.me/username
  const normalizedUrl = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
  try {
    const u = new URL(normalizedUrl);
    const hostname = u.hostname.toLowerCase();
    if (!['t.me', 'telegram.me', 'telegram.dog'].includes(hostname)) return null;
    const segments = u.pathname.split('/').filter(Boolean);
    if (segments.length === 0) return null;

    if (segments[0].startsWith('+') && segments[0].length > 1) {
      const hash = segments[0].slice(1);
      return { kind: 'invite', hash, url: `https://t.me/+${hash}` };
    }
    if (segments[0].toLowerCase() === 'joinchat' && segments[1]) {
      return { kind: 'invite', hash: segments[1], url: `https://t.me/+${segments[1]}` };
    }

    const reserved = new Set(['s', 'addstickers', 'addemoji', 'proxy', 'socks', 'share', 'iv', 'bg', 'setlanguage', 'addtheme', 'c']);
    const candidate = segments[0].replace(/^@/, '');
    if (!reserved.has(candidate.toLowerCase()) && /^[a-zA-Z0-9_]{4,64}$/.test(candidate)) {
      return { kind: 'public', username: candidate, url: `https://t.me/${candidate}` };
    }
  } catch {
    return null;
  }
  return null;
}

function formatTelegramChatEntityToUiChat(entity: any, connectedUserId: string, fallbackMemberCount?: number) {
  const accountId = `acc_tg_${connectedUserId}`;
  const isChannelEntity = entity?.className === 'Channel' || entity?.className === 'ChannelForbidden';
  const isBasicChatEntity = entity?.className === 'Chat' || entity?.className === 'ChatForbidden';
  const isUserEntity = entity?.className === 'User';
  const rawDialogId = isChannelEntity
    ? `-100${entity.id}`
    : isBasicChatEntity
      ? `-${entity.id}`
      : `${entity.id}`;
  const title = isUserEntity
    ? ([entity.firstName, entity.lastName].filter(Boolean).join(' ').trim() || (entity.username ? `@${entity.username}` : `User ${entity.id}`))
    : String(entity?.title || entity?.username || `Chat ${entity?.id || ''}`).trim();
  const isMegagroup = Boolean(entity?.megagroup);
  const isBroadcast = Boolean(entity?.broadcast && !isMegagroup);
  const isGroup = isBasicChatEntity || isMegagroup;

  return {
    id: `tg_${rawDialogId}`,
    accountId,
    title,
    avatarUrl: signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(rawDialogId)}`, accountId),
    avatarBg: pickAvatarBg(rawDialogId),
    avatarInitial: (title || 'TG').slice(0, 2).toUpperCase(),
    isGroup,
    isChannel: isBroadcast,
    username: entity?.username ? `@${entity.username}` : undefined,
    memberCount: typeof entity?.participantsCount === 'number' ? entity.participantsCount : fallbackMemberCount,
    lastMessage: isBroadcast ? '已打开频道' : isGroup ? '已加入群组' : '已打开对话',
    lastTime: '刚刚',
    unreadCount: 0,
    sourceLang: 'Auto',
    targetLang: 'Auto',
  };
}

// 20.3.5.1 Preview Telegram Group/Channel Invite Link (CheckChatInvite / ResolveUsername)
app.post('/api/telegram/user/invite/preview', requireTenantAuth, async (req: Request, res: Response) => {
  let scopedAccountId = '';
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
    }
    const accountId = scope.accountId;
    scopedAccountId = accountId;
    const rawUrl = typeof req.body?.url === 'string' ? req.body.url.trim() : '';
    const parsed = parseTelegramInviteOrPublicLink(rawUrl);
    if (!parsed) {
      return res.status(400).json({ ok: false, error: '无效的 Telegram 群组或频道链接' });
    }
    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto' });
    }

    if (parsed.kind === 'invite') {
      const inviteRes: any = await connected.client.invoke(new Api.messages.CheckChatInvite({ hash: parsed.hash }));
      const cls = inviteRes?.className;
      if ((cls === 'ChatInviteAlready' || cls === 'ChatInvitePeek') && inviteRes.chat) {
        const chat = formatTelegramChatEntityToUiChat(inviteRes.chat, connected.userId);
        return res.json({
          ok: true,
          kind: 'invite',
          url: parsed.url,
          alreadyMember: cls === 'ChatInviteAlready',
          title: chat.title,
          isChannel: Boolean(chat.isChannel),
          isGroup: Boolean(chat.isGroup),
          participantsCount: chat.memberCount,
          chat,
        });
      }
      return res.json({
        ok: true,
        kind: 'invite',
        url: parsed.url,
        alreadyMember: false,
        requestNeeded: Boolean(inviteRes?.requestNeeded),
        title: String(inviteRes?.title || 'Telegram 群组'),
        about: String(inviteRes?.about || ''),
        participantsCount: typeof inviteRes?.participantsCount === 'number' ? inviteRes.participantsCount : undefined,
        isGroup: Boolean(!inviteRes?.broadcast || inviteRes?.megagroup),
        isChannel: Boolean(inviteRes?.broadcast && !inviteRes?.megagroup),
      });
    }

    const resolved: any = await connected.client.invoke(new Api.contacts.ResolveUsername({ username: parsed.username }));
    const targetEntity = resolved?.chats?.[0] || resolved?.users?.[0];
    if (!targetEntity) {
      return res.status(404).json({ ok: false, error: `未找到公开链接 @${parsed.username} 对应的群组或频道` });
    }
    const chat = formatTelegramChatEntityToUiChat(targetEntity, connected.userId);
    const alreadyMember = targetEntity?.className === 'User' ? true : targetEntity?.left === false;
    return res.json({
      ok: true,
      kind: 'public',
      url: parsed.url,
      alreadyMember,
      title: chat.title,
      about: String(targetEntity?.about || ''),
      participantsCount: chat.memberCount,
      isChannel: Boolean(chat.isChannel),
      isGroup: Boolean(chat.isGroup),
      chat,
    });
  } catch (err: any) {
    return await handleMtprotoRouteError(res, err, {
      accountId: scopedAccountId,
    }, 400);
  }
});

// 20.3.5.2 Join Telegram Group/Channel via Invite Hash or Public Username
app.post('/api/telegram/user/invite/join', requireTenantAuth, async (req: Request, res: Response) => {
  const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
  if (!scope.ok) {
    return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
  }
  const accountId = scope.accountId;
  const rawUrl = typeof req.body?.url === 'string' ? req.body.url.trim() : '';
  const parsed = parseTelegramInviteOrPublicLink(rawUrl);
  if (!parsed) {
    return res.status(400).json({ ok: false, error: '无效的 Telegram 群组或频道链接' });
  }
  const connected = resolveConnectedTelegramUser(accountId);
  if (!connected || !connected.client) {
    return res.status(400).json({ ok: false, error: '当前账号未在线连接 Telegram MTProto' });
  }

  try {
    if (parsed.kind === 'invite') {
      const importRes: any = await connected.client.invoke(new Api.messages.ImportChatInvite({ hash: parsed.hash }));
      const chatEntity = importRes?.chats?.[0] || importRes?.updates?.chats?.[0];
      const chat = chatEntity ? formatTelegramChatEntityToUiChat(chatEntity, connected.userId) : undefined;
      return res.json({ ok: true, alreadyMember: false, chat });
    }

    const resolved: any = await connected.client.invoke(new Api.contacts.ResolveUsername({ username: parsed.username }));
    const targetEntity = resolved?.chats?.[0] || resolved?.users?.[0];
    if (!targetEntity) {
      return res.status(404).json({ ok: false, error: `未找到 @${parsed.username}` });
    }
    if (targetEntity.className === 'Channel' && targetEntity.left !== false) {
      const joinRes: any = await connected.client.invoke(new Api.channels.JoinChannel({ channel: targetEntity }));
      const joinedEntity = joinRes?.chats?.[0] || targetEntity;
      return res.json({ ok: true, alreadyMember: false, chat: formatTelegramChatEntityToUiChat(joinedEntity, connected.userId) });
    }
    return res.json({ ok: true, alreadyMember: true, chat: formatTelegramChatEntityToUiChat(targetEntity, connected.userId) });
  } catch (err: any) {
    const msg = String(err?.errorMessage || err?.message || err || '');
    if (msg.includes('USER_ALREADY_PARTICIPANT') && parsed.kind === 'invite') {
      try {
        const checkRes: any = await connected.client.invoke(new Api.messages.CheckChatInvite({ hash: parsed.hash }));
        if (checkRes?.chat) {
          return res.json({ ok: true, alreadyMember: true, chat: formatTelegramChatEntityToUiChat(checkRes.chat, connected.userId) });
        }
      } catch {
        // fall through to standard error handler
      }
    }
    if (msg.includes('INVITE_REQUEST_SENT')) {
      return res.json({ ok: true, requestSent: true });
    }
    return await handleMtprotoRouteError(res, err, { accountId }, 400);
  }
});

// 20.3.6 Real Telegram VoIP Call Signaling via MTProto (messages.GetDhConfig + phone.RequestCall / DiscardCall)
interface ActiveTelegramCallSession {
  callId: string;
  tgCallId: any;
  accessHash: any;
  client: TelegramClient;
  accountId: string;
  userId?: string;
  ownerUserId?: string;
  status: 'ringing' | 'accepted' | 'discarded' | 'failed';
  startedAt: number;
  acceptedAt?: number;
  discardedAt?: number;
  endedReason?: string;
}
export const CALL_DISCARDED_TTL_MS = 30 * 1000;
export const CALL_RINGING_MAX_TTL_MS = 5 * 60 * 1000;
export const CALL_ACCEPTED_MAX_TTL_MS = 4 * 60 * 60 * 1000;
export const MAX_ACTIVE_TELEGRAM_CALLS = 100;
export const activeTelegramCalls = new Map<string, ActiveTelegramCallSession>();

export function pruneActiveTelegramCalls(now = Date.now()): number {
  let removed = 0;
  for (const [id, session] of activeTelegramCalls.entries()) {
    if (!session) {
      activeTelegramCalls.delete(id);
      removed++;
      continue;
    }
    const isExpiredDiscarded =
      (session.status === 'discarded' || session.status === 'failed') &&
      now - (session.discardedAt || session.startedAt) >= CALL_DISCARDED_TTL_MS;
    const isStaleRinging =
      session.status === 'ringing' && now - session.startedAt >= CALL_RINGING_MAX_TTL_MS;
    const isStaleAccepted = now - session.startedAt >= CALL_ACCEPTED_MAX_TTL_MS;
    if (isExpiredDiscarded || isStaleRinging || isStaleAccepted) {
      activeTelegramCalls.delete(id);
      removed++;
    }
  }
  while (activeTelegramCalls.size > MAX_ACTIVE_TELEGRAM_CALLS) {
    const oldestId = activeTelegramCalls.keys().next().value;
    if (oldestId === undefined) break;
    activeTelegramCalls.delete(oldestId);
    removed++;
  }
  return removed;
}

function isCallSessionOwnedByCaller(
  callSession: ActiveTelegramCallSession,
  req: Request,
  callerAccountId: string
): boolean {
  const authContext = (req as any).auth;
  const authSession = authContext?.session;
  if (!authSession || authSession.isBot || authContext?.isBot) return false;
  if (!authSession.isMaster && callSession.ownerUserId && authSession.userId && callSession.ownerUserId !== authSession.userId) {
    return false;
  }
  const callerVariants = getScopedAccountIdVariants(callerAccountId);
  const callVariants = getScopedAccountIdVariants(callSession.accountId);
  if (callSession.userId) {
    const uid = String(callSession.userId).trim();
    if (uid) {
      callVariants.push(uid, `acc_tg_${uid}`);
    }
  }
  return callerVariants.some((v) => callVariants.includes(v));
}

function bufferToBigInt(buf: Buffer): bigint {
  if (!buf || buf.length === 0) return 0n;
  return BigInt('0x' + buf.toString('hex'));
}

function bigIntTo256ByteBuffer(val: bigint): Buffer {
  let hex = val.toString(16);
  if (hex.length % 2 === 1) hex = '0' + hex;
  const raw = Buffer.from(hex, 'hex');
  if (raw.length === 256) return raw;
  if (raw.length > 256) return raw.subarray(raw.length - 256);
  const out = Buffer.alloc(256, 0);
  raw.copy(out, 256 - raw.length);
  return out;
}

function modPowBigInt(base: bigint, exp: bigint, mod: bigint): bigint {
  if (mod === 1n) return 0n;
  let result = 1n;
  let b = ((base % mod) + mod) % mod;
  let e = exp;
  while (e > 0n) {
    if (e & 1n) result = (result * b) % mod;
    e >>= 1n;
    b = (b * b) % mod;
  }
  return result;
}

function ensurePhoneCallListener(client: TelegramClient) {
  if ((client as any)._hasTgProCallListener) return;
  (client as any)._hasTgProCallListener = true;
  client.addEventHandler((update: any) => {
    try {
      if (update?.className !== 'UpdatePhoneCall' && !(update instanceof Api.UpdatePhoneCall)) return;
      const phoneCall = update.phoneCall;
      if (!phoneCall?.id) return;
      const tgIdStr = String(phoneCall.id);
      for (const session of activeTelegramCalls.values()) {
        if (String(session.tgCallId) === tgIdStr) {
          if (phoneCall.className === 'PhoneCallAccepted' || phoneCall.className === 'PhoneCall') {
            session.status = 'accepted';
            if (!session.acceptedAt) session.acceptedAt = Date.now();
          } else if (phoneCall.className === 'PhoneCallDiscarded') {
            session.status = 'discarded';
            session.discardedAt = Date.now();
            const reasonClass = phoneCall.reason?.className || '';
            session.endedReason =
              reasonClass === 'PhoneCallDiscardReasonBusy'
                ? '对方忙线或已拒接'
                : reasonClass === 'PhoneCallDiscardReasonMissed'
                  ? '对方未接听'
                  : '通话已挂断';
            const cleanupTimer = setTimeout(() => {
              if (activeTelegramCalls.get(session.callId) === session) {
                activeTelegramCalls.delete(session.callId);
              }
            }, CALL_DISCARDED_TTL_MS);
            cleanupTimer.unref?.();
          } else if (phoneCall.className === 'PhoneCallWaiting') {
            session.status = 'ringing';
          }
        }
      }
    } catch {}
  }, new Raw({}));
}

app.post('/api/telegram/user/call/start', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
    }
    const accountId = scope.accountId;
    const authContext = (req as any).auth;
    const { chatId, username, phone } = req.body || {};

    const connected = resolveConnectedTelegramUser(accountId);
    if (!connected || !connected.client) {
      return res.status(400).json({
        ok: false,
        cloudSynced: false,
        error: '当前账号未在线连接 Telegram MTProto，无法向对方客户端发起真实语音呼叫',
      });
    }

    let inputUser: Api.InputUser | null = null;
    if (chatId) inputUser = await resolveTelegramInputUser(connected.client, String(chatId));
    if (!inputUser && username) inputUser = await resolveTelegramInputUser(connected.client, String(username));
    if (!inputUser && phone) inputUser = await resolveTelegramInputUser(connected.client, String(phone));

    if (!inputUser) {
      return res.status(400).json({
        ok: false,
        cloudSynced: false,
        error: '未匹配到有效的 Telegram 个人用户（仅支持向真实私聊联系人发起 1 对 1 语音呼叫，不支持群组/频道）',
      });
    }

    ensurePhoneCallListener(connected.client);

    const dhConfig: any = await connected.client.invoke(
      new Api.messages.GetDhConfig({ version: 0, randomLength: 256 })
    );
    const pBuf = Buffer.isBuffer(dhConfig?.p) ? dhConfig.p : Buffer.from(dhConfig?.p || []);
    const pBig = bufferToBigInt(pBuf);
    const gBig = BigInt(dhConfig?.g || 2);
    const aBig = bufferToBigInt(crypto.randomBytes(256));
    const gABuf = bigIntTo256ByteBuffer(modPowBigInt(gBig, aBig, pBig));
    const gAHash = crypto.createHash('sha256').update(gABuf).digest();

    const callRes: any = await connected.client.invoke(
      new Api.phone.RequestCall({
        userId: inputUser,
        randomId: crypto.randomInt(1, 0x7fffffff),
        gAHash,
        protocol: new Api.PhoneCallProtocol({
          minLayer: 92,
          maxLayer: 92,
          udpP2p: true,
          udpReflector: true,
          libraryVersions: ['4.0.0'],
        }),
      })
    );

    const phoneCallObj = callRes?.phoneCall;
    if (!phoneCallObj?.id) {
      throw new Error('Telegram 云端未返回通话信令句柄');
    }

    const nowCall = Date.now();
    pruneActiveTelegramCalls(nowCall);
    const callId = `call_${String(phoneCallObj.id)}_${nowCall}`;
    const canonicalCallAccount = connected.userId ? `acc_tg_${connected.userId}` : accountId;
    activeTelegramCalls.set(callId, {
      callId,
      tgCallId: phoneCallObj.id,
      accessHash: phoneCallObj.accessHash,
      client: connected.client,
      accountId: canonicalCallAccount,
      userId: connected.userId,
      ownerUserId: authContext?.session?.userId,
      status: 'ringing',
      startedAt: nowCall,
    });

    return res.json({
      ok: true,
      cloudSynced: true,
      callId,
      tgCallId: String(phoneCallObj.id),
      status: 'ringing',
    });
  } catch (err: any) {
    const msg = String(err?.message || err || '发起 Telegram 语音呼叫失败');
    const friendly = msg.includes('USER_PRIVACY_RESTRICTED')
      ? '对方隐私设置限制了语音来电'
      : msg.includes('PARTICIPANT_VERSION_OUTDATED')
        ? '对方客户端版本不支持当前呼叫协议'
        : msg.includes('CALL_PROTOCOL_FLAGS_INVALID')
          ? '呼叫协议参数不受支持'
          : msg;
    return res.status(400).json({ ok: false, cloudSynced: false, error: friendly });
  }
});

app.get('/api/telegram/user/call/status/:callId', requireTenantAuth, (req: Request, res: Response) => {
  const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
  if (!scope.ok) {
    return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
  }
  const session = activeTelegramCalls.get(req.params.callId);
  if (!session) {
    return res.json({ ok: true, status: 'discarded', endedReason: '通话会话已结束', elapsedSeconds: 0 });
  }
  if (!isCallSessionOwnedByCaller(session, req, scope.accountId)) {
    return res.status(403).json({
      ok: false,
      code: 'CALL_OWNERSHIP_FORBIDDEN',
      error: '权限不足：无权查看不属于当前账号的语音通话状态',
    });
  }
  const elapsedSeconds = session.acceptedAt ? Math.max(0, Math.floor((Date.now() - session.acceptedAt) / 1000)) : 0;
  return res.json({
    ok: true,
    status: session.status,
    endedReason: session.endedReason,
    elapsedSeconds,
  });
});

app.post('/api/telegram/user/call/end', requireTenantAuth, async (req: Request, res: Response) => {
  try {
    const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
    if (!scope.ok) {
      return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
    }
    const callId = String(req.body?.callId || '');
    const duration = Number(req.body?.duration || 0);
    const session = activeTelegramCalls.get(callId);
    if (!session) {
      return res.json({ ok: true, cloudSynced: false });
    }
    if (!isCallSessionOwnedByCaller(session, req, scope.accountId)) {
      return res.status(403).json({
        ok: false,
        code: 'CALL_OWNERSHIP_FORBIDDEN',
        error: '权限不足：无权挂断不属于当前账号的语音通话',
      });
    }
    if (session.status !== 'discarded') {
      try {
        await session.client.invoke(
          new Api.phone.DiscardCall({
            peer: new Api.InputPhoneCall({
              id: session.tgCallId,
              accessHash: session.accessHash,
            }),
            duration: Math.max(0, Math.floor(duration)),
            reason: new Api.PhoneCallDiscardReasonHangup(),
            connectionId: BigInt(0) as any,
          })
        );
      } catch {}
      session.status = 'discarded';
      session.discardedAt = Date.now();
      session.endedReason = '已挂断';
    }
    const callCleanupTimer = setTimeout(() => activeTelegramCalls.delete(callId), CALL_DISCARDED_TTL_MS);
    callCleanupTimer.unref?.();
    return res.json({ ok: true, cloudSynced: true });
  } catch (err: any) {
    return res.status(500).json({ ok: false, error: err?.message || '挂断失败' });
  }
});

function parseTelegramReactions(m: any): {
  reactions?: Record<string, number>;
  myReactions?: string[];
} {
  const results = Array.isArray(m?.reactions?.results) ? m.reactions.results : [];
  if (results.length === 0) return {};
  const reactions: Record<string, number> = {};
  const myReactions: string[] = [];
  for (const rc of results) {
    const emoji = rc?.reaction?.emoticon ? String(rc.reaction.emoticon) : '';
    if (!emoji) continue;
    reactions[emoji] = Number(rc.count || 1);
    if (rc.chosenOrder !== undefined && rc.chosenOrder !== null) {
      myReactions.push(emoji);
    }
  }
  return {
    reactions: Object.keys(reactions).length > 0 ? reactions : undefined,
    myReactions: myReactions.length > 0 ? myReactions : undefined,
  };
}

function extractTelegramSenderPeerId(m: any): string {
  const fromId = m?.fromId;
  if (fromId?.userId) return String(fromId.userId);
  if (fromId?.channelId) return `-100${String(fromId.channelId)}`;
  if (fromId?.chatId) return `-${String(fromId.chatId)}`;
  if (m?.senderId) return String(m.senderId);
  if (m?.sender?.id) {
    const sid = String(m.sender.id);
    const cls = String(m.sender.className || '');
    if (cls === 'Channel' || cls === 'ChannelForbidden') return sid.startsWith('-100') ? sid : `-100${sid}`;
    if (cls === 'Chat' || cls === 'ChatForbidden') return sid.startsWith('-') ? sid : `-${sid}`;
    return sid;
  }
  return '';
}

function getTelegramMessageSenderName(m: any, isOut: boolean): string {
  if (isOut) return '';
  const postAuthor = typeof m?.postAuthor === 'string' ? m.postAuthor.trim() : '';
  if (postAuthor) return postAuthor;
  const sender = m?.sender;
  if (sender) {
    const full = [sender.firstName, sender.lastName].filter(Boolean).join(' ').trim() || sender.title || sender.username;
    if (full) return String(full);
  }
  return '';
}

// ==================== SENDER INFO BOUNDED LRU + SINGLE-FLIGHT + CONCURRENCY LIMITER ====================
export const TELEGRAM_SENDER_CACHE_MAX_ENTRIES = 5000;
export const TELEGRAM_SENDER_CACHE_POSITIVE_TTL_MS = 10 * 60 * 1000;
export const TELEGRAM_SENDER_CACHE_ERROR_TTL_MS = 15 * 1000;
export const TELEGRAM_SENDER_MAX_CONCURRENT = 4;

export interface TelegramSenderInfoResult {
  senderId: string;
  senderName: string;
  senderAvatarUrl?: string;
}

interface TelegramSenderCacheEntry {
  value: TelegramSenderInfoResult;
  expiresAt: number;
  isErrorFallback: boolean;
}

const telegramSenderInfoCache = new Map<string, TelegramSenderCacheEntry>();
const telegramSenderInFlight = new Map<string, Promise<TelegramSenderInfoResult>>();
const senderAccountLimiters = new Map<string, { active: number; waiters: Array<() => void> }>();
const senderCacheStats = {
  hitsTotal: 0,
  missesTotal: 0,
  singleFlightHitsTotal: 0,
  errorFallbacksTotal: 0,
  evictionsTotal: 0,
};

function acquireSenderSlot(accountScope: string): Promise<() => void> {
  let state = senderAccountLimiters.get(accountScope);
  if (!state) {
    state = { active: 0, waiters: [] };
    senderAccountLimiters.set(accountScope, state);
  }
  const makeRelease = () => {
    let released = false;
    return () => {
      if (released) return;
      released = true;
      const st = senderAccountLimiters.get(accountScope);
      if (!st) return;
      st.active = Math.max(0, st.active - 1);
      while (st.waiters.length > 0 && st.active < TELEGRAM_SENDER_MAX_CONCURRENT) {
        const next = st.waiters.shift()!;
        st.active += 1;
        next();
      }
      if (st.active === 0 && st.waiters.length === 0) {
        senderAccountLimiters.delete(accountScope);
      }
    };
  };
  if (state.active < TELEGRAM_SENDER_MAX_CONCURRENT) {
    state.active += 1;
    return Promise.resolve(makeRelease());
  }
  return new Promise<() => void>((resolve) => {
    state!.waiters.push(() => resolve(makeRelease()));
  });
}

function getCachedSenderEntry(key: string, now = Date.now()): TelegramSenderInfoResult | null {
  const entry = telegramSenderInfoCache.get(key);
  if (!entry) return null;
  if (entry.expiresAt <= now) {
    telegramSenderInfoCache.delete(key);
    return null;
  }
  // LRU touch
  telegramSenderInfoCache.delete(key);
  telegramSenderInfoCache.set(key, entry);
  return entry.value;
}

function setCachedSenderEntry(
  key: string,
  value: TelegramSenderInfoResult,
  isErrorFallback: boolean,
  now = Date.now()
): void {
  const ttl = isErrorFallback
    ? TELEGRAM_SENDER_CACHE_ERROR_TTL_MS
    : TELEGRAM_SENDER_CACHE_POSITIVE_TTL_MS;
  if (telegramSenderInfoCache.has(key)) {
    telegramSenderInfoCache.delete(key);
  } else if (telegramSenderInfoCache.size >= TELEGRAM_SENDER_CACHE_MAX_ENTRIES) {
    pruneTelegramSenderCache(now);
    while (telegramSenderInfoCache.size >= TELEGRAM_SENDER_CACHE_MAX_ENTRIES) {
      const oldest = telegramSenderInfoCache.keys().next().value;
      if (oldest === undefined) break;
      telegramSenderInfoCache.delete(oldest);
      senderCacheStats.evictionsTotal += 1;
    }
  }
  telegramSenderInfoCache.set(key, { value, expiresAt: now + ttl, isErrorFallback });
}

export function pruneTelegramSenderCache(now = Date.now()): number {
  let removed = 0;
  for (const [k, entry] of telegramSenderInfoCache.entries()) {
    if (!entry || entry.expiresAt <= now) {
      telegramSenderInfoCache.delete(k);
      removed += 1;
    }
  }
  return removed;
}

export function invalidateTelegramSenderCache(accountId: string, peerId: string): void {
  const cleanPeer = String(peerId || '').replace(/^tg_/, '').trim();
  if (!cleanPeer) return;
  const accKey = normalizeMsgDbAccountKey(accountId);
  telegramSenderInfoCache.delete(`${accKey}:${cleanPeer}`);
  if (accountId) {
    telegramSenderInfoCache.delete(`${accountId}:${cleanPeer}`);
  }
}

export function clearTelegramSenderCacheForTesting(): void {
  telegramSenderInfoCache.clear();
  telegramSenderInFlight.clear();
  senderAccountLimiters.clear();
}

export function getTelegramSenderCacheStats() {
  let activeSlots = 0;
  let queuedSlots = 0;
  for (const st of senderAccountLimiters.values()) {
    activeSlots += st.active;
    queuedSlots += st.waiters.length;
  }
  return {
    entries: telegramSenderInfoCache.size,
    maxEntries: TELEGRAM_SENDER_CACHE_MAX_ENTRIES,
    inFlightSingleFlight: telegramSenderInFlight.size,
    activeSlots,
    queuedSlots,
    maxConcurrentPerAccount: TELEGRAM_SENDER_MAX_CONCURRENT,
    ...senderCacheStats,
  };
}

registerPerformanceQueueStatsProvider('senderInfoCache', getTelegramSenderCacheStats);

function buildTelegramSenderInfoResult(
  m: any,
  resolvedId: string,
  entity: any,
  accountId: string
): { result: TelegramSenderInfoResult; hasName: boolean } {
  const postAuthor = typeof m?.postAuthor === 'string' ? m.postAuthor.trim() : '';
  const entityName = entity
    ? [entity.firstName, entity.lastName].filter(Boolean).join(' ').trim() ||
      entity.title ||
      entity.username ||
      ''
    : '';
  const senderName = String(postAuthor || entityName || '').trim();
  const senderAvatarUrl =
    resolvedId && accountId && accountId !== 'acc_telegram_bot'
      ? signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(resolvedId)}`, accountId)
      : undefined;
  return {
    result: {
      senderId: resolvedId,
      senderName,
      ...(senderAvatarUrl ? { senderAvatarUrl } : {}),
    },
    hasName: Boolean(senderName),
  };
}

export function peekTelegramMessageSenderInfoSync(
  m: any,
  isOut: boolean,
  accountId: string,
  connObj?: any,
  canonicalChatId?: string,
  rawChatId?: string
): { hit: boolean; info: TelegramSenderInfoResult } {
  if (isOut) return { hit: true, info: { senderId: '', senderName: '' } };
  const peerId = extractTelegramSenderPeerId(m);
  const accKey = normalizeMsgDbAccountKey(accountId || 'global');
  const globalKey = peerId ? `${accKey}:${peerId}` : '';

  const matchedDlg: any =
    connObj && Array.isArray(connObj.dialogs)
      ? connObj.dialogs.find(
          (d: any) => d && (String(d.id) === canonicalChatId || String(d.rawId || '') === rawChatId)
        )
      : undefined;
  const dlgTitle =
    matchedDlg &&
    !matchedDlg.isGroup &&
    !matchedDlg.isChannel &&
    typeof matchedDlg.title === 'string' &&
    !/^Telegram\s*\(/i.test(matchedDlg.title.trim())
      ? matchedDlg.title.trim()
      : '';

  if (globalKey) {
    const globalHit = getCachedSenderEntry(globalKey);
    if (globalHit) {
      senderCacheStats.hitsTotal += 1;
      if (!globalHit.senderName && dlgTitle) {
        return { hit: true, info: { ...globalHit, senderName: dlgTitle } };
      }
      return { hit: true, info: globalHit };
    }
  }

  if (m?.sender) {
    const resolvedId = peerId || (m.sender?.id ? String(m.sender.id) : '');
    const { result, hasName } = buildTelegramSenderInfoResult(m, resolvedId, m.sender, accountId);
    if (resolvedId && hasName && globalKey) {
      setCachedSenderEntry(globalKey, result, false);
    }
    return { hit: true, info: result };
  }

  const cleanRaw = String(rawChatId || '').replace(/^tg_/, '').trim();
  const fallbackId = peerId || (cleanRaw && !cleanRaw.startsWith('-') ? cleanRaw : '');
  const postAuthor = typeof m?.postAuthor === 'string' ? m.postAuthor.trim() : '';
  const fallbackName = String(postAuthor || dlgTitle || '').trim();
  const fallbackAvatarUrl =
    fallbackId && accountId && accountId !== 'acc_telegram_bot'
      ? signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(fallbackId)}`, accountId)
      : undefined;
  return {
    hit: false,
    info: {
      senderId: fallbackId,
      senderName: fallbackName,
      ...(fallbackAvatarUrl ? { senderAvatarUrl: fallbackAvatarUrl } : {}),
    },
  };
}

export async function resolveTelegramMessageSenderInfo(
  m: any,
  isOut: boolean,
  accountId: string,
  senderCache?: Map<string, { senderId: string; senderName: string; senderAvatarUrl?: string }>
): Promise<{ senderId: string; senderName: string; senderAvatarUrl?: string }> {
  if (isOut) return { senderId: '', senderName: '' };
  const peerId = extractTelegramSenderPeerId(m);
  const accKey = normalizeMsgDbAccountKey(accountId || 'global');
  const globalKey = peerId ? `${accKey}:${peerId}` : '';

  if (peerId && senderCache?.has(peerId)) {
    senderCacheStats.hitsTotal += 1;
    return senderCache.get(peerId)!;
  }
  if (globalKey) {
    const globalHit = getCachedSenderEntry(globalKey);
    if (globalHit) {
      senderCacheStats.hitsTotal += 1;
      senderCache?.set(peerId, globalHit);
      return globalHit;
    }
  }

  // Fast inline path when GramJS already hydrated m.sender (zero RPC needed)
  if (m?.sender) {
    const resolvedId = peerId || (m.sender?.id ? String(m.sender.id) : '');
    const { result, hasName } = buildTelegramSenderInfoResult(m, resolvedId, m.sender, accountId);
    if (resolvedId && hasName) {
      senderCache?.set(resolvedId, result);
      if (globalKey) setCachedSenderEntry(globalKey, result, false);
    }
    return result;
  }

  if (globalKey && telegramSenderInFlight.has(globalKey)) {
    senderCacheStats.singleFlightHitsTotal += 1;
    const coalesced = await telegramSenderInFlight.get(globalKey)!;
    if (peerId) senderCache?.set(peerId, coalesced);
    return coalesced;
  }

  senderCacheStats.missesTotal += 1;
  const runResolve = async (): Promise<TelegramSenderInfoResult> => {
    let senderEntity: any = null;
    let rpcErrored = false;
    if (typeof m?.getSender === 'function') {
      const release = await acquireSenderSlot(accKey);
      try {
        senderEntity = await scheduleTelegramRpc(accKey, 'P2', 'resolveSender.getSender', () =>
          withTelegramTimeout(m.getSender(), 5000, '解析发送者信息超时')
        );
      } catch {
        rpcErrored = true;
      } finally {
        release();
      }
    }
    const resolvedId = peerId || (senderEntity?.id ? String(senderEntity.id) : '');
    const { result, hasName } = buildTelegramSenderInfoResult(m, resolvedId, senderEntity, accountId);
    if (resolvedId) {
      const isFallback = rpcErrored || !hasName;
      if (isFallback) senderCacheStats.errorFallbacksTotal += 1;
      if (senderCache && hasName) {
        senderCache.set(resolvedId, result);
      }
      if (globalKey) {
        setCachedSenderEntry(globalKey, result, isFallback);
      }
    }
    return result;
  };

  if (!globalKey) {
    return await runResolve();
  }
  const promise = runResolve().finally(() => {
    if (telegramSenderInFlight.get(globalKey) === promise) {
      telegramSenderInFlight.delete(globalKey);
    }
  });
  telegramSenderInFlight.set(globalKey, promise);
  const finalResult = await promise;
  if (peerId && finalResult.senderName) {
    senderCache?.set(peerId, finalResult);
  }
  return finalResult;
}

function extractTelegramMediaFields(
  m: any,
  canonicalId: string,
  accountId: string,
  groupServiceOverride?: { text: string; systemEventType: TelegramSystemEventType } | null
) {
  const callInfo = extractTelegramPhoneCallFields(m);
  if (callInfo) {
    return {
      text: callInfo.text,
      isAudio: false,
      audioDuration: 0,
      audioUrl: '',
      isImage: false,
      imageUrl: '',
      imageCaption: '',
      isVideo: false,
      videoDuration: 0,
      videoWidth: undefined,
      videoHeight: undefined,
      videoUrl: '',
      isFile: false,
      fileName: undefined,
      fileSize: undefined,
      fileUrl: '',
      isCall: true,
      callType: callInfo.callType,
      callDuration: callInfo.callDuration,
      isVideoCall: callInfo.isVideoCall,
      telegramCallId: callInfo.telegramCallId,
    };
  }

  const groupSvcInfo = groupServiceOverride ?? extractTelegramGroupServiceFields(m);
  if (groupSvcInfo) {
    return {
      text: groupSvcInfo.text,
      systemEventType: groupSvcInfo.systemEventType,
      isAudio: false,
      audioDuration: 0,
      audioUrl: '',
      isImage: false,
      imageUrl: '',
      imageCaption: '',
      isVideo: false,
      videoDuration: 0,
      videoWidth: undefined,
      videoHeight: undefined,
      videoUrl: '',
      isFile: false,
      fileName: undefined,
      fileSize: undefined,
      fileUrl: '',
    };
  }

  const media = m?.media;
  const doc = media?.document;
  const attrs: any[] = Array.isArray(doc?.attributes) ? doc.attributes : [];
  const audioAttr = attrs.find((a) => a.className === 'DocumentAttributeAudio');
  const videoAttr = attrs.find((a) => a.className === 'DocumentAttributeVideo');
  const stickerAttr = attrs.find((a) => a.className === 'DocumentAttributeSticker');
  const filenameAttr = attrs.find((a) => a.className === 'DocumentAttributeFilename');
  const animatedAttr = attrs.find((a) => a.className === 'DocumentAttributeAnimated');
  const mimeType = String(doc?.mimeType || '').toLowerCase();

  const mediaProxyUrl = signTelegramResourceUrl(
    `/api/telegram/user/media/${encodeURIComponent(canonicalId)}/${Number(m.id)}?accountId=${encodeURIComponent(accountId)}`
  );

  const isVideo = Boolean(videoAttr || animatedAttr || mimeType.startsWith('video/'));
  const isAudio = Boolean(!isVideo && (audioAttr || mimeType.startsWith('audio/')));
  const isStickerThumb = Boolean(stickerAttr && mimeType.includes('tgsticker'));
  const isStickerImage = Boolean(
    stickerAttr && (!mimeType || mimeType === 'image/webp' || mimeType === 'image/png' || mimeType === 'image/jpeg')
  );
  const isImage = Boolean(
    !isVideo &&
      !isAudio &&
      (m.photo ||
        media?.className === 'MessageMediaPhoto' ||
        isStickerImage ||
        isStickerThumb ||
        (mimeType.startsWith('image/') && !mimeType.includes('svg')))
  );
  const isFile = Boolean(doc && !isImage && !isVideo && !isAudio);

  const fileName = filenameAttr?.fileName
    ? String(filenameAttr.fileName)
    : stickerAttr
      ? `sticker_${m.id}.webp`
      : isFile
        ? `file_${m.id}`
        : undefined;
  const fileSize = doc?.size ? formatTelegramFileSize(Number(doc.size)) : undefined;

  const caption = String(m.message || '').trim();
  let text = caption;
  if (!text) {
    if (isAudio) text = '🎤 语音消息';
    else if (isVideo) text = videoAttr?.roundMessage ? '🎥 视频消息' : '🎬 视频';
    else if (stickerAttr) text = stickerAttr.alt ? `${stickerAttr.alt} [贴纸]` : '🖼️ 贴纸';
    else if (isImage) text = '🖼️ 图片消息';
    else if (isFile) text = `📎 ${fileName || '文件附件'}`;
    else if (media?.className === 'MessageMediaGeo' || media?.className === 'MessageMediaGeoLive') text = '📍 位置信息';
    else if (media?.className === 'MessageMediaContact') {
      text = `👤 联系人名片: ${[media.firstName, media.lastName, media.phoneNumber].filter(Boolean).join(' ')}`.trim();
    } else if (media?.className === 'MessageMediaPoll') {
      text = `📊 投票: ${media.poll?.question?.text || media.poll?.question || ''}`.trim();
    } else if (media?.className === 'MessageMediaWebPage') {
      text = media.webpage?.title || media.webpage?.url || '🔗 网页链接';
    } else if (media) {
      text = '📎 媒体消息';
    }
  }

  return {
    text,
    isAudio,
    audioDuration: isAudio ? Number(audioAttr?.duration || 0) : 0,
    audioUrl: isAudio ? mediaProxyUrl : '',
    isImage,
    imageUrl: isImage ? (isStickerThumb ? `${mediaProxyUrl}&thumb=1` : mediaProxyUrl) : '',
    imageCaption: isImage ? caption : '',
    isVideo,
    videoDuration: isVideo ? Number(videoAttr?.duration || 0) : 0,
    videoWidth: isVideo ? Number(videoAttr?.w || 0) : undefined,
    videoHeight: isVideo ? Number(videoAttr?.h || 0) : undefined,
    videoUrl: isVideo ? mediaProxyUrl : '',
    isFile,
    fileName,
    fileSize,
    fileUrl: isFile ? `${mediaProxyUrl}&download=1` : '',
  };
}

// Sync real historical chat messages from Telegram Cloud MTProto (supports offsetId pagination & cloud search)
export async function syncTelegramUserChatMessages(
  client: TelegramClient,
  rawChatId: string,
  limit = 40,
  explicitUserId?: string,
  options?: {
    offsetId?: number;
    search?: string;
    throwOnError?: boolean;
    filter?: Api.TypeMessagesFilter;
    metaOut?: { rawCount: number; minRawId?: number; totalCount?: number };
  }
) {
  try {
    const rawId = rawChatId.startsWith('tg_') ? rawChatId.replace('tg_', '') : rawChatId;
    let peerTarget: any = rawId;
    if (/^-?\d+$/.test(rawId)) {
      try {
        peerTarget = Number(rawId);
      } catch {
        peerTarget = rawId;
      }
    }

    const iterParams: any = { limit };
    if (options?.offsetId && Number.isInteger(options.offsetId) && options.offsetId > 0) {
      iterParams.offsetId = options.offsetId;
    }
    if (options?.search && options.search.trim()) {
      iterParams.search = options.search.trim();
    }
    if (options?.filter) {
      iterParams.filter = options.filter;
    }

    const syncStartedAt = Date.now();
    const accountId = `acc_tg_${explicitUserId || (client as any)._selfId || 'user'}`;
    const canonicalId =
      rawId === 'me' && explicitUserId
        ? `tg_${explicitUserId}`
        : rawChatId.startsWith('tg_')
          ? rawChatId
          : `tg_${rawChatId}`;

    const messages = await scheduleTelegramRpc(accountId, 'P1', 'messages.GetHistory', () =>
      client.getMessages(peerTarget, iterParams)
    );
    const rawMessagesList = Array.isArray(messages) ? messages : [];
    const rawIds = rawMessagesList
      .map((m: any) => Number(m?.id || 0))
      .filter((id: number) => Number.isInteger(id) && id > 0);
    if (options?.metaOut) {
      options.metaOut.rawCount = rawMessagesList.length;
      options.metaOut.minRawId = rawIds.length > 0 ? Math.min(...rawIds) : undefined;
      options.metaOut.totalCount =
        typeof (messages as any)?.total === 'number' ? (messages as any).total : undefined;
    }

    const allFetched: any[] = [...rawMessagesList];

    // On initial sync (not pagination/search/filter), also include up to 5 latest pinned messages so older pinned banners appear
    if (!options?.offsetId && !options?.search && !options?.filter) {
      try {
        const pinnedMsgs = await scheduleTelegramRpc(accountId, 'P1', 'messages.GetHistory.pinned', () =>
          client.getMessages(peerTarget, {
            limit: 5,
            filter: new Api.InputMessagesFilterPinned(),
          })
        );
        if (Array.isArray(pinnedMsgs)) {
          const existingIds = new Set(allFetched.map((m) => Number(m?.id)).filter(Boolean));
          for (const pm of pinnedMsgs) {
            if (pm && pm.id && !existingIds.has(Number(pm.id))) {
              allFetched.push(pm);
            }
          }
        }
      } catch {}
    }

    if (allFetched.length === 0) {
      if (!options?.offsetId && !options?.search && !options?.filter) {
        try {
          const altChatId = canonicalId.startsWith('tg_') ? canonicalId.replace(/^tg_/, '') : `tg_${canonicalId}`;
          const accVariants = getScopedAccountIdVariants(accountId);
          const accPlaceholders = accVariants.map(() => '?').join(', ');
          await enqueueMessageDbWrite({
            priority: 'LOW',
            kind: 'sync_empty_clear',
            accountId,
            chatId: canonicalId,
            snapshotTakenAt: syncStartedAt,
            exec: async () => {
              if (isMessageBlockedByDeleteBarrier(accountId, canonicalId, undefined, syncStartedAt)) {
                return;
              }
              await db
                .prepare(
                  `DELETE FROM messages
                   WHERE (chat_id = ? OR chat_id = ?)
                     AND account_id IN (${accPlaceholders})
                     AND COALESCE(delivery_status, 'delivered') = 'delivered'
                     AND COALESCE(created_at, 0) <= ?`
                )
                .run(canonicalId, altChatId, ...accVariants, syncStartedAt);
            },
          });
        } catch {}
      }
      return [];
    }

    const msgById = new Map<number, any>();
    const missingReplyIds = new Set<number>();
    for (const m of allFetched) {
      if (!m || !m.id) continue;
      msgById.set(Number(m.id), m);
    }
    for (const m of allFetched) {
      const replyId = Number((m as any)?.replyTo?.replyToMsgId || 0);
      if (replyId > 0 && !msgById.has(replyId)) {
        missingReplyIds.add(replyId);
      }
    }
    if (missingReplyIds.size > 0) {
      try {
        const extraReplies = await scheduleTelegramRpc(accountId, 'P1', 'messages.GetMessages.replies', () =>
          client.getMessages(peerTarget, {
            ids: Array.from(missingReplyIds).slice(0, 30),
          })
        );
        for (const rm of extraReplies || []) {
          if (rm && rm.id) msgById.set(Number(rm.id), rm);
        }
      } catch {}
    }

    const synced: any[] = [];
    const senderInfoCache = new Map<string, { senderId: string; senderName: string; senderAvatarUrl?: string }>();
    const groupMemberNameCache = new Map<string, string>();
    for (const m of allFetched) {
      if (!m) continue;
      const resolvedGroupSvc =
        m?.action && !extractTelegramPhoneCallFields(m)
          ? await resolveTelegramGroupServiceFields(m, client, groupMemberNameCache)
          : null;
      const mediaParsed = extractTelegramMediaFields(m, canonicalId, accountId, resolvedGroupSvc);
      if (!mediaParsed.text && !m.media && !mediaParsed.isCall && !mediaParsed.systemEventType) continue;

      const isOut = Boolean(m.out);
      const createdAt = m.date ? m.date * 1000 : Date.now();
      const timestamp = new Date(createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
      const internalId = `tg_cloud_${m.id}_${createdAt}_${accountId}`;
      const senderInfo = await resolveTelegramMessageSenderInfo(m, isOut, accountId, senderInfoCache);
      const senderName = senderInfo.senderName;

      let replyTo: { id: string; telegramMessageId?: number; senderName?: string; text: string } | undefined = undefined;
      const replyToId = Number((m as any).replyTo?.replyToMsgId || 0);
      if (replyToId > 0) {
        const targetReply = msgById.get(replyToId);
        const quoteText = String((m as any).replyTo?.quoteText || '').trim();
        const replySummary = quoteText || (targetReply ? summarizeTelegramDialogMedia(targetReply) : `消息 #${replyToId}`);
        let replySenderName = '回复消息';
        if (targetReply) {
          if (targetReply.out) {
            replySenderName = '我';
          } else {
            const replySenderInfo = await resolveTelegramMessageSenderInfo(targetReply, false, accountId, senderInfoCache);
            replySenderName = replySenderInfo.senderName || '回复消息';
          }
        }
        replyTo = {
          id: targetReply
            ? `tg_cloud_${targetReply.id}_${(targetReply.date || 0) * 1000}_${accountId}`
            : buildTelegramRealtimeMessageId(String(explicitUserId || (client as any)._selfId || 'user'), canonicalId, replyToId),
          telegramMessageId: replyToId,
          senderName: replySenderName,
          text: replySummary,
        };
      }

      const { reactions, myReactions } = parseTelegramReactions(m);
      const fwdFrom = (m as any).fwdFrom;
      const forwardFrom = fwdFrom?.fromName ? String(fwdFrom.fromName) : undefined;

      synced.push({
        id: internalId,
        telegramMessageId: Number(m.id),
        chatId: canonicalId,
        accountId,
        sender: mediaParsed.systemEventType ? 'system' : (isOut ? 'me' : 'peer'),
        ...(mediaParsed.systemEventType ? { systemEventType: mediaParsed.systemEventType } : {}),
        senderName,
        ...(senderInfo.senderId ? { senderId: senderInfo.senderId } : {}),
        ...(senderInfo.senderAvatarUrl ? { senderAvatarUrl: senderInfo.senderAvatarUrl } : {}),
        text: mediaParsed.text,
        translatedText: '',
        isAudio: mediaParsed.isAudio,
        audioDuration: mediaParsed.audioDuration,
        audioUrl: mediaParsed.audioUrl,
        sttText: '',
        voiceTone: '',
        isImage: mediaParsed.isImage,
        imageUrl: mediaParsed.imageUrl,
        imageCaption: mediaParsed.imageCaption,
        isVideo: mediaParsed.isVideo,
        videoUrl: mediaParsed.videoUrl,
        videoDuration: mediaParsed.videoDuration,
        videoWidth: mediaParsed.videoWidth,
        videoHeight: mediaParsed.videoHeight,
        isFile: mediaParsed.isFile,
        fileName: mediaParsed.fileName,
        fileSize: mediaParsed.fileSize,
        fileUrl: mediaParsed.fileUrl,
        ...(mediaParsed.isCall
          ? {
              isCall: true,
              callType: mediaParsed.callType,
              callDuration: mediaParsed.callDuration,
              isVideoCall: mediaParsed.isVideoCall,
              ...(mediaParsed.telegramCallId ? { telegramCallId: mediaParsed.telegramCallId } : {}),
            }
          : {}),
        replyTo,
        reactions,
        myReactions,
        isPinned: Boolean((m as any).pinned),
        isEdited: Boolean((m as any).editDate),
        forwardFrom,
        timestamp,
        createdAt,
        deliveryStatus: 'delivered',
      });
    }

    // Save to unified database cache (LOW priority batched queue with delete resurrection barrier)
    if (!options?.search && !options?.filter) {
      await Promise.allSettled(
        synced.map((msg) =>
          upsertSyncedMessageToDb(msg, canonicalId, accountId, {
            priority: 'LOW',
            snapshotTakenAt: syncStartedAt,
            source: 'history_sync',
          })
        )
      );
    }

    return synced.sort((a, b) => a.createdAt - b.createdAt);
  } catch (err: any) {
    if (isTelegramSessionExpiredError(err) || options?.throwOnError) {
      throw err;
    }
    console.warn(`[Sync Telegram Cloud Messages Warning] for ${rawChatId}:`, err.message);
    return [];
  }
}

export async function querySqlitePaginatedMessagesFallback(
  chatId: string,
  accountId: string | undefined,
  options?: { limit?: number; offsetId?: number; beforeCreatedAt?: number; search?: string }
): Promise<{ messages: UnifiedChatMessage[]; hasMore: boolean }> {
  const safeLimit = Math.min(Math.max(Number(options?.limit) || 30, 1), 100);
  const altChatId = chatId.startsWith('tg_') ? chatId.replace(/^tg_/, '') : `tg_${chatId}`;
  const effectiveAcc = String(accountId || '').trim();
  await flushMessageDbWriteQueueForChat(effectiveAcc || undefined, chatId, { timeoutMs: 2500 });
  const selfTgMatch = effectiveAcc.match(/^acc_tg_(\d+)$/);
  const chatIdCandidates = Array.from(
    new Set(
      [
        chatId,
        altChatId,
        ...((chatId === 'me' || chatId === 'tg_me') && selfTgMatch ? [`tg_${selfTgMatch[1]}`, selfTgMatch[1]] : []),
      ].filter(Boolean)
    )
  );
  const chatIdPlaceholders = chatIdCandidates.map(() => '?').join(', ');
  const accVariants = effectiveAcc ? getScopedAccountIdVariants(effectiveAcc) : [''];
  const accPlaceholders = accVariants.map(() => '?').join(', ');

  const conditions = [
    `chat_id IN (${chatIdPlaceholders})`,
    effectiveAcc ? `account_id IN (${accPlaceholders})` : '1=1',
  ];
  const args: any[] = [...chatIdCandidates, ...(effectiveAcc ? accVariants : [])];

  if (options?.offsetId && Number.isInteger(options.offsetId) && options.offsetId > 0) {
    conditions.push('telegram_message_id IS NOT NULL AND telegram_message_id > 0 AND telegram_message_id < ?');
    args.push(options.offsetId);
  }
  if (options?.beforeCreatedAt && Number.isFinite(options.beforeCreatedAt) && options.beforeCreatedAt > 0) {
    conditions.push('created_at < ?');
    args.push(Math.floor(options.beforeCreatedAt));
  }
  if (options?.search && options.search.trim()) {
    const likePattern = `%${options.search.trim()}%`;
    conditions.push('(text LIKE ? OR translated_text LIKE ? OR stt_text LIKE ? OR file_name LIKE ?)');
    args.push(likePattern, likePattern, likePattern, likePattern);
  }

  args.push(safeLimit + 1);
  const descRows = (await db
    .prepare(
      `SELECT
        id, chat_id as chatId, account_id as accountId, sender, sender_name as senderName,
        sender_id as senderId,
        text, translated_text as translatedText, is_audio as isAudio, audio_duration as audioDuration,
        audio_url as audioUrl, stt_text as sttText, voice_tone as voiceTone,
        is_image as isImage, image_url as imageUrl, image_caption as imageCaption,
        is_video as isVideo, video_url as videoUrl, video_duration as videoDuration,
        is_file as isFile, file_name as fileName, file_size as fileSize, file_url as fileUrl,
        timestamp, created_at as createdAt, delivery_status as deliveryStatus,
        telegram_message_id as telegramMessageId,
        reply_to_json as replyToJson,
        is_edited as isEdited,
        is_pinned as isPinned,
        forward_from as forwardFrom,
        reactions_json as reactionsJson,
        system_event_type as systemEventType
      FROM messages
      WHERE ${conditions.join(' AND ')}
      ORDER BY COALESCE(telegram_message_id, 0) DESC, created_at DESC
      LIMIT ?`
    )
    .all(...args)) as any[];

  const hasMore = descRows.length > safeLimit;
  const pageRows = (hasMore ? descRows.slice(0, safeLimit) : descRows).reverse();

  const resignUrlIfNeeded = (rawUrl?: string, msgAcc?: string) => {
    if (!rawUrl || typeof rawUrl !== 'string') return rawUrl;
    if (rawUrl.startsWith('/api/messages/local-media/') || isSignedResourceUrlExpiring(rawUrl)) {
      return resignTelegramResourceUrl(rawUrl, msgAcc || effectiveAcc) || rawUrl;
    }
    return rawUrl;
  };

  const messages: UnifiedChatMessage[] = pageRows.map((r: any) => {
    const replyTo = r.replyToJson ? safeJsonParse(r.replyToJson, undefined) : undefined;
    const parsedReactions = parseStoredReactionsJson(r.reactionsJson);
    const cleanSenderId = r.senderId ? String(r.senderId).trim() : '';
    const senderAvatarUrl =
      r.sender !== 'me' && cleanSenderId && r.accountId && r.accountId !== 'acc_telegram_bot'
        ? signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(cleanSenderId)}`, r.accountId)
        : undefined;
    const senderRole: 'me' | 'peer' | 'system' =
      r.sender === 'me' ? 'me' : r.sender === 'system' ? 'system' : 'peer';
    return {
      id: r.id,
      chatId: r.chatId,
      accountId: r.accountId,
      sender: senderRole,
      senderName: r.senderName || '',
      ...(cleanSenderId ? { senderId: cleanSenderId } : {}),
      ...(senderAvatarUrl ? { senderAvatarUrl } : {}),
      text: r.text || '',
      translatedText: r.translatedText || '',
      isAudio: Boolean(r.isAudio),
      audioDuration: Number(r.audioDuration || 0),
      audioUrl: resignUrlIfNeeded(r.audioUrl, r.accountId) || '',
      sttText: r.sttText || '',
      voiceTone: r.voiceTone || '',
      isImage: Boolean(r.isImage),
      imageUrl: resignUrlIfNeeded(r.imageUrl, r.accountId) || '',
      imageCaption: r.imageCaption || '',
      isVideo: Boolean(r.isVideo),
      videoUrl: resignUrlIfNeeded(r.videoUrl, r.accountId) || '',
      videoDuration: Number(r.videoDuration || 0),
      isFile: Boolean(r.isFile),
      fileName: r.fileName || '',
      fileSize: r.fileSize || '',
      fileUrl: resignUrlIfNeeded(r.fileUrl, r.accountId) || '',
      timestamp: r.timestamp || '',
      createdAt: Number(r.createdAt || Date.now()),
      deliveryStatus: r.deliveryStatus || 'delivered',
      telegramMessageId: r.telegramMessageId ? Number(r.telegramMessageId) : undefined,
      ...(replyTo ? { replyTo } : {}),
      isEdited: Boolean(r.isEdited),
      isPinned: Boolean(r.isPinned),
      ...(r.forwardFrom ? { forwardFrom: r.forwardFrom } : {}),
      ...(parsedReactions.reactions ? { reactions: parsedReactions.reactions } : {}),
      ...(parsedReactions.myReactions ? { myReactions: parsedReactions.myReactions } : {}),
      ...inferCallMetadataFromStoredRecord(r, senderRole),
      ...(r.systemEventType ? { systemEventType: r.systemEventType } : {}),
    };
  });

  return { messages, hasMore };
}

// 20.4 Fetch real cloud messages from Telegram for a specific conversation (supports offsetId pagination, search, readOutboxMaxId & SQLite fallback)
app.get('/api/telegram/user/messages/:chatId', requireTenantAuth, async (req: Request, res: Response) => {
  const { chatId } = req.params;
  const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
  if (!scope.ok) {
    return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
  }
  const accountId = scope.accountId;
  let connected: ConnectedTelegramUser | undefined;
  const limit = Math.min(Math.max(Number(req.query.limit) || 30, 1), 100);
  const rawOffsetId = req.query.offsetId ? Number(req.query.offsetId) : undefined;
  const offsetId = rawOffsetId && Number.isInteger(rawOffsetId) && rawOffsetId > 0 ? rawOffsetId : undefined;
  const search = typeof req.query.search === 'string' ? req.query.search.trim() : undefined;

  try {
    connected = accountId
      ? connectedUserClients.get(accountId) ||
        Array.from(connectedUserClients.values()).find(
          (u) => u.userId === accountId || u.phone === accountId || `acc_tg_${u.userId}` === accountId
        )
      : undefined;

    if (!connected || !connected.client) {
      const localFallback = await querySqlitePaginatedMessagesFallback(chatId, accountId, {
        limit,
        offsetId,
        search,
      });
      if (localFallback.messages.length > 0 || offsetId) {
        return res.json({
          ok: true,
          fromLocalFallback: true,
          messages: localFallback.messages,
          hasMore: localFallback.hasMore,
        });
      }
      return res.json({ ok: false, fromLocalFallback: true, messages: [], hasMore: false, message: '未找到在线的 Telegram 客户端会话' });
    }

    const msgFloodCooldown = getTelegramFloodCooldown({
      accountId: accountId || `acc_tg_${connected.userId}`,
      userId: connected.userId,
      phone: connected.phone,
    });
    if (msgFloodCooldown) {
      const localFallback = await querySqlitePaginatedMessagesFallback(
        chatId,
        accountId || `acc_tg_${connected.userId}`,
        { limit, offsetId, search }
      );
      if (localFallback.messages.length > 0) {
        return res.json({
          ok: true,
          fromLocalFallback: true,
          floodWait: true,
          code: 'TELEGRAM_FLOOD_WAIT',
          retryAfterSeconds: msgFloodCooldown.retryAfterSeconds,
          floodWaitUntil: msgFloodCooldown.floodWaitUntil,
          messages: localFallback.messages,
          hasMore: localFallback.hasMore,
        });
      }
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: msgFloodCooldown.retryAfterSeconds,
        floodWaitUntil: msgFloodCooldown.floodWaitUntil,
        error: formatTelegramError({ errorMessage: `FLOOD_WAIT_${msgFloodCooldown.retryAfterSeconds}` }),
        messages: [],
        hasMore: false,
      });
    }

    const syncMeta: { rawCount: number; minRawId?: number; totalCount?: number } = {
      rawCount: 0,
    };
    const messages = await syncTelegramUserChatMessages(connected.client, chatId, limit, connected.userId, {
      offsetId,
      search,
      throwOnError: true,
      metaOut: syncMeta,
    });

    if (offsetId && messages.length === 0) {
      const localOlder = await querySqlitePaginatedMessagesFallback(
        chatId,
        accountId || `acc_tg_${connected.userId}`,
        { limit, offsetId, search }
      );
      if (localOlder.messages.length > 0) {
        return res.json({
          ok: true,
          fromLocalFallback: true,
          messages: localOlder.messages,
          hasMore: localOlder.hasMore,
        });
      }
    }

    let readOutboxMaxId: number | undefined;
    if (!offsetId && !search) {
      try {
        const { inputPeer } = await resolveTelegramInputPeer(connected.client, chatId, connected.userId);
        const peerDialogs: any = await connected.client.invoke(
          new Api.messages.GetPeerDialogs({ peers: [new Api.InputDialogPeer({ peer: inputPeer })] })
        );
        const d = peerDialogs?.dialogs?.[0];
        if (d && typeof d.readOutboxMaxId === 'number') {
          readOutboxMaxId = d.readOutboxMaxId;
        }
      } catch {}
    }

    const visibleTgIds = messages
      .map((m: any) => Number(m?.telegramMessageId || 0))
      .filter((id: number) => Number.isInteger(id) && id > 0);
    const nextOffsetId =
      syncMeta.minRawId || (visibleTgIds.length > 0 ? Math.min(...visibleTgIds) : undefined);

    res.json({
      ok: true,
      messages,
      hasMore: syncMeta.rawCount >= limit,
      ...(nextOffsetId ? { nextOffsetId } : {}),
      ...(typeof readOutboxMaxId === 'number' ? { readOutboxMaxId } : {}),
    });
  } catch (err: any) {
    const floodEntry = recordTelegramFloodWait(
      { accountId, userId: connected?.userId, phone: connected?.phone },
      err,
      'messages.GetHistory'
    );
    if (isTelegramSessionExpiredError(err)) {
      await markTelegramSessionExpired({
        accountId,
        userId: connected?.userId,
        phone: connected?.phone,
        reason: formatTelegramError(err),
      });
      return res.status(401).json({
        ok: false,
        code: 'TELEGRAM_SESSION_EXPIRED',
        error: formatTelegramError(err),
        messages: [],
      });
    }
    try {
      const localFallback = await querySqlitePaginatedMessagesFallback(
        chatId,
        accountId || (connected?.userId ? `acc_tg_${connected.userId}` : ''),
        { limit, offsetId, search }
      );
      if (localFallback.messages.length > 0) {
        return res.json({
          ok: true,
          fromLocalFallback: true,
          ...(floodEntry
            ? {
                floodWait: true,
                code: 'TELEGRAM_FLOOD_WAIT',
                retryAfterSeconds: floodEntry.retryAfterSeconds,
                floodWaitUntil: floodEntry.floodWaitUntil,
              }
            : {}),
          messages: localFallback.messages,
          hasMore: localFallback.hasMore,
        });
      }
    } catch {}
    if (floodEntry) {
      return res.status(429).json({
        ok: false,
        code: 'TELEGRAM_FLOOD_WAIT',
        retryAfterSeconds: floodEntry.retryAfterSeconds,
        floodWaitUntil: floodEntry.floodWaitUntil,
        error: formatTelegramError(err),
        messages: [],
        hasMore: false,
      });
    }
    res.status(500).json({ ok: false, error: formatTelegramError(err), messages: [] });
  }
});

type SharedMediaFilterType = 'media' | 'files' | 'voice' | 'links';

function resolveSharedMediaType(raw?: unknown): SharedMediaFilterType {
  const val = String(raw || '').trim().toLowerCase();
  if (val === 'files' || val === 'voice' || val === 'links') return val;
  return 'media';
}

export async function querySqliteSharedMediaFallback(
  chatId: string,
  accountId: string | undefined,
  options?: { type?: SharedMediaFilterType; limit?: number; offsetId?: number }
): Promise<{ items: UnifiedChatMessage[]; hasMore: boolean; nextOffsetId?: number; totalCount: number }> {
  const mediaType = resolveSharedMediaType(options?.type);
  const safeLimit = Math.min(Math.max(Number(options?.limit) || 60, 1), 100);
  const altChatId = chatId.startsWith('tg_') ? chatId.replace(/^tg_/, '') : `tg_${chatId}`;
  const effectiveAcc = String(accountId || '').trim();
  const selfTgMatch = effectiveAcc.match(/^acc_tg_(\d+)$/);
  const chatIdCandidates = Array.from(
    new Set(
      [
        chatId,
        altChatId,
        ...((chatId === 'me' || chatId === 'tg_me') && selfTgMatch ? [`tg_${selfTgMatch[1]}`, selfTgMatch[1]] : []),
      ].filter(Boolean)
    )
  );
  const chatIdPlaceholders = chatIdCandidates.map(() => '?').join(', ');
  const accVariants = effectiveAcc ? getScopedAccountIdVariants(effectiveAcc) : [''];
  const accPlaceholders = accVariants.map(() => '?').join(', ');

  const baseConditions = [
    `chat_id IN (${chatIdPlaceholders})`,
    effectiveAcc ? `account_id IN (${accPlaceholders})` : '1=1',
  ];
  const baseArgs: any[] = [...chatIdCandidates, ...(effectiveAcc ? accVariants : [])];

  if (mediaType === 'media') {
    baseConditions.push("(is_image = 1 OR is_video = 1 OR COALESCE(image_url, '') != '' OR COALESCE(video_url, '') != '')");
  } else if (mediaType === 'files') {
    baseConditions.push("(is_file = 1 OR COALESCE(file_name, '') != '')");
  } else if (mediaType === 'voice') {
    baseConditions.push("(is_audio = 1 OR COALESCE(audio_url, '') != '')");
  } else {
    baseConditions.push("(text LIKE '%http://%' OR text LIKE '%https://%' OR text LIKE '%t.me/%')");
  }

  let totalCount = 0;
  try {
    const countRow = (await db
      .prepare(`SELECT COUNT(*) as cnt FROM messages WHERE ${baseConditions.join(' AND ')}`)
      .get(...baseArgs)) as any;
    totalCount = Number(countRow?.cnt || 0);
  } catch {}

  const pagedConditions = [...baseConditions];
  const pagedArgs = [...baseArgs];
  if (options?.offsetId && Number.isInteger(options.offsetId) && options.offsetId > 0) {
    pagedConditions.push('telegram_message_id IS NOT NULL AND telegram_message_id > 0 AND telegram_message_id < ?');
    pagedArgs.push(options.offsetId);
  }
  pagedArgs.push(safeLimit + 1);

  const descRows = (await db
    .prepare(
      `SELECT
        id, chat_id as chatId, account_id as accountId, sender, sender_name as senderName,
        sender_id as senderId,
        text, translated_text as translatedText, is_audio as isAudio, audio_duration as audioDuration,
        audio_url as audioUrl, stt_text as sttText, voice_tone as voiceTone,
        is_image as isImage, image_url as imageUrl, image_caption as imageCaption,
        is_video as isVideo, video_url as videoUrl, video_duration as videoDuration,
        is_file as isFile, file_name as fileName, file_size as fileSize, file_url as fileUrl,
        timestamp, created_at as createdAt, delivery_status as deliveryStatus,
        telegram_message_id as telegramMessageId,
        reply_to_json as replyToJson,
        is_edited as isEdited,
        is_pinned as isPinned,
        forward_from as forwardFrom,
        reactions_json as reactionsJson,
        system_event_type as systemEventType
      FROM messages
      WHERE ${pagedConditions.join(' AND ')}
      ORDER BY COALESCE(telegram_message_id, 0) DESC, created_at DESC
      LIMIT ?`
    )
    .all(...pagedArgs)) as any[];

  const hasMore = descRows.length > safeLimit;
  const pageRows = hasMore ? descRows.slice(0, safeLimit) : descRows;

  const resignUrlIfNeeded = (rawUrl?: string, msgAcc?: string) => {
    if (!rawUrl || typeof rawUrl !== 'string') return rawUrl;
    if (rawUrl.startsWith('/api/messages/local-media/') || isSignedResourceUrlExpiring(rawUrl)) {
      return resignTelegramResourceUrl(rawUrl, msgAcc || effectiveAcc) || rawUrl;
    }
    return rawUrl;
  };

  const items: UnifiedChatMessage[] = pageRows.map((r: any) => {
    const replyTo = r.replyToJson ? safeJsonParse(r.replyToJson, undefined) : undefined;
    const parsedReactions = parseStoredReactionsJson(r.reactionsJson);
    const cleanSenderId = r.senderId ? String(r.senderId).trim() : '';
    const senderAvatarUrl =
      r.sender !== 'me' && cleanSenderId && r.accountId && r.accountId !== 'acc_telegram_bot'
        ? signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(cleanSenderId)}`, r.accountId)
        : undefined;
    const senderRole: 'me' | 'peer' | 'system' =
      r.sender === 'me' ? 'me' : r.sender === 'system' ? 'system' : 'peer';
    return {
      id: r.id,
      chatId: r.chatId,
      accountId: r.accountId,
      sender: senderRole,
      senderName: r.senderName || '',
      ...(cleanSenderId ? { senderId: cleanSenderId } : {}),
      ...(senderAvatarUrl ? { senderAvatarUrl } : {}),
      text: r.text || '',
      translatedText: r.translatedText || '',
      isAudio: Boolean(r.isAudio),
      audioDuration: Number(r.audioDuration || 0),
      audioUrl: resignUrlIfNeeded(r.audioUrl, r.accountId) || '',
      sttText: r.sttText || '',
      voiceTone: r.voiceTone || '',
      isImage: Boolean(r.isImage),
      imageUrl: resignUrlIfNeeded(r.imageUrl, r.accountId) || '',
      imageCaption: r.imageCaption || '',
      isVideo: Boolean(r.isVideo),
      videoUrl: resignUrlIfNeeded(r.videoUrl, r.accountId) || '',
      videoDuration: Number(r.videoDuration || 0),
      isFile: Boolean(r.isFile),
      fileName: r.fileName || '',
      fileSize: r.fileSize || '',
      fileUrl: resignUrlIfNeeded(r.fileUrl, r.accountId) || '',
      timestamp: r.timestamp || '',
      createdAt: Number(r.createdAt || Date.now()),
      deliveryStatus: r.deliveryStatus || 'delivered',
      telegramMessageId: r.telegramMessageId ? Number(r.telegramMessageId) : undefined,
      ...(replyTo ? { replyTo } : {}),
      isEdited: Boolean(r.isEdited),
      isPinned: Boolean(r.isPinned),
      ...(r.forwardFrom ? { forwardFrom: r.forwardFrom } : {}),
      ...(parsedReactions.reactions ? { reactions: parsedReactions.reactions } : {}),
      ...(parsedReactions.myReactions ? { myReactions: parsedReactions.myReactions } : {}),
      ...inferCallMetadataFromStoredRecord(r, senderRole),
      ...(r.systemEventType ? { systemEventType: r.systemEventType } : {}),
    };
  });

  const tgIds = items
    .map((m) => Number(m.telegramMessageId || 0))
    .filter((id) => Number.isInteger(id) && id > 0);
  const nextOffsetId = tgIds.length > 0 ? Math.min(...tgIds) : undefined;

  return { items, hasMore, nextOffsetId, totalCount };
}

// 20.4.1 Fetch full shared media/files/voice/links across entire chat history via Telegram MTProto filter + SQLite fallback
app.get('/api/telegram/user/shared-media/:chatId', requireTenantAuth, async (req: Request, res: Response) => {
  const { chatId } = req.params;
  const scope = resolveScopedAccountFromRequest(req, { allowBot: true });
  if (!scope.ok) {
    return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
  }
  const accountId = scope.accountId;
  const mediaType = resolveSharedMediaType(req.query.type);
  const limit = Math.min(Math.max(Number(req.query.limit) || 60, 1), 100);
  const rawOffsetId = req.query.offsetId ? Number(req.query.offsetId) : undefined;
  const offsetId = rawOffsetId && Number.isInteger(rawOffsetId) && rawOffsetId > 0 ? rawOffsetId : undefined;

  let connected: ConnectedTelegramUser | undefined;
  try {
    connected =
      accountId && accountId !== 'acc_telegram_bot'
        ? connectedUserClients.get(accountId) ||
          Array.from(connectedUserClients.values()).find(
            (u) => u.userId === accountId || u.phone === accountId || `acc_tg_${u.userId}` === accountId
          )
        : undefined;

    if (!connected || !connected.client) {
      const localFallback = await querySqliteSharedMediaFallback(chatId, accountId, {
        type: mediaType,
        limit,
        offsetId,
      });
      return res.json({
        ok: true,
        fromLocalFallback: true,
        items: localFallback.items,
        hasMore: localFallback.hasMore,
        nextOffsetId: localFallback.nextOffsetId,
        totalCount: localFallback.totalCount,
      });
    }

    const floodCooldown = getTelegramFloodCooldown({
      accountId: accountId || `acc_tg_${connected.userId}`,
      userId: connected.userId,
      phone: connected.phone,
    });
    if (floodCooldown) {
      const localFallback = await querySqliteSharedMediaFallback(
        chatId,
        accountId || `acc_tg_${connected.userId}`,
        { type: mediaType, limit, offsetId }
      );
      return res.json({
        ok: true,
        fromLocalFallback: true,
        floodWait: true,
        items: localFallback.items,
        hasMore: localFallback.hasMore,
        nextOffsetId: localFallback.nextOffsetId,
        totalCount: localFallback.totalCount,
      });
    }

    const filterInstance: Api.TypeMessagesFilter =
      mediaType === 'files'
        ? new Api.InputMessagesFilterDocument()
        : mediaType === 'voice'
          ? new Api.InputMessagesFilterRoundVoice()
          : mediaType === 'links'
            ? new Api.InputMessagesFilterUrl()
            : new Api.InputMessagesFilterPhotoVideo();

    const syncMeta: { rawCount: number; minRawId?: number; totalCount?: number } = {
      rawCount: 0,
    };
    const syncedDesc = (
      await syncTelegramUserChatMessages(connected.client, chatId, limit, connected.userId, {
        offsetId,
        filter: filterInstance,
        throwOnError: true,
        metaOut: syncMeta,
      })
    ).sort((a, b) => {
      if (
        typeof a.telegramMessageId === 'number' &&
        a.telegramMessageId > 0 &&
        typeof b.telegramMessageId === 'number' &&
        b.telegramMessageId > 0
      ) {
        return b.telegramMessageId - a.telegramMessageId;
      }
      return (b.createdAt || 0) - (a.createdAt || 0);
    });

    const itemTgIds = syncedDesc
      .map((m: any) => Number(m?.telegramMessageId || 0))
      .filter((id: number) => Number.isInteger(id) && id > 0);
    const nextOffsetId =
      syncMeta.minRawId || (itemTgIds.length > 0 ? Math.min(...itemTgIds) : undefined);

    res.json({
      ok: true,
      items: syncedDesc,
      hasMore: syncMeta.rawCount >= limit,
      ...(nextOffsetId ? { nextOffsetId } : {}),
      ...(typeof syncMeta.totalCount === 'number' ? { totalCount: syncMeta.totalCount } : {}),
    });
  } catch (err: any) {
    recordTelegramFloodWait(
      { accountId, userId: connected?.userId, phone: connected?.phone },
      err,
      'messages.Search'
    );
    if (isTelegramSessionExpiredError(err)) {
      await markTelegramSessionExpired({
        accountId,
        userId: connected?.userId,
        phone: connected?.phone,
        reason: formatTelegramError(err),
      });
      return res.status(401).json({
        ok: false,
        code: 'TELEGRAM_SESSION_EXPIRED',
        error: formatTelegramError(err),
        items: [],
      });
    }
    try {
      const localFallback = await querySqliteSharedMediaFallback(
        chatId,
        accountId || (connected?.userId ? `acc_tg_${connected.userId}` : ''),
        { type: mediaType, limit, offsetId }
      );
      return res.json({
        ok: true,
        fromLocalFallback: true,
        items: localFallback.items,
        hasMore: localFallback.hasMore,
        nextOffsetId: localFallback.nextOffsetId,
        totalCount: localFallback.totalCount,
      });
    } catch {}
    res.status(500).json({ ok: false, error: formatTelegramError(err), items: [] });
  }
});

// Autopilot state storage (strictly isolated per accountId::chatId)
export const activeAutonomousChats = new Set<string>();

export function normalizeAutopilotAccountScope(accountId?: string): string {
  const clean = String(accountId || '').trim();
  if (!clean) return 'default';
  if (/^\d+$/.test(clean)) return `acc_tg_${clean}`;
  return clean;
}

function buildAutopilotScopedKeys(accountId: string | undefined, chatId: string): string[] {
  const scope = normalizeAutopilotAccountScope(accountId);
  const raw = String(chatId || '').trim();
  const bare = raw.replace(/^tg_/, '');
  if (!bare) return [];
  const prefixed = `tg_${bare}`;
  return [`${scope}::${prefixed}`, `${scope}::${bare}`];
}

export function isAutopilotEnabledForChat(accountId: string | undefined, chatId: string): boolean {
  const keys = buildAutopilotScopedKeys(accountId, chatId);
  return keys.some((k) => activeAutonomousChats.has(k));
}

export function setAutopilotEnabledForChat(accountId: string | undefined, chatId: string, enabled: boolean): boolean {
  const keys = buildAutopilotScopedKeys(accountId, chatId);
  if (keys.length === 0) return false;
  for (const k of keys) {
    if (enabled) activeAutonomousChats.add(k);
    else activeAutonomousChats.delete(k);
  }
  return isAutopilotEnabledForChat(accountId, chatId);
}

// 20.5 Autopilot Status & Toggle Endpoints (strictly scoped per accountId, blocks Bot Webhook)
app.get('/api/telegram/autopilot/status', requireTenantAuth, (req: Request, res: Response) => {
  const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
  if (!scope.ok) {
    return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
  }
  const chatId = String(req.query.chatId || '').trim();
  const accountId = scope.accountId;
  const scopePrefix = `${normalizeAutopilotAccountScope(accountId)}::`;
  const scopedActiveChats = Array.from(activeAutonomousChats)
    .filter((k) => k.startsWith(scopePrefix))
    .map((k) => k.slice(scopePrefix.length));

  res.json({
    ok: true,
    accountId: normalizeAutopilotAccountScope(accountId),
    activeChats: scopedActiveChats,
    isChatEnabled: chatId ? isAutopilotEnabledForChat(accountId, chatId) : false,
  });
});

app.post('/api/telegram/autopilot/toggle', requireTenantAuth, (req: Request, res: Response) => {
  const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
  if (!scope.ok) {
    return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
  }
  const { chatId, enabled } = req.body || {};
  if (!chatId) return res.status(400).json({ ok: false, error: 'chatId is required' });
  const accountId = scope.accountId;

  const currentEnabled = setAutopilotEnabledForChat(accountId, String(chatId), Boolean(enabled));
  const scopePrefix = `${normalizeAutopilotAccountScope(accountId)}::`;
  const scopedCount = Array.from(activeAutonomousChats).filter((k) => k.startsWith(scopePrefix)).length;

  res.json({
    ok: true,
    accountId: normalizeAutopilotAccountScope(accountId),
    chatId,
    enabled: currentEnabled,
    activeCount: scopedCount,
  });
});

// Real-time MTProto NewMessage event listener for personal Telegram account
export interface LocalIncomingUpdate {
  id: string;
  type?: 'message' | 'edit' | 'delete' | 'read_outbox' | 'read_inbox' | 'dialog_pinned' | 'dialogs_pinned_order' | 'dialog_unread_mark' | 'dialog_muted' | 'dialog_archived' | 'self_profile' | 'peer_profile' | 'chat_meta' | 'settings_updated' | 'folders_updated' | 'pin' | 'user_status' | 'peer_blocked' | 'reactions' | 'phone_call_ringing' | 'delivery_receipt' | 'flood_state' | 'peer_flood';
  messageId?: string;
  clientMessageId?: string;
  deliveryStatus?: 'pending' | 'delivered' | 'paused' | 'failed' | 'retrying';
  queuePauseReason?: string;
  floodWaitUntil?: number;
  retryAfterSeconds?: number;
  floodMethod?: string;
  dialogState?: OutboundDialogState;
  peerFloodRestricted?: boolean;
  peerFloodReason?: string;
  error?: string;
  telegramMessageId?: number;
  deletedMessageIds?: number[];
  readOutboxMaxId?: number;
  readInboxMaxId?: number;
  unreadCount?: number;
  pinnedMessageIds?: number[];
  pinned?: boolean;
  isOnline?: boolean;
  statusText?: string;
  isBlocked?: boolean;
  reactions?: Record<string, number>;
  myReactions?: string[];
  chatId: string;
  rawChatId?: string;
  accountId: string;
  sender: 'me' | 'peer' | 'system';
  senderName: string;
  systemEventType?: TelegramSystemEventType;
  senderId?: string;
  senderAvatarUrl?: string;
  text: string;
  translatedText?: string;
  sttText?: string;
  timestamp: string;
  createdAt: number;
  isAudio?: boolean;
  audioDuration?: number;
  audioUrl?: string;
  isVideo?: boolean;
  videoDuration?: number;
  videoWidth?: number;
  videoHeight?: number;
  videoUrl?: string;
  isImage?: boolean;
  imageUrl?: string;
  imageCaption?: string;
  isFile?: boolean;
  fileName?: string;
  fileSize?: string;
  fileUrl?: string;
  isCall?: boolean;
  callType?: 'incoming' | 'outgoing' | 'missed';
  callDuration?: number;
  isVideoCall?: boolean;
  telegramCallId?: string;
  replyTo?: { id: string; telegramMessageId?: number; senderName?: string; text: string };
  isEdited?: boolean;
  isPinned?: boolean;
  pinOrder?: number;
  pinnedChatOrder?: string[];
  folderId?: number;
  unreadMark?: boolean;
  isMuted?: boolean;
  isArchived?: boolean;
  needsDialogRefresh?: boolean;
  profileName?: string;
  profileUsername?: string;
  profileAvatarUrl?: string;
  isGroup?: boolean;
  isChannel?: boolean;
  chatTitle?: string;
}
export const pendingLocalUpdates: LocalIncomingUpdate[] = [];

let pendingLocalUpdatesDbChain: Promise<void> = Promise.resolve();

function enqueuePendingLocalUpdateDbOp(task: () => Promise<void>): void {
  pendingLocalUpdatesDbChain = pendingLocalUpdatesDbChain
    .then(async () => {
      for (let attempt = 0; attempt < 3; attempt += 1) {
        try {
          await runWithSqliteWriteLock(task);
          return;
        } catch (err: any) {
          const msg = String(err?.message || err || '');
          const isBusy = /SQLITE_BUSY|database is locked/i.test(msg);
          if (!isBusy || attempt >= 2) {
            throw err;
          }
          await new Promise((r) => setTimeout(r, 40 * (attempt + 1)));
        }
      }
    })
    .catch((err: any) => {
      const msg = String(err?.message || err || '');
      if (!/no such table/i.test(msg)) {
        console.warn('[PendingLocalUpdates DB] Sync error:', msg);
      }
    });
}

export async function flushPendingLocalUpdatesDbQueue(): Promise<void> {
  await pendingLocalUpdatesDbChain.catch(() => {});
}

export async function loadPendingLocalUpdatesFromDb(): Promise<number> {
  try {
    const rows = (await db
      .prepare('SELECT payload_json FROM pending_local_updates ORDER BY seq ASC LIMIT 2400')
      .all()) as Array<{ payload_json?: string }>;
    if (!Array.isArray(rows) || rows.length === 0) return 0;
    const existingIds = new Set(pendingLocalUpdates.map((u) => String(u.id)));
    let restored = 0;
    for (const row of rows) {
      if (!row?.payload_json) continue;
      try {
        const parsed = JSON.parse(row.payload_json) as LocalIncomingUpdate;
        if (parsed && parsed.id && !existingIds.has(String(parsed.id))) {
          existingIds.add(String(parsed.id));
          pendingLocalUpdates.push(parsed);
          restored += 1;
        }
      } catch {}
    }
    if (restored > 0) {
      console.log(`[PendingLocalUpdates] Restored ${restored} un-ACKed real-time update(s) from SQLite`);
    }
    return restored;
  } catch (err: any) {
    console.warn('[PendingLocalUpdates] Load error:', err?.message || err);
    return 0;
  }
}

async function deletePendingLocalUpdateIdsSql(ids: string[]): Promise<void> {
  if (ids.length === 0) return;
  const CHUNK_SIZE = 300;
  for (let i = 0; i < ids.length; i += CHUNK_SIZE) {
    const chunk = ids.slice(i, i + CHUNK_SIZE);
    const placeholders = chunk.map(() => '?').join(',');
    await db
      .prepare(`DELETE FROM pending_local_updates WHERE update_id IN (${placeholders})`)
      .run(...chunk);
  }
}

function persistPushAndEvictionsToDb(upd: LocalIncomingUpdate, evictedIds: string[]): void {
  enqueuePendingLocalUpdateDbOp(async () => {
    await db
      .prepare(
        `INSERT OR REPLACE INTO pending_local_updates (update_id, account_id, update_type, payload_json, created_at)
         VALUES (?, ?, ?, ?, ?)`
      )
      .run(
        String(upd.id),
        String(upd.accountId || ''),
        String(upd.type || 'message'),
        JSON.stringify(upd),
        Number(upd.createdAt || Date.now())
      );
    if (evictedIds.length > 0) {
      await deletePendingLocalUpdateIdsSql(evictedIds);
    }
  });
}

function deletePendingLocalUpdateIdsInDb(ids: string[]): void {
  if (ids.length === 0) return;
  enqueuePendingLocalUpdateDbOp(() => deletePendingLocalUpdateIdsSql(ids));
}

function deletePendingLocalUpdatesByAccountsInDb(accountIds: string[]): void {
  if (accountIds.length === 0) return;
  const placeholders = accountIds.map(() => '?').join(',');
  enqueuePendingLocalUpdateDbOp(async () => {
    await db
      .prepare(`DELETE FROM pending_local_updates WHERE account_id IN (${placeholders})`)
      .run(...accountIds);
  });
}

function clearPendingLocalUpdatesInDb(): void {
  enqueuePendingLocalUpdateDbOp(async () => {
    await db.prepare('DELETE FROM pending_local_updates').run();
  });
}

interface SseUpdateSubscriber {
  id: string;
  scopedAccountFilter: string;
  authorizedAccounts: string[];
  isMaster: boolean;
  res: Response;
}

const activeFocusChatByAccount = new Map<string, string>();
const sseUpdateSubscribers = new Set<SseUpdateSubscriber>();
const backgroundGroupBatchStates = new Map<
  string,
  { timer: NodeJS.Timeout | null; chatIds: Set<string>; rawAccountId: string }
>();

export function setActiveFocusChat(accountId: string, chatId?: string | null): void {
  const key = getOutboundAccountSchedulerKey(accountId);
  const cleanChat = String(chatId || '').trim();
  if (!cleanChat) {
    activeFocusChatByAccount.delete(key);
    return;
  }
  activeFocusChatByAccount.set(key, canonicalizeSchedulerChatId(cleanChat));
}

export function getActiveFocusChat(accountId: string): string | null {
  const key = getOutboundAccountSchedulerKey(accountId);
  return activeFocusChatByAccount.get(key) || null;
}

export function clearActiveFocusAndSseForTesting(): void {
  activeFocusChatByAccount.clear();
  for (const state of backgroundGroupBatchStates.values()) {
    if (state.timer) clearTimeout(state.timer);
  }
  backgroundGroupBatchStates.clear();
  for (const sub of sseUpdateSubscribers) {
    try {
      sub.res.end();
    } catch {}
  }
  sseUpdateSubscribers.clear();
}

function sendSseWakeupToSubscribers(accountId: string, payload: Record<string, any>): void {
  const frame = `event: wakeup\ndata: ${JSON.stringify(payload)}\n\n`;
  for (const sub of sseUpdateSubscribers) {
    if (sub.res.destroyed || sub.res.writableEnded) {
      sseUpdateSubscribers.delete(sub);
      continue;
    }
    if (sub.scopedAccountFilter) {
      if (!doesUpdateBelongToAccount(accountId, sub.scopedAccountFilter)) continue;
    } else if (!sub.isMaster) {
      continue;
    } else {
      const acc = String(accountId || '').trim();
      if (!acc.startsWith('acc_tg_') && !sub.authorizedAccounts.includes(acc)) continue;
    }
    try {
      sub.res.write(frame);
    } catch {
      sseUpdateSubscribers.delete(sub);
    }
  }
}

function notifySseUpdateAvailable(upd: LocalIncomingUpdate): void {
  if (sseUpdateSubscribers.size === 0) return;
  const isMessageKind = !upd.type || upd.type === 'message';
  const conn = resolveConnectedTelegramUser(upd.accountId);
  const isGroup = isTelegramGroupChatId(upd.chatId, conn);
  const focusedChat = getActiveFocusChat(upd.accountId);
  const isFocused = Boolean(focusedChat && upd.chatId && isSameCanonicalChatId(upd.chatId, focusedChat));
  const isBackgroundGroupMsg = isMessageKind && isGroup && !isFocused;

  if (!isBackgroundGroupMsg) {
    sendSseWakeupToSubscribers(upd.accountId, {
      kind: 'wakeup',
      mode: 'immediate',
      type: upd.type || 'message',
      accountId: upd.accountId,
      chatId: upd.chatId,
      ts: Date.now(),
    });
    return;
  }

  const accKey = getOutboundAccountSchedulerKey(upd.accountId);
  let batchState = backgroundGroupBatchStates.get(accKey);
  if (!batchState) {
    batchState = { timer: null, chatIds: new Set<string>(), rawAccountId: upd.accountId };
    backgroundGroupBatchStates.set(accKey, batchState);
  }
  if (upd.chatId) batchState.chatIds.add(upd.chatId);
  if (!batchState.timer) {
    const waitMs = randomIntBetween(
      outboundRuntimeConfig.bgGroupBatchMinMs,
      outboundRuntimeConfig.bgGroupBatchMaxMs
    );
    batchState.timer = setTimeout(() => {
      const st = backgroundGroupBatchStates.get(accKey);
      if (!st) return;
      st.timer = null;
      const chatIds = Array.from(st.chatIds);
      st.chatIds.clear();
      backgroundGroupBatchStates.delete(accKey);
      sendSseWakeupToSubscribers(st.rawAccountId, {
        kind: 'wakeup',
        mode: 'batch_group',
        accountId: st.rawAccountId,
        chatIds,
        ts: Date.now(),
      });
    }, waitMs);
    batchState.timer.unref?.();
  }
}

export function pushPendingLocalUpdate(upd: LocalIncomingUpdate, maxPerAccount = 600, maxTotal = 2400) {
  pendingLocalUpdates.push(upd);
  const evictedIds: string[] = [];
  let accountCount = 0;
  for (let i = 0; i < pendingLocalUpdates.length; i++) {
    if (pendingLocalUpdates[i].accountId === upd.accountId) accountCount++;
  }
  if (accountCount > maxPerAccount) {
    const oldestIdx = pendingLocalUpdates.findIndex((item) => item.accountId === upd.accountId);
    if (oldestIdx >= 0) {
      const [removed] = pendingLocalUpdates.splice(oldestIdx, 1);
      if (removed?.id) evictedIds.push(String(removed.id));
    }
  }
  while (pendingLocalUpdates.length > maxTotal) {
    const countsByAcc = new Map<string, number>();
    for (const item of pendingLocalUpdates) {
      countsByAcc.set(item.accountId, (countsByAcc.get(item.accountId) || 0) + 1);
    }
    let busiestAcc = pendingLocalUpdates[0].accountId;
    let busiestCount = 0;
    for (const [acc, cnt] of countsByAcc.entries()) {
      if (cnt > busiestCount) {
        busiestCount = cnt;
        busiestAcc = acc;
      }
    }
    const evictIdx = pendingLocalUpdates.findIndex((item) => item.accountId === busiestAcc);
    const [removed] = pendingLocalUpdates.splice(evictIdx >= 0 ? evictIdx : 0, 1);
    if (removed?.id) evictedIds.push(String(removed.id));
  }
  persistPushAndEvictionsToDb(upd, evictedIds);
  notifySseUpdateAvailable(upd);
}

function doesUpdateBelongToAccount(updateAccountId: string | undefined, targetAccountId: string): boolean {
  const updAcc = String(updateAccountId || '').trim();
  const target = String(targetAccountId || '').trim();
  if (!updAcc || !target) return false;
  const targetVariants = getScopedAccountIdVariants(target);
  return targetVariants.includes(updAcc) || updAcc === `acc_tg_${target}` || target === `acc_tg_${updAcc}`;
}

// Endpoint for local desktop app to poll new incoming Telegram messages non-destructively (ACK required to dequeue)
app.get('/api/telegram/user/poll-updates', requireTenantAuth, (req: Request, res: Response) => {
  const authContext = (req as any).auth;
  const session = authContext?.session;
  if (!session || session.isBot || authContext?.isBot) {
    return res.status(403).json({
      ok: false,
      code: 'BOT_FORBIDDEN',
      error: '权限不足：Bot Webhook 凭证无权拉取个人账号实时更新队列',
    });
  }

  const rawRequested =
    (typeof req.query.accountId === 'string' && req.query.accountId.trim()) ||
    (typeof req.headers['x-account-id'] === 'string' && req.headers['x-account-id'].trim()) ||
    '';

  if (!session.isMaster) {
    const lockedAccount = String(authContext.effectiveAccountId || session.accountId || '').trim();
    if (rawRequested && !doesUpdateBelongToAccount(rawRequested, lockedAccount)) {
      return res.status(403).json({
        ok: false,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `权限不足：禁止跨账号读取 (${rawRequested}) 的实时更新队列`,
      });
    }
    const matched = pendingLocalUpdates.filter((upd) => doesUpdateBelongToAccount(upd.accountId, lockedAccount));
    return res.json({ ok: true, updates: matched });
  }

  if (rawRequested) {
    const authorized: string[] = Array.isArray(session.authorizedAccounts) ? session.authorizedAccounts : [];
    const isAllowed =
      rawRequested === authContext.effectiveAccountId ||
      rawRequested.startsWith('acc_tg_') ||
      authorized.includes(rawRequested);
    if (!isAllowed) {
      return res.status(403).json({
        ok: false,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `权限不足：无权读取未授权账号 (${rawRequested}) 的实时更新队列`,
      });
    }
    const matched = pendingLocalUpdates.filter((upd) => doesUpdateBelongToAccount(upd.accountId, rawRequested));
    return res.json({ ok: true, updates: matched });
  }

  const authorized: string[] = Array.isArray(session.authorizedAccounts) ? session.authorizedAccounts : [];
  const matched = pendingLocalUpdates.filter((upd) => {
    const acc = String(upd.accountId || '').trim();
    return acc.startsWith('acc_tg_') || authorized.includes(acc);
  });
  res.json({ ok: true, updates: matched });
});

// Explicit client acknowledgement endpoint: removes delivered update IDs only for authorized/scoped account
app.post('/api/telegram/user/ack-updates', requireTenantAuth, (req: Request, res: Response) => {
  const authContext = (req as any).auth;
  const session = authContext?.session;
  if (!session || session.isBot || authContext?.isBot) {
    return res.status(403).json({
      ok: false,
      code: 'BOT_FORBIDDEN',
      error: '权限不足：Bot Webhook 凭证无权清理个人账号实时更新队列',
    });
  }

  const ids = Array.isArray(req.body?.ids) ? req.body.ids.map(String) : [];
  if (ids.length === 0) {
    return res.json({ ok: true, ackedCount: 0 });
  }

  const rawRequested =
    (typeof req.body?.accountId === 'string' && req.body.accountId.trim()) ||
    (typeof req.headers['x-account-id'] === 'string' && req.headers['x-account-id'].trim()) ||
    '';

  let scopedAccountFilter = '';
  if (!session.isMaster) {
    const lockedAccount = String(authContext.effectiveAccountId || session.accountId || '').trim();
    if (rawRequested && !doesUpdateBelongToAccount(rawRequested, lockedAccount)) {
      return res.status(403).json({
        ok: false,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `权限不足：禁止跨账号清理 (${rawRequested}) 的实时更新队列`,
      });
    }
    scopedAccountFilter = lockedAccount;
  } else if (rawRequested) {
    const authorized: string[] = Array.isArray(session.authorizedAccounts) ? session.authorizedAccounts : [];
    const isAllowed =
      rawRequested === authContext.effectiveAccountId ||
      rawRequested.startsWith('acc_tg_') ||
      authorized.includes(rawRequested);
    if (!isAllowed) {
      return res.status(403).json({
        ok: false,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `权限不足：无权清理未授权账号 (${rawRequested}) 的实时更新队列`,
      });
    }
    scopedAccountFilter = rawRequested;
  }

  const ackSet = new Set<string>(ids);
  const beforeLen = pendingLocalUpdates.length;
  const ackedIds: string[] = [];
  const remaining = pendingLocalUpdates.filter((upd) => {
    if (!ackSet.has(String(upd.id))) return true;
    if (scopedAccountFilter && !doesUpdateBelongToAccount(upd.accountId, scopedAccountFilter)) {
      return true;
    }
    ackedIds.push(String(upd.id));
    return false;
  });
  pendingLocalUpdates.length = 0;
  pendingLocalUpdates.push(...remaining);
  if (ackedIds.length > 0) {
    deletePendingLocalUpdateIdsInDb(ackedIds);
  }
  res.json({ ok: true, ackedCount: beforeLen - remaining.length });
});

// Sync currently focused chatId per account so SSE batches background groups and pushes private/focused updates immediately
app.post('/api/telegram/user/focus-chat', requireTenantAuth, (req: Request, res: Response) => {
  const scope = resolveScopedAccountFromRequest(req, { allowBot: false });
  if (!scope.ok) {
    return res.status(scope.status).json({ ok: false, code: scope.code, error: scope.error });
  }
  const chatId = typeof req.body?.chatId === 'string' ? req.body.chatId.trim() : '';
  setActiveFocusChat(scope.accountId, chatId || null);
  return res.json({
    ok: true,
    accountId: scope.accountId,
    chatId: getActiveFocusChat(scope.accountId),
  });
});

// Differentiated SSE wakeup stream: immediate for private/focused/receipts/flood; 1.5-2.5s coalesced batch for background groups
app.get('/api/telegram/user/updates-stream', requireTenantAuth, (req: Request, res: Response) => {
  const authContext = (req as any).auth;
  const session = authContext?.session;
  if (!session || session.isBot || authContext?.isBot) {
    return res.status(403).json({
      ok: false,
      code: 'BOT_FORBIDDEN',
      error: '权限不足：Bot Webhook 凭证无权订阅个人账号实时更新流',
    });
  }

  const rawRequested =
    (typeof req.query.accountId === 'string' && req.query.accountId.trim()) ||
    (typeof req.headers['x-account-id'] === 'string' && req.headers['x-account-id'].trim()) ||
    '';

  let scopedAccountFilter = '';
  const authorized: string[] = Array.isArray(session.authorizedAccounts) ? session.authorizedAccounts : [];
  if (!session.isMaster) {
    const lockedAccount = String(authContext.effectiveAccountId || session.accountId || '').trim();
    if (rawRequested && !doesUpdateBelongToAccount(rawRequested, lockedAccount)) {
      return res.status(403).json({
        ok: false,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `权限不足：禁止跨账号订阅 (${rawRequested}) 的实时更新流`,
      });
    }
    scopedAccountFilter = lockedAccount;
  } else if (rawRequested) {
    const isAllowed =
      rawRequested === authContext.effectiveAccountId ||
      rawRequested.startsWith('acc_tg_') ||
      authorized.includes(rawRequested);
    if (!isAllowed) {
      return res.status(403).json({
        ok: false,
        code: 'ACCOUNT_SCOPE_FORBIDDEN',
        error: `权限不足：无权订阅未授权账号 (${rawRequested}) 的实时更新流`,
      });
    }
    scopedAccountFilter = rawRequested;
  }

  res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
  res.setHeader('Cache-Control', 'no-cache, no-transform');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');
  res.flushHeaders?.();

  const sub: SseUpdateSubscriber = {
    id: `sse_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    scopedAccountFilter,
    authorizedAccounts: authorized,
    isMaster: Boolean(session.isMaster),
    res,
  };
  sseUpdateSubscribers.add(sub);

  try {
    res.write(`: connected\n\n`);
    const hasPending = pendingLocalUpdates.some((upd) => {
      if (scopedAccountFilter) return doesUpdateBelongToAccount(upd.accountId, scopedAccountFilter);
      const acc = String(upd.accountId || '').trim();
      return acc.startsWith('acc_tg_') || authorized.includes(acc);
    });
    if (hasPending) {
      res.write(`event: wakeup\ndata: ${JSON.stringify({ kind: 'wakeup', mode: 'initial', ts: Date.now() })}\n\n`);
    }
  } catch {}

  const heartbeat = setInterval(() => {
    if (res.destroyed || res.writableEnded) {
      clearInterval(heartbeat);
      sseUpdateSubscribers.delete(sub);
      return;
    }
    try {
      res.write(`: ping\n\n`);
    } catch {
      clearInterval(heartbeat);
      sseUpdateSubscribers.delete(sub);
    }
  }, 20_000);
  heartbeat.unref?.();

  const cleanup = () => {
    clearInterval(heartbeat);
    sseUpdateSubscribers.delete(sub);
  };
  req.on('close', cleanup);
  res.on('close', cleanup);
});

// In-memory cache of recently sent outbound messages and processed MTProto message IDs to prevent echo duplicates
export const MAX_RECENT_OUTBOUND_IDS = 1000;
export const MAX_RECENT_OUTBOUND_CACHE = 1000;
export const MAX_PROCESSED_MTPROTO_MSG_IDS = 2000;
export const MTPROTO_DEDUP_TTL_MS = 60 * 1000;
export const recentlySentOutboundCache = new Map<string, { count: number; expiresAt: number }>();
export const recentlySentOutboundIds = new Map<string, number>();
export const processedMtprotoMsgIds = new Map<string, number>();

export function pruneOutboundAndMtprotoDedupCaches(now = Date.now()): {
  outboundIdsRemoved: number;
  outboundCacheRemoved: number;
  mtprotoIdsRemoved: number;
} {
  let outboundIdsRemoved = 0;
  for (const [k, exp] of recentlySentOutboundIds.entries()) {
    if (now >= exp) {
      recentlySentOutboundIds.delete(k);
      outboundIdsRemoved++;
    }
  }
  while (recentlySentOutboundIds.size > MAX_RECENT_OUTBOUND_IDS) {
    const oldest = recentlySentOutboundIds.keys().next().value;
    if (oldest === undefined) break;
    recentlySentOutboundIds.delete(oldest);
    outboundIdsRemoved++;
  }

  let outboundCacheRemoved = 0;
  for (const [k, item] of recentlySentOutboundCache.entries()) {
    if (!item || now >= item.expiresAt) {
      recentlySentOutboundCache.delete(k);
      outboundCacheRemoved++;
    }
  }
  while (recentlySentOutboundCache.size > MAX_RECENT_OUTBOUND_CACHE) {
    const oldest = recentlySentOutboundCache.keys().next().value;
    if (oldest === undefined) break;
    recentlySentOutboundCache.delete(oldest);
    outboundCacheRemoved++;
  }

  let mtprotoIdsRemoved = 0;
  for (const [k, ts] of processedMtprotoMsgIds.entries()) {
    if (now - ts >= MTPROTO_DEDUP_TTL_MS) {
      processedMtprotoMsgIds.delete(k);
      mtprotoIdsRemoved++;
    }
  }
  while (processedMtprotoMsgIds.size > MAX_PROCESSED_MTPROTO_MSG_IDS) {
    const oldest = processedMtprotoMsgIds.keys().next().value;
    if (oldest === undefined) break;
    processedMtprotoMsgIds.delete(oldest);
    mtprotoIdsRemoved++;
  }

  return { outboundIdsRemoved, outboundCacheRemoved, mtprotoIdsRemoved };
}

function buildOutboundEchoKey(chatId: string, text: string, accountId?: string): string {
  const scope = accountId ? normalizeAutopilotAccountScope(accountId) : 'shared';
  return `${scope}:${chatId.replace(/^tg_/, '')}:${text.trim()}`;
}

function buildOutboundEchoIdKey(chatId: string, telegramMessageId: number, accountId?: string): string {
  const scope = accountId ? normalizeAutopilotAccountScope(accountId) : 'shared';
  return `${scope}:${chatId.replace(/^tg_/, '')}:${telegramMessageId}`;
}

export function markOutboundTelegramMessageIdSent(chatId: string, telegramMessageId?: number, accountId?: string) {
  if (!telegramMessageId || !Number.isInteger(telegramMessageId) || telegramMessageId <= 0) return;
  const now = Date.now();
  const key = buildOutboundEchoIdKey(chatId, telegramMessageId, accountId);
  if (recentlySentOutboundIds.has(key)) {
    recentlySentOutboundIds.delete(key);
  }
  recentlySentOutboundIds.set(key, now + 30000);
  if (recentlySentOutboundIds.size > 300) {
    for (const [k, exp] of recentlySentOutboundIds.entries()) {
      if (now >= exp) recentlySentOutboundIds.delete(k);
    }
    while (recentlySentOutboundIds.size > MAX_RECENT_OUTBOUND_IDS) {
      const oldest = recentlySentOutboundIds.keys().next().value;
      if (oldest === undefined) break;
      recentlySentOutboundIds.delete(oldest);
    }
  }
}

export function markOutboundMessageSent(chatId: string, text: string, accountId?: string) {
  if (!text) return;
  const key = buildOutboundEchoKey(chatId, text, accountId);
  const now = Date.now();
  const prev = recentlySentOutboundCache.get(key);
  const nextCount = prev && now < prev.expiresAt ? prev.count + 1 : 1;
  if (recentlySentOutboundCache.has(key)) {
    recentlySentOutboundCache.delete(key);
  }
  recentlySentOutboundCache.set(key, { count: nextCount, expiresAt: now + 25000 });
  if (recentlySentOutboundCache.size > 300) {
    for (const [k, item] of recentlySentOutboundCache.entries()) {
      if (now >= item.expiresAt) recentlySentOutboundCache.delete(k);
    }
    while (recentlySentOutboundCache.size > MAX_RECENT_OUTBOUND_CACHE) {
      const oldest = recentlySentOutboundCache.keys().next().value;
      if (oldest === undefined) break;
      recentlySentOutboundCache.delete(oldest);
    }
  }
}

export function isRecentOutboundEcho(
  chatId: string,
  text: string,
  accountId?: string,
  telegramMessageId?: number
): boolean {
  const now = Date.now();
  if (telegramMessageId && Number.isInteger(telegramMessageId) && telegramMessageId > 0) {
    const idKey = buildOutboundEchoIdKey(chatId, telegramMessageId, accountId);
    const idExp = recentlySentOutboundIds.get(idKey);
    if (idExp !== undefined) {
      recentlySentOutboundIds.delete(idKey);
      if (now < idExp) return true;
    }
  }
  if (!text) return false;
  const key = buildOutboundEchoKey(chatId, text, accountId);
  const entry = recentlySentOutboundCache.get(key);
  if (!entry) return false;
  if (now < entry.expiresAt && entry.count > 0) {
    if (entry.count <= 1) {
      recentlySentOutboundCache.delete(key);
    } else {
      recentlySentOutboundCache.set(key, { count: entry.count - 1, expiresAt: entry.expiresAt });
    }
    return true;
  }
  recentlySentOutboundCache.delete(key);
  return false;
}

// Real-time MTProto NewMessage event listener for personal Telegram account (Zero-Database local buffer + Autopilot)
export function attachTelegramClientMessageListener(client: TelegramClient, phone: string, userId: string) {
  try {
    if ((client as any)._hasTgProListener) {
      return;
    }
    (client as any)._hasTgProListener = true;
    const listenerAccountId = `acc_tg_${userId}`;
    const senderEnrichEmittedAt = new Map<string, number>();

    client.addEventHandler(async (event: any) => {
      try {
        if (!isTelegramClientGenerationCurrent(client, { userId, phone, accountId: listenerAccountId })) {
          return;
        }
        const message = event.message;
        if (!message) return;
        markTelegramAccountTrafficAlive(listenerAccountId);

        const senderId = message.senderId ? String(message.senderId) : null;
        const rawChatId = String(message.chatId || senderId || 'unknown');

        // Deduplicate MTProto events per chat+message ID (channel/supergroup IDs are only unique per chat)
        const mtprotoMsgKey = `${userId}_${rawChatId}_${message.id}`;
        if (processedMtprotoMsgIds.has(mtprotoMsgKey)) {
          return;
        }
        const nowDedup = Date.now();
        processedMtprotoMsgIds.set(mtprotoMsgKey, nowDedup);
        if (processedMtprotoMsgIds.size > 500) {
          for (const [k, ts] of processedMtprotoMsgIds.entries()) {
            if (nowDedup - ts >= MTPROTO_DEDUP_TTL_MS) processedMtprotoMsgIds.delete(k);
          }
          while (processedMtprotoMsgIds.size > MAX_PROCESSED_MTPROTO_MSG_IDS) {
            const oldest = processedMtprotoMsgIds.keys().next().value;
            if (oldest === undefined) break;
            processedMtprotoMsgIds.delete(oldest);
          }
        }
        // Always enforce canonical tg_ prefix matching the desktop dialog list
        const canonicalChatId = rawChatId.startsWith('tg_') ? rawChatId : `tg_${rawChatId}`;
        const isOut = Boolean(message.out);
        const createdAt = message.date ? message.date * 1000 : Date.now();
        const messageId = buildTelegramRealtimeMessageId(userId, canonicalChatId, message.id);
        const accountId = `acc_tg_${userId}`;
        const timestamp = new Date(createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });

        const parsedMedia = extractTelegramMediaFields(message, canonicalChatId, accountId);
        const isAudio = parsedMedia.isAudio;
        const audioDuration = parsedMedia.audioDuration;
        // Always use signed /api/telegram/user/media/... URL for real-time voice notes (never write multi-MB Base64 into localStorage)
        const audioUrl: string | undefined = parsedMedia.audioUrl || undefined;
        const isVideo = parsedMedia.isVideo;
        const videoDuration = parsedMedia.videoDuration;
        const videoUrl: string | undefined = parsedMedia.videoUrl || undefined;
        const isImage = parsedMedia.isImage;
        const imageUrl: string | undefined = parsedMedia.imageUrl || undefined;
        const isFile = parsedMedia.isFile;
        const fileUrl: string | undefined = parsedMedia.fileUrl || undefined;

        const text = parsedMedia.text || '';

        // Filter out echo duplicates for outbound messages already sent by this applet (scoped per account)
        if (isOut && isRecentOutboundEcho(canonicalChatId, text, accountId, Number(message.id))) {
          return;
        }

        const isOfficialService =
          rawChatId === '777000' ||
          senderId === '777000' ||
          canonicalChatId === 'tg_777000' ||
          rawChatId === '42777' ||
          senderId === '42777' ||
          canonicalChatId === 'tg_42777';

        let replyTo: { id: string; senderName?: string; text: string } | undefined = undefined;
        const replyToId = Number((message as any).replyTo?.replyToMsgId || 0);
        if (replyToId > 0) {
          const quoteText = String((message as any).replyTo?.quoteText || '').trim();
          replyTo = {
            id: buildTelegramRealtimeMessageId(userId, canonicalChatId, replyToId),
            senderName: '回复消息',
            text: quoteText || `消息 #${replyToId}`,
          };
        }

        const msgChatObj: any = (message as any).chat;
        const isChannelMsg = Boolean(
          (message as any).isChannel &&
            !msgChatObj?.megagroup &&
            !(message as any).isGroup
        );
        const isGroupMsg = Boolean(
          ((message as any).isGroup || msgChatObj?.megagroup || /^tg_-/.test(canonicalChatId)) &&
            !isChannelMsg
        );
        const resolvedChatTitle =
          typeof msgChatObj?.title === 'string' && msgChatObj.title.trim()
            ? msgChatObj.title.trim()
            : undefined;
        const msgConnObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);

        let senderInfo: TelegramSenderInfoResult;
        let needsBackgroundSenderEnrich = false;
        if (isOfficialService) {
          senderInfo = { senderId: senderId || '', senderName: 'Telegram 官方服务通知', senderAvatarUrl: undefined };
        } else {
          const syncSender = peekTelegramMessageSenderInfoSync(
            message,
            isOut,
            accountId,
            msgConnObj,
            canonicalChatId,
            rawChatId
          );
          if (syncSender.hit) {
            senderInfo = syncSender.info;
          } else if (!isGroupMsg && !isChannelMsg) {
            // Private chats (e.g. UpdateShortMessage where GramJS leaves m.sender empty) push immediately
            // with zero P2 RPC blocking; sender metadata enriches asynchronously in the background.
            senderInfo = syncSender.info;
            needsBackgroundSenderEnrich = !isOut && typeof (message as any)?.getSender === 'function';
          } else {
            senderInfo = await resolveTelegramMessageSenderInfo(message, isOut, accountId);
          }
        }

        const realtimeUpdate: LocalIncomingUpdate = {
          id: messageId,
          telegramMessageId: Number(message.id),
          chatId: canonicalChatId,
          rawChatId,
          accountId,
          sender: parsedMedia.systemEventType ? 'system' : (isOut ? 'me' : 'peer'),
          ...(parsedMedia.systemEventType ? { systemEventType: parsedMedia.systemEventType } : {}),
          senderName: senderInfo.senderName,
          ...(senderInfo.senderId ? { senderId: senderInfo.senderId } : {}),
          ...(senderInfo.senderAvatarUrl ? { senderAvatarUrl: senderInfo.senderAvatarUrl } : {}),
          ...(isGroupMsg ? { isGroup: true } : {}),
          ...(isChannelMsg ? { isChannel: true } : {}),
          ...(resolvedChatTitle ? { chatTitle: resolvedChatTitle } : {}),
          text,
          timestamp,
          createdAt,
          isAudio,
          audioDuration,
          audioUrl,
          isVideo,
          videoDuration,
          videoWidth: parsedMedia.videoWidth,
          videoHeight: parsedMedia.videoHeight,
          videoUrl,
          isImage,
          imageUrl,
          imageCaption: parsedMedia.imageCaption || undefined,
          isFile,
          fileName: parsedMedia.fileName,
          fileSize: parsedMedia.fileSize,
          fileUrl,
          replyTo,
          isEdited: Boolean((message as any).editDate),
          isPinned: Boolean((message as any).pinned),
        };
        pushPendingLocalUpdate(realtimeUpdate);
        if (msgConnObj && Array.isArray(msgConnObj.dialogs)) {
          const matchedCachedDlg: any = msgConnObj.dialogs.find(
            (d: any) => d && (String(d.id) === canonicalChatId || String(d.rawId || '') === rawChatId)
          );
          if (matchedCachedDlg) {
            const summaryText = summarizeTelegramDialogMedia(message);
            const msgDateSec = message.date ? Number(message.date) : Math.floor(createdAt / 1000);
            patchConnectedDialogCache(
              msgConnObj,
              canonicalChatId,
              {
                lastMessage: summaryText,
                lastTime: timestamp,
                lastDate: Math.max(Number(matchedCachedDlg.lastDate || 0), msgDateSec),
                ...(!isOut && !parsedMedia.systemEventType ? { unreadCount: Number(matchedCachedDlg.unreadCount || 0) + 1 } : {}),
              },
              { invalidateCache: Boolean(!isOut && !parsedMedia.systemEventType && matchedCachedDlg.isArchived && !matchedCachedDlg.isMuted) }
            );
          } else {
            msgConnObj.dialogsFetchedAt = 0;
            msgConnObj.dialogsInFlight = undefined;
          }
        }

        // Persist real-time MTProto message into unified conversation store via HIGH-priority queue (zero main-thread stall)
        void upsertSyncedMessageToDb(realtimeUpdate, canonicalChatId, accountId, {
          priority: 'HIGH',
          source: 'realtime_new_message',
        });

        if (needsBackgroundSenderEnrich) {
          void resolveTelegramMessageSenderInfo(message, isOut, accountId)
            .then((resolved) => {
              if (!isTelegramClientGenerationCurrent(client, { userId, phone, accountId: listenerAccountId })) {
                return;
              }
              const resolvedName = String(resolved?.senderName || '').trim();
              if (!resolvedName) return;
              const latestConn = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
              if (latestConn && Array.isArray(latestConn.dialogs)) {
                const dlg: any = latestConn.dialogs.find(
                  (d: any) => d && (String(d.id) === canonicalChatId || String(d.rawId || '') === rawChatId)
                );
                if (dlg && (!dlg.title || /^Telegram\s*\(/i.test(String(dlg.title)))) {
                  patchConnectedDialogCache(latestConn, canonicalChatId, { title: resolvedName });
                }
              }
              if (!senderInfo.senderName || senderInfo.senderName !== resolvedName) {
                void enqueueMessageDbWrite({
                  priority: 'LOW',
                  kind: 'edit',
                  accountId,
                  chatId: canonicalChatId,
                  tgMsgIds: Number(message.id) > 0 ? [Number(message.id)] : [],
                  msgId: messageId,
                  exec: async () => {
                    await db
                      .prepare(
                        `UPDATE messages SET sender_name = ? WHERE id = ? AND (sender_name IS NULL OR sender_name = '')`
                      )
                      .run(resolvedName, messageId);
                  },
                }).catch(() => {});
                const enrichKey = `${canonicalChatId}::${resolvedName}`;
                const nowEnrichMs = Date.now();
                const lastEmittedAt = senderEnrichEmittedAt.get(enrichKey) || 0;
                if (nowEnrichMs - lastEmittedAt >= 3000) {
                  senderEnrichEmittedAt.set(enrichKey, nowEnrichMs);
                  if (senderEnrichEmittedAt.size > 300) {
                    const oldest = senderEnrichEmittedAt.keys().next().value;
                    if (oldest) senderEnrichEmittedAt.delete(oldest);
                  }
                  pushPendingLocalUpdate({
                    id: `sender_enrich_${userId}_${rawChatId}_${message.id}_${nowEnrichMs}`,
                    type: 'peer_profile',
                    chatId: canonicalChatId,
                    rawChatId,
                    accountId,
                    sender: 'peer',
                    senderName: resolvedName,
                    profileName: resolvedName,
                    ...(resolved.senderAvatarUrl ? { profileAvatarUrl: resolved.senderAvatarUrl } : {}),
                    text: '',
                    timestamp: '',
                    createdAt: nowEnrichMs,
                  });
                }
              }
            })
            .catch(() => {});
        }

        // Check if Autopilot is enabled for this chat strictly scoped by accountId (NEVER run Autopilot on official notifications or group join/leave notices)
        const isAutopilotOn =
          !parsedMedia.systemEventType &&
          !isOfficialService &&
          (isAutopilotEnabledForChat(accountId, canonicalChatId) || isAutopilotEnabledForChat(accountId, rawChatId));

        if (!isOut && isAutopilotOn) {
          console.log(`[HumanSense Autopilot] Auto-generating holographic memory reply for chat ${canonicalChatId}...`);
          setImmediate(async () => {
            try {
              const rawServerCustomConfig = await getServerCustomLlmConfig().catch(() => null);
              const isDualOff = Boolean(
                rawServerCustomConfig &&
                  (rawServerCustomConfig.enabled === false || rawServerCustomConfig.explicitlyDisabled)
              );
              if (isDualOff) {
                console.warn(
                  `[HumanSense Autopilot Dual-Off Guard] Chat ${canonicalChatId}: 当前处于双关状态（官方大模型与自有密钥均已关闭），跳过自动回复并保持静默。`
                );
                return;
              }

              const serverCustomConfig =
                rawServerCustomConfig ||
                (lastActiveUserJwt || (process.env.RAILWAY_BRAIN_KEY || '').trim()
                  ? {
                      enabled: true,
                      explicitlyDisabled: false,
                      engineMode: 'cloud',
                      modelName: 'gemini-4-hydrogen',
                      enableKnowledgeBaseRAG: true,
                    }
                  : null);
              const isPriorityCustom = Boolean(
                serverCustomConfig?.enabled && serverCustomConfig?.engineMode === 'custom'
              );

              // 0. If incoming message is a voice note without transcript text, download and transcribe via 3-state STT
              let effectiveIncomingText = (text || '').trim();
              const isVoicePlaceholder =
                isAudio &&
                (!effectiveIncomingText || /^(\[语音消息\]|Voice Message|🎤)/i.test(effectiveIncomingText));
              if (isVoicePlaceholder) {
                if (!message.media) {
                  console.warn(`[HumanSense Autopilot Voice Guard] Chat ${canonicalChatId}: 语音消息缺少可下载媒体体，跳过自动回复。`);
                  return;
                }
                try {
                  const downloaded = await client.downloadMedia(message, {});
                  const audioBuf = Buffer.isBuffer(downloaded)
                    ? downloaded
                    : downloaded
                    ? Buffer.from(downloaded as any)
                    : Buffer.alloc(0);
                  const voiceMimeType =
                    String((message.media as any)?.document?.mimeType || '').trim() || 'audio/ogg';
                  const sttRes = await transcribeAudioBufferStrictly(
                    audioBuf,
                    voiceMimeType,
                    serverCustomConfig
                  );
                  if (!sttRes.ok || !sttRes.text.trim()) {
                    console.warn(
                      `[HumanSense Autopilot Voice STT Failed] Chat ${canonicalChatId}: ${sttRes.error || '未能识别语音文字'}，严禁对占位符自动回复。`
                    );
                    return;
                  }
                  effectiveIncomingText = sttRes.text.trim();
                  try {
                    await enqueueMessageDbWrite({
                      priority: 'NORMAL',
                      kind: 'edit',
                      accountId,
                      chatId: canonicalChatId,
                      tgMsgIds: Number(message.id) > 0 ? [Number(message.id)] : [],
                      msgId: messageId,
                      exec: async () => {
                        await db
                          .prepare(`UPDATE messages SET stt_text = ? WHERE id = ?`)
                          .run(effectiveIncomingText, messageId);
                      },
                    });
                  } catch {}
                  pushPendingLocalUpdate({
                    ...realtimeUpdate,
                    sttText: effectiveIncomingText,
                  });
                } catch (voiceErr: any) {
                  console.warn(
                    `[HumanSense Autopilot Voice Download/STT Error] Chat ${canonicalChatId}: ${voiceErr?.message || String(voiceErr)}`
                  );
                  return;
                }
              }

              if (!effectiveIncomingText) {
                console.warn(`[HumanSense Autopilot Guard] Chat ${canonicalChatId}: 入站消息无有效文本内容，跳过自动回复。`);
                return;
              }

              // 1. Get customer profile from database strictly scoped by accountId
              const p =
                (await getScopedCustomerProfile(canonicalChatId, accountId)) ||
                (await getScopedCustomerProfile(rawChatId, accountId)) ||
                (await getScopedCustomerProfile(`tg_${rawChatId}`, accountId));
              const likes = p ? safeJsonParse<string[]>(p.likes_interests, []) : [];
              const taboos = p ? safeJsonParse<string[]>(p.dislikes_taboos, []) : [];
              const memories = p ? safeJsonParse<any[]>(p.key_memories, []) : [];

              // Retrieve active Global Persona, Evolution state, and Oral Transcript styles strictly scoped by accountId
              let autoPersonaContext = '';
              let autoHabitIds: string[] = [];
              let hasAutoConfiguredPersona = false;
              try {
                const autoPersona = await getGlobalPersonaFromDb(accountId);
                const autoEvo = await getEvolutionStateFromDb(accountId);
                const autoStageOverride = resolveCustomerPersonaStageKey(p?.relationship_stage);
                const autoCtx = buildActivePersonaAndEvolutionContext(autoPersona, autoEvo, autoStageOverride, 3);
                autoPersonaContext = autoCtx.context;
                autoHabitIds = autoCtx.activeHabitIds;
                hasAutoConfiguredPersona = autoCtx.hasConfiguredPersona;
              } catch {}

              const { cloudKbEnabled: autoCloudKbEnabled, localKbEnabled: autoLocalKbEnabled } =
                resolveKnowledgeRagScope(serverCustomConfig);
              const oralStyleContext = autoLocalKbEnabled
                ? await loadUnifiedTranscriptContext(accountId)
                : '';

              // Retrieve recent 30 two-way conversation turns strictly scoped by accountId so replies never leak across accounts
              let recentHistoryTurns: NormalizedChatTurn[] = [];
              try {
                recentHistoryTurns = await extractRecentTwoWayMessages(canonicalChatId, rawChatId, [], 30, accountId);
                // Avoid duplicating the current incoming turn if upsertSyncedMessageToDb already saved it
                recentHistoryTurns = recentHistoryTurns.filter((t) => t.id !== messageId);
                if (
                  recentHistoryTurns.length > 0 &&
                  recentHistoryTurns[recentHistoryTurns.length - 1].sender === 'peer' &&
                  recentHistoryTurns[recentHistoryTurns.length - 1].text.trim() === effectiveIncomingText
                ) {
                  recentHistoryTurns.pop();
                }
              } catch {}

              // Retrieve Cloud Brain Knowledge Base (Official Cloud only) OR Local SQLite RAG (Custom LLM only)
              const autoRagQuery = buildUnifiedRagQuery(recentHistoryTurns, effectiveIncomingText);
              let kbContext = '';
              if (autoCloudKbEnabled) {
                let railwayRes: RemoteKbSearchResult;
                try {
                  railwayRes = await searchRailwayKnowledgeBase(
                    autoRagQuery,
                    serverCustomConfig?.knowledgeBaseApiUrl,
                    serverCustomConfig?.knowledgeBaseApiKey || serverCustomConfig?.apiKey,
                    7000,
                    lastActiveUserJwt || undefined,
                    serverCustomConfig?.engineLicenseKey
                  );
                } catch (kbErr: any) {
                  railwayRes = {
                    ok: false,
                    connected: false,
                    context: '',
                    matchedCount: 0,
                    source: 'remote_cloud_kb_error',
                    error: kbErr?.message || '云端知识库检索异常',
                    statusCode: 502,
                  };
                }
                if (!railwayRes.ok) {
                  console.warn(
                    `[HumanSense Autopilot Cloud KB Guard] Chat ${canonicalChatId}: 云端知识库检索断连或失败 (${railwayRes.error || '未知网络错误'})，触发安全阻断并保持静默（严禁降级自动回复）`
                  );
                  return;
                }
                if (railwayRes.matchedCount > 0 && railwayRes.context) {
                  kbContext += `\n${railwayRes.context}\n`;
                }
              } else if (autoLocalKbEnabled) {
                try {
                  const localRag = await queryKnowledgeRAG(autoRagQuery, 3, accountId);
                  if (localRag.matchedCount > 0 && localRag.context) {
                    kbContext += `\n${localRag.context}\n`;
                  }
                } catch {}
              }

              const cleanAutoIncoming = String(effectiveIncomingText || '').replace(/^📊\s*投票\s*[:：]\s*/, '').trim();
              let targetLangCode =
                cleanAutoIncoming && !isSystemMediaPlaceholderText(cleanAutoIncoming)
                  ? detectSourceLangCode(cleanAutoIncoming)
                  : '';
              if (!targetLangCode && Array.isArray(recentHistoryTurns)) {
                for (let i = recentHistoryTurns.length - 1; i >= 0; i--) {
                  const turn = recentHistoryTurns[i];
                  if (!turn || turn.sender !== 'peer') continue;
                  const candidate = String(turn.text || '').replace(/^📊\s*投票\s*[:：]\s*/, '').trim();
                  if (!candidate || isSystemMediaPlaceholderText(candidate)) continue;
                  const code = detectSourceLangCode(candidate);
                  if (code) {
                    targetLangCode = code;
                    break;
                  }
                }
              }
              if ((!targetLangCode || targetLangCode === 'zh-CN') && p?.location_timezone) {
                const tz = String(p.location_timezone).toLowerCase();
                if (tz.includes('istanbul') || tz.includes('turkey') || tz.includes('土耳其')) targetLangCode = 'tr';
                else if (tz.includes('moscow') || tz.includes('russia') || tz.includes('俄')) targetLangCode = 'ru';
                else if (tz.includes('utc+') || tz.includes('london') || tz.includes('america')) targetLangCode = 'en';
              }
              const langConstraint = (targetLangCode && targetLangCode !== 'zh-CN')
                ? `【母语强制约束】：检测到客户当前发送的消息语言为 ${targetLangCode}（如土耳其语、英语等）。你必须 100% 严格使用地道纯正的对应母语回复对方，绝不允许使用中文回复客户！`
                : '';

              const isColdStartAutopilot = isCustomerColdStartProfile(p, likes, memories);
              const autopilotColdStartGuideline = buildUnifiedColdStartGuideline(isColdStartAutopilot, likes);

              const autoBasePersona = `${
                hasAutoConfiguredPersona
                  ? autoPersonaContext
                  : '你是一位真诚自然、高效有温度的沟通助手。'
              }${
                !hasAutoConfiguredPersona && autoPersonaContext
                  ? `\n\n${autoPersonaContext}`
                  : ''
              }`;

              const autoProfileSection = p
                ? buildCustomerProfilePromptSection(
                    p,
                    likes,
                    Array.isArray(taboos) ? taboos : [],
                    memories,
                    canonicalChatId
                  )
                : '';

              const budgetedAutopilotPrompt = applyPromptCharacterBudget({
                persona: autoBasePersona,
                antiAi: buildUnifiedAntiAiDirective(UNIFIED_REPLY_HISTORY_LIMIT),
                coldStartGuideline: autopilotColdStartGuideline,
                profile: autoProfileSection,
                knowledge: kbContext.trim(),
                transcripts: oralStyleContext.trim(),
                langConstraint: langConstraint.trim(),
              });
              const memoryPrompt = budgetedAutopilotPrompt.prompt;

              const contextMessages = [
                ...recentHistoryTurns.map((t) => ({
                  role: t.sender === 'me' ? 'assistant' : 'user',
                  content: t.text,
                })),
                { role: 'user', content: effectiveIncomingText },
              ];

              let replyText = '';
              if (serverCustomConfig?.enabled) {
                try {
                  const candidate = await callCustomLlm({
                    customConfig: serverCustomConfig,
                    systemInstruction: memoryPrompt,
                    messages: contextMessages,
                    temperature: 0.7,
                    maxTokens: 500,
                    timeoutMs: 120000,
                    userJwt: lastActiveUserJwt || undefined,
                    throwOnError: true,
                    skipSync: true,
                  });
                  if (candidate?.trim()) {
                    replyText = extractStructuredReplyText(candidate);
                  }
                } catch (autoLlmErr: any) {
                  console.warn(
                    `[HumanSense Autopilot LLM Guard] Chat ${canonicalChatId}: ${
                      isPriorityCustom ? '自定义大模型' : '云端引擎'
                    }调用失败 (${autoLlmErr?.message || String(autoLlmErr)})，严格保持静默`
                  );
                }
              } else {
                console.warn(
                  `[HumanSense Autopilot Guard] Chat ${canonicalChatId}: 未检测到可用的大模型会话或授权令牌，跳过自动回复`
                );
              }

              if (replyText) {
                const autoFlood = getTelegramFloodCooldown({ accountId, userId });
                if (autoFlood) {
                  console.warn(
                    `[HumanSense Autopilot Flood Guard] Account ${accountId} in cooldown (${autoFlood.retryAfterSeconds}s left), skipping auto-reply to ${canonicalChatId}`
                  );
                  return;
                }
                const cleanPeer = rawChatId.replace(/^tg_/, '');
                const rawPeer: any = /^-?\d+$/.test(cleanPeer) ? Number(cleanPeer) : cleanPeer;
                markOutboundMessageSent(canonicalChatId, replyText, accountId);
                try {
                  await scheduleTelegramRpc(accountId, 'P0', 'autopilot.sendMessage', () =>
                    client.sendMessage(rawPeer, { message: replyText })
                  );
                } catch (autoSendErr: any) {
                  recordTelegramFloodWait({ accountId, userId }, autoSendErr, 'autopilot.sendMessage');
                  throw autoSendErr;
                }
                void incrementEvolutionHabitUsage(autoHabitIds, accountId);
                const replyMsgId = `msg_auto_${Date.now()}`;
                let replyZh = '';
                try {
                  const autopilotChatTargetLang = (await getScopedChatTargetLang(canonicalChatId, accountId)) || undefined;
                  replyZh = await getCnTranslationIfForeign(
                    replyText,
                    serverCustomConfig,
                    lastActiveUserJwt || undefined,
                    autopilotChatTargetLang,
                    accountId
                  );
                } catch {}
                const replyTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });

                try {
                  await enqueueMessageDbWrite({
                    priority: 'HIGH',
                    kind: 'upsert',
                    accountId,
                    chatId: canonicalChatId,
                    msgId: replyMsgId,
                    exec: async () => {
                      await db.prepare(`
                        INSERT INTO messages (
                          id, chat_id, account_id, sender, sender_name, text, translated_text,
                          timestamp, created_at, delivery_status
                        ) VALUES (?, ?, ?, 'me', '我方 (AI托管)', ?, ?, ?, ?, 'delivered')
                      `).run(replyMsgId, canonicalChatId, accountId, replyText, replyZh, replyTime, Date.now());
                    },
                  });
                } catch {}

                pushPendingLocalUpdate({
                  id: replyMsgId,
                  chatId: canonicalChatId,
                  rawChatId,
                  accountId,
                  sender: 'me',
                  senderName: '我方 (AI托管)',
                  text: replyText,
                  translatedText: replyZh,
                  timestamp: replyTime,
                  createdAt: Date.now(),
                });
                console.log(`[HumanSense Autopilot] Sent auto-reply to ${canonicalChatId}: "${replyText}"`);
              }
            } catch (autoErr: any) {
              console.warn('[HumanSense Autopilot Exception]:', autoErr?.message || String(autoErr));
            }
          });
        }
      } catch (e: any) {
        console.warn('[MTProto Message Listener Event Error]:', e.message);
      }
    }, new NewMessage({}));

    // Real-time MTProto Raw updates for Message Edits, Deletions, Outbox Read Receipts & Pinned Changes
    const resolveRawPeerChatId = (peer: any): string => {
      if (!peer) return '';
      if (peer.userId !== undefined) return `tg_${String(peer.userId)}`;
      if (peer.chatId !== undefined) return `tg_-${String(peer.chatId)}`;
      if (peer.channelId !== undefined) return `tg_-100${String(peer.channelId)}`;
      return '';
    };

    let lastSelfProfileSyncAt = 0;
    const peerMetaSyncAt = new Map<string, number>();

    client.addEventHandler(async (update: any) => {
      try {
        const accountId = `acc_tg_${userId}`;
        if (!isTelegramClientGenerationCurrent(client, { userId, phone, accountId })) {
          return;
        }
        if (update instanceof Api.UpdateUserName) {
          const firstName = String(update.firstName || '').trim();
          const lastName = String(update.lastName || '').trim();
          const fullName = [firstName, lastName].filter(Boolean).join(' ').trim() || 'Telegram 用户';
          const usernamesList = Array.isArray(update.usernames) ? update.usernames : [];
          const primaryU =
            usernamesList.find((u: any) => u?.active !== false && u?.editable && u?.username) ||
            usernamesList.find((u: any) => u?.active !== false && u?.username);
          const cleanU = primaryU?.username ? String(primaryU.username).replace(/^@/, '').trim() : '';
          const formattedU = cleanU ? `@${cleanU}` : '';
          const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
          if (String(update.userId) !== String(userId)) {
            const targetUid = update.userId !== undefined ? String(update.userId) : '';
            if (!targetUid) return;
            const peerChatId = `tg_${targetUid}`;
            let resolvedTitle: string | undefined = [firstName, lastName].filter(Boolean).join(' ').trim() || undefined;
            try {
              const { inputPeer } = await resolveTelegramInputPeer(client, peerChatId, userId, 'P2');
              const ent: any = await scheduleTelegramRpc(accountId, 'P2', 'raw.updateUserName.getEntity', () =>
                client.getEntity(inputPeer)
              );
              if (ent?.contact) {
                const savedContactName = [ent?.firstName, ent?.lastName].filter(Boolean).join(' ').trim();
                resolvedTitle = savedContactName || undefined;
              }
            } catch {}
            patchConnectedDialogCache(connObj, peerChatId, {
              ...(resolvedTitle ? { title: resolvedTitle } : {}),
              username: cleanU,
            });
            pushPendingLocalUpdate({
              id: `peername_${userId}_${targetUid}_${Date.now()}`,
              type: 'peer_profile',
              chatId: peerChatId,
              accountId,
              sender: 'peer',
              senderName: resolvedTitle || formattedU || targetUid,
              ...(resolvedTitle ? { profileName: resolvedTitle } : {}),
              profileUsername: formattedU,
              text: '',
              timestamp: '',
              createdAt: Date.now(),
            });
            return;
          }
          if (connObj) {
            connObj.firstName = firstName;
            connObj.lastName = lastName;
            connObj.username = formattedU;
            connObj.avatarInitial = fullName.slice(0, 2).toUpperCase();
          }
          try {
            await db
              .prepare('UPDATE telegram_user_sessions SET first_name = ?, username = ?, updated_at = ? WHERE user_id = ?')
              .run(fullName, cleanU, Date.now(), String(userId));
          } catch {}
          pushPendingLocalUpdate({
            id: `selfprof_${userId}_${Date.now()}`,
            type: 'self_profile',
            chatId: '',
            accountId,
            sender: 'me',
            senderName: fullName,
            profileName: fullName,
            profileUsername: formattedU,
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateUser) {
          const targetUid = update.userId !== undefined ? String(update.userId) : '';
          if (!targetUid) return;
          invalidateTelegramAvatarCacheEntries(userId, targetUid);
          clearAvatarNegativeCacheForPeer(userId, targetUid);
          invalidateTelegramSenderCache(accountId, targetUid);
          if (targetUid !== String(userId)) {
            const nowMs = Date.now();
            const prevSync = peerMetaSyncAt.get(`u:${targetUid}`) || 0;
            if (nowMs - prevSync >= 3000) {
              peerMetaSyncAt.set(`u:${targetUid}`, nowMs);
              if (peerMetaSyncAt.size > 300) {
                const oldestKey = peerMetaSyncAt.keys().next().value;
                if (oldestKey) peerMetaSyncAt.delete(oldestKey);
              }
              try {
                const peerChatId = `tg_${targetUid}`;
                const { inputPeer } = await resolveTelegramInputPeer(client, peerChatId, userId, 'P2');
                const peerEntity: any = await scheduleTelegramRpc(accountId, 'P2', 'raw.updateUser.getEntity', () =>
                  client.getEntity(inputPeer)
                );
                const fullName = [peerEntity?.firstName, peerEntity?.lastName].filter(Boolean).join(' ').trim();
                const cleanU = peerEntity?.username ? String(peerEntity.username).replace(/^@/, '').trim() : '';
                const formattedU = cleanU ? `@${cleanU}` : '';
                const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
                patchConnectedDialogCache(connObj, peerChatId, {
                  ...(fullName ? { title: fullName } : {}),
                  username: cleanU,
                });
                pushPendingLocalUpdate({
                  id: `peeruser_${userId}_${targetUid}_${nowMs}`,
                  type: 'peer_profile',
                  chatId: peerChatId,
                  accountId,
                  sender: 'peer',
                  senderName: fullName || formattedU || targetUid,
                  ...(fullName ? { profileName: fullName } : {}),
                  profileUsername: formattedU,
                  profileAvatarUrl: signTelegramResourceUrl(`/api/telegram/user/avatar/${targetUid}?v=${nowMs}`, accountId),
                  text: '',
                  timestamp: '',
                  createdAt: nowMs,
                });
              } catch {}
            }
            return;
          }
          const nowMs = Date.now();
          if (nowMs - lastSelfProfileSyncAt >= 3000) {
            lastSelfProfileSyncAt = nowMs;
            try {
              const fullRes: any = await scheduleTelegramRpc(accountId, 'P2', 'raw.selfFullUser', () =>
                client.invoke(new Api.users.GetFullUser({ id: new Api.InputUserSelf() }))
              );
              const meU: any = Array.isArray(fullRes?.users)
                ? fullRes.users.find((u: any) => u?.self || String(u?.id) === String(userId)) || fullRes.users[0]
                : null;
              if (meU) {
                const firstName = String(meU.firstName || '').trim();
                const lastName = String(meU.lastName || '').trim();
                const fullName = [firstName, lastName].filter(Boolean).join(' ').trim() || 'Telegram 用户';
                const cleanU = meU.username ? String(meU.username).replace(/^@/, '').trim() : '';
                const formattedU = cleanU ? `@${cleanU}` : '';
                const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
                if (connObj) {
                  connObj.firstName = firstName;
                  connObj.lastName = lastName;
                  connObj.username = formattedU;
                  connObj.avatarInitial = fullName.slice(0, 2).toUpperCase();
                }
                try {
                  await db
                    .prepare('UPDATE telegram_user_sessions SET first_name = ?, username = ?, updated_at = ? WHERE user_id = ?')
                    .run(fullName, cleanU, Date.now(), String(userId));
                } catch {}
                pushPendingLocalUpdate({
                  id: `selfuser_${userId}_${Date.now()}`,
                  type: 'self_profile',
                  chatId: '',
                  accountId,
                  sender: 'me',
                  senderName: fullName,
                  profileName: fullName,
                  profileUsername: formattedU,
                  profileAvatarUrl: signTelegramResourceUrl(`/api/telegram/user/avatar/${userId}?v=${Date.now()}`, accountId),
                  text: '',
                  timestamp: '',
                  createdAt: Date.now(),
                });
              }
            } catch {}
          }
          return;
        }

        if (update instanceof Api.UpdateChat || update instanceof Api.UpdateChannel) {
          const isCh = update instanceof Api.UpdateChannel;
          const rawEntityId = isCh
            ? String((update as Api.UpdateChannel).channelId || '')
            : String((update as Api.UpdateChat).chatId || '');
          if (!rawEntityId) return;
          const peerChatId = isCh ? `tg_-100${rawEntityId}` : `tg_-${rawEntityId}`;
          const rawNumId = isCh ? `-100${rawEntityId}` : `-${rawEntityId}`;
          const nowMs = Date.now();
          const prevSync = peerMetaSyncAt.get(peerChatId) || 0;
          if (nowMs - prevSync < 3000) return;
          peerMetaSyncAt.set(peerChatId, nowMs);
          if (peerMetaSyncAt.size > 300) {
            const oldestKey = peerMetaSyncAt.keys().next().value;
            if (oldestKey) peerMetaSyncAt.delete(oldestKey);
          }
          invalidateTelegramAvatarCacheEntries(userId, rawNumId);
          clearAvatarNegativeCacheForPeer(userId, rawNumId);
          invalidateTelegramSenderCache(accountId, rawNumId);
          try {
            const { inputPeer } = await resolveTelegramInputPeer(client, peerChatId, userId, 'P2');
            const ent: any = await scheduleTelegramRpc(accountId, 'P2', 'raw.updateChat.getEntity', () =>
              client.getEntity(inputPeer)
            );
            const nextTitle = String(ent?.title || '').trim();
            const cleanU = ent?.username ? String(ent.username).replace(/^@/, '').trim() : '';
            const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
            patchConnectedDialogCache(connObj, peerChatId, {
              ...(nextTitle ? { title: nextTitle } : {}),
              ...(isCh ? { username: cleanU } : {}),
            });
            pushPendingLocalUpdate({
              id: `chatmeta_${userId}_${rawNumId}_${nowMs}`,
              type: 'chat_meta',
              chatId: peerChatId,
              accountId,
              sender: 'peer',
              senderName: nextTitle,
              ...(nextTitle ? { profileName: nextTitle } : {}),
              ...(isCh ? { profileUsername: cleanU ? `@${cleanU}` : '' } : {}),
              profileAvatarUrl: signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(rawNumId)}?v=${nowMs}`, accountId),
              text: '',
              timestamp: '',
              createdAt: nowMs,
            });
          } catch {}
          return;
        }

        if (
          update instanceof Api.UpdateDialogFilter ||
          update instanceof Api.UpdateDialogFilterOrder ||
          update instanceof Api.UpdateDialogFilters
        ) {
          pushPendingLocalUpdate({
            id: `fld_${userId}_${Date.now()}`,
            type: 'folders_updated',
            chatId: '',
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateEditMessage || update instanceof Api.UpdateEditChannelMessage) {
          const msgObj: any = update.message;
          if (!msgObj || !msgObj.id) return;
          const peerChatId = resolveRawPeerChatId(msgObj.peerId);
          if (!peerChatId) return;
          const tgMsgId = Number(msgObj.id);
          const editedText = typeof msgObj.message === 'string' ? msgObj.message : '';
          pushPendingLocalUpdate({
            id: `edit_${userId}_${tgMsgId}_${Date.now()}`,
            type: 'edit',
            telegramMessageId: tgMsgId,
            chatId: peerChatId,
            accountId,
            sender: msgObj.out ? 'me' : 'peer',
            senderName: msgObj.out ? '我方' : '对方',
            text: editedText,
            timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
            createdAt: Date.now(),
            isEdited: true,
          });
          await enqueueMessageDbWrite({
            priority: 'NORMAL',
            kind: 'edit',
            accountId,
            chatId: peerChatId,
            tgMsgIds: [tgMsgId],
            exec: async () => {
              const altChatId = peerChatId.replace(/^tg_/, '');
              await db
                .prepare(
                  `UPDATE messages
                   SET text = CASE WHEN ? != '' THEN ? ELSE text END,
                       image_caption = CASE WHEN (is_image = 1 OR is_video = 1) THEN ? ELSE image_caption END,
                       is_edited = 1
                   WHERE (chat_id = ? OR chat_id = ?) AND telegram_message_id = ? AND account_id = ?`
                )
                .run(editedText, editedText, editedText, peerChatId, altChatId, tgMsgId, accountId);
            },
          }).catch(() => {});
          return;
        }

        if (update instanceof Api.UpdateDeleteMessages) {
          const delIds = (update.messages || []).map((n: any) => Number(n)).filter((n: number) => Number.isInteger(n) && n > 0);
          if (delIds.length === 0) return;
          pushPendingLocalUpdate({
            id: `del_${userId}_${Date.now()}_${Math.random().toString(36).slice(2, 5)}`,
            type: 'delete',
            deletedMessageIds: delIds,
            chatId: '',
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          await enqueueMessageDbWrite({
            priority: 'NORMAL',
            kind: 'delete_non_channel',
            accountId,
            tgMsgIds: delIds,
            exec: async () => {
              const placeholders = delIds.map(() => '?').join(', ');
              await db
                .prepare(
                  `DELETE FROM messages WHERE account_id = ? AND chat_id NOT LIKE 'tg_-100%' AND chat_id NOT LIKE '-100%' AND telegram_message_id IN (${placeholders})`
                )
                .run(accountId, ...delIds);
            },
          }).catch(() => {});
          return;
        }

        if (update instanceof Api.UpdateDeleteChannelMessages) {
          const delIds = (update.messages || []).map((n: any) => Number(n)).filter((n: number) => Number.isInteger(n) && n > 0);
          const channelChatId = update.channelId ? `tg_-100${String(update.channelId)}` : '';
          if (delIds.length === 0) return;
          pushPendingLocalUpdate({
            id: `delch_${userId}_${Date.now()}_${Math.random().toString(36).slice(2, 5)}`,
            type: 'delete',
            deletedMessageIds: delIds,
            chatId: channelChatId,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          if (channelChatId) {
            await enqueueMessageDbWrite({
              priority: 'NORMAL',
              kind: 'delete_channel',
              accountId,
              chatId: channelChatId,
              tgMsgIds: delIds,
              exec: async () => {
                const placeholders = delIds.map(() => '?').join(', ');
                const alt = channelChatId.replace(/^tg_/, '');
                await db
                  .prepare(`DELETE FROM messages WHERE account_id = ? AND (chat_id = ? OR chat_id = ?) AND telegram_message_id IN (${placeholders})`)
                  .run(accountId, channelChatId, alt, ...delIds);
              },
            }).catch(() => {});
          }
          return;
        }

        if (update instanceof Api.UpdateReadHistoryInbox) {
          const peerChatId = resolveRawPeerChatId(update.peer);
          if (!peerChatId) return;
          const nextUnread = Math.max(0, Number(update.stillUnreadCount || 0));
          const nextReadMaxId = Number(update.maxId || 0) || undefined;
          patchConnectedDialogCache(connectedUserClients.get(accountId), peerChatId, {
            unreadCount: nextUnread,
            ...(nextReadMaxId ? { readInboxMaxId: nextReadMaxId } : {}),
          });
          pushPendingLocalUpdate({
            id: `readin_${userId}_${peerChatId}_${Number(update.maxId || 0)}_${Date.now()}`,
            type: 'read_inbox',
            chatId: peerChatId,
            readInboxMaxId: nextReadMaxId,
            unreadCount: nextUnread,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateReadChannelInbox) {
          const channelChatId = update.channelId ? `tg_-100${String(update.channelId)}` : '';
          if (!channelChatId) return;
          const nextUnread = Math.max(0, Number(update.stillUnreadCount || 0));
          const nextReadMaxId = Number(update.maxId || 0) || undefined;
          patchConnectedDialogCache(connectedUserClients.get(accountId), channelChatId, {
            unreadCount: nextUnread,
            ...(nextReadMaxId ? { readInboxMaxId: nextReadMaxId } : {}),
          });
          pushPendingLocalUpdate({
            id: `readchin_${userId}_${channelChatId}_${Number(update.maxId || 0)}_${Date.now()}`,
            type: 'read_inbox',
            chatId: channelChatId,
            readInboxMaxId: nextReadMaxId,
            unreadCount: nextUnread,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateDialogPinned) {
          const innerPeer = (update.peer as any)?.peer;
          const peerChatId = resolveRawPeerChatId(innerPeer);
          if (!peerChatId) return;
          const nextPinned = Boolean(update.pinned);
          const nextPinOrder = nextPinned ? -Date.now() : undefined;
          const hasExplicitFolder = update.folderId !== undefined && update.folderId !== null;
          const folderId = Number(update.folderId || 0);
          const isArchivedTarget = folderId === 1;
          const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
          const rawPeerId = peerChatId.replace(/^tg_/, '');
          const matchedCachedDlg: any = connObj?.dialogs?.find(
            (d: any) => d && (String(d.id) === peerChatId || String(d.rawId || '') === rawPeerId)
          );
          if (matchedCachedDlg && (!hasExplicitFolder || Boolean(matchedCachedDlg.isArchived) === isArchivedTarget)) {
            patchConnectedDialogCache(
              connObj,
              peerChatId,
              {
                isPinned: nextPinned,
                pinOrder: nextPinOrder,
              },
              { invalidateCache: false }
            );
          } else if (!matchedCachedDlg && connObj) {
            connObj.dialogsFetchedAt = 0;
            connObj.dialogsInFlight = undefined;
          }
          pushPendingLocalUpdate({
            id: `dlgpin_${userId}_${peerChatId}_${Date.now()}`,
            type: 'dialog_pinned',
            chatId: peerChatId,
            ...(hasExplicitFolder ? { folderId } : {}),
            ...(!matchedCachedDlg ? { needsDialogRefresh: true } : {}),
            isPinned: nextPinned,
            ...(nextPinOrder !== undefined ? { pinOrder: nextPinOrder } : {}),
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdatePinnedDialogs) {
          const folderId = Number(update.folderId || 0);
          const isArchivedTarget = folderId === 1;
          const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
          if (Array.isArray(update.order)) {
            const orderedChatIds = update.order
              .map((dp: any) => (dp?.peer ? resolveRawPeerChatId(dp.peer) : ''))
              .filter(Boolean);
            const orderIndexMap = new Map<string, number>();
            orderedChatIds.forEach((cid: string, idx: number) => orderIndexMap.set(cid, idx));
            let hasMissingCachedDialog = false;
            if (connObj && Array.isArray(connObj.dialogs)) {
              const existingIdSet = new Set(connObj.dialogs.map((d: any) => String(d?.id || '')));
              hasMissingCachedDialog = orderedChatIds.some((cid: string) => !existingIdSet.has(cid));
              connObj.dialogs = connObj.dialogs.map((d: any) => {
                if (!d || Boolean(d.isArchived) !== isArchivedTarget) return d;
                const cid = String(d.id || '');
                const idx = orderIndexMap.get(cid);
                return idx !== undefined
                  ? { ...d, isPinned: true, pinOrder: idx }
                  : { ...d, isPinned: false, pinOrder: undefined };
              });
            }
            pushPendingLocalUpdate({
              id: `dlgpinorder_${userId}_${folderId}_${Date.now()}`,
              type: 'dialogs_pinned_order',
              chatId: '',
              folderId,
              pinnedChatOrder: orderedChatIds,
              ...(hasMissingCachedDialog ? { needsDialogRefresh: true } : {}),
              accountId,
              sender: 'peer',
              senderName: '',
              text: '',
              timestamp: '',
              createdAt: Date.now(),
            });
          } else {
            if (connObj) {
              connObj.dialogsFetchedAt = 0;
              connObj.dialogsInFlight = undefined;
            }
            pushPendingLocalUpdate({
              id: `dlgpinorder_${userId}_${folderId}_${Date.now()}`,
              type: 'dialogs_pinned_order',
              chatId: '',
              folderId,
              needsDialogRefresh: true,
              accountId,
              sender: 'peer',
              senderName: '',
              text: '',
              timestamp: '',
              createdAt: Date.now(),
            });
          }
          return;
        }

        if (update instanceof Api.UpdateDialogUnreadMark) {
          const innerPeer = (update.peer as any)?.peer;
          const peerChatId = resolveRawPeerChatId(innerPeer);
          if (!peerChatId) return;
          const nextUnreadMark = Boolean(update.unread);
          const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
          const rawPeerId = peerChatId.replace(/^tg_/, '');
          const cachedDlg = connObj?.dialogs?.find(
            (d: any) => d && (String(d.id) === peerChatId || String(d.rawId || '') === rawPeerId)
          );
          const nextUnread = nextUnreadMark ? Math.max(1, Number(cachedDlg?.unreadCount || 0)) : 0;
          patchConnectedDialogCache(connObj, peerChatId, { unreadCount: nextUnread });
          pushPendingLocalUpdate({
            id: `dlgunread_${userId}_${peerChatId}_${Date.now()}`,
            type: 'dialog_unread_mark',
            chatId: peerChatId,
            unreadCount: nextUnread,
            unreadMark: nextUnreadMark,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateNotifySettings) {
          if (!(update.peer instanceof Api.NotifyPeer)) {
            if (
              update.peer instanceof Api.NotifyUsers ||
              update.peer instanceof Api.NotifyChats ||
              update.peer instanceof Api.NotifyBroadcasts
            ) {
              pushPendingLocalUpdate({
                id: `setnotify_${userId}_${Date.now()}`,
                type: 'settings_updated',
                chatId: '',
                accountId,
                sender: 'peer',
                senderName: '',
                text: '',
                timestamp: '',
                createdAt: Date.now(),
              });
            }
            return;
          }
          const peerChatId = resolveRawPeerChatId((update.peer as any).peer);
          if (!peerChatId) return;
          const notify: any = update.notifySettings || {};
          const nowSec = Math.floor(Date.now() / 1000);
          const nextMuted = Boolean(
            notify.silent ||
              (notify.muteUntil !== undefined && notify.muteUntil !== null && Number(notify.muteUntil) > nowSec)
          );
          const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
          patchConnectedDialogCache(connObj, peerChatId, { isMuted: nextMuted });
          pushPendingLocalUpdate({
            id: `dlgmute_${userId}_${peerChatId}_${Date.now()}`,
            type: 'dialog_muted',
            chatId: peerChatId,
            isMuted: nextMuted,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdatePrivacy) {
          pushPendingLocalUpdate({
            id: `setpriv_${userId}_${Date.now()}`,
            type: 'settings_updated',
            chatId: '',
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateFolderPeers) {
          const connObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
          const folderUpdates = Array.isArray(update.folderPeers) ? update.folderPeers : [];
          let hasMissingCachedDialog = false;
          for (const fp of folderUpdates) {
            const peerChatId = resolveRawPeerChatId((fp as any)?.peer);
            if (!peerChatId) continue;
            const nextArchived = Number((fp as any)?.folderId) === 1;
            const rawPeerId = peerChatId.replace(/^tg_/, '');
            if (connObj && Array.isArray(connObj.dialogs)) {
              const existed = connObj.dialogs.some(
                (d: any) => d && (String(d.id) === peerChatId || String(d.rawId || '') === rawPeerId)
              );
              if (!existed) hasMissingCachedDialog = true;
              connObj.dialogs = connObj.dialogs.map((d: any) =>
                d && (String(d.id) === peerChatId || String(d.rawId || '') === rawPeerId)
                  ? { ...d, isArchived: nextArchived }
                  : d
              );
            }
            pushPendingLocalUpdate({
              id: `dlgarch_${userId}_${peerChatId}_${Date.now()}`,
              type: 'dialog_archived',
              chatId: peerChatId,
              isArchived: nextArchived,
              ...(hasMissingCachedDialog ? { needsDialogRefresh: true } : {}),
              accountId,
              sender: 'peer',
              senderName: '',
              text: '',
              timestamp: '',
              createdAt: Date.now(),
            });
          }
          if (connObj && hasMissingCachedDialog) {
            connObj.dialogsFetchedAt = 0;
            connObj.dialogsInFlight = undefined;
          }
          return;
        }

        if (update instanceof Api.UpdateReadHistoryOutbox) {
          const peerChatId = resolveRawPeerChatId(update.peer);
          const maxId = Number(update.maxId || 0);
          if (!peerChatId || !maxId) return;
          pushPendingLocalUpdate({
            id: `readout_${userId}_${peerChatId}_${maxId}`,
            type: 'read_outbox',
            chatId: peerChatId,
            readOutboxMaxId: maxId,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateReadChannelOutbox) {
          const channelChatId = update.channelId ? `tg_-100${String(update.channelId)}` : '';
          const maxId = Number(update.maxId || 0);
          if (!channelChatId || !maxId) return;
          pushPendingLocalUpdate({
            id: `readchout_${userId}_${channelChatId}_${maxId}`,
            type: 'read_outbox',
            chatId: channelChatId,
            readOutboxMaxId: maxId,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdatePinnedMessages || update instanceof Api.UpdatePinnedChannelMessages) {
          const pinIds = (update.messages || []).map((n: any) => Number(n)).filter((n: number) => Number.isInteger(n) && n > 0);
          const peerChatId =
            update instanceof Api.UpdatePinnedChannelMessages
              ? (update.channelId ? `tg_-100${String(update.channelId)}` : '')
              : resolveRawPeerChatId((update as Api.UpdatePinnedMessages).peer);
          if (!peerChatId || pinIds.length === 0) return;
          const pinnedVal = Boolean(update.pinned);
          pushPendingLocalUpdate({
            id: `pin_${userId}_${peerChatId}_${Date.now()}`,
            type: 'pin',
            chatId: peerChatId,
            pinnedMessageIds: pinIds,
            pinned: pinnedVal,
            accountId,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          await enqueueMessageDbWrite({
            priority: 'NORMAL',
            kind: 'pin',
            accountId,
            chatId: peerChatId,
            tgMsgIds: pinIds,
            exec: async () => {
              const alt = peerChatId.replace(/^tg_/, '');
              const placeholders = pinIds.map(() => '?').join(', ');
              await db
                .prepare(`UPDATE messages SET is_pinned = ? WHERE account_id = ? AND (chat_id = ? OR chat_id = ?) AND telegram_message_id IN (${placeholders})`)
                .run(pinnedVal ? 1 : 0, accountId, peerChatId, alt, ...pinIds);
            },
          }).catch(() => {});
          return;
        }

        if (update instanceof Api.UpdateMessageReactions) {
          const peerChatId = resolveRawPeerChatId(update.peer);
          const tgMsgId = Number(update.msgId || 0);
          if (!peerChatId || !tgMsgId) return;
          const parsed = parseTelegramReactions({ reactions: update.reactions });
          const nextReactions = parsed.reactions || {};
          const nextMyReactions = parsed.myReactions || [];
          pushPendingLocalUpdate({
            id: `react_${userId}_${peerChatId}_${tgMsgId}_${Date.now()}`,
            type: 'reactions',
            telegramMessageId: tgMsgId,
            chatId: peerChatId,
            accountId,
            reactions: nextReactions,
            myReactions: nextMyReactions,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          await enqueueMessageDbWrite({
            priority: 'NORMAL',
            kind: 'reactions',
            accountId,
            chatId: peerChatId,
            tgMsgIds: [tgMsgId],
            exec: async () => {
              const alt = peerChatId.replace(/^tg_/, '');
              const accVariants = getScopedAccountIdVariants(accountId);
              const accPlaceholders = accVariants.map(() => '?').join(', ');
              const serialized = serializeStoredReactionsJson({
                reactions: nextReactions,
                myReactions: nextMyReactions,
              });
              await db
                .prepare(
                  `UPDATE messages SET reactions_json = ? WHERE account_id IN (${accPlaceholders}) AND (chat_id = ? OR chat_id = ?) AND telegram_message_id = ?`
                )
                .run(serialized, ...accVariants, peerChatId, alt, tgMsgId);
            },
          }).catch(() => {});
          return;
        }

        if (update instanceof Api.UpdateUserStatus) {
          const targetUid = update.userId !== undefined ? String(update.userId) : '';
          if (!targetUid) return;
          const uStatus = formatTelegramUserStatus({ id: targetUid, status: update.status });
          pushPendingLocalUpdate({
            id: `status_${userId}_${targetUid}_${Date.now()}`,
            type: 'user_status',
            chatId: `tg_${targetUid}`,
            accountId,
            isOnline: uStatus.isOnline,
            statusText: uStatus.statusText,
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdatePeerBlocked) {
          const peerChatId = resolveRawPeerChatId(update.peerId);
          if (!peerChatId) return;
          pushPendingLocalUpdate({
            id: `blk_${userId}_${peerChatId}_${Date.now()}`,
            type: 'peer_blocked',
            chatId: peerChatId,
            accountId,
            isBlocked: Boolean(update.blocked),
            sender: 'peer',
            senderName: '',
            text: '',
            timestamp: '',
            createdAt: Date.now(),
          });
          return;
        }

        if (update instanceof Api.UpdateNewMessage || update instanceof Api.UpdateNewChannelMessage) {
          const msgObj: any = update.message;
          const callInfo = msgObj ? extractTelegramPhoneCallFields(msgObj) : null;
          const groupServiceInfo =
            !callInfo && msgObj?.action ? await resolveTelegramGroupServiceFields(msgObj, client) : null;
          if ((!callInfo && !groupServiceInfo) || !msgObj?.id) return;

          const canonicalChatId =
            resolveRawPeerChatId(msgObj.peerId) ||
            (msgObj.fromId ? resolveRawPeerChatId(msgObj.fromId) : '');
          if (!canonicalChatId) return;
          const rawChatId = canonicalChatId.replace(/^tg_/, '');

          const mtprotoMsgKey = `${userId}_${rawChatId}_${msgObj.id}`;
          if (processedMtprotoMsgIds.has(mtprotoMsgKey)) return;
          const nowDedup = Date.now();
          processedMtprotoMsgIds.set(mtprotoMsgKey, nowDedup);
          if (processedMtprotoMsgIds.size > 500) {
            for (const [k, ts] of processedMtprotoMsgIds.entries()) {
              if (nowDedup - ts >= MTPROTO_DEDUP_TTL_MS) processedMtprotoMsgIds.delete(k);
            }
            while (processedMtprotoMsgIds.size > MAX_PROCESSED_MTPROTO_MSG_IDS) {
              const oldest = processedMtprotoMsgIds.keys().next().value;
              if (oldest === undefined) break;
              processedMtprotoMsgIds.delete(oldest);
            }
          }

          const isOut = Boolean(msgObj.out);
          const createdAt = msgObj.date ? Number(msgObj.date) * 1000 : Date.now();
          const messageId = buildTelegramRealtimeMessageId(userId, canonicalChatId, msgObj.id);
          const timestamp = new Date(createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });

          let senderInfo = await resolveTelegramMessageSenderInfo(msgObj, isOut, accountId).catch(() => ({
            senderId: rawChatId,
            senderName: '',
            senderAvatarUrl: undefined as string | undefined,
          }));
          if (!isOut && !senderInfo.senderName && !groupServiceInfo) {
            try {
              const entity: any = await client.getEntity(/^-?\d+$/.test(rawChatId) ? Number(rawChatId) : rawChatId);
              const entName =
                [entity?.firstName, entity?.lastName].filter(Boolean).join(' ').trim() ||
                entity?.title ||
                entity?.username ||
                '';
              if (entName) {
                senderInfo = {
                  senderId: senderInfo.senderId || rawChatId,
                  senderName: entName,
                  senderAvatarUrl:
                    senderInfo.senderAvatarUrl ||
                    signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(rawChatId)}`, accountId),
                };
              }
            } catch {}
          }

          const serviceUpdate: LocalIncomingUpdate = {
            id: messageId,
            type: 'message',
            telegramMessageId: Number(msgObj.id),
            chatId: canonicalChatId,
            rawChatId,
            accountId,
            sender: groupServiceInfo ? 'system' : (isOut ? 'me' : 'peer'),
            ...(groupServiceInfo ? { systemEventType: groupServiceInfo.systemEventType } : {}),
            senderName: senderInfo.senderName,
            ...(senderInfo.senderId ? { senderId: senderInfo.senderId } : {}),
            ...(senderInfo.senderAvatarUrl ? { senderAvatarUrl: senderInfo.senderAvatarUrl } : {}),
            ...(groupServiceInfo && /^tg_-/.test(canonicalChatId) ? { isGroup: true } : {}),
            text: callInfo ? callInfo.text : groupServiceInfo!.text,
            timestamp,
            createdAt,
            ...(callInfo
              ? {
                  isCall: true,
                  callType: callInfo.callType,
                  callDuration: callInfo.callDuration,
                  isVideoCall: callInfo.isVideoCall,
                  ...(callInfo.telegramCallId ? { telegramCallId: callInfo.telegramCallId } : {}),
                }
              : {}),
          };
          pushPendingLocalUpdate(serviceUpdate);
          if (groupServiceInfo) {
            const msgConnObj = connectedUserClients.get(accountId) || connectedUserClients.get(userId);
            if (msgConnObj && Array.isArray(msgConnObj.dialogs)) {
              const matchedCachedDlg: any = msgConnObj.dialogs.find(
                (d: any) => d && (String(d.id) === canonicalChatId || String(d.rawId || '') === rawChatId)
              );
              if (matchedCachedDlg) {
                const msgDateSec = msgObj.date ? Number(msgObj.date) : Math.floor(createdAt / 1000);
                patchConnectedDialogCache(msgConnObj, canonicalChatId, {
                  lastMessage: groupServiceInfo.text,
                  lastTime: timestamp,
                  lastDate: Math.max(Number(matchedCachedDlg.lastDate || 0), msgDateSec),
                });
              }
            }
          }
          void upsertSyncedMessageToDb(serviceUpdate, canonicalChatId, accountId, {
            priority: 'HIGH',
            source: 'raw_service',
          });
          return;
        }

        if (update instanceof Api.UpdatePhoneCall || update?.className === 'UpdatePhoneCall') {
          const phoneCall: any = update.phoneCall;
          if (phoneCall?.className === 'PhoneCallRequested' && phoneCall.adminId !== undefined) {
            const callerId = String(phoneCall.adminId);
            if (callerId && callerId !== String(userId)) {
              const callerChatId = `tg_${callerId}`;
              const isVideoCall = Boolean(phoneCall.video);
              let callerName = '';
              try {
                const entity: any = await client.getEntity(/^-?\d+$/.test(callerId) ? Number(callerId) : callerId);
                callerName =
                  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ').trim() ||
                  entity?.title ||
                  entity?.username ||
                  '';
              } catch {}
              pushPendingLocalUpdate({
                id: `ring_${userId}_${String(phoneCall.id || Date.now())}`,
                type: 'phone_call_ringing',
                chatId: callerChatId,
                rawChatId: callerId,
                accountId,
                sender: 'peer',
                senderName: callerName || `Telegram (${callerId})`,
                senderId: callerId,
                senderAvatarUrl: signTelegramResourceUrl(`/api/telegram/user/avatar/${encodeURIComponent(callerId)}`, accountId),
                text: isVideoCall ? '📹 对方正在向您发起视频通话' : '📞 对方正在向您发起语音通话',
                timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
                createdAt: Date.now(),
                isCall: true,
                callType: 'incoming',
                isVideoCall,
                ...(phoneCall.id !== undefined ? { telegramCallId: String(phoneCall.id) } : {}),
              });
            }
          }
          return;
        }
      } catch {}
    }, new Raw({}));
    ensurePhoneCallListener(client);
  } catch (err: any) {
    console.warn('[Attach Telegram Listener Error]:', err.message);
  }
}

export interface TelegramRestoreDeps {
  createClient?: (
    sessionStr: string,
    apiId: number,
    apiHash: string,
    proxy?: { ip: string; port: number; socksType: 4 | 5; timeout?: number; username?: string; password?: string }
  ) => TelegramClient;
  probeProxy?: typeof probeTelegramTransportEndpoint;
  destroyClient?: typeof destroyTelegramClientSafely;
  attachListener?: typeof attachTelegramClientMessageListener;
  getProxyConfig?: typeof getConfiguredTelegramProxy;
  resolveCredentials?: typeof resolveTelegramApiCredentials;
  connectTimeoutMs?: number;
  authTimeoutMs?: number;
  now?: () => number;
}

// On-demand/startup restoration of encrypted Telegram user sessions (uses RAM-only/grace credentials, deduplicated & token-upgrade safe)
export async function restoreTelegramUserSessionsOnStartup(
  bearerToken?: string,
  options?: { forceReconnect?: boolean } & {
    targetAccountKeys?: string[];
    reason?: string;
    deps?: TelegramRestoreDeps;
  }
): Promise<number> {
  const effectiveBearer = (bearerToken && bearerToken.trim()) || lastActiveUserJwt || undefined;
  const forceReconnect = Boolean(options?.forceReconnect);
  const currentProxyFingerprint = getTelegramProxyFingerprint(
    (options?.deps?.getProxyConfig || getConfiguredTelegramProxy)()
  );
  const targetAccountSet =
    Array.isArray(options?.targetAccountKeys) && options.targetAccountKeys.length > 0
      ? new Set(options.targetAccountKeys.filter(Boolean))
      : null;

  if (activeRestorePromise) {
    const needsTokenUpgrade = Boolean(effectiveBearer && !activeRestoreMeta?.hasBearerToken);
    const needsForceUpgrade = Boolean(forceReconnect && !activeRestoreMeta?.forceReconnect);
    const hasUncoveredTargets = Boolean(
      activeRestoreMeta?.targetAccountKeys &&
        (!targetAccountSet ||
          Array.from(targetAccountSet).some((k) => !activeRestoreMeta!.targetAccountKeys!.has(k)))
    );
    const proxyChangedDuringFlight = Boolean(
      activeRestoreMeta?.proxyFingerprint &&
        activeRestoreMeta.proxyFingerprint !== currentProxyFingerprint
    );
    if (needsTokenUpgrade || needsForceUpgrade || hasUncoveredTargets || proxyChangedDuringFlight) {
      const inflight = activeRestorePromise;
      try {
        await inflight;
      } catch {}
      return restoreTelegramUserSessionsOnStartup(effectiveBearer, options);
    }
    return activeRestorePromise;
  }

  activeRestoreMeta = {
    hasBearerToken: Boolean(effectiveBearer),
    forceReconnect,
    targetAccountKeys: targetAccountSet ? new Set(targetAccountSet) : null,
    proxyFingerprint: currentProxyFingerprint,
  };

  activeRestorePromise = (async () => {
    telegramSessionRestoreState.inProgress = true;
    telegramSessionRestoreState.lastAttemptAt = Date.now();
    telegramSessionRestoreState.lastError = null;

    const nowFn = options?.deps?.now || Date.now;
    const probeFn = options?.deps?.probeProxy || probeTelegramTransportEndpoint;
    const destroyFn = options?.deps?.destroyClient || destroyTelegramClientSafely;
    const attachFn = options?.deps?.attachListener || attachTelegramClientMessageListener;
    const resolveCredsFn = options?.deps?.resolveCredentials || resolveTelegramApiCredentials;
    const getProxyFn = options?.deps?.getProxyConfig || getConfiguredTelegramProxy;
    const connectTimeoutMs = options?.deps?.connectTimeoutMs ?? 15000;
    const authTimeoutMs = options?.deps?.authTimeoutMs ?? 10000;
    const reason = options?.reason || 'startup';

    try {
      await purgePersistedTelegramApiCredentialsFromDb();
      if (!options?.deps?.getProxyConfig) {
        await loadSystemProxyConfigFromDb();
      }

      let rows: any[] = [];
      try {
        rows = (await db.prepare(`
          SELECT phone, session_string, user_id, username, first_name
          FROM telegram_user_sessions
          WHERE is_active = 1
          ORDER BY updated_at DESC
          LIMIT ${MAX_TELEGRAM_ACCOUNTS * 2}
        `).all()) as any[];
      } catch (dbErr: any) {
        telegramSessionRestoreState.lastError = dbErr?.message || '读取本地 Telegram 会话表失败';
        return 0;
      }

      if (!rows || rows.length === 0) {
        telegramSessionRestoreState.restoredCount = 0;
        return 0;
      }

      // Deduplicate rows by user_id (keep newest updated_at row, clean up stale duplicate keys)
      const dedupedRows: any[] = [];
      const seenDbUserIds = new Set<string>();
      for (const r of rows) {
        const uid = r.user_id ? String(r.user_id).trim() : '';
        if (uid) {
          if (seenDbUserIds.has(uid)) {
            try {
              await db
                .prepare('DELETE FROM telegram_user_sessions WHERE user_id = ? AND phone = ?')
                .run(uid, r.phone);
            } catch {}
            continue;
          }
          seenDbUserIds.add(uid);
        }
        dedupedRows.push(r);
        if (dedupedRows.length >= MAX_TELEGRAM_ACCOUNTS) break;
      }

      const filteredRows = targetAccountSet
        ? dedupedRows.filter((r) => {
            const rowUid = r.user_id ? String(r.user_id).trim() : '';
            const rowPhoneRaw = r.phone ? String(r.phone).trim() : '';
            const rowNormPhone = rowPhoneRaw ? normalizePhoneNumber(rowPhoneRaw) || rowPhoneRaw : '';
            const canonicalKey = resolveTelegramAccountRuntimeKey({
              userId: rowUid || undefined,
              phone: rowNormPhone || undefined,
            });
            return Boolean(
              (canonicalKey && targetAccountSet.has(canonicalKey)) ||
                (rowNormPhone && targetAccountSet.has(`phone:${rowNormPhone}`)) ||
                (rowPhoneRaw && targetAccountSet.has(`phone:${rowPhoneRaw}`)) ||
                (rowUid && targetAccountSet.has(`uid:${rowUid}`))
            );
          })
        : dedupedRows;

      if (filteredRows.length === 0) {
        return 0;
      }

      const hasCredsPath = Boolean(
        options?.deps?.resolveCredentials ||
          effectiveBearer ||
          getEnvTelegramApiCredentials() ||
          getInMemoryTelegramApiCredentials()
      );
      if (!hasCredsPath) {
        telegramSessionRestoreState.lastError = null;
        return 0;
      }

      const creds = await resolveCredsFn({ bearerToken: effectiveBearer });
      if (!creds.ok || !creds.apiId || !creds.apiHash) {
        telegramSessionRestoreState.lastError =
          creds.error || '云端 Telegram 接入凭据暂不可用，请检查会员登录或网络连接';
        return 0;
      }

      const useApiId = creds.apiId;
      const useApiHash = creds.apiHash;
      const telegramProxy = getProxyFn();
      const proxyFingerprint = getTelegramProxyFingerprint(telegramProxy);
      let restoredCount = 0;
      let lastFailureMsg: string | null = null;

      const restoreSingleRow = async (row: any): Promise<boolean> => {
        const rawDbPhone = String(row.phone || '').trim();
        const cleanPhone = rawDbPhone ? normalizePhoneNumber(rawDbPhone) || rawDbPhone : '';
        const uidStr = row.user_id ? String(row.user_id).trim() : '';
        const accountId = uidStr ? `acc_tg_${uidStr}` : cleanPhone;
        const runtime = getOrCreateTelegramAccountRuntimeState({
          userId: uidStr || undefined,
          phone: cleanPhone || undefined,
          accountId,
        });

        // Per-account single-flight coordination with bounded preemption wait
        if (runtime.activeRestoreTask) {
          if (!forceReconnect) {
            return await runtime.activeRestoreTask;
          }
          // Preempt older generation only when explicitly forcing reconnect
          runtime.generationId += 1;
          try {
            runtime.abortActiveRestore?.();
          } catch {}
          try {
            await Promise.race([
              runtime.activeRestoreTask.catch(() => false),
              new Promise<void>((r) => setTimeout(r, 1500).unref?.()),
            ]);
          } catch {}
        }

        const myGeneration = ++runtime.generationId;
        const rawEncryptedSession = row.session_string;
        const decryptedSession = decryptSensitiveData(rawEncryptedSession);
        if (!decryptedSession) return false;

        runtime.isRestoring = true;
        if (runtime.lastConnectedAt === null) {
          runtime.isInitialConnecting = true;
        }
        runtime.offlineReason = null;

        let task: Promise<boolean> | null = null;
        task = (async (): Promise<boolean> => {
          let candidateClient: TelegramClient | null = null;
          let candidateDisposePromise: Promise<void> | null = null;
          let candidateCommitted = false;
          let disconnectedOldClient: TelegramClient | null = null;
          const restoreAbortController = new AbortController();

          const disposeCandidate = (): Promise<void> => {
            if (candidateCommitted) return Promise.resolve();
            if (candidateDisposePromise) return candidateDisposePromise;
            const orphan = candidateClient;
            candidateClient = null;
            if (!orphan) {
              candidateDisposePromise = Promise.resolve();
              return candidateDisposePromise;
            }
            candidateDisposePromise = Promise.resolve(destroyFn(orphan)).catch(() => {});
            return candidateDisposePromise;
          };
          runtime.abortActiveRestore = () => {
            restoreAbortController.abort();
            void disposeCandidate();
          };

          const activeFlood = getTelegramFloodCooldown(
            { accountId, userId: uidStr || undefined, phone: cleanPhone },
            nowFn()
          );
          if (activeFlood && reason !== 'manual_reconnect') {
            runtime.nextRetryAt = Math.max(runtime.nextRetryAt, activeFlood.floodWaitUntil);
            runtime.lastError = formatTelegramError({
              errorMessage: `FLOOD_WAIT_${activeFlood.retryAfterSeconds}`,
            });
            runtime.lastErrorCategory = 'telegram_unreachable';
            runtime.offlineReason = runtime.lastError;
            lastFailureMsg = runtime.lastError;
            return false;
          }

          try {
            const existingConn = resolveConnectedTelegramUser(
              accountId,
              cleanPhone || rawDbPhone,
              uidStr || undefined
            );

            const hasKnownProxy = Boolean(
              existingConn?.proxyFingerprint && existingConn.proxyFingerprint !== ''
            );
            const proxyChanged = Boolean(
              existingConn && (!hasKnownProxy || existingConn.proxyFingerprint !== proxyFingerprint)
            );
            const existingInspected = inspectGramJsClientState(existingConn?.client);

            if (reason === 'proxy_changed' && existingConn && !existingInspected.destroyed && !proxyChanged) {
              const existingSnap = getTelegramAccountConnectionSnapshot(existingConn, runtime, {
                now: nowFn(),
              });
              if (existingSnap.isConnected) {
                runtime.retryCount = 0;
                runtime.nextRetryAt = 0;
                runtime.lastError = null;
                runtime.lastErrorCategory = null;
                runtime.offlineReason = null;
                return true;
              }
            }

            // Step 1: Check existing client BEFORE creating any candidate client or touching connectedUserClients
            if (
              existingConn &&
              existingConn.client &&
              !existingInspected.destroyed &&
              !proxyChanged &&
              !forceReconnect
            ) {
              const snap = getTelegramAccountConnectionSnapshot(existingConn, runtime, {
                now: nowFn(),
              });
              // 1a. Healthy and already online
              if (snap.isConnected) {
                runtime.retryCount = 0;
                runtime.nextRetryAt = 0;
                runtime.lastError = null;
                runtime.lastErrorCategory = null;
                runtime.offlineReason = null;
                runtime.proxyFingerprint = proxyFingerprint;
                return true;
              }
              // 1b. GramJS is actively reconnecting/connecting with the right proxy -> respect autoReconnect, do NOT create duplicate client!
              if (existingInspected.senderIsReconnecting || existingInspected.senderIsConnecting) {
                runtime.senderIsReconnecting = existingInspected.senderIsReconnecting;
                return false;
              }
              // 1c. Existing client is idle/disconnected with matching proxy -> try in-place reconnect FIRST
              try {
                if (telegramProxy) {
                  await probeFn({
                    proxy: telegramProxy,
                    connectTimeoutMs: Math.min(5000, connectTimeoutMs),
                    handshakeTimeoutMs: Math.min(7000, connectTimeoutMs),
                    signal: restoreAbortController.signal,
                  });
                }
                if (runtime.generationId !== myGeneration) return false;
                const inPlaceConnectRes = await withTelegramTimeout(
                  existingConn.client.connect(),
                  connectTimeoutMs,
                  '恢复现有 Telegram 连接超时',
                  {
                    signal: restoreAbortController.signal,
                    onTimeout: () => {
                      if (runtime.generationId !== myGeneration) return;
                      try {
                        (existingConn.client as any)?._sender?._connection?.disconnect?.();
                      } catch {}
                    },
                  }
                );
                if (inPlaceConnectRes === false || !existingConn.client.connected) {
                  throw new TelegramNetworkError(
                    'telegram_unreachable',
                    telegramProxy
                      ? '代理节点已连通，但连接 Telegram 服务器失败或超时，请尝试切换代理节点'
                      : '连接 Telegram 服务器失败或超时，请检查本地网络或启用代理后重试'
                  );
                }
                const inPlaceAuth = await withTelegramTimeout(
                  existingConn.client.isUserAuthorized(),
                  authTimeoutMs,
                  '校验现有 Telegram 会话超时',
                  {
                    signal: restoreAbortController.signal,
                    onTimeout: () => {
                      if (runtime.generationId !== myGeneration) return;
                      try {
                        (existingConn.client as any)?._sender?._connection?.disconnect?.();
                      } catch {}
                    },
                  }
                );
                if (runtime.generationId !== myGeneration) return false;
                if (inPlaceAuth) {
                  (existingConn.client as any)._tgProGenerationId = myGeneration;
                  existingConn.connectedAt = nowFn();
                  existingConn.proxyFingerprint = proxyFingerprint;
                  runtime.isAuthorized = true;
                  runtime.transportConnected = true;
                  runtime.senderIsReconnecting = false;
                  runtime.reconnectingSinceAt = null;
                  runtime.connectingSinceAt = null;
                  runtime.suspectedStuckWarningAt = null;
                  runtime.reconnectProbeFailures = 0;
                  runtime.lastConnectedAt = nowFn();
                  runtime.retryCount = 0;
                  runtime.nextRetryAt = 0;
                  runtime.lastError = null;
                  runtime.lastErrorCategory = null;
                  runtime.offlineReason = null;
                  runtime.proxyFingerprint = proxyFingerprint;
                  attachTelegramConnectionStateTracker(existingConn.client, {
                    userId: uidStr || undefined,
                    phone: cleanPhone,
                    accountId,
                  });
                  restoredCount++;
                  return true;
                }
              } catch (inPlaceErr: any) {
                if (runtime.generationId !== myGeneration) return false;
                if (
                  isTelegramSessionExpiredError(inPlaceErr) ||
                  extractFloodWaitSeconds(inPlaceErr) !== null
                ) {
                  throw inPlaceErr;
                }
                console.warn(
                  `[Telegram Recovery] In-place reconnect failed for ${cleanPhone}, trying candidate client:`,
                  inPlaceErr?.message || inPlaceErr
                );
              }
            }

            // Step 2: Build & authenticate candidateClient WITHOUT deleting existing connected client prematurely
            if (telegramProxy) {
              await probeFn({
                proxy: telegramProxy,
                connectTimeoutMs: Math.min(5000, connectTimeoutMs),
                handshakeTimeoutMs: Math.min(7000, connectTimeoutMs),
                signal: restoreAbortController.signal,
              });
            }

            if (runtime.generationId !== myGeneration) return false;

            // Step 2a: Prevent dual concurrent MTProto sockets for the same StringSession (406 AUTH_KEY_DUPLICATED):
            // hush/disconnect any live or auto-reconnecting old transport BEFORE dialing candidateClient.
            const currentOldInspected = inspectGramJsClientState(existingConn?.client);
            if (
              existingConn?.client &&
              !currentOldInspected.destroyed &&
              (currentOldInspected.userConnected ||
                currentOldInspected.transportConnected ||
                currentOldInspected.senderIsReconnecting ||
                currentOldInspected.senderIsConnecting)
            ) {
              disconnectedOldClient = existingConn.client;
              try {
                silenceGramJsSenderReconnect(disconnectedOldClient);
                await withTelegramTimeout(
                  Promise.resolve(disconnectedOldClient.disconnect?.()).catch(() => {}),
                  2000,
                  '断开旧 Telegram 连接超时'
                ).catch(() => {});
              } catch {}
            }

            const effectiveTransport = options?.deps?.getProxyConfig
              ? await resolveEffectiveTelegramTransport(telegramProxy)
              : await resolveEffectiveTelegramTransport();
            candidateClient = options?.deps?.createClient
              ? options.deps.createClient(decryptedSession, useApiId, useApiHash, telegramProxy)
              : new TelegramClient(new StringSession(decryptedSession), useApiId, useApiHash, {
                  ...TELEGRAM_CLIENT_RETRY_OPTIONS,
                  useWSS: false,
                  connection: ConnectionTCPObfuscated443,
                  autoReconnect: true,
                  ...TELEGRAM_DESKTOP_CLIENT_PARAMS,
                  ...(effectiveTransport.mode === 'socks'
                    ? { proxy: effectiveTransport.proxy }
                    : effectiveTransport.mode === 'http'
                      ? { networkSocket: createHttpConnectNetworkSocketClass(effectiveTransport.httpProxy) as any }
                      : {}),
                });
            (candidateClient as any)._tgProGenerationId = myGeneration;

            configureTelegramClientErrorGuard(candidateClient, cleanPhone, {
              userId: uidStr || undefined,
              phone: cleanPhone,
              accountId: uidStr ? `acc_tg_${uidStr}` : undefined,
            });
            attachTelegramConnectionStateTracker(candidateClient, {
              userId: uidStr || undefined,
              phone: cleanPhone,
              accountId: uidStr ? `acc_tg_${uidStr}` : undefined,
            });

            const candidateConnectRes = await withTelegramTimeout(
              candidateClient.connect(),
              connectTimeoutMs,
              runtime.lastConnectedAt === null
                ? '初次连接 Telegram 服务器超时'
                : '运行期重连 Telegram 服务器超时',
              {
                signal: restoreAbortController.signal,
                onTimeout: () => {
                  void disposeCandidate();
                },
              }
            );
            if (runtime.generationId !== myGeneration || candidateDisposePromise !== null) {
              await disposeCandidate();
              return false;
            }
            if (candidateConnectRes === false || !candidateClient?.connected) {
              throw new TelegramNetworkError(
                'telegram_unreachable',
                telegramProxy
                  ? '代理节点已连通，但无法连接到 Telegram 服务器，请尝试切换代理节点'
                  : '无法连接到 Telegram 服务器，请检查本地网络或代理设置后重试'
              );
            }

            const isAuth = await withTelegramTimeout(
              candidateClient.isUserAuthorized(),
              authTimeoutMs,
              '校验 Telegram 会话授权超时',
              {
                signal: restoreAbortController.signal,
                onTimeout: () => {
                  void disposeCandidate();
                },
              }
            );

            // Generation guard: abort cleanly if a newer task took over while connecting/authorizing
            if (runtime.generationId !== myGeneration || candidateDisposePromise !== null) {
              await disposeCandidate();
              return false;
            }

            if (!isAuth) {
              await disposeCandidate();
              runtime.isAuthorized = false;
              await markTelegramSessionExpired({
                accountId: uidStr ? `acc_tg_${uidStr}` : cleanPhone,
                userId: uidStr || undefined,
                phone: cleanPhone,
                reason: '恢复会话时检测到 Telegram 授权已失效，请重新登录',
              });
              lastFailureMsg = `账号 ${cleanPhone} 会话已失效，请重新登录`;
              return false;
            }

            if (typeof rawEncryptedSession === 'string' && !rawEncryptedSession.startsWith('enc:gcm:')) {
              try {
                await db
                  .prepare('UPDATE telegram_user_sessions SET session_string = ?, updated_at = ? WHERE phone = ?')
                  .run(encryptSensitiveData(decryptedSession), nowFn(), rawDbPhone || cleanPhone);
              } catch {}
            }

            // Re-verify generation AFTER async DB write and BEFORE atomic client swap
            if (runtime.generationId !== myGeneration || candidateDisposePromise !== null || !candidateClient) {
              await disposeCandidate();
              return false;
            }

            // Atomic switchover: commit candidateClient into connectedUserClients before destroying oldClient
            const previousMapped = resolveConnectedTelegramUser(
              accountId,
              cleanPhone || rawDbPhone,
              uidStr || undefined
            );
            const oldClient =
              previousMapped?.client && previousMapped.client !== candidateClient
                ? previousMapped.client
                : disconnectedOldClient && disconnectedOldClient !== candidateClient
                  ? disconnectedOldClient
                  : null;
            disconnectedOldClient = null;

            const userObj: ConnectedTelegramUser = {
              client: candidateClient,
              phone: cleanPhone,
              userId: uidStr,
              username: row.username
                ? row.username.startsWith('@')
                  ? row.username
                  : `@${row.username}`
                : '',
              firstName: row.first_name || 'Telegram 用户',
              avatarInitial: (row.first_name || 'TG').slice(0, 2).toUpperCase(),
              avatarBg: '#2481cc',
              apiId: useApiId,
              apiHash: useApiHash,
              connectedAt: nowFn(),
              proxyFingerprint,
              dialogs: previousMapped?.dialogs || [],
              dialogsFetchedAt: previousMapped?.dialogsFetchedAt,
            };

            if (uidStr) {
              connectedUserClients.set(uidStr, userObj);
              connectedUserClients.set(`acc_tg_${uidStr}`, userObj);
            }
            if (cleanPhone) {
              connectedUserClients.set(cleanPhone, userObj);
            }
            clearExpiredAccountRecord(uidStr, cleanPhone);
            attachFn(candidateClient, cleanPhone, uidStr);

            runtime.isAuthorized = true;
            runtime.transportConnected = true;
            runtime.senderIsReconnecting = false;
            runtime.reconnectingSinceAt = null;
            runtime.connectingSinceAt = null;
            runtime.suspectedStuckWarningAt = null;
            runtime.reconnectProbeFailures = 0;
            runtime.lastConnectedAt = nowFn();
            runtime.retryCount = 0;
            runtime.nextRetryAt = 0;
            runtime.lastError = null;
            runtime.lastErrorCategory = null;
            runtime.offlineReason = null;
            runtime.proxyFingerprint = proxyFingerprint;

            // Mark candidate committed BEFORE clearing local pointer so disposeCandidate can never destroy committed client
            (candidateClient as any)._tgProGenerationId = myGeneration;
            candidateCommitted = true;
            candidateClient = null;

            if (oldClient) {
              await destroyFn(oldClient);
            }

            if (uidStr && process.env.NODE_ENV !== 'test') {
              void fetchTelegramAvatarWithLimiting({
                cacheAccountScope: `acc_tg_${uidStr}`,
                cleanId: uidStr,
                candidates: [userObj],
              }).catch(() => {});
            }
            if (userObj.dialogs.length === 0) {
              getOrFetchConnectedAccountDialogs(userObj, { limit: 150 }).catch(() => {});
            }
            restoredCount++;
            return true;
          } catch (clientErr: any) {
            restoreAbortController.abort();
            await disposeCandidate();

            // Stale / timed-out / superseded generation must NEVER mutate newer task's runtime or connected map
            if (runtime.generationId !== myGeneration) {
              return false;
            }

            // If we proactively disconnected oldClient to prevent 406 AUTH_KEY_DUPLICATED and candidate failed,
            // purge the disconnected zombie entry from connectedUserClients so it cannot stay stale/unrecoverable,
            // while keeping SQLite session & runtime backoff intact for automatic Watchdog recovery.
            if (disconnectedOldClient) {
              for (const keyCandidate of [cleanPhone, rawDbPhone, uidStr, uidStr ? `acc_tg_${uidStr}` : '']) {
                if (keyCandidate && connectedUserClients.get(keyCandidate)?.client === disconnectedOldClient) {
                  connectedUserClients.delete(keyCandidate);
                }
              }
              await destroyFn(disconnectedOldClient);
              disconnectedOldClient = null;
            }

            if (isTelegramSessionExpiredError(clientErr)) {
              const formattedExp = formatTelegramError(clientErr);
              lastFailureMsg = formattedExp;
              runtime.isAuthorized = false;
              await markTelegramSessionExpired({
                accountId: uidStr ? `acc_tg_${uidStr}` : cleanPhone,
                userId: uidStr || undefined,
                phone: cleanPhone,
                reason: formattedExp,
              });
              return false;
            }

            const floodSeconds = extractFloodWaitSeconds(clientErr);
            if (floodSeconds !== null) {
              const floodEntry = recordTelegramFloodWait(
                { accountId, userId: uidStr || undefined, phone: cleanPhone },
                floodSeconds,
                `restore.${reason}`,
                nowFn()
              );
              const floodWaitUntil = floodEntry?.floodWaitUntil || nowFn() + floodSeconds * 1000;
              const formattedFlood = formatTelegramError(clientErr);
              // Do NOT increment runtime.retryCount on official FLOOD_WAIT to avoid double penalty
              runtime.lastFailureAt = nowFn();
              runtime.nextRetryAt = Math.max(runtime.nextRetryAt, floodWaitUntil);
              runtime.lastError = formattedFlood;
              runtime.lastErrorCategory = 'telegram_unreachable';
              runtime.offlineReason = formattedFlood;
              lastFailureMsg = formattedFlood;
              return false;
            }

            const classified = classifyTelegramNetworkError(clientErr, Boolean(telegramProxy));
            lastFailureMsg = classified.message || '连接 Telegram MTProto 超时';
            runtime.lastFailureAt = nowFn();
            runtime.retryCount += 1;
            runtime.nextRetryAt = nowFn() + computeTelegramReconnectBackoffMs(runtime.retryCount);
            runtime.lastError = lastFailureMsg;
            runtime.lastErrorCategory = classified.category;
            runtime.offlineReason = lastFailureMsg;
            console.warn(
              `[Telegram User Auth Recovery] Could not restore session for ${cleanPhone}:`,
              clientErr?.message || clientErr
            );
            return false;
          } finally {
            if (runtime.generationId === myGeneration) {
              runtime.isRestoring = false;
              runtime.isInitialConnecting = false;
              runtime.abortActiveRestore = null;
            }
            if (task && runtime.activeRestoreTask === task) {
              runtime.activeRestoreTask = null;
            }
          }
        })();

        runtime.activeRestoreTask = task;
        return await task;
      };

      // Restore accounts with bounded concurrency (3) so multiple accounts don't serialize startup
      const CONCURRENCY = 3;
      for (let i = 0; i < filteredRows.length; i += CONCURRENCY) {
        const batch = filteredRows.slice(i, i + CONCURRENCY);
        await Promise.allSettled(batch.map((r) => restoreSingleRow(r)));
      }

      telegramSessionRestoreState.restoredCount = restoredCount;
      if (restoredCount > 0) {
        telegramSessionRestoreState.lastSuccessAt = Date.now();
        telegramSessionRestoreState.lastError = null;
        console.log(
          `[Telegram User Auth Recovery] Successfully restored ${restoredCount} active personal user session(s) from encrypted storage.`
        );
      } else if (lastFailureMsg) {
        telegramSessionRestoreState.lastError = lastFailureMsg;
      }
      return restoredCount;
    } catch (err: any) {
      telegramSessionRestoreState.lastError = err?.message || '恢复 Telegram 会话失败';
      console.warn('[Telegram User Auth Recovery Exception]:', err?.message || err);
      return 0;
    } finally {
      telegramSessionRestoreState.inProgress = false;
      activeRestorePromise = null;
      activeRestoreMeta = null;
    }
  })();

  return activeRestorePromise;
}

let inFlightProxyRecovery: {
  proxyFingerprint: string;
  promise: Promise<{ triggered: boolean; targetKeys: string[] }>;
} | null = null;

export async function triggerProxyChangeRecovery(
  bearerToken?: string
): Promise<{ triggered: boolean; targetKeys: string[] }> {
  const newProxyFingerprint = getTelegramProxyFingerprint(getConfiguredTelegramProxy());

  // Coalesce concurrent/duplicate /api/auth/proxy and /api/system/proxy triggers for the same proxy configuration
  if (inFlightProxyRecovery && inFlightProxyRecovery.proxyFingerprint === newProxyFingerprint) {
    return inFlightProxyRecovery.promise;
  }

  const recoveryPromise = (async (): Promise<{ triggered: boolean; targetKeys: string[] }> => {
    let activeRows: any[] = [];
    try {
      activeRows = (await db
        .prepare('SELECT phone, user_id FROM telegram_user_sessions WHERE is_active = 1 LIMIT ?')
        .all(MAX_TELEGRAM_ACCOUNTS * 2)) as any[];
    } catch (err: any) {
      console.error('[Telegram Proxy Recovery DB Error]:', err?.message || err);
      return { triggered: false, targetKeys: [] };
    }

    const switchKeys: string[] = [];
    const offlineKeys: string[] = [];
    const seenKeys = new Set<string>();

    for (const row of activeRows) {
      const uid = row?.user_id ? String(row.user_id).trim() : '';
      const rawPhone = row?.phone ? String(row.phone).trim() : '';
      const phone = rawPhone ? normalizePhoneNumber(rawPhone) || rawPhone : '';
      const key = resolveTelegramAccountRuntimeKey({
        userId: uid || undefined,
        phone: phone || undefined,
      });
      if (!key || seenKeys.has(key)) continue;
      seenKeys.add(key);

      const isExpired = Boolean(
        (uid && (recentlyExpiredAccounts.has(uid) || recentlyExpiredAccounts.has(`acc_tg_${uid}`))) ||
          (phone && recentlyExpiredAccounts.has(phone)) ||
          (rawPhone && recentlyExpiredAccounts.has(rawPhone))
      );
      if (isExpired) continue;

      const runtime = getOrCreateTelegramAccountRuntimeState({
        userId: uid || undefined,
        phone: phone || undefined,
        accountId: uid ? `acc_tg_${uid}` : phone,
      });
      const conn = resolveConnectedTelegramUser(
        uid ? `acc_tg_${uid}` : phone,
        phone || rawPhone,
        uid
      );
      const snap = getTelegramAccountConnectionSnapshot(conn, runtime);

      // Missing/empty proxyFingerprint is treated as UNKNOWN, never assumed matching
      const hasKnownMatchingProxy = Boolean(
        conn?.proxyFingerprint && conn.proxyFingerprint === newProxyFingerprint
      );
      if (snap.isConnected && hasKnownMatchingProxy) {
        continue;
      }

      // Respect active official FLOOD_WAIT cooldown
      if (
        getTelegramFloodCooldown({
          accountId: uid ? `acc_tg_${uid}` : phone,
          userId: uid || undefined,
          phone: phone || undefined,
        })
      ) {
        continue;
      }

      if (snap.isConnected && !hasKnownMatchingProxy) {
        runtime.nextRetryAt = 0;
        runtime.retryCount = 0;
        switchKeys.push(key);
      } else if (!runtime.activeRestoreTask || runtime.proxyFingerprint !== newProxyFingerprint) {
        runtime.nextRetryAt = 0;
        runtime.retryCount = 0;
        offlineKeys.push(key);
      }
    }

    const allTargets = [...switchKeys, ...offlineKeys];
    if (allTargets.length === 0) {
      return { triggered: false, targetKeys: [] };
    }

    const runBackground = async () => {
      if (switchKeys.length > 0) {
        await restoreTelegramUserSessionsOnStartup(bearerToken, {
          targetAccountKeys: switchKeys,
          forceReconnect: true,
          reason: 'proxy_changed',
        });
      }
      if (offlineKeys.length > 0) {
        await restoreTelegramUserSessionsOnStartup(bearerToken, {
          targetAccountKeys: offlineKeys,
          forceReconnect: false,
          reason: 'proxy_changed',
        });
      }
    };
    runBackground().catch((bgErr: any) => {
      const msg = bgErr?.message || String(bgErr || '代理切换恢复任务失败');
      telegramSessionRestoreState.lastError = msg;
      console.error('[Telegram Proxy Recovery Async Error]:', msg);
    });

    return { triggered: true, targetKeys: allTargets };
  })().finally(() => {
    if (inFlightProxyRecovery?.promise === recoveryPromise) {
      inFlightProxyRecovery = null;
    }
  });

  inFlightProxyRecovery = { proxyFingerprint: newProxyFingerprint, promise: recoveryPromise };
  return recoveryPromise;
}

// Background Connection Health Watchdog (every 25s): respects GramJS auto-reconnect, uses per-account tiered backoff, and detects OS sleep/wake
let telegramWatchdogInterval: NodeJS.Timeout | null = null;
let lastWatchdogTickAt = 0;
let lastSystemResumeAt = 0;
let inFlightSystemResumePromise: Promise<number> | null = null;
let lastHttpSystemResumeAt = 0;

export async function handleSystemResumeWakeup(source = 'power_resume'): Promise<number> {
  if (inFlightSystemResumePromise) {
    return inFlightSystemResumePromise;
  }
  lastSystemResumeAt = Date.now();
  const wakePromise = (async (): Promise<number> => {
  // Verify seemingly-connected clients whose socket may have gone half-open during OS sleep
  const uniqueConns = new Map<string, ConnectedTelegramUser>();
  for (const u of connectedUserClients.values()) {
    const dedupKey = u?.userId || u?.phone;
    if (dedupKey && !uniqueConns.has(dedupKey)) {
      uniqueConns.set(dedupKey, u);
    }
  }
  await Promise.allSettled(
    Array.from(uniqueConns.values()).map(async (conn) => {
      if (!conn?.client || (conn.client as any)._destroyed) return;
      const connAccountId = conn.userId ? `acc_tg_${conn.userId}` : conn.phone;
      const runtime = getOrCreateTelegramAccountRuntimeState({
        userId: conn.userId || undefined,
        phone: conn.phone,
        accountId: connAccountId,
      });
      const snap = getTelegramAccountConnectionSnapshot(conn, runtime, { now: Date.now() });
      if (!snap.isConnected) return;
      try {
        await scheduleTelegramRpc(connAccountId, 'P0', 'resume.getMe', () =>
          withTelegramTimeout(conn.client.getMe(), 5000, '唤醒后连接探活超时')
        );
        runtime.lastConnectedAt = Date.now();
        runtime.retryCount = 0;
        runtime.lastError = null;
        runtime.lastErrorCategory = null;
        runtime.offlineReason = null;
        runtime.reconnectingSinceAt = null;
        runtime.suspectedStuckWarningAt = null;
        runtime.reconnectProbeFailures = 0;
      } catch (probeErr: any) {
        if (isTelegramSessionExpiredError(probeErr)) {
          let canonicalUid = conn.userId ? String(conn.userId).trim() : '';
          let canonicalPhone = conn.phone ? String(conn.phone).trim() : '';
          try {
            let uidRow: { phone: string; user_id: string | null } | null = null;
            let phoneRow: { phone: string; user_id: string | null } | null = null;
            if (canonicalUid) {
              const rows = (await db
                .prepare('SELECT phone, user_id FROM telegram_user_sessions WHERE user_id = ?')
                .all(canonicalUid)) as any[];
              if (rows.length === 1 && rows[0]?.phone) {
                uidRow = {
                  phone: String(rows[0].phone).trim(),
                  user_id: rows[0].user_id ? String(rows[0].user_id).trim() : null,
                };
              }
            }
            const normP = canonicalPhone ? normalizePhoneNumber(canonicalPhone) : '';
            const pList = Array.from(new Set([canonicalPhone, normP].filter(Boolean)));
            if (pList.length > 0) {
              const rows = (await db
                .prepare(
                  `SELECT phone, user_id FROM telegram_user_sessions WHERE phone IN (${pList.map(() => '?').join(', ')})`
                )
                .all(...pList)) as any[];
              if (rows.length === 1 && rows[0]?.phone) {
                phoneRow = {
                  phone: String(rows[0].phone).trim(),
                  user_id: rows[0].user_id ? String(rows[0].user_id).trim() : null,
                };
              }
            }
            const chosen =
              uidRow && phoneRow ? (uidRow.phone === phoneRow.phone ? uidRow : null) : uidRow || phoneRow;
            if (chosen) {
              if (chosen.user_id) canonicalUid = chosen.user_id;
              if (chosen.phone) canonicalPhone = chosen.phone;
            }
          } catch (lookupErr: any) {
            console.error('[Telegram Power Resume DB Lookup Error]:', lookupErr?.message || lookupErr);
          }
          await markTelegramSessionExpired({
            accountId: canonicalUid ? `acc_tg_${canonicalUid}` : canonicalPhone || connAccountId,
            userId: canonicalUid || undefined,
            phone: canonicalPhone || undefined,
            reason: formatTelegramError(probeErr),
          });
          return;
        }
        const probeFloodSec = extractFloodWaitSeconds(probeErr);
        if (probeFloodSec !== null) {
          const floodEntry = recordTelegramFloodWait(
            { accountId: connAccountId, userId: conn.userId || undefined, phone: conn.phone },
            probeFloodSec,
            `resume.${source}`
          );
          const formattedFlood = formatTelegramError(probeErr);
          runtime.nextRetryAt = Math.max(
            runtime.nextRetryAt,
            floodEntry?.floodWaitUntil || Date.now() + probeFloodSec * 1000
          );
          runtime.lastError = formattedFlood;
          runtime.lastErrorCategory = 'telegram_unreachable';
          runtime.offlineReason = formattedFlood;
          return;
        }
        const currentProxyFp = getTelegramProxyFingerprint(getConfiguredTelegramProxy());
        const sameProxyForNativeReconnect = Boolean(
          conn.proxyFingerprint && conn.proxyFingerprint === currentProxyFp
        );
        try {
          const senderAny = (conn.client as any)?._sender;
          if (!sameProxyForNativeReconnect && senderAny) {
            // Proxy changed while asleep: silence native reconnect (which reuses old proxy) so Watchdog rebuilds with new proxy
            silenceGramJsSenderReconnect(conn.client);
          } else {
            senderAny?._connection?.disconnect?.();
            senderAny?.reconnect?.();
          }
        } catch {}
        runtime.lastDisconnectedAt = Date.now();
        runtime.nextRetryAt = 0;
        runtime.offlineReason = `系统唤醒探测失败 (${source})，正在重新连接...`;
      }
    })
  );

  // Trigger recovery cycle for disconnected accounts (non-FLOOD_WAIT backoff cleared on resume)
  return await runTelegramConnectionWatchdogCycle({ bypassBackoff: true, reason: source });
  })().finally(() => {
    if (inFlightSystemResumePromise === wakePromise) {
      inFlightSystemResumePromise = null;
    }
  });
  inFlightSystemResumePromise = wakePromise;
  return wakePromise;
}

app.post('/api/internal/system-resume', async (req: Request, res: Response) => {
  const remoteIp = String(req.socket?.remoteAddress || '')
    .replace(/^::ffff:/, '')
    .trim();
  const hasProxyForwardHeader = Boolean(
    req.headers['x-forwarded-for'] ||
      req.headers['forwarded'] ||
      req.headers['x-real-ip'] ||
      req.headers['cf-connecting-ip'] ||
      req.headers['true-client-ip'] ||
      req.headers['x-forwarded-host'] ||
      req.headers['via']
  );
  const secFetchSite = String(req.headers['sec-fetch-site'] || '').trim().toLowerCase();
  const isLoopback =
    !hasProxyForwardHeader && (remoteIp === '127.0.0.1' || remoteIp === '::1');
  if (!isLoopback || secFetchSite === 'cross-site' || !isAllowedClientOrigin(req)) {
    return res.status(403).json({ ok: false, error: 'Forbidden' });
  }
  const nowTs = Date.now();
  if (!inFlightSystemResumePromise && nowTs - lastHttpSystemResumeAt < 2000) {
    return res.json({ ok: true, restoredCount: 0, throttled: true });
  }
  lastHttpSystemResumeAt = nowTs;
  try {
    if (typeof req.body?.autoSystemProxy === 'string') {
      const nextAutoProxy = req.body.autoSystemProxy.trim();
      cachedElectronAutoSystemProxy = nextAutoProxy || null;
      if (nextAutoProxy) process.env.HS_AUTO_SYSTEM_PROXY = nextAutoProxy;
      else delete process.env.HS_AUTO_SYSTEM_PROXY;
    }
    const source = typeof req.body?.source === 'string' && req.body.source.trim()
      ? req.body.source.trim()
      : 'power_resume';
    const restoredCount = await handleSystemResumeWakeup(source);
    return res.json({ ok: true, restoredCount, source });
  } catch (err: any) {
    return res.status(500).json({ ok: false, error: err?.message || '唤醒恢复失败' });
  }
});

app.post('/api/internal/sync-system-proxy', (req: Request, res: Response) => {
  const remoteIp = String(req.socket?.remoteAddress || '')
    .replace(/^::ffff:/, '')
    .trim();
  const hasProxyForwardHeader = Boolean(
    req.headers['x-forwarded-for'] ||
      req.headers['forwarded'] ||
      req.headers['x-real-ip'] ||
      req.headers['cf-connecting-ip'] ||
      req.headers['true-client-ip'] ||
      req.headers['x-forwarded-host'] ||
      req.headers['via']
  );
  const secFetchSite = String(req.headers['sec-fetch-site'] || '').trim().toLowerCase();
  const isLoopback =
    !hasProxyForwardHeader && (remoteIp === '127.0.0.1' || remoteIp === '::1');
  if (!isLoopback || secFetchSite === 'cross-site' || !isAllowedClientOrigin(req)) {
    return res.status(403).json({ ok: false, error: 'Forbidden' });
  }
  if (typeof req.body?.autoSystemProxy === 'string') {
    const nextAutoProxy = req.body.autoSystemProxy.trim();
    cachedElectronAutoSystemProxy = nextAutoProxy || null;
    if (nextAutoProxy) process.env.HS_AUTO_SYSTEM_PROXY = nextAutoProxy;
    else delete process.env.HS_AUTO_SYSTEM_PROXY;
  }
  return res.json({ ok: true, autoSystemProxy: cachedElectronAutoSystemProxy || '' });
});

export const TELEGRAM_SUSPECTED_STUCK_THRESHOLD_MS = 35_000;
export const TELEGRAM_CONFIRMED_ZOMBIE_THRESHOLD_MS = 60_000;
export const TELEGRAM_STUCK_RECONNECT_FORCE_ZOMBIE_MS = 90_000;
export const TELEGRAM_ZOMBIE_PROBE_COOLDOWN_MS = 15_000;
export const TELEGRAM_ZOMBIE_PROBE_FAILURES_REQUIRED = 2;
export const TELEGRAM_ONLINE_HEALTH_PROBE_INTERVAL_MS = 75_000;

export function evaluateTelegramWatchdogAccountState(opts: {
  conn: ConnectedTelegramUser | undefined;
  runtime: TelegramAccountRuntimeState;
  proxyChanged: boolean;
  bypassBackoff?: boolean;
  now?: number;
}): {
  action: 'healthy' | 'probe_online' | 'wait_native' | 'warn_and_probe' | 'confirmed_zombie' | 'reconnect_offline' | 'skip';
  reconnectingDurationMs: number;
} {
  const now = opts.now ?? Date.now();
  const { conn, runtime, proxyChanged, bypassBackoff } = opts;
  const inspected = inspectGramJsClientState(conn?.client);
  syncAccountReconnectLifecycleMarkers(runtime, inspected, now);
  const snap = getTelegramAccountConnectionSnapshot(conn, runtime, { now });

  if (snap.isConnected && !proxyChanged) {
    runtime.retryCount = 0;
    runtime.nextRetryAt = 0;
    runtime.lastError = null;
    runtime.lastErrorCategory = null;
    runtime.offlineReason = null;
    const lastConfirmedAliveAt = Math.max(runtime.lastConnectedAt || 0, runtime.lastAliveProbeAt || 0);
    if (!runtime.activeRestoreTask && now - lastConfirmedAliveAt >= TELEGRAM_ONLINE_HEALTH_PROBE_INTERVAL_MS) {
      return { action: 'probe_online', reconnectingDurationMs: 0 };
    }
    return { action: 'healthy', reconnectingDurationMs: 0 };
  }

  if (runtime.activeRestoreTask) {
    return { action: 'skip', reconnectingDurationMs: 0 };
  }

  const reconnectingDurationMs =
    runtime.reconnectingSinceAt !== null ? Math.max(0, now - runtime.reconnectingSinceAt) : 0;

  if ((snap.isReconnecting || snap.isConnecting) && !proxyChanged) {
    if (inspected.senderIsReconnecting && reconnectingDurationMs >= TELEGRAM_SUSPECTED_STUCK_THRESHOLD_MS) {
      if (runtime.suspectedStuckWarningAt === null) {
        runtime.suspectedStuckWarningAt = now;
        console.warn(
          `[Telegram Watchdog Suspected Stuck] account=${runtime.accountKey} reconnectingDurationMs=${reconnectingDurationMs}`
        );
      }
      if (
        reconnectingDurationMs >= TELEGRAM_CONFIRMED_ZOMBIE_THRESHOLD_MS &&
        runtime.reconnectProbeFailures >= TELEGRAM_ZOMBIE_PROBE_FAILURES_REQUIRED &&
        (!inspected.transportConnected || reconnectingDurationMs >= TELEGRAM_STUCK_RECONNECT_FORCE_ZOMBIE_MS)
      ) {
        return { action: 'confirmed_zombie', reconnectingDurationMs };
      }
      if (now - runtime.lastHealthProbeAt >= TELEGRAM_ZOMBIE_PROBE_COOLDOWN_MS) {
        return { action: 'warn_and_probe', reconnectingDurationMs };
      }
    }
    return { action: 'wait_native', reconnectingDurationMs };
  }

  if (!bypassBackoff && !proxyChanged && runtime.nextRetryAt > now) {
    return { action: 'skip', reconnectingDurationMs };
  }

  return { action: 'reconnect_offline', reconnectingDurationMs };
}

export async function runTelegramConnectionWatchdogCycle(options?: {
  bypassBackoff?: boolean;
  reason?: string;
  deps?: {
    probeTransport?: typeof probeTelegramTransportEndpoint;
    probeClientHealth?: (client: TelegramClient) => Promise<void>;
    restoreSessions?: typeof restoreTelegramUserSessionsOnStartup;
    now?: () => number;
  };
}): Promise<number> {
  const nowFn = options?.deps?.now || Date.now;
  const now = nowFn();
  if (lastWatchdogTickAt > 0 && now - lastWatchdogTickAt > 60_000 && !options?.bypassBackoff && !options?.deps) {
    // Detected OS sleep/suspend wall-clock jump > 60s
    lastWatchdogTickAt = now;
    if (now - lastSystemResumeAt > 10_000) {
      return await handleSystemResumeWakeup('watchdog_wallclock_jump');
    }
  }
  lastWatchdogTickAt = now;

  if (telegramSessionRestoreState.inProgress || activeRestorePromise) return 0;
  // Require either active user JWT or configured env/RAM credentials before attempting reconnect
  const hasCredsPath = Boolean(
    lastActiveUserJwt || getEnvTelegramApiCredentials() || getInMemoryTelegramApiCredentials() || options?.deps?.restoreSessions
  );
  if (!hasCredsPath) return 0;

  let activeRows: any[] = [];
  try {
    activeRows = (await db
      .prepare('SELECT phone, user_id FROM telegram_user_sessions WHERE is_active = 1 LIMIT ?')
      .all(MAX_TELEGRAM_ACCOUNTS * 2)) as any[];
  } catch {
    return 0;
  }
  if (!Array.isArray(activeRows) || activeRows.length === 0) return 0;

  const configuredProxy = getConfiguredTelegramProxy();
  const currentProxyFingerprint = getTelegramProxyFingerprint(configuredProxy);
  const probeTransportFn = options?.deps?.probeTransport || probeTelegramTransportEndpoint;
  const probeClientHealthFn =
    options?.deps?.probeClientHealth ||
    ((client: TelegramClient) => withTelegramTimeout(client.getMe(), 4000, 'Watchdog 探活超时').then(() => undefined));
  const restoreFn = options?.deps?.restoreSessions || restoreTelegramUserSessionsOnStartup;

  const targetAccountKeys: string[] = [];
  const confirmedZombieKeys = new Set<string>();

  for (const row of activeRows) {
    const uid = row?.user_id ? String(row.user_id).trim() : '';
    const phone = row?.phone ? String(row.phone).trim() : '';
    if (!uid && !phone) continue;

    const isExpired = Boolean(
      (uid && (recentlyExpiredAccounts.has(uid) || recentlyExpiredAccounts.has(`acc_tg_${uid}`))) ||
        (phone && recentlyExpiredAccounts.has(phone))
    );
    if (isExpired) continue;

    const accountId = uid ? `acc_tg_${uid}` : phone;
    const runtime = getOrCreateTelegramAccountRuntimeState({
      userId: uid || undefined,
      phone: phone || undefined,
      accountId,
    });
    const conn = resolveConnectedTelegramUser(accountId, phone, uid);

    const hasKnownMatchingProxy = Boolean(
      conn?.proxyFingerprint && conn.proxyFingerprint === currentProxyFingerprint
    );
    const proxyChanged = Boolean(conn && !hasKnownMatchingProxy);

    const evaluation = evaluateTelegramWatchdogAccountState({
      conn,
      runtime,
      proxyChanged,
      bypassBackoff: options?.bypassBackoff,
      now,
    });

    if (evaluation.action === 'healthy' || evaluation.action === 'wait_native' || evaluation.action === 'skip') {
      continue;
    }

    // Never bypass active official Telegram FLOOD_WAIT cooldown during Watchdog (even on bypassBackoff wakeup)
    const activeFlood = getTelegramFloodCooldown(
      { accountId, userId: uid || undefined, phone: phone || undefined },
      now
    );
    if (activeFlood) {
      runtime.nextRetryAt = Math.max(runtime.nextRetryAt, activeFlood.floodWaitUntil);
      continue;
    }

    if (evaluation.action === 'probe_online' && conn?.client) {
      runtime.lastAliveProbeAt = now;
      let aliveOk = false;
      try {
        await scheduleTelegramRpc(accountId, 'P1', 'watchdog.onlineProbe', () =>
          probeClientHealthFn(conn.client)
        );
        aliveOk = true;
      } catch (aliveErr: any) {
        if (isTelegramSessionExpiredError(aliveErr)) {
          await markTelegramSessionExpired({
            accountId,
            userId: uid || undefined,
            phone: phone || undefined,
            reason: formatTelegramError(aliveErr),
          });
          continue;
        }
        const floodSec = extractFloodWaitSeconds(aliveErr);
        if (floodSec !== null) {
          recordTelegramFloodWait(
            { accountId, userId: uid || undefined, phone: phone || undefined },
            floodSec,
            'watchdog.onlineProbe',
            now
          );
          continue;
        }
        const aliveCode = String(aliveErr?.code || '').toUpperCase();
        if (aliveCode === 'TELEGRAM_RPC_QUEUE_FULL' || aliveCode === 'RPC_ABORTED') {
          continue;
        }
        aliveOk = false;
      }
      if (aliveOk) {
        runtime.lastConnectedAt = now;
        runtime.reconnectProbeFailures = 0;
        continue;
      }
      runtime.reconnectProbeFailures += 1;
      if (runtime.reconnectProbeFailures >= TELEGRAM_ZOMBIE_PROBE_FAILURES_REQUIRED && runtime.accountKey) {
        confirmedZombieKeys.add(runtime.accountKey);
        targetAccountKeys.push(runtime.accountKey);
      }
      continue;
    }

    if (evaluation.action === 'warn_and_probe' && conn?.client) {
      runtime.lastHealthProbeAt = now;
      let probePassed = false;
      try {
        if (configuredProxy) {
          await probeTransportFn({
            proxy: configuredProxy,
            connectTimeoutMs: 4000,
            handshakeTimeoutMs: 5000,
          });
        }
        await scheduleTelegramRpc(accountId, 'P0', 'watchdog.healthProbe', () => probeClientHealthFn(conn.client));
        probePassed = true;
      } catch {
        probePassed = false;
      }
      if (probePassed) {
        runtime.reconnectProbeFailures = 0;
        runtime.suspectedStuckWarningAt = null;
        continue;
      }
      runtime.reconnectProbeFailures += 1;
      const recheck = evaluateTelegramWatchdogAccountState({
        conn,
        runtime,
        proxyChanged,
        bypassBackoff: options?.bypassBackoff,
        now,
      });
      if (recheck.action !== 'confirmed_zombie') {
        continue;
      }
    }

    if (evaluation.action === 'confirmed_zombie' || runtime.reconnectProbeFailures >= TELEGRAM_ZOMBIE_PROBE_FAILURES_REQUIRED) {
      if (runtime.accountKey) {
        confirmedZombieKeys.add(runtime.accountKey);
        targetAccountKeys.push(runtime.accountKey);
      }
      continue;
    }

    if (runtime.accountKey) {
      targetAccountKeys.push(runtime.accountKey);
    }
  }

  if (targetAccountKeys.length === 0) {
    return 0;
  }

  const shouldForceReconnect =
    confirmedZombieKeys.size > 0 ||
    targetAccountKeys.some((k) => {
      const rt = telegramAccountRuntimeStates.get(k);
      const conn = rt ? resolveConnectedTelegramUser(rt.accountId, rt.phone, rt.userId) : undefined;
      return Boolean(conn && (!conn.proxyFingerprint || conn.proxyFingerprint !== currentProxyFingerprint));
    });

  return await restoreFn(lastActiveUserJwt || undefined, {
    targetAccountKeys,
    forceReconnect: shouldForceReconnect,
    reason: confirmedZombieKeys.size > 0 ? 'watchdog_zombie_recovery' : options?.reason || 'watchdog',
  });
}

export function startTelegramConnectionWatchdog(): void {
  if (telegramWatchdogInterval) return;
  telegramWatchdogInterval = setInterval(() => {
    void runTelegramConnectionWatchdogCycle().catch(() => {});
  }, 25000);
  telegramWatchdogInterval.unref?.();
}

export function stopTelegramConnectionWatchdog(): void {
  if (telegramWatchdogInterval) {
    clearInterval(telegramWatchdogInterval);
    telegramWatchdogInterval = null;
  }
}

export async function gracefulShutdownServer(reason = 'shutdown'): Promise<void> {
  console.log(`[Server Shutdown] Initiating graceful cleanup (${reason})...`);
  await stopTelegramBotLongPolling();
  stopTelegramConnectionWatchdog();
  stopTelegramCacheCleanupTimer();

  // Force-abort any pending withTelegramTimeout operations & destroy their temporary sockets cleanly
  for (const cancelFn of Array.from(activeTimeoutCleanupCallbacks)) {
    try {
      cancelFn();
    } catch {}
  }
  activeTimeoutCleanupCallbacks.clear();

  try {
    for (const qrSession of activeQrSessions.values()) {
      try {
        if (qrSession.pollTimer) clearTimeout(qrSession.pollTimer);
        if (qrSession.passwordTimeoutTimer) clearTimeout(qrSession.passwordTimeoutTimer);
        qrSession.isStopped = true;
        await destroyTelegramClientSafely(qrSession.client);
      } catch {}
    }
    activeQrSessions.clear();

    for (const pending of activeUserClients.values()) {
      try {
        if (pending.timeoutTimer) clearTimeout(pending.timeoutTimer);
        await destroyTelegramClientSafely(pending.client);
      } catch {}
    }
    activeUserClients.clear();

    pendingChangePhoneSessions.clear();
    activeTelegramCalls.clear();
    telegramStickerThumbCache.clear();
    inMemoryCloudTelegramCreds.clear();

    const uniqueClients = new Set<TelegramClient>();
    for (const conn of connectedUserClients.values()) {
      if (conn?.client) uniqueClients.add(conn.client);
    }
    await Promise.allSettled(Array.from(uniqueClients).map((c) => destroyTelegramClientSafely(c)));
    connectedUserClients.clear();
    telegramAccountRuntimeStates.clear();
  } catch {}

  await flushMessageDbWriteQueue({ timeoutMs: 3000 });
  await flushPendingLocalUpdatesDbQueue();
  await checkpointSqliteWal();

  if (activeHttpServer) {
    const srv = activeHttpServer;
    activeHttpServer = null;
    await new Promise<void>((resolve) => {
      try {
        srv.close(() => resolve());
        try {
          (srv as any).closeIdleConnections?.();
          (srv as any).closeAllConnections?.();
        } catch {}
        setTimeout(resolve, 1500).unref();
      } catch {
        resolve();
      }
    });
  }
}

// Expose graceful cleanup hook for Electron in-process main.cjs before-quit handler
(globalThis as any).__humansenseGracefulShutdown = gracefulShutdownServer;

// Start server
async function startServer() {
  try {
    dbInitError = null;
    await initDatabase();
    await loadPendingLocalUpdatesFromDb();
    await loadRevokedJwtTokensFromDb();
    await purgePersistedTelegramApiCredentialsFromDb();
    await loadSystemProxyConfigFromDb();
    await seedDatabaseIfEmpty();
  } catch (err: any) {
    dbInitError = err?.message || '本地 SQLite 数据库初始化失败';
    console.error('[Database Init Error]:', dbInitError);
  }

  // Automatic webhook registration on server startup if configured
  const autoRegister = process.env.TELEGRAM_AUTO_REGISTER_WEBHOOK === 'true' || process.env.AUTO_REGISTER_WEBHOOK === 'true';
  const autoBotToken = process.env.TELEGRAM_BOT_TOKEN;
  const autoWebhookUrl = process.env.TELEGRAM_WEBHOOK_URL;
  if (autoRegister && autoBotToken && autoWebhookUrl) {
    try {
      console.log(`[Telegram Auto-Register] Auto-registering Webhook URL: ${autoWebhookUrl}...`);
      const payload: Record<string, any> = {
        url: autoWebhookUrl,
        allowed_updates: ['message', 'edited_message', 'channel_post', 'callback_query'],
      };
      if (process.env.TELEGRAM_WEBHOOK_SECRET) {
        payload.secret_token = process.env.TELEGRAM_WEBHOOK_SECRET;
      }
      const tgRes = await fetch(`https://api.telegram.org/bot${autoBotToken}/setWebhook`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const tgData = await tgRes.json();
      console.log('[Telegram Auto-Register] Telegram response:', tgData);
    } catch (autoErr: any) {
      console.warn('[Telegram Auto-Register Warning]:', autoErr.message);
    }
  } else if (autoBotToken) {
    void startTelegramBotLongPolling();
  }

  const httpServer = http.createServer(app);
  activeHttpServer = httpServer;

  if (!isProduction) {
    const isHmrDisabled = process.env.DISABLE_HMR === 'true';
    const { createServer: createViteServer } = await import('vite');
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        hmr: isHmrDisabled ? false : { server: httpServer },
      },
      appType: 'spa',
    });
    app.use(vite.middlewares);

    // SPA fallback in development mode
    app.use('*', async (req: Request, res: Response, next: NextFunction) => {
      if (req.method !== 'GET' || req.originalUrl.startsWith('/api')) {
        return next();
      }
      try {
        const indexPath = path.resolve(__dirname, 'index.html');
        if (fs.existsSync(indexPath)) {
          let html = fs.readFileSync(indexPath, 'utf-8');
          html = await vite.transformIndexHtml(req.originalUrl, html);
          res.status(200).set({ 'Content-Type': 'text/html' }).end(html);
          return;
        }
      } catch (e: any) {
        vite.ssrFixStacktrace?.(e);
        return next(e);
      }
      next();
    });
  } else {
    const distDir = path.resolve(__dirname, 'dist');
    const staticDir = fs.existsSync(path.resolve(distDir, 'index.html'))
      ? distDir
      : __dirname;
    app.use(express.static(staticDir));
    app.get('*', (req: Request, res: Response) => {
      if (req.path === '/api' || req.path.startsWith('/api/')) {
        return res.status(404).json({ ok: false, error: '请求的 API 接口不存在' });
      }
      return res.sendFile(path.resolve(staticDir, 'index.html'));
    });
  }

  httpServer.on('error', (err: any) => {
    if (err?.code === 'EADDRINUSE') {
      console.error(`[Fatal Server Error] Port ${PORT} on ${HOST} is already in use.`);
      if (!isElectronMainProcess) {
        process.exit(1);
      } else {
        void gracefulShutdownServer('eaddrinuse');
      }
    }
  });

  if (!isElectronMainProcess) {
    const onShutdown = (sig: string) => {
      void gracefulShutdownServer(sig).finally(() => process.exit(0));
      setTimeout(() => process.exit(0), 2500).unref();
    };
    process.on('SIGTERM', () => onShutdown('SIGTERM'));
    process.on('SIGINT', () => onShutdown('SIGINT'));
  }

  httpServer.listen(PORT, HOST, () => {
    console.log(`HumanSense Server running at http://${HOST}:${PORT}`);
    // Run Telegram MTProto session recovery asynchronously AFTER HTTP port is bound so /api/health responds immediately
    void restoreTelegramUserSessionsOnStartup();
    startTelegramConnectionWatchdog();
    startTelegramCacheCleanupTimer();
  });
}

const isTestMode =
  process.env.AIS_TEST_IMPORT === 'true' ||
  process.env.NODE_ENV === 'test';

if (!isTestMode) {
  startServer();
}
